=\"\" column_spacing=\"\" rule_style=\"default\" rule_size=\"\" rule_color=\"\" content_alignment_medium=\"\" content_alignment_small=\"\" content_alignment=\"left\" hide_on_mobile=\"small-visibility,medium-visibility,large-visibility\" sticky_display=\"normal,sticky\" class=\"\" id=\"\" margin_top=\"\" margin_right=\"\" margin_bottom=\"\" margin_left=\"\" font_size=\"\" fusion_font_family_text_font=\"\" fusion_font_variant_text_font=\"\" line_height=\"\" letter_spacing=\"\" text_transform=\"none\" text_color=\"\" animation_type=\"\" animation_direction=\"left\" animation_speed=\"0.3\" animation_offset=\"\"]\r\n<h5><span style=\"color: #ffffff;\">Piet                                                                                                                                                                                                                              Actief in bronbemaling</span></h5>\r\n[/fusion_text][/fusion_builder_column][fusion_builder_column type=\"1_2\" layout=\"1_2\" align_self=\"auto\" content_layout=\"column\" align_content=\"flex-start\" valign_content=\"flex-start\" content_wrap=\"wrap\" spacing=\"\" center_content=\"no\" link=\"\" target=\"_self\" link_description=\"\" min_height=\"\" hide_on_mobile=\"small-visibility,medium-visibility,large-visibility\" sticky_display=\"normal,sticky\" class=\"\" id=\"\" background_image_id=\"\" type_medium=\"\" type_small=\"\" order_medium=\"0\" order_small=\"0\" spacing_left_medium=\"\" spacing_right_medium=\"\" spacing_left_small=\"\" spacing_right_small=\"\" spacing_left=\"\" spacing_right=\"\" margin_top_medium=\"\" margin_bottom_medium=\"\" margin_top_small=\"\" margin_bottom_small=\"\" margin_top=\"\" margin_bottom=\"\" padding_top_medium=\"\" padding_right_medium=\"\" padding_bottom_medium=\"\" padding_left_medium=\"\" padding_top_small=\"\" padding_right_small=\"\" padding_bottom_small=\"\" padding_left_small=\"\" padding_top=\"\" padding_right=\"\" padding_bottom=\"\" padding_left=\"\" hover