radient_end_position=\"100\" gradient_type=\"linear\" radial_direction=\"center center\" linear_angle=\"180\" background_position=\"left top\" background_repeat=\"no-repeat\" background_blend_mode=\"none\" filter_type=\"regular\" filter_hue=\"0\" filter_saturation=\"100\" filter_brightness=\"100\" filter_contrast=\"100\" filter_invert=\"0\" filter_sepia=\"0\" filter_opacity=\"100\" filter_blur=\"0\" filter_hue_hover=\"0\" filter_saturation_hover=\"100\" filter_brightness_hover=\"100\" filter_contrast_hover=\"100\" filter_invert_hover=\"0\" filter_sepia_hover=\"0\" filter_opacity_hover=\"100\" filter_blur_hover=\"0\" animation_direction=\"left\" animation_speed=\"0.3\" last=\"false\" border_position=\"all\" first=\"true\" border_sizes_top=\"2px\" border_sizes_right=\"2px\" border_sizes_bottom=\"2px\" border_sizes_left=\"2px\" border_color=\"#003b7f\" border_radius_top_left=\"5px\" border_radius_top_right=\"5px\" border_radius_bottom_right=\"5px\" border_radius_bottom_left=\"5px\" min_height=\"\" link=\"\"][fusion_text rule_style=\"default\" hide_on_mobile=\"small-visibility,medium-visibility,large-visibility\" sticky_display=\"normal,sticky\" margin_top=\"20px\" margin_right=\"20px\" margin_bottom=\"20px\" margin_left=\"20px\" text_transform=\"none\" animation_direction=\"left\" animation_speed=\"0.3\"]\r\n<p><span style=\"color: rgb(0, 59, 127); font-family: Ubuntu; font-weight: 500;\" data-fusion-font=\"true\" data-fusion-google-font=\"Ubuntu\" data-fusion-google-variant=\"500\"><span style=\"letter-spacing: normal;\" data-fusion-font=\"true\">\'\'Er staan van ons honderden pompen in Nederland en wisten niet of de installaties wel goed werkt. Nu krijgen wij een seintje via SMS of email wanneer er niet meer gepompt wordt en kunnen wij direct actie ondernemen, bespaart ons veel tijd en dus geld.\'\'</span></span></p>\r\n<p><span style=\"color: #003b7f; font-family: Ubuntu; font-weight: 500;\" data-fusion-font=\"true\" data-fusion-google-font=\"Ubuntu\" data-fusion-google-variant=\"500\"> </span></p>\r\n<p><span style=\"color: #003b7f; font-family: Ubuntu;\" data-fusion-font=\"true\" data-fusion-google-font=\"Ubuntu\" data-fusion-google-variant=\"500\"><b>- Piet</b></span></p>\r\n<p><span style=\"color: #003b7f; font-family: Ubuntu; font-weight: 500;\" data-fusion-font=\"true\" data-fusion-google-font=\"Ubuntu\" data-fusion-google-variant=\"500\">Actief in bronbemaling</span></p>\r\n<h5 class=\"fusion-responsive-typography-calculated\" style=\"--fontsize: 24; line-height: 1.4;\" data-fontsize=\"24\" data-lineheight=\"33.6px\"></h5>\r\n[/fusion_text][/fusion_builder_column][fusion_builder_column type=\"1_2\" type=\"1_2\" layout=\"1_2\" align_self=\"auto\" content_layout=\"column\" align_content=\"flex-start\" valign_content=\"flex-start\" content_wrap=\"wrap\" center_content=\"no\" target=\"_self\" hide_on_mobile=\"small-visibility,medium-visibility,large-visibility\" sticky_display=\"normal,sticky\" order_medium=\"0\" order_small=\"0\" hover_type=\"none\" border_style=\"solid\" box_shadow=\"no\" box_shadow_blur=\"0\" box_shadow_spread=\"0\" background_type=\"single\" gradient_start_position=\"0\" gradient_end_position=\"100\" gradient_type=\"linear\" radial_direction=\"center center\" linear_angle=\"180\" background_color=\"#ffffff\" background_position=\"left top\" background_repeat=\"no-repeat\" background_blend_mode=\"none\" filter_type=\"regular\" filter_hue=\"0\" filter_saturation=\"100\" filter_brightness=\"100\" filter_contrast=\"100\" filter_invert=\"0\" filter_sepia=\"0\" filter_opacity=\"100\" filter_blur=\"0\" filter_hue_hover=\"0\" filter_saturation_hover=\"100\" filter_brightness_hover=\"100\" filter_contrast_hover=\"100\" filter_invert_hover=\"0\" filter_sepia_hover=\"0\" filter_opacity_hover=\"100\" filter_blur_hover=\"0\" animation_direction=\"left\" animation_speed=\"0.3\" last=\"true\" border_position=\"all\" first=\"false\" padding_bottom=\"10px\" border_sizes_top=\"2px\" border_sizes_right=\"2px\" border_sizes_bottom=\"2px\" border_sizes_left=\"2px\" margin_bottom=\"0px\" border_color=\"#f49200\" border_radius_top_left=\"5px\" border_radius_top_right=\"5px\" border_radius_bottom_right=\"5px\" border_radius_bottom_left=\"5px\" min_height=\"\" link=\"\"][fusion_text rule_style=\"default\" hide_on_mobile=\"small-visibility,medium-visibility,large-visibility\" sticky_display=\"normal,sticky\" margin_top=\"20px\" margin_right=\"20px\" margin_bottom=\"20px\" margin_left=\"20px\" text_transform=\"none\" animation_direction=\"left\" animation_speed=\"0.3\"]\r\n<p style=\"color: rgb(0, 59, 127); font-family: Ubuntu; font-weight: 500;\" data-fusion-font=\"true\" data-fusion-google-font=\"Ubuntu\" data-fusion-google-variant=\"500\">\'\' Ons bedrijf hebben veel toegangsdeuren die nog niet op afstand te monitoren zijn. Door gebruik te maken van het Salland Electronics ThingsWay platform is dat wel mogelijk. Binnen een week was de eerste deur connected. De service afdeling werkt nu veel efficiënter en wij weten nu veel meer van de gebruiker.\'\'</p>\r\n<p style=\"color: rgb(0, 59, 127); font-family: Ubuntu;\" data-fusion-font=\"true\" data-fusion-google-font=\"Ubuntu\" data-fusion-google-variant=\"500\"><span style=\"font-weight: 500;\">-</span><b> Theresa</b></p>\r\n<p style=\"color: rgb(0, 59, 127); font-family: Ubuntu; font-weight: 500;\" data-fusion-font=\"true\" data-fusion-google-font=\"Ubuntu\" data-fusion-google-variant=\"500\">Toegangsverlening </p>\r\n[/fusion_text][/fusion_builder_column][fusion_builder_column type=\"1_2\" type=\"1_2\" layout=\"1_2\" align_self=\"auto\" content_layout=\"column\" align_content=\"flex-start\" valign_content=\"flex-start\" content_wrap=\"wrap\" center_content=\"no\" target=\"_self\" hide_on_mobile=\"small-visibility,medium-visibility,large-visibility\" sticky_display=\"normal,sticky\" order_medium=\"0\" order_small=\"0\" hover_type=\"none\" border_style=\"solid\" box_shadow=\"no\" box_shadow_blur=\"0\" box_shadow_spread=\"0\" background_type=\"single\" gradient_start_position=\"0\" gradient_end_position=\"100\" gradient_type=\"linear\" radial_direction=\"center center\" linear_angle=\"180\" background_color=\"#ffffff\" background_position=\"left top\" background_repeat=\"no-repeat\" background_blend_mode=\"none\" filter_type=\"regular\" filter_hue=\"0\" filter_saturation=\"100\" filter_brightness=\"100\" filter_contrast=\"100\" filter_invert=\"0\" filter_sepia=\"0\" filter_opacity=\"100\" filter_blur=\"0\" filter_hue_hover=\"0\" filter_saturation_hover=\"100\" filter_brightness_hover=\"100\" filter_contrast_hover=\"100\" filter_invert_hover=\"0\" filter_sepia_hover=\"0\" filter_opacity_hover=\"100\" filter_blur_hover=\"0\" animation_direction=\"left\" animation_speed=\"0.3\" last=\"false\" border_position=\"all\" first=\"true\" border_sizes_top=\"2px\" border_sizes_right=\"2px\" border_sizes_bottom=\"2px\" border_sizes_left=\"2px\" border_color=\"#f49200\" border_radius_top_left=\"5px\" border_radius_top_right=\"5px\" border_radius_bottom_right=\"5px\" border_radius_bottom_left=\"5px\" min_height=\"\" link=\"\"][fusion_text rule_style=\"default\" hide_on_mobile=\"small-visibility,medium-visibility,large-visibility\" sticky_display=\"normal,sticky\" margin_top=\"20px\" margin_right=\"20px\" margin_bottom=\"20px\" margin_left=\"20px\" text_transform=\"none\" animation_direction=\"left\" animation_speed=\"0.3\"]\r\n<p><span style=\"color: rgb(0, 59, 127); font-family: Ubuntu; font-weight: 500;\" data-fusion-font=\"true\" data-fusion-google-font=\"Ubuntu\" data-fusion-google-variant=\"500\">\'\' Wij zetten in op IoT technologie om ons bedrijf te internationaliseren. Wij weten veel van onderhoud van daken, maar met het ThingsWay platform weten wij nu echt wat er gebeurt en kunnen aan predictive maintenance beginnen. Wij lopen hiermee ver voor op de internationale concurrentie met onze slimme dakgoot.\'\'</span></p>\r\n<p></p>\r\n<p style=\"color: rgb(0, 59, 127);\"><b>- Peter</b></p>\r\n<p style=\"color: rgb(0, 59, 127); font-family: Ubuntu; font-weight: 500;\" data-fusion-font=\"true\" data-fusion-google-font=\"Ubuntu\" data-fusion-google-variant=\"500\">Actief in dak onderhoud </p>\r\n[/fusion_text][/fusion_builder_column][fusion_builder_column type=\"1_2\" type=\"1_2\" layout=\"1_2\" align_self=\"auto\" content_layout=\"column\" align_content=\"flex-start\" valign_content=\"flex-start\" content_wrap=\"wrap\" center_content=\"no\" target=\"_self\" hide_on_mobile=\"small-visibility,medium-visibility,large-visibility\" sticky_display=\"normal,sticky\" order_medium=\"0\" order_small=\"0\" hover_type=\"none\" border_style=\"solid\" box_shadow=\"no\" box_shadow_blur=\"0\" box_shadow_spread=\"0\" background_type=\"single\" gradient_start_position=\"0\" gradient_end_position=\"100\" gradient_type=\"linear\" radial_direction=\"center center\" linear_angle=\"180\" background_color=\"#ffffff\" background_position=\"left top\" background_repeat=\"no-repeat\" background_blend_mode=\"none\" filter_type=\"regular\" filter_hue=\"0\" filter_saturation=\"100\" filter_brightness=\"100\" filter_contrast=\"100\" filter_invert=\"0\" filter_sepia=\"0\" filter_opacity=\"100\" filter_blur=\"0\" filter_hue_hover=\"0\" filter_saturation_hover=\"100\" filter_brightness_hover=\"100\" filter_contrast_hover=\"100\" filter_invert_hover=\"0\" filter_sepia_hover=\"0\" filter_opacity_hover=\"100\" filter_blur_hover=\"0\" animation_direction=\"left\" animation_speed=\"0.3\" last=\"true\" border_position=\"all\" first=\"false\" padding_bottom=\"30px\" border_sizes_top=\"2px\" border_sizes_right=\"2px\" border_sizes_bottom=\"2px\" border_sizes_left=\"2px\" border_color=\"#003b7f\" border_radius_top_left=\"5px\" border_radius_top_right=\"5px\" border_radius_bottom_right=\"5px\" border_radius_bottom_left=\"5px\" min_height=\"\" link=\"\"][fusion_text rule_style=\"default\" hide_on_mobile=\"small-visibility,medium-visibility,large-visibility\" sticky_display=\"normal,sticky\" margin_top=\"20px\" margin_right=\"20px\" margin_bottom=\"20px\" margin_left=\"20px\" text_transform=\"none\" animation_direction=\"left\" animation_speed=\"0.3\"]\r\n<p><span style=\"color: rgb(0, 59, 127); font-family: Ubuntu; font-weight: 500;\" data-fusion-font=\"true\" data-fusion-google-font=\"Ubuntu\" data-fusion-google-variant=\"500\">\'\' Wij werken al jaren naar alle tevredenheid met Salland samen. Onze containers worden al meer dan 15 jaar online gemonitoord. Tegenwoordig met de modernste communicatie mogelijkheden, cloud omgeving en app’s.\'\'</span></p>\r\n<p></p>\r\n<p><span style=\"color: rgb(0, 59, 127);\"><b>- Edward</b></span></p>\r\n<p><span style=\"color: rgb(0, 59, 127); font-family: Ubuntu; font-weight: 500;\" data-fusion-font=\"true\" data-fusion-google-font=\"Ubuntu\" data-fusion-google-variant=\"500\">Millie sector</span></p>\r\n[/fusion_text][/fusion_builder_column][/fusion_builder_row][/fusion_builder_container]','Homepagina','','inherit','closed','closed','','2-revision-v1','','','2022-01-31 09:33:33','2022-01-31 09:33:33','',2,'https://thingsway.media2netdev.nl/?p=318',0,'revision','',0),(319,1,'2022-01-31 09:58:56','2022-01-31 09:58:56','Onderhoud is voor veel bedrijven enorm belangrijk, ook voor bedrijven in de installatiebranche. In dit artikel leest u waarom onderhoud zo belangrijk is voor deze bedrijven, maar tevens hoe het Internet of Things daarbij kan helpen.\r\n<h2>Wat houdt de installatiebranche in?</h2>\r\nIn de installatiebranche werken bedrijven die technische installaties aanleggen en bovendien onderhouden. Als voorbeelden kunnen we bedrijven noemen in de woningbouw, utiliteitsbouw en in de industrie. Een installatie wordt ontworpen door een installatiebedrijf, maar in sommige gevallen ook door een technisch bureau of door een technische afdeling van een opdrachtgever.\r\n\r\nDeze installaties worden aangelegd en onderhouden door een installateur of installatiemonteur. Dit zijn verzamelnamen voor medewerkers in verschillende technische takken. U kunt dan denken aan elektriciens, loodgieters en cv-monteurs.\r\nDe werkzaamheden van de installateur hangen af van de taken van het bedrijf. Enkele voorbeelden van de werkzaamheden van een installateur zijn:\r\n<h2>Het belang van onderhoud in de installatiebranche</h2>\r\nZoals u leest is het aanleggen van een installatie slechts een klein deel van de taken van een installateur. Onderhoud is voor bedrijven in de installatiebranche één van de belangrijkste taken. Een installatie kan nog zo goed aangelegd zijn, het zal niet goed functioneren wanneer er daarna geen onderhoud aan gepleegd wordt.\r\n\r\nCv-ketels, airconditionings, liften, koelinstallaties, het heeft allemaal onderhoud nodig om een veilige en efficiënte werking te garanderen. Alle onderdelen zijn nu eenmaal aan slijtage onderhevig. Het is daarom belangrijk voor deze bedrijven om een gedegen onderhoudsplan te hebben. In dit plan kunt u het best gebruik maken van verschillende soorten onderhoud; reactief onderhoud op onderdelen die niet kritisch zijn en makkelijk vervangbaar, periodiek onderhoud en voorspellend onderhoud.\r\n\r\nPeriodiek onderhoud wordt gedaan op basis van voorspellingen uit het verleden en volgens aanwijzingen van fabrikanten. Deze fabrikanten weten door testen vrij goed te voorspellen hoelang een bepaald onderdeel of een apparaat meegaat en hoe vaak er dus onderhoud gepleegd moet worden. De installateurs werken dagelijks met deze onderdelen en apparaten, hun rapportage en ervaringen dienen ook meegenomen te worden in de voorspellingen voor periodiek onderhoud.\r\n\r\nVoorspellend onderhoud is een andere vorm van onderhoud. Het kan een bedrijf helpen om een nadeel van periodiek onderhoud weg te nemen; namelijk onverwachte storingen aan of uitval van installaties. Voorspellend onderhoud wordt gedaan door middel van Internet of Things- toepassingen.\r\n\r\n<img class=\"size-full wp-image-1856 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/11/onderhoud-installatiebranche.jpg\" alt=\"belang van onderhoud in de installatiebranche\" width=\"1000\" height=\"800\" />\r\n<h2>De mogelijkheden van het IoT in de installatiebranche</h2>\r\nEen bedrijf in de installatiebranche weet vaak precies welke onderdelen van installaties kritisch zijn voor het veilig en effectief functioneren van een installatie. Gaat zo’n onderdeel kapot dan valt het gehele proces stil of er wordt mogelijk schade veroorzaakt aan de gehele installatie. Dit is de reden waarom deze onderdelen regelmatig gecontroleerd, vervangen en schoongemaakt worden.\r\n\r\nOm de effectiviteit van uw installatiebedrijf te vergroten zou u gebruik kunnen maken van een IoT-oplossing om deze onderdelen te monitoren. Bij het Internet of Things wordt gebruik gemaakt van sensoren. Deze sensoren meten continu bepaalde veranderingen in de omgeving, dat gaan om beweging, gas, licht, warmte etc. Deze veranderingen kunnen indicatoren zijn van slijtage en dus toekomstige storingen en uitval. Wanneer zo’n verandering plaatsvindt dan wordt dit via een directe internetverbinding naar een centraal punt gestuurd. Dat kan gaan om een laptop, computer of de smartphone van één van uw installatie medewerkers.\r\n\r\nDeze kan onderhoud plegen exact op het juiste moment, voordat zich een storing voordoet. De sensor neemt de periodieke onderhoudstaak weg van de installatiemonteur. Dit zorgt voor een veel effectiever onderhoudsplan.\r\n<h2>De Thingsway</h2>\r\nEen mooi voorbeeld van zo’n IoT-sensor is de Thingsway. Dit is een sensor dat voor veel verschillende toepassingen in de installatiebranche geschikt is. Deze sensor is namelijk eenvoudig en snel aan te passen aan de werkzaamheden en wensen van uw bedrijf. Bij aanpassingen die gedaan worden aan het basisproduct moet u denken aan de benodigde sensoren, de behuizing en de aansluiting. Salland Electronics, de ontwikkelaar van de Thingsway, kan al deze aanpassingen binnen een dag doen. Zodoende heeft u razendsnel een IoT-oplossing in uw bedrijf die u van dienst zal zijn bij het onderhoud van installaties.\r\n\r\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\r\n<h2>Vrijblijvend contact</h2>\r\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\r\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\r\n\r\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\r\n\r\n</div>','Het belang van onderhoud in de installatiebranche','','publish','open','open','','onderhoud-installatiebranche','','','2022-03-13 18:58:40','2022-03-13 18:58:40','',0,'https://thingsway.media2netdev.nl/het-belang-van-onderhoud-in-de-installatiebranche/',0,'post','',0),(320,1,'2022-01-31 09:33:37','2022-01-31 09:33:37','','onderhoud-in-installatiebranche','','inherit','open','closed','','onderhoud-in-installatiebranche','','','2022-01-31 09:58:59','2022-01-31 09:58:59','',319,'https://thingsway.media2netdev.nl/wp-content/uploads/2022/01/onderhoud-in-installatiebranche.jpg',0,'attachment','image/jpeg',0),(321,1,'2022-01-31 09:58:56','2022-01-31 09:58:56','IoT is een afkorting van het Internet of Things. Dit is een systeem waarbij allerlei alledaagse objecten met elkaar worden verbonden via het internet. U kunt dan denken aan computers, machines en apparaten, maar ook aan bijvoorbeeld dakgoten. Deze objecten kunnen zonder de tussenkomst van de mens met elkaar communiceren.\r\n\r\nAndere dagelijkse voorbeelden van Internet of Things-toepassingen zijn een hartimplantaat bij een persoon, een dier met een bio chip-ontvanger of een auto met sensoren om de bestuurder te waarschuwen voor gladde wegen of een lage bandenspanning. Voorwaarde voor een IoT-toepassing is dat het object een eigen IP-adres heeft en daardoor onafhankelijk gegevens over een netwerk kan verzenden.\r\n\r\nEr wordt steeds meer gebruik gemaakt van het IoT door bedrijven in verschillende bedrijfstakken. Het IoT helpt bedrijven om efficiënter te draaien, klanten beter te kunnen helpen, betere besluiten te kunnen nemen en voor het vergroten van de waarde.\r\n<h2>Hoe het IoT werkt</h2>\r\nEen IoT-toepassing bestaat uit verschillende slimme onderdelen zoals processors, sensoren en hardware voor communicatie. Deze onderdelen worden gebruikt om informatie uit de omgeving te halen, verzamelen, verzenden en om op te reageren. De gegevens die verzameld worden door sensoren worden gedeeld door middel van een gateway. Deze stuurt gegevens naar een cloud waar ze geanalyseerd kunnen worden.\r\n\r\nIn sommige IoT-systemen communiceren apparaten met elkaar en reageren zelf op de data die ze van elkaar krijgen. Het meeste werk in een IoT-systeem wordt dus gedaan door de apparaten, menselijke tussenkomt is vaak niet nodig. Natuurlijk kunnen mensen wel met deze apparaten communiceren, bijvoorbeeld wanneer ze ingesteld worden of wanneer toegang tot gegevens verkregen moet worden.\r\n\r\nDe specifieke IoT-toepassingen bepalen wat voor connectie en netwerk het best werkt voor de communicatie. Binnen het IoT wordt ook vaak gebruik gemaakt van kunstmatige intelligentie (AI). Hierbij leren machines zelf hoe een bepaald proces beter kan verlopen en past zich aan.\r\n<h2>Waarom is het IoT belangrijk?</h2>\r\nHet Internet of Things is een hulpmiddel voor mensen om slimmer en tegelijkertijd eenvoudiger te kunnen leven. Behalve het slimmer maken van huizen en apparaten om ons heen, is het IoT heel belangrijk voor bedrijven. Het IoT zorgt ervoor dat bedrijven continu real-time informatie krijgen over hun systemen. Dit biedt de mogelijkheid om een gedetailleerd inzicht te krijgen in bepaalde processen, hoe machines werken, productie, onderhoud en logistiek.\r\n\r\nMeerdere processen binnen een bedrijf kunnen met het IoT geautomatiseerd worden. Dit helpt een bedrijf om de arbeidskosten te verlagen. Andere positieve gevolgen zijn het tegengaan van verspilling, het verbeteren van de dienstverlening en het vergroten van efficiëntie op gebied van productie en onderhoud.\r\n\r\nHet Internet of Things wordt gezien als één van de belangrijkste technologieën van de afgelopen jaren. De verwachting is dat het niet alleen bepalend zal worden in ons dagelijks leven, maar ook voor de concurrerende positie van bedrijven.\r\n<h2>De invloed van het IoT op onderhoud</h2>\r\nBijna alle bedrijven hebben te maken met onderhoud, want alles om ons heen is nu eenmaal onderhevig aan slijtage. Om de werking van bepaalde processen te garanderen is onderhoud nodig. Of het nu gaat om een lift, een productiemachine of een dakgoot, door omstandigheden kunnen er storingen optreden in een proces.\r\n\r\nOm storingen en uitval te voorkomen wordt er aan onderhoud gedaan. Een veel gebruikte vorm is periodiek onderhoud. Deze vorm van onderhoud wordt gedaan op basis van instructies van fabrikanten en door gebruik van informatie uit het verleden. Hierdoor kunnen voorspellingen worden gedaan hoe vaak en wanneer een bepaald object onderhoud nodig heeft voordat het uitvalt.\r\n\r\nHet nadeel hiervan is dat storingen evengoed onverwacht kan plaatsvinden. Dit zou voorkomen kunnen worden door gebruik te maken van een IoT-toepassing zoals de Thingsway.\r\n<h2>De Thingsway</h2>\r\nDe Thingsway is een IoT-systeem dat voor veel verschillende toepassingen inzetbaar is. U kunt de Thingsway inzetten om een bepaald onderdeel te monitoren dat essentieel is in een bepaald proces.\r\nSensoren in de Thingsway houden eventuele veranderingen in een omgeving continu in de gaten. Als deze optreden dan zal de Thingsway via een directe internetverbinding een signaal geven waardoor u in kunt grijpen voordat storingen of problemen zich voordoen.\r\nEen ander groot voordeel is dat u door het continu monitoren een veel beter beeld krijgt van het gehele proces. Hierdoor kunt u aanpassingen doen die de efficiëntie van onderhoud zullen vergroten.\r\n\r\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\r\n<h2>Vrijblijvend contact</h2>\r\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\r\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\r\n\r\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\r\n\r\n</div>','Wat is de betekenis van IoT?','','publish','open','open','','betekenis-iot','','','2022-03-11 21:42:33','2022-03-11 21:42:33','',0,'https://thingsway.media2netdev.nl/wat-is-de-betekenis-van-iot/',0,'post','',0),(322,1,'2022-01-31 09:33:42','2022-01-31 09:33:42','','wat-is-iot','','inherit','open','closed','','wat-is-iot','','','2022-01-31 09:59:00','2022-01-31 09:59:00','',321,'https://thingsway.media2netdev.nl/wp-content/uploads/2022/01/wat-is-iot.jpg',0,'attachment','image/jpeg',0),(323,1,'2022-01-31 09:58:56','2022-01-31 09:58:56','Bijna in elke bedrijfsbranche wordt gesproken over hoe het Internet of Things zorgt voor een revolutie op de markt. Deze gesprekken worden vooral gevoerd bij grote bedrijven, die over voldoende kapitaal beschikken om mee te gaan in deze revolutie. MKB bedrijven beschikken vaak over minder tot beperkte middelen, toch kan het IoT ook deze bedrijven helpen. De inzet van het IoT zal er voor MKB bedrijven echter iets anders uitzien.\r\n<h2>De voordelen van het IoT</h2>\r\nDe voordelen van het IoT zijn zo goed als eindeloos, veel bedrijfsleiders zullen u dat weten te vertellen. Helaas kan niet ieder bedrijf profiteren van alle voordelen van het IoT, omdat het hoge kosten met zich mee kan brengen. Toch kunnen MKB bedrijven met beperkte middelen ook veel baat hebben bij een IoT-toepassing.\r\n\r\nWat het IoT voor uw bedrijf kan betekenen is afhankelijk van uw bedrijfstak en de beschikbare middelen. De voordelen die u als MKB bedrijf kunt krijgen van een IoT-toepassing vallen in twee categorieën; efficiëntie en verlaging van kosten.\r\n<h2>Voorbeelden van het IoT voor MKB bedrijven</h2>\r\nDoor arbeidsprocessen te vereenvoudigen en te stroomlijnen kunt u de efficiëntie in uw bedrijf vergroten. Een IoT-apparaat kan u daarbij helpen. Planning en andere administratieve taken kosten vaak veel van uw tijd, door deze te automatiseren kunt u de productiviteit binnen het bedrijf verhogen. Dit kunt u doen door deze taken te laten uitvoeren door bijvoorbeeld Google Assistant, een virtuele assistent. Uw werknemers kunnen zich daardoor concentreren op belangrijkere taken.\r\n\r\nHeeft u een MKB-bedrijf dat veel met magazijnbeheer te maken heeft? Het IoT is dan zeer geschikt voor u om de efficiëntie te vergroten. Door gebruik te maken van sensoren kunnen uw medewerkers alle goederen volgen en vinden in het magazijn.\r\n\r\nOver het algemeen zorgen IoT-toepassingen ervoor dat het leven van medewerkers, bewoners of gebruikers gemakkelijker wordt gemaakt. Ook voor MKB bedrijven kan dit leiden tot een hogere productiviteit. Een ander groot voordeel van IoT voor het MKB is de verlaging van kosten. Een Internet of Things versie van een alledaags apparaat kan op langere termijn voor aanzienlijke besparingen zorgen. Denkt u dan bijvoorbeeld aan een slimme thermostaat.\r\n\r\nHet IoT is tevens zeer effectief op gebied van voorspellend onderhoud, daarom is het een populaire toepassing geworden voor veel bedrijven. Wanneer u als bedrijf voorspellend onderhoud toepast, dan kunt u storingen en defecten aan machines en apparaten voorspellen voordat de problemen zich voordoen.\r\n\r\nVoorspellend onderhoud wordt gedaan door middel van sensoren, deze houden continu machines in de gaten. Hierdoor kan onderhoud uitgevoerd worden wanneer het echt nodig is. Het IoT helpt hiermee een bedrijf om reparaties en stilstand te voorkomen, dit scheelt enorm in de kosten.\r\n<h2>Toepassen van het IoT in het MKB</h2>\r\nDe revolutionaire technologie van het IoT is niet alleen geschikt voor grote bedrijven, maar kan ook MKB bedrijven dezelfde voordelen bieden. Deze kunnen dat echter vaak niet op dezelfde schaal toepassen. Sommige MKB bedrijven kiezen niet voor een IoT-toepassing, omdat ze zorgen hebben over de aanschaf- en installatiekosten. Grote bedrijven hebben daarbij een voordeel, maar ook voor MKB bedrijven bestaan er oplossingen en mogelijkheden zonder grote risico’s. Het is daarbij belangrijk om als bedrijf te bepalen wat de kritieke onderdelen of processen zijn in uw bedrijf.\r\n<h2>Wat kan een MKB bedrijf met het IoT?</h2>\r\nOm als MKB bedrijf op een goede manier gebruik te maken van het IoT, dient u te bepalen waar uw behoeften liggen. Waar zitten de inefficiënties in uw bedrijf? Door deze te bepalen kunt u op een gerichte manier een investering doen door een IoT-toepassing te implementeren. Is het gebruik van elektriciteit één van de grote kostenposten in uw bedrijf? Dan kunt u bijvoorbeeld gebruiken maken van slimme lampen of een slimme thermostaat. Is een bepaalde machine essentieel voor uw bedrijf? Laat deze dan monitoren door een IoT-sensor.\r\n<h2>De Thingsway, een IoT-sensor</h2>\r\nDe Thingsway is een IoT-sensor dat ontwikkeld is door Salland Electronics. Deze sensor heeft een aantal grote voordelen:\r\n• De sensor is makkelijk en snel aan te passen aan de wensen van uw bedrijf;\r\n• Binnen een dag kunt u een sensor in uw bedrijf hebben;\r\n• De Thingsway is een voordelig product.\r\n\r\nDoor deze voordelen is de Thingsway een zeer toegankelijk en geschikt product voor een MKB bedrijf. Wilt u als MKB bedrijf profiteren van de mogelijkheden van het IoT? Dan is de Thingsway het geschikte product voor u!\r\n\r\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\r\n<h2>Vrijblijvend contact</h2>\r\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\r\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\r\n\r\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\r\n\r\n</div>','Wat kan IoT voor een ZZP\'er en MKB bedrijf betekenen?','','publish','open','open','','iot-mkb','','','2022-03-13 18:52:34','2022-03-13 18:52:34','',0,'https://thingsway.media2netdev.nl/wat-kan-iot-voor-een-zzper-en-mkb-bedrijf-betekenen/',0,'post','',0),(324,1,'2022-01-31 09:33:45','2022-01-31 09:33:45','','iot-mkb-bedrijven','','inherit','open','closed','','iot-mkb-bedrijven','','','2022-01-31 09:59:01','2022-01-31 09:59:01','',323,'https://thingsway.media2netdev.nl/wp-content/uploads/2022/01/iot-mkb-bedrijven.jpg',0,'attachment','image/jpeg',0),(325,1,'2022-01-31 09:59:02','2022-01-31 09:59:02','De naam duikt steeds vaker op en we maken er ongemerkt steeds meer gebruik van, maar toch klinkt voor velen de term “Internet of Things” nog als een onbekende toekomstvisie. Het Internet of Things is simpelweg het concept van het verbinden van alledaagse dingen aan het internet, waardoor ze in staat zijn om onderling te communiceren. Het principe achter dit idee is niet nieuw. Voorheen werd het Machine-to-Machine genoemd, maar het IoT is veel groter dan dat.\n\nZonder dat we er bewust van zijn, is het aantal verbonden dingen in onze wereld enorm groot geworden en de vraag neemt alleen maar toe. De waarde van de markt in IoT producten en toepassingen groeit daardoor explosief. In dit artikel kunt u lezen van het IoT precies is en geven we u enkele voorbeelden van IoT toepassingen in de wereld.\n<h2>Wat is het IoT en wat is dat ding dan precies?</h2>\nUw computer en uw smartphone zijn voor u bekende dingen die met het internet verbonden zijn. Het Internet of Things gaat verder dan dat, want het gaat om het woord dingen. Alledaagse dingen die nu voorzien worden van een internetverbinding kunnen apparaten, machines en systemen zijn, maar ook objecten zoals een brug, weg of dakgoot. Door de internetverbinding kunnen deze met elkaar communiceren, met als ultieme doel het leven van mensen te versimpelen en effectiever te maken.\n<h2>Hoe maken IoT-toepassingen verbinding met elkaar?</h2>\nOm verbinding te maken met het internet wordt er binnen het IoT gebruik gemaakt van verschillende soorten netwerken zoals:\n<h2>Mobiel netwerk</h2>\nSmartphones hebben gezorgd voor een enorme groei van het IoT want ze zijn een soort assistent geworden van andere apparaten, zonder ingebouwde internetnetconnectie. U kunt dan denken aan persoon weegschalen, fitness-meters en smarthome-apparaten. Deze zijn afhankelijk van de smartphone om zich met het internet te verbinden.\nHet Internet of Things is een grote reden waarom het 5G netwerk opgezet wordt. 5G kan namelijk aan veel meer apparaten connectiviteit bieden dan 4G.\n<h2>Het WiFi-netwerk</h2>\nWe maken steeds meer gebruik van slimme apparaten in ons huis, dit zijn de duidelijkste voorbeelden van het IoT om ons heen. Denkt u maar eens aan een slimme thermostaat, slimme luidsprekers, slimme koelkasten en een videodeurbel. Deze apparaten maken gebruik van uw WIFI-netwerk om uit zichzelf te kunnen functioneren.\n<h2>Vast internet</h2>\nVeel bedrijven in de productie-industrie maken nog steeds gebruik van vast internet om de connectie van hun IoT-toepassingen te waarborgen. Dit wordt echter steeds vaker vervangen door IoT-sensoren met een eigen gateway.\n<h2>Voorbeelden van IoT toepassingen</h2>\nWe hebben al enkele voorbeelden genoemd hoe het Internet of Things steeds meer in ons dagelijks leven aanwezig is. De meeste toepassingen gaan echter ongemerkt zoals bij de volgende voorbeelden:\n<h2>Slimme afvalverwerking in steden</h2>\nAfval wordt afgehaald op een vaste dag in de maand, toch? Helaas niet erg praktisch. Steeds meer gemeentes maken gebruik van het IoT om afval op te halen wanneer het nodig is, dus wanneer de containers vol zijn.\n\n<img class=\"size-full wp-image-1957 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/12/iot-toepassing-bij-afvalverwerking.jpg\" alt=\"iot toepassing\" width=\"1920\" height=\"1080\" />\n<h2>Slimme gebouwen</h2>\nHet IoT is de ideale manier om ons leven makkelijker en aangenamer te maken in gebouwen. Een klein voorbeeld daarvan is een slimme thermostaat. Deze kan voor u regelen dat het op het juiste moment aangenaam is in uw huis. Grote voorbeelden worden gebruikt in grotere gebouwen. IoT-toepassingen zorgen ervoor dat kantoren, ziekenhuizen, fabrieken maar ook hele woningcomplexen ‘slim’ worden. Het gebouw zorgt zelf voor de juiste temperatuur, voor een gezond leefklimaat en dat er zuinig met stroom wordt omgegaan.\n<h2>IoT en de invloed op bedrijven</h2>\nHet IoT heeft voor veel bedrijven gezorgd voor een nieuwe industriële revolutie. Door systemen, machines en objecten te monitoren met sensoren kan een bedrijf een veel beter inzicht krijgen in een proces. Dit kan veel positieve gevolgen hebben voor de effectiviteit van een bedrijf, wat zorgt voor een hogere winst. Om concurrent te blijven als bedrijf is het van groot belang om mee te gaan in de wereld van het IoT.\n\nEen voorbeeld van zo’n sensor is de Thingsway. Deze kan ingezet worden voor veel verschillende IoT-toepassingen. Op dit moment monitort een Thingsway sensor de werking van een dakgoot. Door dit continu te monitoren weet de eigenaar van het pand precies wanneer onderhoud gepleegd moet worden, voordat problemen zich voordoen. Dit is slechts een voorbeeld van de mogelijkheden van de Thingsway. Het is een basisproduct dat zeer snel aan te passen is op uw wensen en het te meten proces.\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>','Voorbeelden van IoT toepassingen','','publish','open','open','','voorbeelden-iot-toepassingen','','','2022-02-04 12:54:25','2022-02-04 12:54:25','',0,'https://thingsway.media2netdev.nl/voorbeelden-van-iot-toepassingen/',0,'post','',0),(326,1,'2022-01-31 09:33:52','2022-01-31 09:33:52','','toepassingen-iot','','inherit','open','closed','','toepassingen-iot','','','2022-01-31 09:59:03','2022-01-31 09:59:03','',325,'https://thingsway.media2netdev.nl/wp-content/uploads/2022/01/toepassingen-iot.jpg',0,'attachment','image/jpeg',0),(327,1,'2022-01-31 09:34:52','2022-01-31 09:34:52','[fusion_builder_container type=\"flex\" hundred_percent=\"no\" hundred_percent_height=\"no\" hundred_percent_height_scroll=\"no\" align_content=\"stretch\" flex_align_items=\"flex-start\" flex_justify_content=\"flex-start\" hundred_percent_height_center_content=\"yes\" equal_height_columns=\"no\" container_tag=\"div\" hide_on_mobile=\"small-visibility,medium-visibility,large-visibility\" status=\"published\" spacing_medium=\"\" spacing_small=\"\" padding_dimensions_medium=\"\" padding_dimensions_small=\"\" border_sizes=\"\" border_style=\"solid\" box_shadow=\"no\" box_shadow_blur=\"0\" box_shadow_spread=\"0\" gradient_start_color=\"\" gradient_end_color=\"\" gradient_start_position=\"0\" gradient_end_position=\"100\" gradient_type=\"linear\" radial_direction=\"center center\" linear_angle=\"180\" background_position=\"center center\" background_repeat=\"no-repeat\" fade=\"no\" background_parallax=\"none\" enable_mobile=\"no\" parallax_speed=\"0.3\" background_blend_mode=\"none\" video_aspect_ratio=\"16:9\" video_loop=\"yes\" video_mute=\"yes\" render_logics=\"\" absolute=\"off\" absolute_devices=\"small,medium,large\" sticky=\"off\" sticky_devices=\"small-visibility,medium-visibility,large-visibility\" sticky_transition_offset=\"0\" scroll_offset=\"0\" animation_direction=\"left\" animation_speed=\"0.3\" filter_hue=\"0\" filter_saturation=\"100\" filter_brightness=\"100\" filter_contrast=\"100\" filter_invert=\"0\" filter_sepia=\"0\" filter_opacity=\"100\" filter_blur=\"0\" filter_hue_hover=\"0\" filter_saturation_hover=\"100\" filter_brightness_hover=\"100\" filter_contrast_hover=\"100\" filter_invert_hover=\"0\" filter_sepia_hover=\"0\" filter_opacity_hover=\"100\" filter_blur_hover=\"0\"][fusion_builder_row][fusion_builder_column type=\"1_1\" align_self=\"auto\" content_layout=\"column\" align_content=\"flex-start\" valign_content=\"flex-start\" content_wrap=\"wrap\" center_content=\"no\" target=\"_self\" hide_on_mobile=\"small-visibility,medium-visibility,large-visibility\" sticky_display=\"normal,sticky\" type_medium=\"\" type_small=\"\" type=\"1_1\" order_medium=\"0\" order_small=\"0\" dimension_spacing_medium=\"\" dimension_spacing_small=\"\" dimension_spacing=\"\" dimension_margin_medium=\"\" dimension_margin_small=\"\" dimension_margin=\"\" padding_medium=\"\" padding_small=\"\" padding=\"\" hover_type=\"none\" border_sizes=\"\" border_style=\"solid\" border_radius=\"\" box_shadow=\"no\" dimension_box_shadow=\"\" box_shadow_blur=\"0\" box_shadow_spread=\"0\" background_type=\"single\" gradient_start_color=\"\" gradient_end_color=\"\" gradient_start_position=\"0\" gradient_end_position=\"100\" gradient_type=\"linear\" radial_direction=\"center center\" linear_angle=\"180\" background_position=\"left top\" background_repeat=\"no-repeat\" background_blend_mode=\"none\" render_logics=\"\" filter_type=\"regular\" filter_hue=\"0\" filter_saturation=\"100\" filter_brightness=\"100\" filter_contrast=\"100\" filter_invert=\"0\" filter_sepia=\"0\" filter_opacity=\"100\" filter_blur=\"0\" filter_hue_hover=\"0\" filter_saturation_hover=\"100\" filter_brightness_hover=\"100\" filter_contrast_hover=\"100\" filter_invert_hover=\"0\" filter_sepia_hover=\"0\" filter_opacity_hover=\"100\" filter_blur_hover=\"0\" animation_direction=\"left\" animation_speed=\"0.3\" min_height=\"\" last=\"no\" link=\"\" border_position=\"all\"][fusion_post_cards post_card=\"60\" post_card_list_view=\"0\" source=\"posts\" post_type=\"post\" posts_by=\"category\" out_of_stock=\"include\" show_hidden=\"no\" number_posts=\"0\" offset=\"0\" orderby=\"date\" orderby_term=\"name\" order=\"DESC\" scrolling=\"pagination\" hide_on_mobile=\"small-visibility,medium-visibility,large-visibility\" layout=\"grid\" flex_align_items=\"flex-start\" columns_medium=\"0\" columns_small=\"0\" separator_style_type=\"none\" separator_alignment=\"center\" autoplay=\"no\" show_nav=\"yes\" mouse_scroll=\"no\" slider_animation=\"fade\" animation_direction=\"left\" animation_speed=\"0.3\" animation_delay=\"0\" exclude_category=\"3\" columns=\"3\" column_spacing=\"40\" row_spacing=\"40\" /][/fusion_builder_column][/fusion_builder_row][/fusion_builder_container]','Nieuws','','inherit','closed','closed','','21-revision-v1','','','2022-01-31 09:34:52','2022-01-31 09:34:52','',21,'https://thingsway.media2netdev.nl/?p=327',0,'revision','',0),(328,1,'2022-01-31 09:35:38','2022-01-31 09:35:38','Waar IoT bij uitstek geschikt voor is, is predictive maintenance. Nog veel service afdelingen werken op basis van periodiek onderhoud of op basis van storingsmeldingen. Het is mogelijk door toepassing van sensoren of uitlezen van informatie, te voorspellen wanneer er een storing kan optreden door bijvoorbeeld slijtage van een bepaald onderdeel of toename van onbalans trillingen. Door het aanbrengen van detectiveniveaus kan automatisch een melding gegenereerd worden en bijvoorbeeld een onderhoudsbezoek worden gepland, voordat een machine uitvalt. Dit geeft een enorme efficiency en een hogere klanttevredenheid. Er kan al gauw 20-30% aan kosten worden bespaard met predictive maintenance.','Predictive maintenance','605','inherit','closed','closed','','199-revision-v1','','','2022-01-31 09:35:38','2022-01-31 09:35:38','',199,'https://thingsway.media2netdev.nl/?p=328',0,'revision','',0),(329,1,'2022-01-31 09:35:38','2022-01-31 09:35:38','[et_pb_section fb_built=\"1\" _builder_version=\"4.5.6\" _module_preset=\"default\"][et_pb_row _builder_version=\"4.5.6\" _module_preset=\"default\" hover_enabled=\"0\"][et_pb_column type=\"4_4\" _builder_version=\"4.5.6\" _module_preset=\"default\"][et_pb_text _builder_version=\"4.5.6\" _module_preset=\"default\" hover_enabled=\"0\"]<p>In de loop van de jaren is de projectaanpak ook flink veranderd. IoT succesvol toepassen binnen een onderneming is vaak een strategische keuze en kan voordelen bieden voor de hele bedrijfsketen. De juiste procesaanpak is cruciaal om tot succesvolle IoT implementaties te komen, vooral bij grotere organisaties. Beginnen met een zg. stakeholder (belanghebbenden) analyse om de functionele eisen boven tafel te halen, is een goede eerste stap. Vergeet daarbij vooral ook niet te kijken naar de voordelen van de klant van de klant. Een grote valkuil is te veel in een keer te willen, het is daarom belangrijk prioriteiten aan te brengen en een roadmap te ontwikkelen. Koppelen aan business cases helpen daar enorm bij, aangezien snel inzichtelijk is wat het meeste rendement oplevert, de zg. quick wins. Regelmatig maken wij mee dat de klant het heeft over big data, app’s voor jan en alleman terwijl er nog geen product aan het internet hangt en data genereert. Het is niet altijd noodzakelijk<ins cite=\"mailto:Emma%20Tuininga\" datetime=\"2020-03-20T13:33\">,</ins> maar een Proof of Concept in de beginfase is te overwegen om IoT tastbaar te maken voor beslissers of de ontwikkelrisico’s te reduceren. Het traject van eerste inventarisatie tot bestek (specificaties), noemen wij de conceptfase. Na de conceptfase start de ontwerpfase, waarbij hoe verder het ontwikkeltraject vordert de wijzigingskosten toenemen. Dat in tegenstelling tot de risico’s die in de conceptfase het hoogst zijn.</p>\n[/et_pb_text][/et_pb_column][/et_pb_row][/et_pb_section]','Aanpak IoT projecten','734','inherit','closed','closed','','200-revision-v1','','','2022-01-31 09:35:38','2022-01-31 09:35:38','',200,'https://thingsway.media2netdev.nl/?p=329',0,'revision','',0),(330,1,'2022-01-31 09:35:39','2022-01-31 09:35:39','[et_pb_section][et_pb_row][et_pb_column type=\"4_4\"][et_pb_text]\n\n<strong>Klantcase VConsyst, de ondergrondse containers</strong>\n\nVrijwel sinds de oprichting van <strong>Salland</strong>Electronics hebben wij ons beziggehouden met systemen die op afstand beheerd moesten worden. Een van onze eerste klanten was VConsyst uit Genemuiden<ins cite=\"mailto:Emma%20Tuininga\" datetime=\"2020-03-20T11:35\">,</ins> leverancier van ondergrondse containers.  Deze ondergrondse containers moesten op afstand kunnen communiceren door de invoering van Diftar midden jaren 90. Diftar staat voor gedifferentieerd tariefstelsel. Diftar was geïnitieerd omdat gemeentes wilden overschakelen naar het principe van de vervuiler betaald. De burger moest dus gaan betalen voor de hoeveelheid afval dat wordt aangeboden. Voor de ondergrondse containers moest er dus een registratie en toegangsverleningssysteem komen om dat mogelijk te maken. Wij hebben destijds voor VConsyst 30 pilotsystemen ontwikkeld. Doel was demonstreren van het systeem op een beurs en in het verlengde daarvan het kunnen houden van eerste pilots. Het systeem was gebaseerd op een PC/104 board, modem, dragerprint en een maatwerk bedieningspaneel. Op locatie moest netspanning en een vaste dataverbinding aangelegd worden. Hierdoor was het mogelijk om de systemen uit te lezen om bijvoorbeeld het aantal stortingen per gezin te registeren en het systeem te voorzien van een zg. whitelist. Een whitelist bevat de pasnummers van de bewoners die op een locatie mogen storten. Aan de hand van het aantal stortingen werd er gefactureerd. Een van de eerste gemeente was Apeldoorn, daar werden 250 containers geplaatst. De WMS I was de eerste generatie toegangsverleningssystemen voor de ondergrondse containers van VConsyst. Tot en met de 4<sup>e</sup> generatie (WMS IV), werd gewerkt met een vaste voeding en een bedrade dataverbinding.\n\nIn dezelfde periode van de opkomst van Diftar vonden de ontwikkelingen plaats van het mobiele gsm-communicatienetwerk. Onder andere 2G was uitermate geschikt voor machine-to-machine (M2M) oplossingen. Rond 2003 is besloten om de 5<sup>e</sup> generatie WMS-systemen te gaan ontwikkelen op basis van een batterijvoeding en communicatie via het 2G GSM mobiele netwerk. Deze keuze werd ook ingegeven door het feit dat de kosten voor het aanleggen van een netspanning en dataverbinding op locatie in de loop der jaren fors opliepen. In 2005 zijn deze systemen voor het eerst geïntroduceerd. Dat ging niet zonder slag of stoot, het toepassen van speciale lithium batterijen en communicatie via het 2G netwerk hebben de nodige hoofdbrekens gekost. Ook het goed beveiligen van de batterijen en de juiste antenne lay-out hebben tot de nodige leermomenten geleid. Omdat de M2M markt in ontwikkeling was ging het werken met de telecomproviders en uitrol procedures met vallen en opstaan<ins cite=\"mailto:Emma%20Tuininga\" datetime=\"2020-03-22T12:08\">.</ins> Om een klein voorbeeld te geven, de M2M SIMS’s moesten door de provider geleverd worden zonder pincode. Echter week dat af van de normale procedure en werd er regelmatig met en zonder een pincode geleverd (de welbekende 0000). Dit had tot gevolg dat op locatie met een mobiel toestel de pincode van de SIM handmatig uitgezet moest worden. Voordat dit vastgesteld was, waren al meer dan 250 systemen in het veld geleverd, met dus veel extra werk als gevolg.\n\nNa 2006 deed de Chiplock generatie zijn intrede (CL-x.x)<ins cite=\"mailto:Emma%20Tuininga\" datetime=\"2020-03-20T11:59\">.</ins> Deze kwam met een batterij en zonnecel uitvoering, beide voorzien van een revolutionaire nieuw display technolog<ins cite=\"mailto:Emma%20Tuininga\" datetime=\"2020-03-20T11:58\">i</ins>e, namelijk een bistabiel LCD display (de technische benaming is Chlorestic Liquid Crystal ChLCD). Het bistabiele display is extreem energiezuinig, want alleen bij verandering van de tekst is energie nodig en de tekst<ins cite=\"mailto:Emma%20Tuininga\" datetime=\"2020-03-20T12:01\"> blijft</ins> staan als er geen spanning aanwezig is. Met name het verlengen van de levensduur van de batterij vraagt om energiezuinige oplossingen. Onder andere door toenemende concurrentie moest de total cost of ownership (TCO) omlaag.\n\nInmiddels is de nieuwste generatie op de markt gekomen onder de aanduiding CL-4.0. De kenmerken van deze generatie zijn; energie efficiënt en modulaire opzet. Het bi-stabiele display is vervangen door een kleuren LCD. Door de voortschrijdende stand der techniek is het verbruik van dit type displays sterk verlaagt. Tevens zijn er meerdere leveranciers, dus geen vendor lock en met een gunstigere total cost of ownership. Door de modulaire opzet van het systeem is deze toekomstbestendiger. Voor met name de mobiele communicatie kan snel omgeschakeld worden naar de nieuwste ontwikkelingen, zoals bijvoorbeeld MTE-M of NB-IoT. Het systeem heeft bluetooth draadloze communicatie<ins cite=\"mailto:Emma%20Tuininga\" datetime=\"2020-03-20T12:06\">,</ins> waardoor het in bedrijfstellen, onderhoud en diagnose ter plaatse, veel efficiënter verloopt. Het systeem is tevens geschikt gemaakt voor betalen met je smartphone. Naast de gekozen hardware modulariteit kennen wij al jaren modulaire software in de vorm van herbruikbare bouwblokken, wij noemen dat atomic embedded modules (AEM). Door de modulaire opzet, is het mogelijk snel varianten van het huidige systeem te maken, bijvoorbeeld een uitgeklede versie waardoor de time-to-market wordt verkleind. Een ander voordeel zijn de lagere ontwikkelrisico’s door hergebruik van hard- en softwaremodules.\n\nDe ontwikkelingen gedaan voor VConsyst de afgelopen 23 jaar laten mooi zien hoe de techniek zich ontwikkelt en de generaties elkaar opvolgen. Van eerste generatie, naar energiezuinig en draadloos, naar verlagen TCO en modulaire bouwblokken met als doel flexibiliteit en het verlagen van de time-to-market.\n\n[/et_pb_text][/et_pb_column][/et_pb_row][/et_pb_section]','Klantcase VConsyst','780','inherit','closed','closed','','201-revision-v1','','','2022-01-31 09:35:39','2022-01-31 09:35:39','',201,'https://thingsway.media2netdev.nl/?p=330',0,'revision','',0),(331,1,'2022-01-31 09:35:40','2022-01-31 09:35:40','Veel IoT projecten mislukken omdat men te veel in een keer wil, technisch is er veel mogelijk. Een goede start met een IoT project is een brede inventarisatie van de wensen en eisen en dan een roadmap te ontwikkelen. Dit is cruciaal om de juiste verwachtingen te managen en een realistische aanpak voor implementatie, uitgangspunt zijn vaak de achterliggende business cases. Zet een stip aan de horizon waar je naar toe wilt, maar begin met de \"quick wins\". Een fictief voorbeeld: stel je bent een leverancier van snack automaten aan de professionele zakelijke branche. Je stip aan de horizon kan zijn om de afnemers, die vaak meerdere automaten hebben staan, inzicht te geven in de prestaties en gebruik van de automaten om de behoefte  van de medewerkers beter af te stemmen op het aanbod. Daar kan van alles bij komen kijken, bv een cloud voor de klant, apps voor de beheerder, office manager, inkoop. Als de automaat nog niet aan het internet hangt, zou een eerste stap kunnen zijn om de service te verbeteren op basis van gebruik en niet op basis van periodiek onderhoud. Hiermee kun je naar voorspelbaar onderhoud, waardoor de efficiency van je service afdeling vaak met meer dan 20% kan verbeteren. Een volgende stap in de roadmap zou kunnen zijn de bevoorrading van de automaten te automatiseren. Je weet dan ook de hardlopers en kunt spelen met alternatieve producten zoals bijvoorbeeld gezonde snacks. Dat zou bijvoorbeeld in een diensten model gegoten worden, waarbij de klant compleet ontzorgd  worden. Door data analyse met bijvoorbeeld Articial Intelligence kan per regio, land, werelddeel een betere afstemming van het aanbod plaatsvinden op basis van cultuur en trends.','Roadmapping','877','inherit','closed','closed','','202-revision-v1','','','2022-01-31 09:35:40','2022-01-31 09:35:40','',202,'https://thingsway.media2netdev.nl/?p=331',0,'revision','',0),(332,1,'2022-01-31 09:35:40','2022-01-31 09:35:40','Inmiddels is het fenomeen Internet of Things (IoT) een ingeburgerd begrip geworden. Eigenlijk bestaat IoT al zolang data op afstand heen en weer gestuurd kan worden. Midden jaren negentig is door het mobiele netwerk de verdere basis gelegd voor IoT, alleen was dat toen beter bekend als Machine to Machine (M2M) communicatie. Door de opkomst van het internet met IP-standaardisatie, maar ook in combinatie met de opkomst van mobiele netwerken, heeft de Internet of Things een grote vlucht genomen. Wij vinden het nu heel normaal overal ter wereld met ons mobieltje, tablet of laptop onderling te communiceren en data te versturen, waar en wanneer wij maar willen. IoT ontwikkelt zich op dezelfde manier, alleen gaat het daarbij niet om smartphones of tablets maar om objecten, sensoren, producten, machines etc. Binnen het wereldwijde mobiele netwerk zijn speciale frequentiebanden voor objecten (things) gereserveerd, zodat geprofiteerd kan worden van de bestaande bewezen infrastructuur. IoT via het mobiele netwerk lift dus automatisch mee met bijvoorbeeld de volgende stap van 4G naar 5G. Een ander fenomeen waardoor IoT een vlucht heeft genomen zijn de ontwikkelingen binnen de elektronica-industrie. De eerste voorloper van de transistor, de elektronenbuis, zag zijn introductie al in 1907. In 1947 is de eerst werkende transistor in Bell labs gerealiseerd. De transistor is weer de basis voor IC integrated circuits, in de volksmond ook wel chips genoemd. IC’s worden in vele elektronische producten gebruikt als bijvoorbeeld computers, smartphones maar ook thermostaten, automobielen etc. Volgens de wet van Moore verdubbelt het aantal transistors per mm<sup>2</sup> elk jaar. Wat wij daar van merken is dat computers en elektronische producten steeds krachtiger worden met een toenemende geheugencapaciteit. Ter illustratie, een gemiddelde iPhone heeft 100.000 meer rekenkracht dan de ruimtecapsule Apollo 11 uit 1969. Naast een toenemende rekenkracht, zijn de IC’s ook steeds energiezuiniger geworden, waardoor systemen steeds langer op batterijen autonoom kunnen functioneren of door zonnecellen gevoed kunnen worden. Elektronica wordt zelfs zo zuinig dat sensorsystemen gevoed kunnen worden met energie uit de omgeving<ins cite=\"mailto:Emma%20Tuininga\" datetime=\"2020-03-20T11:33\">,</ins> zoals RF-straling, thermo energie of licht. Deze technologie zal de komende jaren doorzetten en IoT nog meer een boost geven.','IoT: oude wijn in nieuwe zakken.','988','inherit','closed','closed','','203-revision-v1','','','2022-01-31 09:35:40','2022-01-31 09:35:40','',203,'https://thingsway.media2netdev.nl/?p=332',0,'revision','',0),(333,1,'2022-01-31 09:35:41','2022-01-31 09:35:41','<strong>Ons eigen platform, The ThingsWay</strong>\n\nAl onze ervarin<img class=\"alignright\" src=\"https://www.sallandelectronics.nl/assets/media/logothingsway-v0-2.png\" alt=\"\" width=\"386\" height=\"135\" />gen van de afgelopen jaren hebben wij geïnventariseerd en deze hebben geleid tot een eigen platform voor IoT. <strong>Salland</strong>Electronics brengt dit op de markt onder de naam ThingsWay. The ThingsWay is een samentrekking van Things en Gateway en combineert diverse sensoren, in- en uitgangen met directe communicatie naar het mobiele netwerk. Hierdoor is een gateway overbodig. Bedrijven kunnen heel snel aan de slag met IoT en ons streven is<ins cite=\"mailto:Emma%20Tuininga\" datetime=\"2020-03-20T12:11\">: </ins>“<em>connected in one day”</em>. De ThingsWay is snel aan te passen aan de wensen en eisen van de klant. Als basis is een print ontwikkeld dat modulair uitbreidbaar is. Deze basisprint kan in een eigen behuizing ingezet worden, maar is ook beschikbaar in verschillende uitvoeringen Zo is er als eerste variant een waterdichte uitvoering voor buiten applicaties. Er is ook een Industriële uitvoering beschikbaar voor DIN-rail montage met veel meer aansluitmogelijkheden. Uniek is dat de ThingsWay vanuit de basis opzet energiezuinig is ontworpen waardoor jarenlange werking op een batterij gegarandeerd is. Tot ons dienstenpakket hoort ook het regelen van de SIM’s voor datacommunicatie. De door <strong>Salland</strong>Electronics geleverde SIM<ins cite=\"mailto:Emma%20Tuininga\" datetime=\"2020-03-20T13:21\">’</ins>s zijn een multi-provider<ins cite=\"mailto:Emma%20Tuininga\" datetime=\"2020-03-20T13:21\">,</ins> waardoor de bereikbaarheid en kosten zo gunstig mogelijk zijn voor de klant. Op deze manier hebben wij grip op het communicatie pad vanaf de cloud tot en met de ThingsWay. Voor dataverwerking en visualisatie in een cloud omgeving werken wij samen met Docksters<ins cite=\"mailto:Emma%20Tuininga\" datetime=\"2020-03-20T13:21\">,</ins> onderdeel van X-ICT uit Zwolle. Met dit totaalpakket is <strong>Salland</strong>Electronics in staat de complete keten van cloud tot en met connectiviteit voor een klant te verzorgen.','Het IoT platform ThingsWay','996','inherit','closed','closed','','204-revision-v1','','','2022-01-31 09:35:41','2022-01-31 09:35:41','',204,'https://thingsway.media2netdev.nl/?p=333',0,'revision','',0),(334,1,'2022-01-31 09:35:42','2022-01-31 09:35:42','Bijna alles waar we mee werken, of dagelijks mee te maken hebben, heeft onderhoud nodig. Dat gaat niet alleen om uw huis of auto, dat gaat ook om wegen, koffiezetapparaten op het werk en draaideuren bij een winkel.\n\nHet is daarom niet vreemd dat er veel bedrijven bestaan in maintenance en onderhoud. Heeft u ook zo’n bedrijf, of werkt u bij een bedrijf die aan maintenance doet? De kans is dan groot dat u van tijd tot tijd tegen bepaalde problemen aanloopt die helaas regelmatig terugkomen. Voor deze pijnpunten zou toch een oplossing zou moeten zijn?\n<h2>De problemen van maintenance en onderhoud</h2>\nNeem als voorbeeld dat u bedrijfsleider bent van een woningcorporatie; deze corporatie verhuurt appartementen aan particulieren. Die appartementencomplexen hebben periodiek onderhoud nodig, zoals bijvoorbeeld het dak of de dakgoten. Daarom laat u één keer in de zoveel tijd de goten nakijken. Dit levert u kosten op aan mankracht, maar ook aan eventueel materiaal. Toch blijkt onderhoud niet altijd nodig te zijn.\n\nOp andere momenten blijkt dat u te laat bent met maintenance aan de goten. Dan blijken ze eerder dan verwacht dicht geslipt te zijn met vuil en bladeren. Dit heeft gezorgd voor een overstroming en schade aan de regenpijp en het dak. Dit is niet slechts bij één appartementencomplex gebeurt, maar bij maar liefst 5 complexen. Het resultaat; u heeft een enorme piek in uw agenda en flinke onverwachte kosten wat schade betreft.\n\nDit is slechts een voorbeeld van een probleem waar een bedrijf, dat aan onderhoudsdienstverlening doet, tegen aan kan lopen. Over het algemeen liggen deze problemen op gebied van onverwachte pieken in de agenda en kosten. Wilt u meer controle hebben op uw kosten en uw planning? Dan is er voor u nu een oplossing ontwikkeld; zijn naam is De Thingsway.\n<h2>Wat is De Thingsway?</h2>\nDe Thingsway is een sensor die op de markt gebracht is door Salland Electronics. De naam komt voort uit een samenvoeging van Things en Gateway. Het is een Internet of Things product waarin diverse sensoren gecombineerd worden met in- en uitgangen die zorgen voor een directe verbinding met een mobiel netwerk. Dit zorgt ervoor dat een gateway overbodig is.\n\nDe Thingsway is een basisproduct dat snel aan te passen is op de activiteiten en wensen van uw bedrijf. Daarmee kunt u razendsnel aan de slag. Dit basisproduct kan natuurlijk in een eigen behuizing geplaatst worden, maar er zijn meerdere uitvoeringen mogelijk. De eerste variant van The Thingsway is geplaatst in een waterdichte behuizing, waardoor deze buiten gebruikt kan worden, zoals in regenpijpen. Het berekent daarmee de doorstroom van regen, waardoor eventuele verstoppingen vroeg geconstateerd kunnen worden. Dit is één van de voorbeelden van de mogelijkheden van de Thingsway.\n\nEen industriële uitvoering is tevens beschikbaar. Deze is geschikt voor zogenaamde DIN-rail montage en is voorzien van meer aansluitmogelijkheden.\n\nWat uniek is aan de Thingsway is dat het product energiezuinig ontworpen is. De energie komt van een batterij die jarenlange werking (10 jaar) garandeert.\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"voordelen thingsway\" width=\"416\" height=\"294\" />\n<h2>Wat zijn de voordelen van de Thingsway?</h2>\nBehalve dat het een energiezuinig product is, kan de Thingsway u als bedrijf veel voordelen opleveren wat betreft onderhoud en maintenance. Heeft u een bedrijf in onderhoudsdienstverlening en maintenance en wilt u de kosten hiervan reduceren? De Thingsway kan u daarbij heel goed van dienst zijn.\n\nZoals eerder genoemd liggen de pijnpunten voor bedrijven die doen aan maintenance in het feit dat u van te voren niet weet waar of wanneer zich problemen gaan voordoen. Denk dan aan regenpijpen die verstoppen, of koffiezetapparaten die vastlopen doordat een buis vastgelopen is. Deze problemen zorgen niet alleen voor schade en de nodige kosten, ze zorgen er ook voor dat periodieke controle nodig is, ook al is onderhoud misschien niet vereist.\n\nDoor het continue meten van een bepaalde doorstroom of druk middels bepaalde sensoren, kunt u monitoren waar en wanneer maintenance wel vereist is. Dit scheelt u kosten in schade en manuren, maar ook in ongewenste pieken in uw agenda. De Thingsway kunt u daarmee ook zien als een preventief onderhoudsproduct. Door het analyseren van de metingen kunt u tevens in de toekomst onderhoud beter plannen.\n\nSalland Electronics regelt voor u ook de SIM’s voor communicatie van data. Deze SIMS’s zijn zogenaamde Multi providers, dit garandeert de bereikbaarheid en zorgt voor gunstige kosten. Dit totaalpakket met Thingsway, Cloud en connectiviteit zorgt ervoor dat Salland Electronics u een ideaal totaalpakket kan bieden.\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>','De voordelen van Thingsway in maintenance en onderhoud','1532','inherit','closed','closed','','205-revision-v1','','','2022-01-31 09:35:42','2022-01-31 09:35:42','',205,'https://thingsway.media2netdev.nl/?p=334',0,'revision','',0),(335,1,'2022-01-31 09:35:42','2022-01-31 09:35:42','Wanneer u eigenaar of manager bent van een bedrijf of instelling, dan is de kans groot dat u regelmatig te maken heeft met periodiek onderhoud. Het kan ook zijn dat u werkt in een branche waar maintenance een belangrijk onderdeel is van uw werkzaamheden.\n\nHet nadeel van periodiek onderhoud is dat het concept gebaseerd is op voorspellingen. Hoe lang zal een machine of object mee gaan? Wanneer moet een bepaald onderdeel van een machine vervangen worden? Om de hoeveel tijd moet er onderhoud gepleegd worden aan een dakgoot? De planning van deze werkzaamheden wordt bepaald door richtlijnen van fabrikanten aan te houden, door zelf te experimenteren en door middel van onderhoudsgegevens uit het verleden van de machine of het object.\n\nHet analyseren van al deze gegevens bepalen mede de interval tussen tijdsstippen van periodiek onderhoud. De werking van een machine/object wordt als het ware gemonitord. Dit monitoren gebeurt echter op bepaalde momenten en wordt uitgevoerd door een persoon. Het zou veel effectiever zijn wanneer een bepaalde machine continu gemonitord wordt. Niet door een persoon, want dat zou veel kosten met zich meebrengen. Nee, door middel van een apparaat, die metingen uitvoert en deze bovendien verwerkt in bepaalde data. Door middel van het analyseren van deze data kunt u een veel beter beeld krijgen van de werking en eventuele te verwachte storing. Dit zou uw bedrijf de ideale mogelijkheid geven om kosten te reduceren. Die mogelijkheid bestaat door middel van een IoT-oplossing.\n<h2>Internet of Things -oplossingen</h2>\nDe Internet of Things (IoT) wordt gezien als de next step in technologie. Het helpt ondernemers, bedrijven en branches om niet alleen efficiënter te werken, maar ook veiliger en duurzamer. Door het continu monitoren van objecten krijgt u meer informatie en daarmee inzichten. Dit kan u helpen om onderhoud gerichter te plannen, maar ook om schade en storingen te voorkomen.\n\nDe onderliggende gedachte van IoT is dat er meer machines, producten of objecten aan het internet zijn aangesloten dan mensen. Deze machines krijgen dus een internetverbinding, waardoor ze op afstand gemonitord kunnen worden.\n<h2>Hoe gaat monitoren op afstand in zijn werk?</h2>\nIn de Internet of Things wereld wordt veel gebruik gemaakt van sensoren. Een apparaat met sensoren wordt aangebracht op een machine of object. Deze sensoren doen continu metingen, dit wordt omgezet in data. Doordat het apparaat met sensoren ook voorzien is van een internetconnectie, kan deze data onmiddellijk verstuurd worden.\n\nDe gegevens kunnen daardoor op afstand bekeken worden op een smartphone, computer of tablet. De internetconnectie kan worden verkregen via verschillende netwerken. Ieder Internet of Things bedrijf geeft u daar verschillende mogelijkheden in.\n\nVerkoopt of verhuurt uw bedrijf bijvoorbeeld volautomatische koffiemachines voor bedrijven? Misschien verzorgt u daar dan ook het onderhoud voor? Koffiemachines hebben enorm veel onderhoud nodig, daar bent u als geen ander van op de hoogte. Het vullen van de bekers, koffie, melk, suiker etc. vergt al vaak dagelijkse aandacht, dat valt over het algemeen te plannen. Schade of uitval valt moeilijker te voorspellen en te plannen, behalve wanneer er sensor wordt geplaatst in de machine. Dit kunt u bijvoorbeeld doen op een buis die regelmatig voor problemen zorgt. Sensoren meten de doorstroming, data wordt doorgestuurd, en constante monitoring op afstand geeft u een beter inzicht in de werking van de machine. Hierdoor kunt u in de toekomst uitval en schade voorkomen.\n\nDit is slechts één voorbeeld van monitoren op afstand.\n<h2>De Thingsway, een maatwerksensor voor uw bedrijf</h2>\nEen voorbeeld van een Internet of Things-sensor is de Thingsway. Dit is een sensor die ontwikkeld is door Salland Electronics, een Internet of Things-bedrijf gevestigd in Zwolle. Het grote voordeel van de Thingsway is zijn multifunctionaliteit; het is namelijk een sensor die op veel manieren in te zetten is.\n\nDe Thingsway kan worden aangepast op de specialistische activiteiten van uw bedrijf, daarmee krijgt u een maatwerksensor in handen. Het maatwerk wat vooraf gedaan moet worden gaat onder andere om de manier van installeren. Een sensor op een machine in een fabriekshal heeft nu eenmaal een andere bevestiging nodig dan een sensor boven een draaideur. En zo geldt dat voor alle objecten of machines. Het overige maatwerk gaat om de verschillende soorten sensoren; verschillende processen vragen om verschillende sensoren. Dit maatwerk kan echter door Salland Electronics razendsnel gedaan worden. Zo kunt u in no-time gebruik maken van monitoren op afstand.\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"voordelen thingsway\" width=\"416\" height=\"294\" />\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>','Monitoren op afstand','1549','inherit','closed','closed','','207-revision-v1','','','2022-01-31 09:35:42','2022-01-31 09:35:42','',207,'https://thingsway.media2netdev.nl/?p=335',0,'revision','',0),(336,1,'2022-01-31 09:35:43','2022-01-31 09:35:43','Misschien zijn we ons er niet meer van bewust, maar onze maatschappij draait op machines. Van het moment dat ’s morgens je wekker gaat, tot je weer naar bed gaat; de hele dag hebben we met machines te maken. Koffiezetter, verwarmingsketel, auto’s, bussen, liften, roltrap, brug over de snelweg, televisie; de hele dag lang werken er machines om ons heen. We zijn er grotendeels afhankelijk van. Deze machines hebben allemaal onderhoud nodig om een goede werking te garanderen.\n\nNiet alleen machines hebben regelmatig onderhoud nodig, ook gebouwen, wegen en zelfs ons lijf kan soms best een onderhoudsbeurt gebruiken. We zitten niet voor niets regelmatig bij de tandarts, toch? Alles is nu eenmaal aan slijtage onderhevig, dat valt niet te vermijden. We weten echter helaas nooit precies wanneer onderhoud nodig is. Vaak zijn we te laat, en is er een gaatje in een kies ontstaan, of een tand afgebroken. Dat is de reden waarom er regelmatig periodiek onderhoud uitgevoerd wordt, vaak door mensen of bedrijven die daar gespecialiseerd in zijn. Maar ook voor zo’n bedrijf zou het heel handig kunnen zijn om onderhoud voorspelbaar te maken.\n<h2>Maintenance en onderhoud voorspelbaar maken</h2>\nNeem als voorbeeld dat u bedrijfsleider bent van een onderhoudsbedrijf, dat aan liftonderhoud doet. Deze hebben periodiek onderhoud nodig, zodat mensen gebruik kunnen maken van een werkende en betrouwbare lift. Dit is de reden waarom u één keer in de zoveel tijd een bepaalde lift aan een controle onderwerpt. Dit zorgt voor kosten aan mankracht, maar mogelijk ook aan materiaal. Onderhoud is echter niet altijd nodig wanneer deze periodiek wordt uitgevoerd.\n\nHet kan ook zijn dat u te laat bent met het onderhouden van een bepaalde lift. Dan is de lift uitgevallen, of er zitten bijvoorbeeld mensen vast. Op zo’n moment kan er geen gebruik gemaakt worden van deze lift. Dit kan erg vervelend zijn voor de bewoners van een flat, denk bijvoorbeeld eens aan oudere bewoners van een bejaardenhuis. Hier biedt u service voor, en daar bestaat uw bedrijf voor, maar het vraagt wel om veel flexibiliteit, een piek in uw agenda, de nodige mankracht en natuurlijk bijkomende schadekosten.\n\nHier wordt slechts een voorbeeld gegeven van de problemen waar een bedrijf tegen aan kan lopen. Of u nu een bedrijf heeft dat doet aan onderhoudsdienstverlening, of u bent bedrijfsleider van een bedrijf die veel met machines te maken heeft; u heeft er ongetwijfeld regelmatig mee te maken. Het zou toch heel handig voor u zijn wanneer er een apparaat zou bestaan dat aan voorspellend onderhoud doet? Welnu, dat apparaat bestaat, het heet de Thingsway.\n<h2>Wat is De Thingsway?</h2>\nDe basis van De Thingsway is een product voorzien van verschillende sensoren in een behuizing. De eerste variant van de Thingsway heeft een waterdichte behuizing, hierdoor kan het gebruikt worden in situaties in de buitenlucht. Denk dan aan bijvoorbeeld het meten van de doorstroming van dakgoten en regenpijpen. Door deze doorstroming continu te meten kan er op tijd ingegrepen worden wanneer deze doorstroming minder wordt. Dit is een teken dat de dakgoot vervuild is geraakt, waardoor de doorstroom minder wordt. Onderhoud is nu nodig en kan op dit moment gepland worden. Dit is slechts een voorbeeld van de mogelijkheden van de Thingsway.\n\nDe Thingsway is een sensor dat snel aan te passen is op alle wensen en activiteiten van uw bedrijf. Zo bestaat er ook een variant die geschikt is voor industrieel gebruik. Heeft u een bedrijf dat veel te maken heeft met onderhoud en maintenance? Of maakt u in uw bedrijf veel gebruik van machines? Dan is de Thingsway een oplossing in voorspellend onderhoud voor u.\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"voordelen thingsway\" width=\"416\" height=\"294\" />\n<h2>Voorspellend onderhoud met de Thingsway</h2>\nDe Thingsway is op de markt gebracht door Salland Electronics, een bedrijf werkzaam in Internet of Things oplossingen. De naam Thingsway is een samenvoeging van Things en Gateway. Het product Thingsway is een letterlijke samenvoeging van een IOT oplossing gecombineerd met een gateway. Het product is voorzien van in- en uitgangen die een directe verbinding met een mobiel netwerk mogelijk maken. Hierdoor bevat het product diverse sensoren en bovendien een eigen gateway.\n\nDoor het continu meten van een bepaalde doorstroom of druk middels bepaalde sensoren, monitort de Thingsway waar en wanneer maintenance vereist is. Dit kunt u zien als voorspellend onderhoud en maakt periodiek onderhoud onnodig. Dit kan flink wat kosten schelen, in manuren, maar ook in schade. Niet alleen dat, maar het scheelt u ook ongewenste pieken in uw agenda. Daarmee kunt u de Thingsway zien als een voorspellend en preventief onderhoudsproduct. In de toekomst kunt u het nodige onderhoud eenvoudig plannen door het analyseren van de metingen.\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>','Voorspellend onderhoud','1552','inherit','closed','closed','','209-revision-v1','','','2022-01-31 09:35:43','2022-01-31 09:35:43','',209,'https://thingsway.media2netdev.nl/?p=336',0,'revision','',0),(337,1,'2022-01-31 09:35:44','2022-01-31 09:35:44','De wereld draait tegenwoordig grotendeels op computers en machines. Dit zou een ideale combinatie kunnen zijn wanneer u een bedrijf heeft dat veel met machines werkt, of een bedrijf dat aan maintenance doet. Het nadeel van machines is dat ze altijd op een moment uitvallen wanneer u dat niet kunt gebruiken. Dan zijn er weer mensenhanden nodig, en de onvermijdbare kosten om deze uitval op te lossen.\n<h2>De gevolgen van uitval voor uw bedrijf</h2>\nDe gevolgen van uitval kunnen voor uw bedrijf groot zijn. Dit is afhankelijk van wat de schade is, welke machine ermee opgehouden is en hoe snel het te herstellen is. Tot die tijd zou bijvoorbeeld uw productie stil kunnen liggen, kunnen bewoners niet hun appartement in, of blijft een brug of weg afgesloten.\n\nDit vergt veel flexibiliteit van uw bedrijf en werknemers, het zorgt voor een grotere belasting op uw werknemers en bovendien kunnen de kosten van deze uitval wel eens flink oplopen. Het kan zijn dat iets simpel op te lossen is, maar over het algemeen valt schade altijd tegen. Soms is het zelfs nodig een compleet nieuwe machine aan te schaffen.\n<h2>Hoe kunt u uitval voorkomen?</h2>\nOver het algemeen wordt uitval van machines, productie of service voorkomen door periodiek onderhoud. Deze wordt één keer in de zoveel tijd uitgevoerd, daar weet u alles van als u in de maintenance zit of als u een bedrijf heeft die een onderhoudsbedrijf inhuurt.\n\nOnderhoud wordt in deze gevallen standaard uitgevoerd, soms is dit nodig, maar niet altijd. Het nadeel van maintenance is dat het plannen van onderhoud moeilijk is; uitval valt maar lastig te voorspellen. Zou het geen oplossing voor uw bedrijf zijn als de werking of doorstroming continue gemonitord wordt? Gelukkig bestaat die oplossing sinds kort, zijn naam is de Thingsway.\n<h2>Wat is de Thingsway?</h2>\nSalland Electronics heeft een sensor op de markt gebracht met de naam Thingsway. De naam is een samenvoeging van Things en Gateway. Salland Electronics werkt aan IOT oplossingen voor bedrijven, de Thingsway is één van deze oplossingen. Dit kan een uitkomst zijn wanneer u regelmatig te maken heeft met uitval. De Thingsway is een product waarin meerdere sensoren een combinatie vormen met in- en uitgangen. Deze in- en uitgangen zorgen voor een directe verbinding met een mobiel netwerk. Daardoor is een extra gateway overbodig.\n\nDe Thingsway sensor is een basisproduct dat snel is aan te passen zodat het geschikt is voor metingen waar u deze wenst. Zodoende kunt u snel voorzien zijn van een Thingsway. De basis Thingsway heeft een eigen behuizing, maar het kan in vele uitvoeringen worden geplaatst. De eerste Thingsway zit in een waterdichte behuizing, omdat deze gebruikt wordt bij metingen in de buitenlucht, zoals het monitoren van de doorstroming van regenwater.\n\nMaar de Thingsway is tevens heel goed inzetbaar in de industriële markt. Er is namelijk ook een industriële uitvoering beschikbaar. Deze is geschikt gemaakt voor zogenaamde DIN-rail montage en heeft meer aansluitmogelijkheden.\n\nHet energiezuinige ontwerp is uniek aan de Thingsway. De energie wordt geleverd door een Li-SOCL2 AA batterij die een 100% dekking over 10 jaar garandeert.\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\n<h2>Wat kan de Thingsway voor uw bedrijf betekenen?</h2>\nHeeft u een bedrijf dat regelmatig te maken heeft met uitval van machines, diensten of service? Dit wilt u toch het liefst voorkomen? Dit kan door het continue monitoren van bepaalde objecten die gevoelig kunnen zijn voor uitval of schade. De Thingsway meet een bepaalde doorstroom of druk door middel van meerdere sensoren. Zodoende kunt u monitoren waar en ook wanneer onderhoud gewenst is. Voorkomen is beter dan genezen. Dit kan u veel uitval schelen, verlaagt uw kosten en verhoogt uw flexibiliteit. De Thingsway kan gezien worden als een soort preventief onderhoudsproduct. In de toekomst kunt u de maintenance en de te verwachtte kosten plannen door middel van het analyseren van de metingen.\n\nSalland Electronics kan u een ideaal totaalpakket bieden met de Thingsway, Cloud en connectiviteit. Salland Electronics regelt namelijk voor u ook de zogenaamde SIMS’s voor communicatie van data. Dit zijn Multi providers, de bereikbaarheid wordt hierdoor gegarandeerd en het houdt de kosten gunstig.\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>','Uitval voorkomen in uw bedrijf?','1555','inherit','closed','closed','','211-revision-v1','','','2022-01-31 09:35:44','2022-01-31 09:35:44','',211,'https://thingsway.media2netdev.nl/?p=337',0,'revision','',0),(338,1,'2022-01-31 09:35:46','2022-01-31 09:35:46','Alles om ons heen slijt of is aan onderhoud onderhevig. Van sommige apparaten accepteren we dat, dan kopen we gewoon een nieuwe. Niet alles is echter snel, eenvoudig en goedkoop te vervangen. Dit is de reden waarom we bijvoorbeeld bepaalde dingen in en aan ons huis regelmatig onderhouden, zoals de verwarmingsketel, de kozijnen en de dakgoot. Soms doen we dit zelf, maar vaak laten we het ook uitbesteden aan gespecialiseerde onderhoudsbedrijven. Deze bedrijven voeren dan periodiek onderhoud uit.\n\nHeeft u een bedrijf in onderhoud en maintenance? Werkt u voor een bedrijf dat veel gebruik maakt van machines? Of heeft uw bedrijf regelmatig te maken met het nodige onderhoud, zoals bijvoorbeeld een woningcorporatie? Dan zult u waarschijnlijk erkennen dat periodiek onderhoud nuttig is, maar niet de absolute oplossing biedt bij het voorkomen van schade door slijtage. Continue monitoring zou een effectiever middel zijn.\n<h2>De nadelen van periodiek onderhoud</h2>\nDe nadelen van periodiek onderhoud liggen in de kosten voor mankracht, en in het feit dat nuttig onderhoud maar moeilijk te plannen is. Eigenlijk weten we nooit wanneer er schade zal ontstaan, of wanneer een machine ermee op zal houden. Periodiek onderhoud wordt uitgevoerd om schade voor te zijn, door bijvoorbeeld preventief bepaalde onderdelen te vervangen, door iets schoon te maken, of om eventuele slijtage vast te stellen. Dit, door mensenhanden uitgevoerd onderhoud, is een middel wat tot een bepaalde hoogte effectief is. Want schade komt vaak onverwacht, en soms worden onderdelen onnodig vervangen. Helaas valt niet alles te voorspellen zonder constante gegevens, dit kan zorgen voor hoge en onverwachte kosten.\n\nHet zou echter veel effectiever werken wanneer een apparaat of een proces continu gemonitord wordt.\n<h2>De voordelen van continue monitoring</h2>\nContinue monitoring van een machine, apparaat of een bepaald proces zorgt ervoor dat er op tijd kan worden ingegrepen wanneer dit nodig is. Zodoende is de kans groter dat eventuele schade voorkomen kan worden.\n\nPeriodiek onderhoud wordt ingezet omdat het onmogelijk is om alles in de gaten te blijven houden door mankracht. Dat zou immers een enorme kostenpost opleveren. Wanneer je continue monitoring zou kunnen inzetten door middel van een apparaat, of een sensor, dan zou dit u enorm in de kosten schelen voor periodiek onderhoud en eventuele onverwachte schade.\n<h2>Continue monitoring met de Thingsway</h2>\nDe Thingsway is een Internet of Things product, geproduceerd door Salland Electronics. Door het constant meten van een bepaalde druk of doorstroom, monitort het product of onderhoud nodig is. Deze continue monitoring zorgt dus voor een soort voorspellend onderhoud, dit maakt periodiek onderhoud zo goed als onnodig. Dit is aantrekkelijk voor ieder bedrijf dat te maken heeft met regelmatig maintenance, of dat nu is aan machines, gebouwen of apparaten.\n\nDe Thingsway is een product dat is voorzien van bepaalde sensoren in een bepaalde behuizing. De eerste Thingsway heeft een waterdichte variant, hierdoor kan deze buiten gebruikt worden. Op dit moment wordt het ingezet in dakgoten van gebouwen. Door deze doorstroming constant in de gaten te houden kan er onderhoud gedaan worden wanneer nodig. Wanneer de dakgoten vervuild zijn geraakt zal de doorstroming verminderen. Dit zal door de verschillende sensoren opgepikt worden en middels data en een gateway gecommuniceerd worden. Onderhoud kan nu gepland en gepleegd worden. Dit is een van de voorbeelden van hoe de Thingsway in te zetten is.\n\nDe Thingsway is een zogenaamd basisproduct. Vanuit deze basis is de Thingsway snel aan te passen met sensoren (en eventueel behuizing) die het best geschikt zijn voor continue monitoring bij uw bedrijf. Uw wensen en activiteiten bepalen uw Thingsway, daarmee is de Thingsway een zeer flexibel en snel in te zetten IOT product. Ook voor gebruik op industrieel gebied bestaat er een Thingsway variant. Deze is voorzien van meerdere aansluitmogelijkheden en is geschikt voor zogenaamde DIN-rail montage.\n\nDe Thingsway is een energiezuinig ontworpen product. De energie komt van een Li-SOCL 2 AA batterij die zorgt voor 100% dekking over een periode van maar liefst 10 jaar.\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\n<h2>Een totaalpakket bij Salland Electronics</h2>\nVoor communicatie van data regelt producent Salland Electronics voor u de SIM’s. Dit zijn Multi providers die zorgen voor bereikbaarheid. Middels dit totaalpakket, inclusief Thingsway, Cloud en connectiviteit, heeft u een ideaal totaalpakket tegen gunstige kosten.\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>\n&nbsp;','De voordelen van continue monitoring','1558','inherit','closed','closed','','213-revision-v1','','','2022-01-31 09:35:46','2022-01-31 09:35:46','',213,'https://thingsway.media2netdev.nl/?p=338',0,'revision','',0),(339,1,'2022-01-31 09:35:47','2022-01-31 09:35:47','Het IOT (Internet of Things) bedrijf Salland Electonics heeft een product ontwikkeld die u voortaan kan helpen met het voorkomen van schade. Dit product heeft de naam Thingsway gekregen. Het werkt door middel van sensoren die constant een bepaald proces in de gaten kan houden.\n\nDit product kan een ideale oplossing zijn voor veel verschillende soorten bedrijven, instanties en corporaties.\n<h2>Voor welke bedrijven is de Thingsway aantrekkelijk?</h2>\nDe Thingsway kan een heel aantrekkelijk product zijn voor bedrijven die veel te maken hebben met onderhoud (of maintenance). Denk daarbij aan bedrijven die onderhoudsdiensten aanbieden, zoals bijvoorbeeld machineonderhoud, koffiemachine-onderhoud en onderhoud van liften of roltrappen. Ook bedrijven die veel met machines werken hebben zeer regelmatig te maken met onderhoud alsmede schade.\n\nAndere instanties die veel aan onderhoud doen zijn woningcorporaties. Het onderhouden van gebouwen is nu een doorgaand proces. Waar gewoond wordt, wordt geleefd en daar vind logischerwijs slijtage plaats.\n\nDit zijn slechts enkele voorbeelden van bedrijven die veel te maken hebben met maintenance en onderhoud. Wat deze bedrijven verder gemeen hebben is het feit dat ze van tijd tot tijd te maken hebben met schade. Deze schade kan de nodige gevolgen hebben voor uw bedrijf.\n<h2>Gevolgen van schade</h2>\nDe gevolgen van schade zijn op het oog duidelijk. Er is een defect opgetreden in een proces, een machine werkt niet meer, een dak is lek, of een draaideur gaat niet meer open. Zo’n verstoring van een proces moet verholpen worden door middel van onderhoud. Dat zorgt ten eerste voor kosten in mankracht, de persoon die het probleem gaat verhelpen moet immers betaald worden.\n\nTen tweede zorgt het voor kosten in het verhelpen van het probleem. Soms gaat het slechts om een klein probleem, maar het zal ook regelmatig voorkomen dat de schade groter is. Dan moet er bijvoorbeeld een duur onderdeel vervangen worden, of er moet een gehele nieuwe machine aangeschaft worden. Dit zijn bijkomende schadekosten die u toch liever zou willen vermijden.\n\nSchade staat helaas bijna nooit op zichzelf. Vaak gaat het nooit om één onderdeel dat defect is geraakt. Wanneer een proces verstoort wordt door een defect dan heeft dit vaak effect op het gehele systeem. Als voorbeeld kunt u denken aan een dakgoot, wanneer deze verstopt raakt dan zal er een overstroming ontstaan. Dit zal niet alleen voor schade zorgen aan de goot of regenpijp, maar mogelijk ook aan het dak, of misschien zelfs wel aan het interieur van bewoners.\n\nAndere gevolgen van schade zijn misschien minder zichtbaar, maar zijn wel degelijk aanwezig. Heeft u een bedrijf dat veel met machines werkt, dan zal een defecte machine negatieve gevolgen hebben op het productieproces. Tevens zijn er gevolgen voor de belasting van andere machines, maar ook werknemers.\n\nEen ander minder zichtbaar gevolg van schade zijn de hoge kosten voor verzekeringen alsmede het aangaan van contracten voor maintenance en onderhoud. Maintenance en periodiek onderhoud is op dit moment namelijk de manier om schade te voorkomen. Maar het kan anders, beter en eenvoudiger.\n<h2>Schade voorkomen door middel van de Thingsway</h2>\nDe Thingsway is misschien wel de manier om schade te voorkomen. Via sensoren houdt de Thingsway een bepaald proces in de gaten. Het kan dan gaan om de doorstroom van een buis, hoeveel bezoekers er door een winkeldeur lopen, of de afvoer van water door een sluis. De sensoren in de Thingsway, en tevens zijn behuizing, zijn heel snel aanpasbaar. Hierdoor kan het product voor zeer veel doeleinden gebruikt worden.\n\nHet voordeel van de Thingsway is dat deze een proces continu in de gaten houdt. Op zo’n manier wordt verstoring van een doorstroom onmiddellijk geconstateerd en kan mogelijke schade voorkomen worden.\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\n<h2>Continue monitoring</h2>\nHet nadeel van periodiek onderhoud zit al in de benaming: periodiek. Eén keer in de zoveel tijd wordt er een machine, een object of proces aan een controle onderworpen. Onderhoud wordt gedaan waar nodig; er wordt schoongemaakt, of de nodige onderdelen worden vervangen. Het valt echter maar moeilijk te voorspellen wanneer er schade zal ontstaan. Natuurlijk wordt er gelet op belemmering van een proces of eventuele slijtage, maar om uitval of schade te voorspellen is constante observatie nodig.\n\nDit is onmogelijk door middel van mankracht uit te voeren. Om iets continu te laten monitoren en bovendien via data inzicht te houden op het proces is een IOT oplossing nodig. Die IOT oplossing bestaat nu, het heet de Thingsway. De Thingsway kan voor veel verschillende bedrijven de oplossing zijn om schade te voorkomen, en daarmee kosten te reduceren.\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>','Schade voorkomen','1561','inherit','closed','closed','','215-revision-v1','','','2022-01-31 09:35:47','2022-01-31 09:35:47','',215,'https://thingsway.media2netdev.nl/?p=339',0,'revision','',0),(340,1,'2022-01-31 09:35:48','2022-01-31 09:35:48','Als u dit leest dan is de kans groot dat u de term monitoring kent. Kent u deze term niet, of bent u er nog vrij onbekend mee, dan is hier een eenvoudige uitleg:\n\nMonitoring is het proces waarbij een machine of apparaat connectie maakt met internet om gegevens te verzamelen en te interpreteren.\n\nBij IoT- oplossingen wordt veel gebruik gemaakt van monitoring. IoT staat voor Internet of Things, daarbij worden alledaagse dingen, zoals producten, of machines, met een internet connectie voorzien. Op zo’n manier kunnen deze op afstand gemonitord worden. Dit wordt gedaan om eventuele problemen voor te zijn, processen te verbeteren of machines up te daten.\n\nHeeft u zich wel eens afgevraagd hoe dit werkt? Hoe wordt er verbinding gemaakt met machines of sensoren? En hoe worden die gedeeld en geanalyseerd? Wat zijn die tools voor monitoring, en hoe werkt het in de praktijk?\n<h2>Integratie</h2>\nDe eerste stap bij monitoring is om een internetconnectie te leggen tussen uw machine en de meetapparatuur. IoT bedrijven maken vaak gebruik van zogenaamde gateway’s om deze connectie te kunnen leggen. Daarna kan het bedrijf verbinding leggen via wifi, ethernet, USB en / of mobiel.\n<h2>Data overdragen en opslaan</h2>\nNu er verbinding is gelegd met internet, is het tijd om de data over te dragen. Door de kracht van het internet stromen gegevens continu van een aangesloten machine naar een bepaalde externe server (beveiligd). Door deze data naar een server te sturen, kunt u toegang krijgen tot analytische gegevens, informatie, grafieken en rapporten.\n\n<img class=\"alignnone size-full wp-image-1417\" src=\"https://thingsway.nl/wp-content/uploads/2020/09/Screenshot-2019-11-14-at-15.28.28.png\" alt=\"monitoren onderhoud \" width=\"3814\" height=\"2108\" />\n<h2>Gegevens kunnen worden weergegeven</h2>\nU kunt de gegevens inzien en analyseren, maar u zou ze ook bijvoorbeeld op de werkvloer kunnen weergeven. De gegevens kunt u weergeven via computers, een monitor of zelfs via smartphones en tablets.\n<h2>Productieverhoging</h2>\nDoor de gegevens in realtime aan uw werknemers te laten zien, krijgen uw medewerkers meer inzicht in de machines waarmee ze dagelijks werken. Hierdoor kunnen ze eerder ingrijpen in geval van een storing of onverwacht probleem. Maar het kan ook goed werken om de efficiëntie en productie te verhogen.\n<h2>Het analyseren van gegevens</h2>\nEen IoT oplossing biedt u de mogelijkheid om zowel realtime gegevens in te zien, maar ook gegevens en rapportage uit het verleden. Hierdoor kunnen managers of supervisors ter plekke de gegevens analyseren om betere en weloverwogen beslissingen te nemen.\n<h2>Meer productie, efficiëntie en kosten reductie</h2>\nDe productie en efficiëntie zal naar verwachting toenemen wanneer u de mogelijkheid heeft om de prestaties van machines of objecten te monitoren en analyseren. U kunt beslissingen nemen die gebaseerd zijn op data, niet op gevoel of verwachtingen. Zo kunt u bijvoorbeeld werktijden verbeteren, onderhoud beter plannen, uitvaltijd beperken, en nauwkeurigere offertes maken. Bovendien kunt u schade beperken, dit zal de kosten reduceren en bovendien de productie verhogen.\n\nDit is hoe monitoring van machines of van een bepaald object werkt via een IoT oplossing. Nu kunt u zich nog afvragen hoe deze metingen worden gedaan? Waar komen de gegevens vandaan? Bij tools die ingezet worden voor monitoring wordt veel gebruik gemaakt van verschillende sensoren.\n<h2>De Thingsway</h2>\nEen mooi voorbeeld van een tool voor monitoring is de Thingsway. Dit is een product van Salland Electronics. De Thingsway is ontwikkeld om verschillende metingen mee te kunnen doen, bijvoorbeeld hoeveel mensen er door een deur lopen of hoeveel water er afgevoerd wordt. Dit wordt gedaan via sensoren, deze zijn aan te passen op het bedoelde gebruik van de Thingsway. Bepaalde details van de basis Thingsway kunnen worden aangepast, zodat deze ingezet kan worden om specifieke metingen bij uw bedrijf vast te leggen.\n\nHet grootste voordeel van de Thingsway is dat deze details snel kunnen worden toegepast. Zodoende kunt u binnen zeer korte tijd een IoT oplossing voor uw bedrijf in handen hebben.\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\n<h2>Voor wat voor bedrijven is de Thingsway aantrekkelijk?</h2>\nDe Thingsway is zeer aantrekkelijk voor branches en bedrijven die veel te maken hebben met onderhoud. Denkt u dan aan bedrijven die aan onderhoudsdienstverlening doen, bedrijven die veel met machines werken, of bijvoorbeeld woningbouwverenigingen. Als u de kosten van onderhoud wilt reduceren, dan kan de Thingsway een ideale oplossing voor u zijn.\n\nDe Thingsway is ontwikkeld door Salland Electronics, een bedrijf dat zich specialiseert in innovatieve en grensverleggende IoT- oplossingen.\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>','Welke tools zijn er om continue te kunnen monitoren?','1564','inherit','closed','closed','','217-revision-v1','','','2022-01-31 09:35:48','2022-01-31 09:35:48','',217,'https://thingsway.media2netdev.nl/?p=340',0,'revision','',0),(341,1,'2022-01-31 09:35:49','2022-01-31 09:35:49','Periodiek machine onderhoud houdt de activiteiten in die worden uitgevoerd op een machine, dit volgens een bepaald tijdsinterval. Een goede werking behouden van de machine is het doel van periodiek machine onderhoud.\n<h2>Periodiek machine onderhoud in een werkstroom</h2>\nPeriodiek machine onderhoud wordt vaak volgens een bepaalde werkstroom uitgevoerd. Als eerste wordt een machine geselecteerd, daarna worden de historische gegevens van het uitgevoerde maintenance geanalyseerd. Aan de hand van deze gegevens wordt de beste interval bepaald om onderhoud te doen. Tijdens de periodieke controle wordt de machine aangezet en laat de controleur deze draaien onder normale condities. Hierna wordt bepaald of de machine aan onderhoud toe is en wordt deze uitgevoerd.\n<h2>Waarom onderhoud aan machines nodig is</h2>\nSlijtage aan machines valt nu eenmaal niet te vermijden, dit zorgt ervoor dat machines er een keer voorgoed mee op zullen houden. Gelukkig gebeurt dit niet van de ene op de andere dag. Integendeel zelfs, moderne machines die voor productie worden ontworpen worden duurzaam gemaakt. Daardoor kunnen ze heel lang meegaan, lang genoeg om tijdens de levensduur te bepalen hoe vaak er periodiek onderhoud nodig is.\n\nPeriodiek machine onderhoud is een manier van maintenance waarbij onderhoudstaken op vastgezette tijden moeten worden gedaan, dit terwijl de machine draait. Periodiek machine onderhoud wordt van tevoren gepland en uitgevoerd, ongeacht problemen of schade aan de machine.\n\nMet de historische gegevens die bekend zijn van een elke specifieke machine wordt de frequentie van het onderhoud bepaald. Fabrikanten van machines kunnen vaak kalenderschema’s voorstellen om controle op een machine uit te voeren. Hierbij worden vaak algemene richtlijnen opgesteld hoe vaak een bepaalde machine onderhoud nodig heeft per kalenderjaar.\n<h2>Hoe effectief is periodiek machine onderhoud?</h2>\nDe effectiviteit van periodiek onderhoud is gebaseerd op de aanname dat het vastlopen of kapot gaan van een machine voorspeld kan worden. Door de historische gegevens te analyseren van een machine, en door eventuele richtlijnen te volgen van een producent, wordt een periode bepaald waarin verwacht wordt dat de machine zonder problemen zal werken. Periodiek onderhoud aan de machine wordt gedaan voordat er een storing op zal treden, dat is althans de bedoeling.\n\nDeze historische gegevens worden veelal verkregen door periodieke metingen of experimenten. Er zit echter een nadeel aan deze periodieke metingen of experimenten. Periodiek is tijdsgebonden, net als een experiment. Een IoT oplossing, waarin een bepaalde machine continue gemonitord wordt, zal veel meer betrouwbare informatie opleveren.\n<h2>Voorbeelden van periodiek onderhoud</h2>\nPeriodiek machine onderhoud kan vaak vervangings- en reparatieproblemen oplossen. Voorbeelden van de werkzaamheden die tijdens dit onderhoud gedaan worden zijn:\n<ul>\n 	<li>Vervangen van smeerolie</li>\n 	<li>Lagervet controleren</li>\n 	<li>Filters vervangen</li>\n 	<li>Roest verwijderen</li>\n 	<li>Controle van druk- en temperatuurmeters</li>\n</ul>\nMachines die constant gebruikt worden hebben het voordeel dat de mate van slijtage op deze machines vrij nauwkeurig voorspeld kan worden. Je weet ten slotte ook van auto’s goed te voorspellen wanneer het olie ververst moet worden.\n\nVoor machines die minder vaak gebruikt worden geldt echter dat eventuele problemen minder voorspelbaar zijn, en daardoor periodiek onderhoud minder effectief is. Ook in zo’n geval zou een IoT oplossing veel effectiever kunnen zijn.\n<h2>Voordelen en nadelen van periodiek machine onderhoud</h2>\nHet voordeel van het doen van periodiek machine onderhoud is dat er geen extra apparaten nodig zijn om aan te geven wanneer een machine onderhoud nodig heeft. De kosten om periodieke schema’s vast te stellen zijn laag.\n\nHet nadeel van periodiek machine onderhoud is dat er een risico bestaat dat de uitgevoerde werkzaamheden op de machine onnodig waren. Een schatting uit de industriële sector geeft aan dat 30% van alle periodieke machine onderhoud slechts preventief was en daarmee dus onnodig werd uitgevoerd.\n\nEen ander nadeel van het uitvoeren van periodiek machine onderhoud is dat een storing op elk willekeurig moment kan optreden. Er zijn nu eenmaal bepaalde storingen die moeilijk voorspelbaar zijn, sommige onderdelen houden zich niet altijd aan de verwachtte slijtagetijd.\n<h2>Periodiek machine onderhoud in het kort</h2>\nBij periodiek onderhoud wordt er vanuit gegaan dat defecten aan machines in de loop van de tijd voorspeld kunnen worden. Het is een strategie van maintenance op basis van historische gegevens en/of specificaties van een producent. Periodiek onderhoud werkt vooral minder effectief bij machines die gevoeliger zijn voor storingen.\n<h2>Voorspellend onderhoud</h2>\nVoor alle machines geldt dat voorspellend onderhoud een effectievere manier is van maintenance. Voorspellend onderhoud kan worden gedaan door middel van een IoT-oplossing. Dat komt er in de praktijk op neer dat de werking van een bepaalde machine continu in de gaten wordt gehouden. Dit levert veel meer data en informatie op. Zo wordt het voorspellen van onderhoud een stuk betrouwbaarder.\n\nEen voorbeeld van een IoT-oplossing is de Thingsway. Dit is een maatwerksensor die de werking van een bepaalde machine continu in de gaten houdt. Door gegevens van de Thingsway te analyseren kan niet alleen schade worden voorkomen, maar het nodige machine onderhoud is daardoor ook beter te plannen.\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>','Voor- en nadelen van periodiek machine onderhoud','1568','inherit','closed','closed','','219-revision-v1','','','2022-01-31 09:35:49','2022-01-31 09:35:49','',219,'https://thingsway.media2netdev.nl/?p=341',0,'revision','',0),(342,1,'2022-01-31 09:35:50','2022-01-31 09:35:50','Als we iets hebben geleerd van de afgelopen boerenprotesten en de CO2 kwestie, dan is het wel dat alles tegenwoordig gemeten wordt, en dat cijfers enorm belangrijk zijn. We zijn er vaak niet van bewust in het dagelijks leven, maar voor bijna elk bedrijf geldt het oude spreekwoord: meten is weten. Zolang u iets niet kunt meten in het productieproces van uw bedrijf, kunt u het niet beheren. Elke fabrikant die zijn bedrijf naar een hoger niveau wil tillen, moet accurate en relevante gegevens en statistieken kunnen verzamelen en analyseren.\n\nIn de industrie draait alles om cijfers. De juiste statistieken kunnen u helpen om zwakke plekken en knelpunten in het productieproces te vinden. Dit geeft u informatie en de nodige inzichten om het bedrijf te blijven verbeteren en verfijnen. Om metingen in de industrie goed uit te voeren moet systematisch gewerkt worden. Informatie moet op de juiste manier verzameld worden, bovendien is er een gedegen proces nodig om deze informatie te analyseren en hierop een beleid in uitvoering te brengen.\n<h2>Voorbeelden van metingen in de industrie</h2>\nIn de industriële wereld worden veel verschillende metingen uitgevoerd. Allen vooral ten gunste van productie, efficiëntie en reductie van kosten. Dit zijn 5 voorbeelden van metingen die veel in de industrie gedaan worden:\n<h2>Productie cyclustijd</h2>\nDe cyclustijd is de totale tijd van de start tot het einde van een productieproces. Tijdens de productie meet het de tijd dat een product nodig heeft om alle machines, processen en cycli te doorlopen om een compleet product te worden.\n<h2>Omschakeltijd</h2>\nOmschakeling is het proces waarbij een lijn of machine wordt omgezet van het ene product naar het andere. Deze statistiek meet dus eenvoudig de tijd die nodig is om deze omschakeling te maken.\n<h2>Doorvoer</h2>\nDit is een van de eenvoudigste, maar belangrijkste, statistieken in productie. Het meet het gemiddelde aantal eenheden dat wordt geproduceerd op een machine, lijn, eenheid of fabriek gedurende een bepaalde tijdsperiode.\n\n<img class=\"size-full wp-image-1574 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/10/metingen-industrie.jpg\" alt=\"voordelen van meten in de industrie\" width=\"1000\" height=\"800\" />\n<h2>Capaciteitsbenutting</h2>\nMedewerkers in de operatie zijn vaak dol op deze gegevens, omdat deze aangeven hoeveel van de totale productiecapaciteit op een bepaald moment wordt gebruikt. In andere woorden; in welke mate wordt aan het potentiële niveaus voldaan?\n<h2>Overall Equipment Effectiveness (OEE)</h2>\nOEE is een analyse van efficiëntie en productiviteit en wordt wereldwijd erkend als een belangrijke prestatie maatstaf. OEE beoordeelt kwaliteit, snelheid en rusttijd, en kan worden gebruikt om de algehele effectiviteit van een apparaat of een volledige productielijn aan te geven.\n<h2>Metingen voor de werking van machines</h2>\nWat opvalt aan alle bovenstaande soorten metingen is dat deze allen zijn gericht op productiviteit, niet op de daadwerkelijke werking of slijtage van een bepaalde machine. Toch is de werking van machines van essentieel belang in een productieproces. Om uitval te voorkomen worden er wel degelijk metingen gedaan aan een machine, ook wordt er periodiek onderhoud gedaan. Tijdens dit onderhoud wordt een machine gebruikt onder de normale omstandigheden en gemonitord. Uit dit onderhoud komen verschillende gegevens: de werking van de machine in kwestie; de verwachtte tijd dat de machine nog mee zal gaan; de eventuele nodige reparaties; en de onderdelen die de komende tijd misschien vervangen zullen moeten worden.\n\nEen andere manier om de werking van machines te monitoren is door middel van continue metingen. Dit kan worden gedaan door middel van een Internet of Things- toepassing. Dit is een apparaat dat is voorzien van sensoren. Deze sensoren meten constant de werking van de machine. Deze gegevens kunnen worden verstuurd via een internetverbinding en op afstand worden beoordeeld en geanalyseerd.\n<h2>De voordelen van continue metingen in de industrie</h2>\nPeriodiek onderhoud is één van de grootste methoden in de industrie om de werking van machines te garanderen. Er zitten echter enkele nadelen aan periodiek onderhoud. Het eerste nadeel is het feit dat periodiek onderhoud gebaseerd is op voorspellingen. Hoe lang een machine echt mee gaat, of wanneer er uitval is, valt eigenlijk niet te voorspellen. Het andere nadeel is dat onderhoud, of het vervangen van onderdelen, misschien helemaal niet nodig is. Dit heeft kosten meegebracht doordat de machine stil lag, door mankracht en bijkomende kosten aan materiaal.\n\nDoor de werking van een machine continue te monitoren kan uitval of het nodige onderhoud veel beter voorspeld worden. Meer meten betekent meer cijfers, meer data betekent meer statistieken en betrouwbare informatie. Dit kan voor een efficiënter productieproces zorgen.\n<h2>De Thingsway voor metingen in de industrie</h2>\nDe Thingsway is een Internet of Things- sensor die geschikt is voor metingen in de industrie. Het is een apparaat dat op alle gebieden metingen zou kunnen uitvoeren, hiervoor worden simpelweg verschillende sensoren aangepast op het doel van de meting. Denkt u dan bijvoorbeeld aan temperatuursensoren, lichtsensoren, druksensoren, of geleidingssensoren.\n\nDoor de Thingsway in te zetten in uw bedrijf krijgt u een beter inzicht in de werking van een bepaalde machine. Dit zorgt voor een efficiënter gebruik van de machine, het kan uitval voorkomen en bovendien weet u precies wanneer maintenance echt nodig is.\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>','Voordelen van metingen in de industrie','1571','inherit','closed','closed','','221-revision-v1','','','2022-01-31 09:35:50','2022-01-31 09:35:50','',221,'https://thingsway.media2netdev.nl/?p=342',0,'revision','',0),(343,1,'2022-01-31 09:35:53','2022-01-31 09:35:53','Bijna alle bedrijven hebben te maken met onderhoud. Alles om ons heen is immers onderhevig aan slijtage en dient daarom onderhouden te worden. Niet alleen machines zijn onderhevig aan onderhoud, maar natuurlijk ook gebouwen en infrastructuur. Voor uw bedrijf kan dat bijvoorbeeld betekenen dat u alle machines regelmatig periodiek laat onderhouden, dit om uitval en schade te voorkomen. Het kan ook zijn dat u werkt voor een maintenance bedrijf. In alle gevallen geldt dat u veel baat heeft bij een goed onderhoudssysteem. Een goede strategie voor een onderhoudssysteem wordt bepaald door de juiste onderhoudsmetingen toe te passen. Dit zorgt ervoor dat onderhoud beter te voorspellen is. Zo kan efficiëntie worden vergroot en kosten worden gereduceerd.\n<h2>Wat wordt gezien als onderhoud?</h2>\nU kunt onderhoud zien als alle nodige activiteiten die het doel hebben om een bepaald object in een goed werkende conditie te houden of brengen. Dit om te zorgen dat het object zijn functionaliteit behoud. Het waarborgen van de functionaliteit is nodig om eventuele negatieve gevolgen tegen te gaan zoals:\n<ul>\n 	<li>Een onveilige situatie. Dit kan bijvoorbeeld zorgen voor schade aan lichaam of gebouw.</li>\n 	<li>Een ongezonde situatie. Wanneer iets niet goed functioneert, dan kan dat gevolgen hebben voor mens, dier en milieu.</li>\n 	<li>Een object wordt onbruikbaar.</li>\n 	<li>Een object wordt minder duurzaam. Zo kan een defect in een machine zorgen voor hogere kosten aan stroom of mankracht.</li>\n 	<li>Afname van comfort. Vermindering van functionaliteit kan ervoor zorgen dat een proces minder prettig wordt, of een minder goed gevoel geeft. Denk bijvoorbeeld aan een lift die schokkend naar boven of beneden gaat.</li>\n 	<li>Een slechtere uitstraling van een object. Een overstromende dakgoot zorgt niet alleen voor directe problemen, het zorgt bovendien onmiddellijk voor een slecht onderhouden aanblik.</li>\n</ul>\nDe functionaliteit van een object kan geleidelijk minder worden door slijtage, maar het kan ook op een bepaald moment onmiddellijk verloren gaan. Het uitvoeren van onderhoud, en onderhoudsmetingen, kan uw bedrijf helpen om uitval van functionaliteit tegen te gaan.\n<h2>Wat voor soorten onderhoud bestaan er?</h2>\nEr bestaan verschillende soorten onderhoud, deze zijn onder te verdelen in drie categorieën:\n<ul>\n 	<li>Reactief onderhoud</li>\n 	<li>Proactief onderhoud</li>\n 	<li>Additief onderhoud</li>\n</ul>\nReactief onderhoud wordt gedaan wanneer iemand bijvoorbeeld een klacht heeft. Service onderhoud wordt uitgevoerd en eventuele gebreken worden hersteld.\n\nProactief onderhoud wordt gedaan wanneer u bekend bent met een object, zoals een gebouw of machine. Een machine wordt preventief onderhouden om defecten te voorkomen, dit wordt gedaan door middel van periodiek onderhoud. Dit wordt ook wel eens planmatig onderhoud genoemd, omdat het vaak gebaseerd is op een onderhoudsplan.\n\nAdditief onderhoud wordt gedaan op basis van een strategie of plan. Dit is een toevoeging op het reguliere onderhoud.\n<h2>De voorspelbaarheid van onderhoud</h2>\nWanneer u een keuze maakt voor een onderhoudssysteem, dan wilt u vooral dat het te verwachten onderhoud zo goed mogelijk te voorspellen is. Voor u als bedrijf zorgt dit voor lagere lasten; niet alleen op gebied van onderhoud, maar ook op gebied van kosten. Een goed onderhoudssysteem zorgt voor een hoge voorspelbaarheid van uitval en fouten die kunnen optreden in een systeem of object. Voor een klant zorgt een gedegen onderhoudssysteem voor vertrouwen, een gevoel van veiligheid en duurzaamheid.\n\nHet voorspellen van onderhoud wordt gedaan door middel van onderhoudsmetingen, veelal tijdens periodiek onderhoud. Het nadeel van periodiek onderhoud is het feit dat het nog steeds een momentopname is. Natuurlijk kan er door middel van periodiek onderhoud over een langere periode een redelijke voorspelling van te verwachten onderhoud worden gedaan. Uit deze gegevens, en de eventuele richtlijnen van de fabrikant, kunt u een redelijk gedegen onderhoudssysteem vastleggen. De voorspelbaarheid kan echter verhoogd worden door middel van continue onderhoudsmetingen.\n<h2>Hogere voorspelbaarheid door continue onderhoudsmetingen</h2>\nOnderhoudsmetingen die continu worden uitgevoerd zorgen voor een veel beter beeld van de werking, slijtage en eventueel te verwachten problemen van een bepaald object. U krijgt namelijk veel meer data en over een veel langere periode. Zo’n continue onderhoudsmeting kan worden uitgevoerd op bijna elk object, of dat nu gaat om een machine, een deur of een dakgoot.\n\nContinu metingen kunnen worden gedaan door middel van een IOT-toepassing. IOT staat voor internet of things. Dit betekent dat het meetsysteem bestaat uit één of meerdere bepaalde sensoren in combinatie met een internetconnectie. Zodoende kunnen gegevens constant worden doorgezonden en geanalyseerd.\n\nEen goed voorbeeld van zo’n onderhoudsmeting-systeem is de Thingsway. Dit product is ontwikkeld door Salland Electronics. De Thingsway is dusdanig ontworpen dat het eenvoudig aan te passen is, speciaal op het object/systeem wat gemeten dient te worden.\n\nEen internet of things oplossing zoals de Thingsway kan reactief onderhoud voorkomen. Bovendien kunt u een heel goed onderhoudssysteem samenstellen dankzij de onderhoudsmetingen en de gegevens die de Thingsway u levert.\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>','Onderhoudsmetingen: wat is daar het nut van?','1581','inherit','closed','closed','','226-revision-v1','','','2022-01-31 09:35:53','2022-01-31 09:35:53','',226,'https://thingsway.media2netdev.nl/?p=343',0,'revision','',0),(344,1,'2022-01-31 09:35:54','2022-01-31 09:35:54','Het welzijn van machines heeft een enorme impact op de algehele efficiëntie van een bedrijf. Dat is de reden waarom onderhoud zo belangrijk is. Om de concurrentie voor te blijven moeten fabrikanten en producenten gebruik maken van de nieuwste technologie. Nadeel is dat het hoge kosten met zich meebrengt. Hoe kunt u innoveren, concurrerend blijven en tegelijkertijd besparen op onderhoudskosten? Om u te helpen volgen hier enkele manieren waarmee u de onderhoudskosten niet alleen kunt verlagen, maar tevens de strategie mee kunt verbeteren.\n<h2>Veiligheid staat voorop!</h2>\nBesparen op de kosten voor onderhoud en stilstand verminderen wordt vaak in verband gebracht met minder veiligheid en service. Dit is echter onjuist! Om de onderhoudskosten te verlagen moet er worden gewerkt aan een hogere efficiëntie. Dat betekent een betere strategie en planning. Door een betere planning kan er gerichter gewerkt worden, wat de veiligheid zal vergroten.\n<h2>Fouten en storingen analyseren</h2>\nOm een onderhoudsprogramma te verbeteren dient u een beter beeld te krijgen van de gegevens van onderhoudsstoringen. Door deze te leren begrijpen kunt u ze effectief maken als kritieke prestatie indicatoren.\n<h2>Beperk reactief onderhoud</h2>\nReactief onderhoud wordt ook wel storingsonderhoud genoemd. Het betekent dat er pas reparaties worden gedaan wanneer een machine is uitgevallen of een object defect is.\n\nOp het eerste gezicht lijkt dit een manier om de kosten te verlagen, u vervangt pas een onderdeel wanneer deze echt defect is. In de praktijk zal dit op de lange duur echter voor hogere kosten zorgen. Deze strategie zou u moeten beperken tot apparaten die niet kritiek zijn en onderdelen die makkelijk vervangbaar zijn.\n<h2>Hou een doel voor ogen</h2>\nDankzij de enorme sprongen op gebied van technologie kunnen onderhoudsbedrijven veel beter doelen stellen en resultaten bijhouden. Om te besparen op onderhoudskosten zal een bedrijf zich moeten concentreren op een specifiek doel. Door een doel te stellen worden uw inspanningen meetbaar gemaakt.\n<h2>Optimaliseer het beheer van uw voorraad</h2>\nAls manager van een onderhoudsbedrijf of onderhoudsteam bent u verantwoordelijk om de kosten voor onderhoud te beheersen en uitval tijd zo laag mogelijk te houden.\n\nIn de industriële sector is het belangrijk om de werking van apparatuur te waarborgen, het gehele proces dient zo efficiënt mogelijk te draaien. De beste manier om dit doel te bereiken is door een strategische organisatie en voorraad van reserveonderdelen. Voor veel bedrijven blijkt het beheren van reserveonderdelen een enorme kopzorg. Wanneer de voorraad van een bedrijf niet optimaal is zal dit zorgen voor hogere kosten.\n\n<img class=\"alignnone size-full wp-image-1586\" src=\"https://thingsway.nl/wp-content/uploads/2020/10/voorraad.jpeg\" alt=\"voorraad beheer \" width=\"1880\" height=\"1254\" />\n<h2>Maak gebruik van Total Productive Maintenance</h2>\nDe algehele prestaties van een bedrijf zullen verbeteren door middel van routine- en preventieve onderhoud strategieën. Bovendien zal dit de uitval van machines beperken. Een van de meest gebruikte methoden is Total Productive Maintenance (TPM). Dit is een methode die zich richt op beheersing van de werkplek. Hierdoor wordt toegankelijkheid, betrouwbaarheid en efficiëntie gegarandeerd.\n\nTPM helpt om storingen op te lossen, minder fouten te maken, en vertragingen te voorkomen. Dit alles zorgt voor grotere prestaties. Het is gebleken dat bedrijven die aan dit beleid doen hun kosten aanzienlijk weten te verlagen.\n<h2>Onderhoudsgegevens bijhouden</h2>\nBij veel bedrijven wordt nog van oude technieken gebruik gemaakt om te rapporteren. Denkt u dan aan logboeken, pen en papier en Excel-documenten. In het verleden zullen die misschien voor u gewerkt hebben, maar ze nemen veel tijd in beslag en zijn vatbaar voor fouten. Bovendien heeft u nu beschikking over veel meer gegevens.\n\nNiet alleen op gebied van rapporteren bestaat er nieuwe technologie, ook om deze gegevens te analyseren zijn er sprongen gemaakt op technologisch gebied. Wanneer u geen gebruik maakt van deze technologie dan loopt u het risico dat u vitale data over het hoofd ziet.\n\nTegenwoordig bestaat er software voor onderhoud waarmee een bedrijf rapportage kan automatiseren. De software stelt u in staat om u op specifieke gegevens te richten. Dit is een veel efficiëntere manier om uw machines, apparatuur of processen mee te volgen.\n<h2>Maak gebruik van de Thingsway om onderhoudskosten te besparen</h2>\nGegevens verzamelen is dus heel belangrijk voor een bedrijf om onderhoudskosten te kunnen besparen. Om deze data van machines, of van een proces, te kunnen verzamelen heeft u een sensor nodig die de machine continu monitort. Dankzij het Internet-of-Things bestaan er tegenwoordig sensoren die niet alleen zorgen voor deze monitoring, de gegevens worden tevens in real-time naar u doorgestuurd. Dit kan dankzij een draadloze internetverbinding.\n\nDe Thingsway van Salland Electronics is zo’n handig IoT-systeem wat ervoor kan zorgen dat u de kosten voor het onderhoud aanzienlijk kunt verlagen. U kunt de Thingsway inzetten om storingen te detecteren voordat deze plaatsvinden. Zodoende kunt u onderhoud plegen wanneer dit werkelijk nodig is. Dit zorgt voor maximaal gebruik van machine en onderdelen.\n\nTevens geeft de Thingsway u de kans om enorm veel data te verzamelen. Dit geeft een veel beter beeld van de optimale werking van een machine.\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>','Hoe kunt u besparen op onderhoudskosten?','1584','inherit','closed','closed','','228-revision-v1','','','2022-01-31 09:35:54','2022-01-31 09:35:54','',228,'https://thingsway.media2netdev.nl/?p=344',0,'revision','',0),(345,1,'2022-01-31 09:35:55','2022-01-31 09:35:55','Wat als een onderdeel u zelf kan vertellen wanneer het moet worden gerepareerd of vervangen? Dankzij een continue verzameling van gegevens, monitoring en toepassing van geavanceerde analyses kan dit. Voorspellend onderhoud biedt bedrijven de mogelijkheid om de betrouwbaarheid te verhogen en de operationele efficiëntie te verbeteren. De ontwikkeling van het Internet-of-Things gaat razendsnel. Industriële machines worden gemonitord door middel van sensoren, deze zijn voorzien van een directe internetverbinding. De door de sensoren verzamelde data wordt hierna in de cloud geanalyseerd. Het is een soort industrieel internet dat bedrijven kansen biedt voor enorme winsten op gebied van productiviteit.\n\nDe machines die worden uitgerust met een groeiend aantal elektronische sensoren kunnen veel meer zien, horen en voelen dan ooit tevoren. Deze enorme hoeveelheden gegevens moeten worden geanalyseerd, dit wordt gedaan door middel van geavanceerde algoritmen. Deze algoritmen zorgen voor inzichten die bedrijven in staat stellen om machines of processen op geheel nieuwe en efficiëntere manieren te gebruiken. Voorspellend onderhoud kan worden uitgevoerd wanneer dit echt nodig is.\n<h2>De voordelen van voorspellend onderhoud</h2>\nVoorspellend onderhoud is een manier van een proactief onderhoudsplan. Voorheen werd voorspellend onderhoud gedaan op basis van metingen en gegevens van periodiek onderhoud, historische gegevens van storingen en gebruiksaanwijzingen van fabrikanten. Aan de hand van deze verzamelde gegevens kon een redelijke voorspelling worden gedaan wanneer een machine of object onderhoud nodig had. Dit had echter een groot nadeel, het gaat in dit geval namelijk om voorspellingen uit het verleden, op basis van relatief weinig gegevens.\n\nEen ander soort voorspellend onderhoud heeft zijn intrede gedaan dankzij de opkomst van het Internet-of-Things. Een IoT-toepassing is een apparaat dat gebruik maakt van sensoren in combinatie met een rechtstreekse internetverbinding. Dit geeft de mogelijkheid om apparaten, maar ook objecten en processen, continu te laten monitoren. Het monitoren heeft twee grote voordelen; ten eerste geeft het u de mogelijkheid om een storing voor te zijn. De IoT-toepassing geeft u een waarschuwing voordat een probleem zich voordoet. Het andere voordeel is dat het continu monitoren zorgt voor enorm veel data. Zoveel gegevens bieden u de kans om een veel beter beeld te krijgen van de werking van een machine of proces.\n<h2>Analyse van maintenance data</h2>\nDe gegevens die verkregen worden via het monitoren van een machine of proces kunt u zien als maintenance data. De IoT-toepassing vormt een deel van uw onderhoudsteam of het maintenance bedrijf wat u inhuurt. De sensoren zorgen voor de monitoring en sturen de gegevens door via de internetverbinding. Het analyseren van de maintenance data kan het best worden gedaan via software en zogenaamde algoritmen. Hiermee kan de optimale werking van een machine of proces worden bepaald. Dit geeft een bedrijf de mogelijkheid om de efficiëntie te vergroten en kosten te besparen. Machines, onderdelen en grondstoffen kunnen maximaal worden benut.\n<h2>De Thingsway</h2>\nDe Thingsway is een IoT-apparaat dat op vele gebieden kan worden ingezet. De Thingsway is een basisproduct dat zeer snel aan te passen is op de wensen van een bedrijf. De aanpassingen die gedaan moeten worden liggen op het gebied van behuizing, montering en de benodigde sensoren. Elk proces heeft namelijk een andere sensor nodig.\n\nDe Thingsway is ontwikkeld door Salland Electronics, zij kunnen u binnen een dag voorzien van een IoT-sensor, inclusief internetverbinding. Zodoende kunt u een analyse van maintenance data uitvoeren. Dit geeft ook u de kans om aan voorspellend onderhoud te doen. Bovendien biedt het u de mogelijkheid om kosten te besparen en de efficiëntie naar een hoger plan te tillen.\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>','Analyse van maintenace data','1588','inherit','closed','closed','','230-revision-v1','','','2022-01-31 09:35:55','2022-01-31 09:35:55','',230,'https://thingsway.media2netdev.nl/?p=345',0,'revision','',0),(346,1,'2022-01-31 09:35:56','2022-01-31 09:35:56','Voor veel bedrijven is het van groot belang om maximaal te kunnen produceren onder de meest effectieve omstandigheden. Helaas gaat er wel eens iets mis tijdens een productieproces van een bedrijf, denk maar eens aan de terugroep acties van bepaalde automerken zoals Tesla. Dit kan een bedrijf tonnen geld kosten. Dit is de reden waarom bedrijven in bijvoorbeeld de luchtvaartindustrie, autofabrikanten en productie-industrie een grote uitdaging hebben om die effectiviteit en maximale inzet van middelen te garanderen. Dit wordt gedaan door de kritieke activa in zo goed mogelijke staat te houden. Tegelijkertijd is het doel om de kosten van onderhoud en reparaties te minimaliseren.\n<h2>Kosten minimaliseren door het Internet-of-Things</h2>\nOm deze kosten te reduceren zouden de oorspronkelijke redenen van defecten en storingen geïdentificeerd moeten kunnen worden zonder menselijke metingen en testen. Hieraan kan voldaan worden dankzij Internet-of-Things toepassingen in de industrie. Steeds meer apparatuur, robots en voertuigen worden aan een server aangesloten. Dit maakt het voor een bedrijf eenvoudiger, goedkoper en praktischer om fouten op te sporen.\n\nHet vroegtijdig opsporen van eventuele problemen helpt een bedrijf om een maintenanceteam effectiever in te zetten. Bovendien wordt er maximaal gebruik gemaakt van onderdelen en apparatuur. Om kritische factoren te bepalen die een storing voorspellen worden gegevens verzameld als bouwjaar, merk, model, garantie en aanwijzingen van fabrikant. Dat zijn gegevens die nog vrij gestructureerd zijn. Andere gegevens zijn vaak minder gestructureerd, zoals logboek gegevens van metingen, onderhoudsrapporten en foutmeldingen.\n\nDeze gegevens worden gebruikt om voorspellend onderhoud uit te voeren. Dit is een onderhoudsstrategie om te voorspellen wanneer een werkende machine defect zal raken. Onderhoud zal uitgevoerd worden voordat dit gebeurt. Wanneer er gebruik gemaakt wordt van een Iot-toepassing kan voorspellend onderhoud uitgevoerd worden aan de hand van real-time data.\n<h2>Voordelen van Data Science bij voorspellend onderhoud</h2>\nEr zijn vele voordelen aan het toepassen van data science bij voorspellend onderhoud. Enkele voordelen zijn:\n<ul>\n 	<li>Het minimaliseert de onderhoudskosten. Er wordt geen tijd verspild aan te voorzichtig en tijdsgebonden onderhoud. Apparatuur wordt vervangen wanneer nodig.</li>\n 	<li>Uitvaltijd wordt verminderd. Door aan voorspellend onderhoud te doen een Iot-oplossing, kunt u toekomstige storingen en defecten voor zijn. Onvoorziene problemen kunnen uw bedrijf niet meer in gevaar brengen.</li>\n 	<li>Analyse van de oorzaken. Door gegevens van de Iot-oplossing te analyseren, kunt u beter de oorzaak van storingen opsporen. Samen met fabrikanten kan het rendement en de effectiviteit van een machine verbeterd worden.</li>\n 	<li>Effectieve inzet van personeel. Geen onnodige reparaties of periodiek onderhoud zorgt voor een efficiëntere inzet van technisch personeel.</li>\n 	<li>Een defect of storing herstellen betekent vaak juridische of garantie kosten. Deze kosten kunnen verminderd worden wanneer storingen voorkomen worden.</li>\n</ul>\nVeel grote bedrijven maken al gebruik van de voordelen van het Internet-of-Things in combinatie met voorspelbaar onderhoud. Een machinestoring komt vaak plotseling en onverwacht. Dit kan de reputatie en het aanzien van een bedrijf ruïneren. Het kan leiden naar hoge kosten, contractboetes en minder inkomsten door stilstand. Met gebruik van een Iot-oplossing en data science kunnen al deze problemen voorkomen worden.\n<h2>Verzamel data met de Thingsway</h2>\nMisschien vraagt u zich nu af hoe dat nu in zijn werk gaat, zo’n Internet-of-Things oplossing. De Thingsway is een voorbeeld van een Iot-oplossing. Dit is een apparaat dat is voorzien van bepaalde sensoren en een directe, draadloze internetverbinding. Deze sensoren monitoren continu veranderingen in de omgeving van een object of machine. Deze veranderingen kunnen zijn warmte, beweging, druk etc. Er bestaan veel verschillende soorten sensoren, bijna alle veranderingen zijn hierdoor meetbaar.\n\nWanneer zo’n verandering optreedt zal de sensor dit registreren en onmiddellijk communiceren via data aan bepaalde hardware. Dat kan gaan om computer, laptop of de smartphone van iemand van het onderhoudsteam. Data science zorgt er vanaf dit moment voor dat u de voordelen van voorspelbaar onderhoud kunt toepassen.\n\nDe Thingsway is ontwikkeld door Salland Electronics. Deze Iot-oplossing is zeer snel toepasbaar en op meerdere gebieden. Er bestaat een Thingsway voor de industriële sector, maar er is ook een Thingsway die op buitenlocaties wordt ingezet. Het basisproduct kan binnen een dag door Salland Electronics worden aangepast zodat het in te zetten is in uw bedrijf. Zodoende kunt u binnen korte tijd werken aan meer effectiviteit en kostenbesparingen. Dat alles door middel van data science en voorspelbaar onderhoud.\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>','De voordelen van data sience voor voorspellend onderhoud','1591','inherit','closed','closed','','232-revision-v1','','','2022-01-31 09:35:56','2022-01-31 09:35:56','',232,'https://thingsway.media2netdev.nl/?p=346',0,'revision','',0),(347,1,'2022-01-31 09:35:58','2022-01-31 09:35:58','Het Internet-of-Things, misschien heeft u er wel eens van gehoord? Het wordt ook wel de nieuwe industriële revolutie genoemd. Het is de afgelopen jaren enorm in opkomst. Voor bedrijven is het de mogelijkheid om efficiënter te werken en daarmee concurrerend te blijven. Bedrijven die veel te maken hebben met onderhoud investeren vaak in het IoT. Waarom? Omdat een Iot-oplossing kan zorgen voor het reduceren van onderhoudskosten.\n<h2>Het doel van onderhoud</h2>\nWanneer we denken aan onderhoud, dan denken we al snel aan het repareren van machines of objecten. Onderhoud betekent echter veel meer. Om een bedrijf gezond te houden is een onderhoudsstrategie nodig die als doel heeft om zo veel mogelijk uitval en schade te voorkomen. Dit zorgt ervoor dat een bedrijf geen stilstand heeft, waardoor de kosten op gebied van arbeidsuren, reparaties en onderdelen laag blijven. Dit zorgt voor meer effectiviteit en een algeheel beter lopend proces.\n<h2>De verschillende manieren van onderhoud</h2>\nEr bestaan veel verschillende manieren van onderhoud. U kunt er voor kiezen om alleen maar reactief onderhoud te plegen. U reageert dan slechts op klachten van bijvoorbeeld bewoners of automatische meldingen van een machine. Onderhoud wordt in zo’n geval alleen gepleegd wanneer iets defect is. Dit heeft flinke nadelen, want u loopt achter de feiten aan. Een reactief onderhoudsplan zorgt er niet voor dat de werking van een proces of machine zo goed mogelijk gewaarborgd blijft. Onderdelen zullen stuk gaan, uitval van machines blijft onvermijdelijk. Reactief onderhoud is een strategie die alleen geschikt is voor onderdelen die niet kritiek zijn in een proces. Denkt u dan aan onderdelen die relatief goedkoop zijn en tevens makkelijk te vervangen.\n\nDe tegengestelde manier van reactief onderhoud is proactief onderhoud. Wanneer u als bedrijf aan proactief onderhoud doet, dan past u strategieën toe die er toe dienen om omstandigheden te creëren die ertoe leiden dat de werking van een bepaald proces zo lang mogelijk gewaarborgd blijft. Een goed voorbeeld van proactief onderhoud is periodiek onderhoud. In geval van periodiek onderhoud wordt onderhoud gepleegd volgens een vastgestelde interval van tijd. Deze tijd wordt bepaald door voorspellingen hoe lang een bepaalde machine, of onderdeel, zal meegaan. Deze voorspellingen worden gedaan op basis van metingen, historische gegevens en aanwijzingen van fabrikanten. Periodiek onderhoud is een vrij goede en betrouwbare manier van onderhoud, het is een soort voorspelbaar onderhoud. Er is echter een manier van voorspelbaar onderhoud dat nog effectiever is vanwege meer en betrouwbaardere data.\n\n<img class=\"alignnone size-full wp-image-1599\" src=\"https://thingsway.nl/wp-content/uploads/2020/10/onderhoud-kosten-reduceren-scaled.jpg\" alt=\"reduceren onderhoudskosten\" width=\"2560\" height=\"1707\" />\n<h2>Voorspelbaar onderhoud dankzij het IoT</h2>\nDankzij het Internet-of-Things kan er aan een nieuwe vorm van voorspelbaar onderhoud worden gedaan. We hebben het dan namelijk over voorspelbaar onderhoud op basis van real-time data. Het Internet-of-Things kunt u zien als de mogelijkheid om alle kritieke onderdelen van uw bedrijf continu te laten monitoren. Voor dit monitoren heeft u geen mensen ter plekke nodig. Via een directe internetverbinding worden gegevens van het proces doorgestuurd naar hardware naar uw keus. Dat kan gaan om een computer, laptop of smartphone.\n\nAls voorbeeld kunnen we een machine nemen die regelmatig oververhit. Daardoor ontstaat een storing en heeft u uitval van de machine. Dit levert u kosten op, niet alleen om de machine weer te repareren, maar ook kosten voor stilstand, onderdelen en arbeidsuren. Misschien krijgt u zelfs te maken met juridische kosten, wanneer u bijvoorbeeld een bestelling niet kunt leveren.\n\nU kunt de machine laten monitoren door een IoT-apparaat. Deze is voorzien van sensoren die het proces continu in de gaten houden. Wanneer de warmte verandert, en dus oververhitting zou kunnen plaatsvinden, dan geven de sensoren dit onmiddellijk door. Een technische dienst, of zelfs iemand die ter plaatse met de machine werkt, kan ingrijpen voordat de storing optreedt.\n<h2>Onderhoudskosten reduceren met de Thingsway</h2>\nDe Thingsway is zo’n IoT-apparaat dat ingezet kan worden voor voorspelbaar onderhoud. Dit is een apparaat dat ontwikkeld is door Salland Electronics. Het grote voordeel van de Thingsway is dat het voor veel toepassingen geschikt gemaakt kan worden. Aanpassingen aan het basisontwerp worden gedaan aan de hand van uw wensen en het te meten proces. Denkt u dan aan aanpassingen als de behuizing, verschillende sensoren en aansluiting.\n\nEen IoT-sensor zoals de Thingsway is de nieuwe manier van voorspelbaar onderhoud. Het geeft u de mogelijkheid om onderhoudskosten te reduceren. Niet alleen door in te grijpen in een proces voordat schade of uitval ontstaat. Op den duur zal de vele data u ook meer inzichten bieden in de werking van een machine, onderdeel of proces. Door goede analyses te doen kunt u bijvoorbeeld kosten reduceren door een efficiëntere inzet van middelen. Ook kosten op gebied van verbruik van grondstoffen en onderdelen kunnen gereduceerd worden.\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>','Onderhoudskosten reduceren met de Thingsway','1597','inherit','closed','closed','','234-revision-v1','','','2022-01-31 09:35:58','2022-01-31 09:35:58','',234,'https://thingsway.media2netdev.nl/?p=347',0,'revision','',0),(348,1,'2022-01-31 09:35:58','2022-01-31 09:35:58','Om een bedrijf te laten groeien is het regelmatig onderhouden van de activa een must. Onderhoud wordt door bedrijven gedaan om de prestaties te optimaliseren. Het doel is om zo min mogelijk uitval te hebben, dit kan leiden naar betere prestaties van activa, maar ook een effectiever productieproces.\n\nBij het woord onderhoud denken velen aan repareren. Onderhoud richt zich echter meer op het opvolgen van een strategisch plan. Een onderhoudsproces volgens een bepaalde methode, dat als doel heeft om de werking van machines, apparatuur of objecten te optimaliseren. Onderhoud is dus veel meer dan alleen repareren. Om een goed lopend bedrijf te hebben is het van belang om meer tijd en inspanning te spenderen aan onderhoud, dan aan reparaties.\n\nDe opkomst van het Internet-of-Things zorgt ook voor grote stappen op gebied van innovatie in de wereld van onderhoud en maintenance. Dit biedt bedrijven de mogelijkheid om hun onderhoudsplan, en daarmee het gehele bedrijf, naar een hoger niveau te tillen.\n<h2>Hoe zet u data analyse in bij onderhoud?</h2>\nHet Internet-of-Things is overal om ons heen, ook al beseffen we ons dat niet. Veel apparaten in ons huis, op ons werk en op straat zijn voorzien van sensoren en een internetconnectie. Dit geeft deze apparaten de mogelijkheid om met ons, maar ook met elkaar, te communiceren.\n\nHet Internet-of-Things is ook zeer goed in te zetten voor onderhoud. Door een IoT-apparaat te gebruiken om een proces of machine te monitoren, krijgt een bedrijf beschikking over enorm veel data. De sensoren houden continu een bepaald proces in de gaten. Veranderingen in dit proces worden via de directe internetverbinding doorgestuurd. Deze data kan daarna worden geanalyseerd. Een analyse kan er bijvoorbeeld voor zorgen dat u een storing voor bent, maar het heeft nog meer voordelen.\n\n<img class=\"size-full wp-image-1604 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/10/onderhoud-data-analyse.jpg\" alt=\"onderhoud data analyse\" width=\"1000\" height=\"800\" />\n<h2>Voordelen van data analyse bij onderhoud op korte termijn</h2>\nIeder proces heeft bepaalde omstandigheden nodig om goed te blijven verlopen. Veranderingen in de omgeving van dit proces kunnen ervoor zorgen dat storingen optreden. Een machine kan bijvoorbeeld vastlopen, omdat de warmte in een ruimte te hoog wordt. Een doorstroom van water in een dakgoot kan stoppen, omdat de goot volgeraakt is met bladeren.\n\nDeze veranderingen kunnen worden geregistreerd door sensoren. Er bestaan veel verschillende sensoren, er bestaan sensoren die warmte meten, maar ook druk, beweging etc.\n\nNa het bepalen van de belangrijke indicator in een proces (druk, warmte, beweging etc.), kan het proces continu gemonitord worden door een Iot-oplossing. Het voordeel hiervan op korte termijn is dat de sensor onmiddellijk een melding zal geven wanneer deze verandering optreedt. Zodoende kan een monteur of technisch team in actie komen, voordat een machine in storing gaat of er schade ontstaat.\n\nAls voorbeeld in de praktijk kunnen we de dakgoot nemen. Een sensor houdt de doorstroom van de dakgoot in de gaten. Neemt de doorstroom af vanwege bladeren in de goot, dan geeft de sensor onmiddellijk een melding. Onderhoud kan uitgevoerd worden voordat de goot overloopt en er schade ontstaat aan goot en/of huizen.\n<h2>Voordelen van data analyse bij onderhoud op lange termijn</h2>\nBehalve dit grote voordeel op korte termijn, wat u al flink in de kosten zal kunnen schelen, zijn er ook voordelen op de lange termijn. Het continu monitoren van een proces geeft u namelijk enorm veel betrouwbare data. Onderhoud wordt meestal gebaseerd op instructies van fabrikanten, gegevens uit het verleden en metingen tijdens onderhoud. Deze factoren bepalen de voorspellingen voor toekomstig onderhoud.\n\nEen IoT-oplossing geeft u in de loop der tijd veel meer informatie, bovendien is deze data up-to-date. Veel meer data zorgt voor een veel beter beeld in de werking van een machine of proces. Aan de hand van dit betrouwbaarder beeld kunt u eventueel aanpassingen doen wat betreft de optimale werking van een machine en verbetering van een proces of product. Tevens kan het op den duur zorgen voor meer effectiviteit, door zuiniger om te gaan met grondstoffen, onderdelen en arbeidsuren.\n<h2>Data verzamelen via de Thingsway</h2>\nOm data te kunnen analyseren, heeft u data nodig. Deze gegevens kunt u verkrijgen door een IoT-oplossing in te zetten. Een mooi voorbeeld van een Iot-oplossing is de Thingsway. Dit is een samenstelling van de termen Internet-of-Things en gateway.\n\nDe Thingsway is een Iot-oplossing die zeer snel in te zetten is in uw bedrijf. Het is een basisproduct waarvan details snel aangepast kunnen worden, zodat u binnen korte tijd metingen kunt doen in uw bedrijf die u van de nodige data kan voorzien. Bij deze details kunt u denken aan behuizing, sensoren en aansluitmogelijkheden. De Thingsway biedt u de ideale mogelijkheid om data analyse in te zetten bij onderhoud. Dit zal zorgen voor verlaging van de kosten en een efficiënter werkend bedrijf.\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>','De voordelen van data analyse inzetten bij onderhoud','1601','inherit','closed','closed','','236-revision-v1','','','2022-01-31 09:35:58','2022-01-31 09:35:58','',236,'https://thingsway.media2netdev.nl/?p=348',0,'revision','',0),(349,1,'2022-01-31 09:35:59','2022-01-31 09:35:59','Onderhoud is een belangrijke factor om de kwaliteit van een bedrijf te waarborgen. In sommige gevallen bepaalt het zelfs het succes van een bedrijf op de lange termijn. Wanneer een bedrijf niet aan onderhoud doet, of minimaal, dan kan dit instabiliteit veroorzaken. De productie kan voor een gedeelte, of volledig, onderbroken worden. Machines die defect zijn, of een algehele storing, zal voor de meeste bedrijven een kostbare aangelegenheid worden. Dit geldt niet alleen voor bedrijven die veel werken met machines, het geldt ook voor onderhoudsbedrijven en vastgoed eigenaren, zoals woningcorporaties.\n\nEen storing zorgt voor meerdere problemen en kosten. Zo zal de productie stil liggen, arbeidskosten zullen stijgen, u heeft kosten op gebied van reparaties en onderdelen. Bovendien komen daar regelmatig bijkomende kosten bij door schade en eventuele juridische kosten. Dit zijn slechts enkele voorbeelden waar een bedrijf in de loop van de tijd mee te maken krijgt, zeker wanneer deze geen betrouwbaar onderhoudsplan heeft. Dankzij de opkomst van het Internet of Things, heeft u juist nu de mogelijkheid om een zeer accuraat onderhoudsplan op te stellen.\n<h2>De verschillende soorten onderhoud</h2>\nUw bedrijf kan op meerdere manieren aan onderhoud doen. Wanneer u een gedegen onderhoudsplan heeft dan zal dit een combinatie zijn van verschillende vormen van onderhoud. De verschillende vormen van onderhoud kunnen globaal worden ingedeeld in twee vormen; reactief onderhoud en proactief onderhoud. In geval van reactief onderhoud wordt er pas onderhoud gepleegd wanneer er een storing of defect is opgetreden. U reageert op een melding van een machine of klacht van bijvoorbeeld een bewoner. Het nadeel hiervan is dat u achter de feiten aanloopt. Dit soort onderhoud kunt u het best toepassen op makkelijk vervangbare en niet kostbare onderdelen.\n\nDe andere vorm van onderhoud is proactief onderhoud. Van proactief onderhoud bestaan meerdere vormen zoals preventief, periodiek en planmatig onderhoud. Deze vormen van onderhoud zou u kunnen zien als voorspellend onderhoud. De onderhoudswerkzaamheden worden namelijk gedaan op basis van voorspellingen. Gegevens als aanwijzingen van fabrikant, ervaringen en metingen uit het verleden bepalen de planning van dit onderhoud. Dit zijn altijd gegevens uit het verleden, bovendien kunt u pas echt een gedegen plan opstellen wanneer u veel gegevens heeft van een machine of object. Dit is de reden waarom er nog steeds storingen voorkomen, ondanks preventief en periodiek onderhoud. Dankzij het Internet-of-Things is dat nu op te lossen, namelijk door voorspellend onderhoud toe te passen op basis van real-time data.\n<h2>Voorspellend onderhoud op basis van real-time data</h2>\nDe laatste jaren is het Internet-of-Things enorm in opkomst in de industrie, maar ook bij bedrijven die veel met maintenance te maken hebben. Het Internet-of-Things biedt namelijk enorme mogelijkheden op gebied van onderhoud en monitoring van machines en objecten. Heeft u geen idee wat het Internet-of-Things is? Eenvoudig uitgelegd kunt u het IoT zien als slimme apparaten die gegevens verzamelen. Zonder het misschien te beseffen treft u ze overal om u heen aan; in de thermostaat, in magnetrons, koelkasten etc.\n\nEen Internet-of-Things-systeem kan ook heel goed toegepast worden voor bedrijven die met onderhoud te maken hebben. Stel dat u een object of machine heeft dat van groot belang is voor uw bedrijf, of er is een onderdeel dat regelmatig defect raakt. Dit zou u kunnen laten monitoren door een Iot-systeem. Dit is een apparaat dat is voorzien van sensoren en een directe internetverbinding. Het monitoren gebeurt continu, dit levert enorm veel gegevens op. Veranderingen in de omgeving worden door de sensor geregistreerd en via de directe internetverbinding verstuurt naar computer, laptop of smartphone. Deze veranderingen kunnen betekenen dat een storing zal optreden, u wordt daarom vooraf gewaarschuwd. U kunt dit zien als voorspellend onderhoud door middel van real-time gegevens via het Iot-systeem.\n<h2>Voordelig datasysteem in één dag geïnstalleerd</h2>\nSalland Electronics heeft de Thingsway ontwikkeld. De Thingsway is een Iot-apparaat dat op veel gebieden van onderhoud in te zetten is. Het nadeel van de meeste Iot-systemen is dat ze log zijn wat inzetbaarheid betreft. Vaak duurt het erg lang voordat een systeem ontwikkeld is.\n\nHet voordeel van de Thingsway is dat het een soort ‘kant en klaar’ product is. Aanpassingen die gedaan moeten worden aan het apparaat hangen af van uw wensen en het te meten proces. Deze aanpassingen worden razendsnel door Salland Electronics uitgevoerd. U kunt zelfs binnen een dag voorzien zijn van een voordelig datasysteem. Ook de internetverbinding wordt door Salland Electronics verzorgd. U kunt kiezen uit verschillende bekende providers.\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>','Voordelig datasysteem in één dag geïnstalleerd','1607','inherit','closed','closed','','238-revision-v1','','','2022-01-31 09:35:59','2022-01-31 09:35:59','',238,'https://thingsway.media2netdev.nl/?p=349',0,'revision','',0),(350,1,'2022-01-31 09:36:00','2022-01-31 09:36:00','Er zijn veel bedrijven die met onderhoudsactiviteiten te maken hebben. Dan kan het gaan om productiebedrijven die veel met machines werken en maintenance bedrijven, maar ook vastgoedbedrijven, zoals woningcorporaties. Er bestaan verschillende strategieën om onderhoud toe te passen, een voorbeeld hiervan is preventief onderhoud. Helaas zorgt preventief onderhoud er niet voor dat storingen nooit meer voorkomen. Wanneer er een storing plaatsvindt bij een machine, object of proces, dan is het verstandig om een storingsanalyse uit te voeren.\n<h2>Wat is een storingsanalyse?</h2>\nEen storingsanalyse is een onderzoek dat gedaan wordt om achter de oorzaak van de storing te komen. Het uiteindelijke doel van het onderzoek is om maatregelen te kunnen nemen die ten eerste het probleem oplossen en ten tweede storingen in de toekomst voorkomen. In vrijwel alle takken van de productie-industrie worden storingsanalyses gedaan om defecten aan machines, objecten en producten in de toekomst te voorkomen. Een storingsanalyse wordt tevens uitgevoerd om mens en milieu te beschermen tegen potentieel gevaarlijke situaties.\n<h2>Redenen om een storingsanalyse uit te voeren</h2>\nHet uitvoeren van een storingsanalyse biedt voor een bedrijf een aantal voordelen. Enkele voordelen hiervan zijn financiële voordelen, juridische en voordelen die met de veiligheid te maken hebben. De resultaten die uit de storingsanalyse komen kunnen namelijk zorgen voor bepaalde inzichten en mogelijkheden. We bespreken de belangrijkste.\n<h2>Inzicht in de hoofdoorzaak van de storing</h2>\nHet fundamentele onderdeel van een storingsanalyse uitvoeren is om erachter te komen wat de hoofdoorzaak van de storing is. Tijdens de storingsanalyse wordt gezocht naar gegevens die kunnen vaststellen waarom de storing is opgetreden. Was het een gevolg van een fabricagefout, een materiaalfout, slijtage of fout gebruik van het object?\n<h2>Hoe kunt u storingen voortaan voorkomen?</h2>\nWanneer de oorzaak van de storing is vastgesteld, dan kunnen er maatregelen genomen worden om te zorgen dat het probleem niet meer op zal treden. Corrigerende maatregelen kunnen zijn; gebruik van andere onderdelen, meer preventief onderhoud en verbetering van het productieproces.\n\n<img class=\"alignnone size-full wp-image-1612\" src=\"https://thingsway.nl/wp-content/uploads/2020/10/voordelen-storingsanalyse.jpeg\" alt=\"storingsanalyse \" width=\"1880\" height=\"1251\" />\n<h2>Verbeteren van toekomstige producten en processen</h2>\nDankzij een goed inzicht in de storing van een proces of machine, kunt u het productieproces verbeteren, maar ook het ontwerp van een machine of product. Dit zorgt voor meer effectiviteit, omdat het probleem zich niet meer voordoet, maar ook voor lagere kosten. Denkt u dan aan de kosten voor het vervangen van onderdelen en de tijd van uitval. Vergeet u ook niet eventuele kostbare juridische stappen of de reputatie van uw bedrijf.\n<h2>Voorkom kosten door defecten en eventuele boetes</h2>\nStoringen kunnen kostbaar zijn. Dat kunnen kosten zijn door uitval, onderhoud en stilstand van de productie. Juridische kosten kunnen zelfs een gevolg zijn van een storing. Door een storingsanalyse te laten uitvoeren kunt u zulke problemen voorkomen. Tevens kunt u voorkomen dat mogelijke storingen in de toekomst optreden.\n<h2>U voldoet aan de normen voor producten en activa</h2>\nEen storingsanalyse kan u in de toekomst helpen om aan normen te voldoen voor een bepaald productieproces, voor componenten, producten en machines.\n<h2>De aansprakelijkheid voor de storing bepalen</h2>\nEen storingsanalyse laat u vooral uitvoeren om de hoofdoorzaak te bepalen. Wanneer u achter de hoofdoorzaak gekomen bent, dan kunt u ook de aansprakelijkheid voor de storing bepalen. Helaas is dit soms nodig in gevallen van storingen. Dit kan u beschermen tijdens eventuele rechtszaken, maar kan ook in gerechtelijke procedures gebruikt worden om uw gelijk te krijgen.\n<h2>Hoe wordt een storingsanalyse uitgevoerd?</h2>\nEen storingsanalyse wordt uitgevoerd wanneer de storing heeft plaatsgevonden. Technici zullen zoeken naar de defecten en na analyse bepalen waardoor de storing heeft plaatsgevonden. U heeft dus altijd te maken met gegevens die achteraf geïnterpreteerd worden. Zou het bepalen van de oorzaak van een storing niet eenvoudiger zijn wanneer u beschikt over real-time data die u later kunt analyseren? Sterker nog, zou het niet nog handiger zijn wanneer u beschikt over real-time data die ervoor zorgt dat een storing voorkomen kan worden?\n\nZo’n storingsanalyse zou u kunnen laten uitvoeren door middel van een Internet-of-Things oplossing.\n<h2>De Thingsway, een IoT-oplossing</h2>\nDe Thingsway is een IoT-oplossing die in te zetten is vele takken van onderhoud en productie. Via sensoren kan de Thingsway bepaalde processen continu monitoren. Dit zorgt voor enorm veel data en inzichten in de werking, of eventuele storing, van een proces of product. Wanneer er veranderingen optreden in dit proces, dan zullen de sensoren dit waarnemen. Via een rechtstreekse internetverbinding worden deze real-time gegevens verstuurd.\n\nDeze enorme hoeveelheid data geeft na het analyseren een veel beter inzicht in de werking en de eventuele reden van de storing. Een storing kan zelfs voorkomen worden wanneer de Thingsway wordt ingezet om een kritiek proces te monitoren.\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>','Wat is een storingsanalyse, en wat zijn de mogelijkheden?','1610','inherit','closed','closed','','240-revision-v1','','','2022-01-31 09:36:00','2022-01-31 09:36:00','',240,'https://thingsway.media2netdev.nl/?p=350',0,'revision','',0),(351,1,'2022-01-31 09:36:01','2022-01-31 09:36:01','Veel bedrijven zijn op zoek naar het antwoord op de volgende vraag: ‘Hoe kunnen we toch onze onderhoudskosten verlagen?’\n\nEen bedrijf kan wat omzet betreft heel goed draaien, maar wanneer de onderhoudskosten heel hoog zijn dan drukt dat flink op de winstmarges. Een bedrijf kan pas bloeien wanneer de onderhoudskosten goed in bedwang worden gehouden. Heeft u een bedrijf dat veel te maken heeft met onderhoud, zoals een productiebedrijf, een woningcorporatie of een maintenance bedrijf? Dan kunt u vast wel wat slimme tips gebruiken om de onderhoudskosten te verlagen. Wilt u besparen? Begin dan vandaag nog!\n<h2>Het doel van onderhoud</h2>\nHet doel van onderhoud is om de volledige beschikbaarheid van apparatuur, voorzieningen, objecten en faciliteiten te garanderen. Dit tegen optimale kosten en onder een aanvaardbare standaard van kwaliteit, veiligheid voor mensen en milieu.\n\nOm te voldoen aan al deze aspecten werkt een bedrijf met een gedegen onderhoudsplan. Voor een bedrijf dat veel te maken heeft met vastgoed of bouwkundig onderhoud, is het van belang om proactief onderhoud te voeren. Proactief onderhoud zorgt ervoor dat u niet achter de feiten aanloopt. U heeft kennis van zaken van uw vastgoed en gebouwen en maakt daar een onderhoudsplan voor. Bedrijven die veel te maken hebben met maintenance van machines voeren storingsafhankelijk en preventief onderhoud uit.\n\nDeze manieren van onderhoud zijn de meest gangbare manieren om de kosten van onderhoud zo laag mogelijk te houden. Toch kunt u zeker nog meer doen om de onderhoudskosten te verlagen. We geven u vijf tips.\n<h2>Tip 1: Storingen voorkomen</h2>\nDe logische eerste tip om de onderhoudskosten te verlagen is door middel van het voorkomen van storingen. Dit is niet alleen vanwege de hoge kosten voor het repareren van een defect, maar het kan ook de activiteiten van een bedrijf vertragen of zelfs stilleggen.\n\nHoe kunt u storingen voorkomen? U doet vanzelfsprekend al aan preventief onderhoud, maar heeft u daar echt een goede strategie voor? Een geautomatiseerd systeem voor uw onderhoudswerkzaamheden biedt u een ideale manier om alle nodige handelingen op gebied van onderhoud goed te volgen, beoordelen en plannen.\n<h2>Tip 2: Gedegen beheer van uw inventaris</h2>\nLigt de gemiddelde tijd voor een reparatie in uw bedrijf hoog? Een reden hiervoor kan zijn dat u niet genoeg reserveonderdelen in uw voorraad heeft. U kunt dit oplossen door meer reserveonderdelen aan te schaffen; vaak kunt u aantrekkelijke prijzen afspreken met leveranciers als u onderdelen in bulk aanschaft.\n\nEen ander manier van besparen op onderdelen is door ervoor te zorgen dat reserveonderdelen verwisselbaar zijn. Het is erg handig wanneer verschillende onderdelen op meerdere machines of objecten te gebruiken zijn. Een fabrikant zal ook eerder technische hulp bieden wanneer al uw onderdelen (of machines) van hem afkomstig zijn.\n<h2>Tip 3: Train uw team</h2>\nDe kans is groot dat u voor onderhoud een technisch team heeft of een maintenance bedrijf inhuurt. Om de onderhoudskosten te verlagen zou u uw gehele team kunnen trainen in de technische werking van een machine. Dit zorgt ervoor dat eventuele storingen veel eerder kunnen worden opgemerkt en zelfs verholpen. Hierdoor zal uitval van productie verholpen worden en bovendien kostbare en tijdrovende reparaties vermeden.\n\n<img class=\"alignnone size-full wp-image-1616\" src=\"https://thingsway.nl/wp-content/uploads/2020/10/team-trainen-scaled.jpg\" alt=\"verlagen onderhoudskosten\" width=\"2560\" height=\"1707\" />\n<h2>Tip 4: Verlengen van garanties of verzekeringen</h2>\nHelaas werkt niets voor altijd en feilloos. Alles is nu eenmaal aan slijtage onderhevig. Daarom is het zeer verstandig om de duurste apparatuur of de meest kwetsbare onderdelen te verzekeren. Ook kunt u vaak bij fabrikanten de garantie verlengen van sommige onderdelen of machines.\n\nOm te bepalen welke onderdelen van een gebouw of machines van een bedrijf het belangrijkst of meest kwetsbaar zijn, zou u het onderhoudsteam kunnen raadplegen. Deze hebben vaak het beste inzicht op de werking en slijtage. U kunt er zelfs voor kiezen om slechts enkele specifieke onderdelen te verzekeren. Een juist beeld krijgen van de kwetsbare en kostbare onderdelen en deze verzekeren, of de garantie verlengen, kan u flink wat onderhoudskosten schelen.\n<h2>Tip 5: Kies voor een IoT-oplossing</h2>\nOm een goed beeld te krijgen van een onderdeel, machine of object is het niet nodig om ze persoonlijk te analyseren met pen en papier op schoot. De werking van een bepaald voorwerp, en het nodige onderhoud om deze werking te garanderen, wordt voorspeld aan de hand van gegevens. Ten eerste de gegevens van de leverancier en daarnaast door middel van ervaring en periodiek onderhoud.\n\nEen veel beter inzicht in de werking van een voorwerp krijgt u door middel van een Internet of Things-oplossing. Dit is een apparaat die continu de werking van een object monitort via sensoren. Via een internet verbinding worden deze gegevens doorgegeven, waarna ze geanalyseerd kunnen worden. Dit geeft een zeer nauwkeurig inzicht in de werking, slijtage en eventueel uitval van een object.\n\nEen mooi voorbeeld van zo’n IoT-oplossing is de Thingsway van Salland Electronics.\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>','De 5 beste tips voor het verlagen van onderhoudskosten','1614','inherit','closed','closed','','242-revision-v1','','','2022-01-31 09:36:01','2022-01-31 09:36:01','',242,'https://thingsway.media2netdev.nl/?p=351',0,'revision','',0),(352,1,'2022-01-31 09:36:03','2022-01-31 09:36:03','Er is een enorme opmars bezig in het verzamelen van interessante data. Data is belangrijk voor elk bedrijf of elke instelling. Voldoende data kan ervoor zorgen dat u goed inzicht heeft in de werking van een object, maar ook in de productiviteit en effectiviteit van een object, of zelfs uw gehele bedrijf. Interessante informatie wordt over het algemeen verzameld door het observeren van een bepaald proces of object, zoals tijdens een steekproef, controle of onderhoud.\n\nHet Internet of Things heeft een wereld aan mogelijkheden blootgelegd op gebied van het verzamelen van interessante data. Een continu proces van verzamelen van data zorgt voor veel meer informatie. Dit biedt mogelijkheden die tot voor kort ondenkbaar waren.\n<h2>Wat is een IoT-oplossing?</h2>\nWat is het Internet of Things? Waarop wordt deze revolutie op gebied van verzamelen van transparante en interessante data voortgestuwd? Op een eenvoudige manier kan een IoT-oplossing worden uitgelegd als ‘een apparaat met sensoren dat verbinding maakt met het internet’.\n\nDeze sensoren kunnen een proces monitoren, interessante data verzamelen en deze gegevens in realtime sturen waar u maar wilt. Dat kan naar een werknemer op de werkvloer, maar bijvoorbeeld ook naar het hoofdkantoor van uw bedrijf. Deze gegevens kunnen geanalyseerd worden, of gecombineerd met gegevens van andere objecten, magazijnen of fabrieken. Dit kan over de hele wereld gecommuniceerd worden en geeft u de ideale mogelijkheid om goed op de hoogte te blijven van al uw producten, processen en benodigd onderhoud.\n<h2>De Thingsway</h2>\nEen IoT-oplossing die zulke interessante informatie kan verzamelen is de Thingsway. Dit is een basis IoT- sensor die op vele manieren kan worden ingezet. Zo kan de Thingsway bijvoorbeeld in de buitenlucht worden ingezet om metingen uit te voeren aan dakgoten. Maar de Thingsway is ook voor industriële doeleinden in te zetten, bijvoorbeeld om continue metingen te verrichten aan de werking van een apparaat of machine.\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\n<h2>Wat voor interessante data wordt verzameld?</h2>\nEen IoT-oplossing werkt dus via sensoren. Een sensor kunt u zien als een kunstmatig zintuig. Een IoT-apparaat monitort via een sensor veranderingen in de omgeving en deze informatie wordt verzameld. Als voorbeeld kunnen we bijvoorbeeld de warmte in een omgeving meten; dit fysieke getal wordt omgezet in een signaal. De metingen in de fysieke omgeving worden vertaald in data en gestuurd naar een digitaal apparaat. Niet alleen warmte kan worden gemeten door sensoren, maar ook beweging, geluid, druk, locatie, vochtigheid, etc. Al deze data kunt u onmiddellijk aflezen, maar ook naar een computer, smartphone of tablet sturen. Zodoende kunt u de gegevens bekijken waar u maar wilt.\n\nNu vraagt u zich misschien af waarom deze data zo interessant is? Meten is weten, zo luid het spreekwoord. Door het verzamelen van dit soort interessante data kunt u als bedrijf een flinke stap voorwaarts maken. Het kan zorgen voor meer effectiviteit en flinke kostenverlagingen.\n<h2>Wat kunt u doen met deze interessante data?</h2>\nHet verzamelen van interessante data via een IoT-oplossing, zoals de Thingsway, kan heel interessant zijn op verschillende gebieden. Op deze wijze kunt u bijvoorbeeld de werking van een machine zeer goed leren kennen. Hoe werkt de machine het zuinigst of meest effectief? Wat is de maximale capaciteit? Wanneer kan er storing verwacht worden? Is onderhoud echt nodig? Op welke temperatuur slaat de machine vast?\n\nPeriodiek onderhoud wordt vaak gepleegd op basis van voorspellingen van de leverancier en door onderhoudsmetingen. Een IoT-oplossing zorgt ervoor dat u continu informatie verzameld. Dit zorgt voor veel meer data en een beter inzicht in de werking van een machine, een object of proces.\n\nOok op gebied van productie en verbruik is data heel belangrijk. Na het analyseren van de metingen heeft u een zeer gedetailleerd beeld van een productieproces en weet u precies hoeveel er verbruikt wordt. Dit geeft u de mogelijkheid om eventueel aanpassingen te doen waar dat nodig is. Dit kan leiden naar een effectievere inzet van personeel, verbruik van materiaal en plegen van onderhoudswerkzaamheden.\n\nHet verzamelen van interessante data via een IoT-oplossing is de manier om uw bedrijf te moderniseren en automatiseren. Vooral als u een bedrijf heeft die veel te maken heeft met maintenance en onderhoud, kan het verzamelen van interessante data heel lucratief zijn. Heeft u zo’n bedrijf? Kijkt u eens naar de mogelijkheden van de Thingsway en wat dit voor uw bedrijf kan betekenen.\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>','Verzamel interessante data met de Thingsway','1620','inherit','closed','closed','','244-revision-v1','','','2022-01-31 09:36:03','2022-01-31 09:36:03','',244,'https://thingsway.media2netdev.nl/?p=352',0,'revision','',0),(353,1,'2022-01-31 09:36:04','2022-01-31 09:36:04','Een van de grote uitdagingen van een bedrijf is om achter de exacte cijfers van verbruik te komen. Welke machines verbruiken het meest, hoeveel precies, en onder welke omstandigheden? Als bedrijf wilt u natuurlijk goed op de hoogte zijn van deze cijfers, zodat u efficiënter zou kunnen gaan produceren. Niet alleen vanwege de kosten, maar ook vanwege milieuredenen. Tegenwoordig is het heel belangrijk om er als bedrijf voor te zorgen dat het productieproces zo min mogelijk belastend is voor het milieu. De CO2 afdruk van een bedrijf verlagen is één van de prioriteiten.\n\nDe exacte cijfers van verbruik achterhalen kan lastig zijn, vooral wanneer een pand groeit, of als er nieuwe machines of voorraden bijkomen. Wat moet er gemeten worden, wanneer en waar?\n\nBedrijven die kennis en inzicht hebben in hun verbruik hebben een grotere productiviteit. Deze kennis en inzicht worden verkregen door middel van metingen en monitoring. Niet alleen de productiviteit is hoger, maar ook de betrokkenheid van medewerkers wordt groter door het tonen van exacte cijfers. Dit is belangrijk voor u als bedrijf om concurrerend te blijven.\n\nWilt u de efficiëntie van uw bedrijf op het gebied van verbruik verbeteren? Dan moet het verbruik van apparaten en machines ter plekke gemeten worden, en bovendien continu. Dit kan op industrieel gebied, maar ook op gebied van dienstverlening en maintenance. Slimme automatisering neemt steeds meer toe, in alle professionele takken. Dit zorgt voor een beter inzicht en grotere efficiëntie, van manager tot de werkvloer.\n<h2>Efficiënter werken door monitoring</h2>\nUit ervaring blijkt dat wanneer er actief gewerkt wordt aan het efficiënter maken van een proces dit 8% extra besparingen oplevert. Dit komt vanwege het op tijd detecteren van eventuele storingen in de werking van een machine of een productie proces.\n\nWanneer een machine continu gemonitord wordt kan een operator, een productieteam of een onderhoudsbedrijf snel in actie komen wanneer een machine storing vertoont, of data vertoont die naar een eventuele storing kunnen leiden.\n\nContinue monitoring kan worden gedaan via een IoT- oplossing, IoT staat voor Internet-of-Things. Een sensor die verbonden is met het internet houdt het gehele proces constant in de gaten. Zodoende kan het verbruik van een machine of apparaat zeer exact gemeten worden.\n<h2>Verbruik meten van machines en apparaten</h2>\nHet verbruik meten van een machine of apparaat via een Internet-of-Things-oplossing kan op veel verschillende manieren gedaan worden. Het soort apparaat, de machine of datgene wat gemeten moet worden, bepaalt wat voor soort sensor er nodig is. Sensoren bestaan in veel verschillende soorten; temperatuursensoren, druksensoren, lichtsensoren en versnellingssensoren zijn slechts enkele voorbeelden.\n\nEen of meerdere sensoren van een IOT-oplossing meten continu het verbruik van een machine. Deze gegevens worden doorgegeven via een internet aansluiting. Deze gegevens kunnen direct worden ingezien, maar ook achteraf worden geanalyseerd. Een voorbeeld van zo’n IoT-sensor is de Thingsway.\n<h2>De Thingsway</h2>\nDe Thingsway is een IoT-sensor die ontwikkeld is door Salland Electronics. Deze sensor kan worden ingezet om veel soorten metingen uit te voeren. Speciaal voor metingen van machines is er ook een industriële versie beschikbaar. Deze is geschikt gemaakt voor DIN-rail montage, bovendien is het voorzien van meerdere aansluitmogelijkheden. De Thingsway kan heel snel aangepast worden op de wensen en werkzaamheden van uw bedrijf. Gecombineerd met het energiezuinige ontwerp (de batterij gaat gegarandeerd 10 jaar mee), krijgt u een product die van grote waarde kan zijn voor de efficiëntie van uw bedrijf.\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\n<h2>Gebruik maken van de gegevens</h2>\nHet gebruik maken van een IoT-oplossing geeft u de mogelijk om op een zeer precieze manier het verbruik te meten van een apparaat of machine. U krijgt relevante gegevens van verbruik en door deze te monitoren en te analyseren krijgt u de mogelijkheid om het productieproces te optimaliseren. Door meer inzicht in verbruik kunt u eventueel aanpassingen doen in het productieproces, tevens kunt u verandering van gedrag van een machine leren begrijpen en hierop uw beleid aanpassen. Dit geldt op gebied van productie, maar ook op gebied van onderhoud.\n\nHet meten en monitoren van het verbruik is cruciaal voor bedrijven die hun efficiëntie en productie willen verbeteren. Voor industriële bedrijven, maar ook voor bedrijven in maintenance, geldt dat het meten van verbruik en het verminderen daarvan geen optie meer is, maar een vast onderdeel van het beleidsplan. Een IoT-oplossing zoals de Thingsway, kan u helpen om uw plannen uit te voeren.\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>','Waarom is verbruik meten van groot belang voor uw bedrijf','1623','inherit','closed','closed','','246-revision-v1','','','2022-01-31 09:36:04','2022-01-31 09:36:04','',246,'https://thingsway.media2netdev.nl/?p=353',0,'revision','',0),(354,1,'2022-01-31 09:36:05','2022-01-31 09:36:05','Flitsende moderne technologieën halen de krantenkoppen, maar er is een stille revolutie gaande op het gebied van metingen van gewicht. De digitale evolutie van de weegschaal kan een revolutie betekenen voor verschillende takken van de industrie. Weegschalen ondergaan een razendsnelle opmars die zorgt voor snellere en efficiëntere metingen van gewicht.\n\nDe bescheiden weegschaal kennen we allemaal, vaak weggestopt in de badkamer of in de keuken. Het is echter een onmisbaar item voor verschillende professionele takken zoals horeca, landbouw, industrie en (lucht)havens. Tot kort geleden waren metingen van gewicht een vergeten stukje technologie, maar het Internet of Things (IoT) zorgt voor een moderne versie van de traditionele metingen van gewicht. Het beter kunnen beheren van dagelijkse weeg taken biedt bedrijven de mogelijkheid om in positieve zin het bedrijf te transformeren. Er is een snelle technologische opmars bezig op gebied van het meten van gewicht. Dit zorgt voor snellere en efficiëntere metingen. Maar hoe werken die metingen van gewicht via een IoT-oplossing eigenlijk?\n<h2>Hoe worden IoT-metingen van gewicht uitgevoerd?</h2>\nEen IoT-oplossing die gewicht metingen uitvoert zijn voorzien van een sensor. Zo’n sensor wordt een Load Cell genoemd, deze zet fysieke kracht om in elektrische signalen. Door middel van een draadloze aansluiting met het internet kunnen deze elektrische gegevens doorgegeven worden in vorm van data. Deze gegevens bieden de mogelijkheid om, waar u ook wilt, gegevens in te zien en te analyseren.\n\nEen voorbeeld van een IoT-oplossing is de Thingsway, deze werd ontwikkeld door Salland Electronics. Het grote voordeel van de Thingsway is zijn multifunctionaliteit; het is een basisproduct die aan te passen is naar de wensen van elk bedrijf. Binnen korte tijd kan de behuizing, maar kunnen ook de type sensoren, aangepast worden op het te meten object. Zo kan de Thingsway dus ook ingezet worden om metingen van gewicht uit te voeren. U kunt de Thingsway zien als een slimme weegschaal.\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\n<h2>Nieuwe normen door gebruik van slimme weegschalen</h2>\nMetingen van gewicht worden gedaan om de gebruiker gegevens te laten verzamelen. Door deze gegevens te analyseren kunnen wijzigingen worden gedaan, indien nodig. Controle op gewicht kan essentieel zijn, of dat nu gaat om de gezondheid van iemand, het beladen van vracht of het verzenden van pakketten.\n\nDoor draadloos verbonden weegschalen zijn bedrijven beter in staat om de gegevens te bekijken zonder er fysiek in aanraking mee te komen. Deze gegevens kunnen eenvoudig worden verwerkt in tabellen en grafieken. Deze beschikbare informatie geeft u de mogelijkheid om weloverwogen beslissingen te maken. Dit komt ten goede aan de controle van kwaliteit, efficiëntie, automatisering, verspilling van goederen, onderhoud en kostenreductie.\n<h2>Het voordeel van een dynamische weegschaal</h2>\nEen dynamische weegschaal weegt een bepaald object wanneer het in beweging is. Dit werkt door de combinatie van een beweging sensor en een sensor voor metingen van gewicht. Dit kan heel handig zijn wanneer u bijvoorbeeld een wagenpark heeft. Een dynamische weegschaal is veel efficiënter dan een continue weegschaal; er is geen handmatige bediening meer vereist.\n\nWerkt u in een industrie waar metingen van gewicht worden gedaan op bewegende objecten? Dan is een dynamische weegschaal de perfecte oplossing voor u.\n<h2>Metingen van gewicht van bagage en passagiers</h2>\nOok in de luchtvaart is het van groot belang om metingen van gewicht uit te voeren. Iedereen weet dat de bagage tijdens het inchecken wordt gewogen. Dit is van belang omdat het gewicht van een vliegtuig onder andere bepaalt hoeveel brandstof er in het vliegtuig moet. Meer gewicht betekent nu eenmaal meer brandstof en meer kosten. Brandstofkosten liggen ook in de luchtvaart hoog, bovendien is het ook voor de luchtvaart van belang om de CO2-uitstoot te verlagen.\n\nDit is de reden waarom er in de luchtvaart wordt gesproken over de plannen om passagiers te gaan wegen. Zodoende krijgt de maatschappij een veel beter en betrouwbaar beeld van het totale gewicht. Op zo’n manier kan de maatschappij exact uitrekenen hoeveel brandstof er nodig is. Dit verlaagt de kosten aanzienlijk.\n\nNatuurlijk zullen de maatschappijen u niet vragen om in bijzijn van iedereen naast uw bagage te gaan staan. Een discrete IoT-oplossing die metingen uitvoert op uw gewicht kan daarop het antwoord zijn. Een meting van gewicht die onmiddellijk, maar discreet, in data aan de maatschappij geleverd wordt.\n\n<img class=\"alignnone size-full wp-image-1630\" src=\"https://thingsway.nl/wp-content/uploads/2020/10/meting-gewicht-scaled.jpg\" alt=\"gewicht metingen industrie \" width=\"2560\" height=\"1920\" />\n<h2>Metingen van gewicht in terminals en machine-industrie</h2>\nTijdens het laden en lossen van goederen kan een gewichtsmeting via een IoT-oplossing van grote waarde zijn. Door nieuwe technologieën kunnen weegschalen op hoge snelheden materialen en goederen nauwkeurig afmeten. Dit zorgt voor een betere beheersing van alle goederen; menselijke fouten kunnen hierdoor worden verminderd.\n\nOok in de machine-industrie worden steeds meer IoT-oplossingen toegepast. Zo worden bijvoorbeeld laders voorzien van weeg technologie, deze systemen geven de bestuurder continu informatie over het proces. Dit zorgt ervoor dat een vrachtwagen iedere keer geladen wordt met het juiste gewicht.\n\nU kunt veel efficiënter werken wanneer u de mogelijkheid heeft om constant nauwkeurig te kunnen laden. Dit zorgt voor bovendien voor meer productiviteit. U medewerkers kunnen eenvoudig realtime gegevens inzien die accuraat zijn.\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>','Gewicht meten en monitoren','1626','inherit','closed','closed','','248-revision-v1','','','2022-01-31 09:36:05','2022-01-31 09:36:05','',248,'https://thingsway.media2netdev.nl/?p=354',0,'revision','',0),(355,1,'2022-01-31 09:36:06','2022-01-31 09:36:06','[et_pb_section][et_pb_row][et_pb_column type=\"4_4\"][et_pb_text]\n\nAlle gebouwen zijn onderhevig aan slijtage en moeten daarom onderhouden worden. Installaties, daken, betonvloeren, kozijnen; helaas bestaat er niets wat voor altijd mee gaat. Ook kan het zo zijn dat bewoners of gebruikers van een bepaald gebouw andere wensen hebben. In zo’n geval dient er onderhoud gepleegd te worden om deze wensen in veranderingen om te zetten.\n\nOm gebouwen gedegen te kunnen onderhouden is een onderhoudsplan nodig. Hierin staan onderhoudsplannen voor de toekomst (zoals het vervangen van een dak) en er staan mogelijke toekomstige investeringen in, zoals bijvoorbeeld zonnepanelen. Wat natuurlijk ook in het plan staat is regelmatig terugkerend onderhoud, zoals het schilderen van kozijnen. Zo’n onderhoudsplan wordt opgesteld door een bouwkundige. Aan de hand van een meting van de conditie van het betreffende gebouw, en de eventuele wensen van gebruikers, bewoners, beheerders of eigenaren, wordt een planning gemaakt voor een bepaald aantal jaren. Dit soort onderhoud wordt conditie gestuurd onderhoud genoemd, dit is een vorm van proactief onderhoud.\n<h2>De voordelen van proactief onderhoud</h2>\nBent u eigenaar of beheerder van een bepaald gebouw? Dan kunt u er natuurlijk voor kiezen om alleen onderhoud te plegen wanneer dit echt nodig is, bijvoorbeeld na een klacht van een bewoner, of wanneer een bepaald deel van het gebouw een defect vertoont. Maar dit heeft veel nadelen, u loopt als het ware achter de feiten aan.\n\nEen proactieve houding als beheerder of eigenaar zorgt ervoor dat u eventuele defecten voor bent, tevens draagt het bij aan de waarde en betrouwbaarheid van uw bedrijf en het gevoel van veiligheid voor bewoners of gebruikers. De actieve houding is de reden waarom dit proactief onderhoud genoemd wordt, een onderdeel daarvan is conditie gestuurd onderhoud.\n<h2>Wat houdt conditie gestuurd onderhoud in?</h2>\nDe conditie van een bepaald object (gebouw) bepaalt wat voor onderhoud er direct, of in de toekomst, uitgevoerd moet worden. Dit is in eenvoudige woorden uitgelegd wat conditie gestuurd onderhoud is. Om deze conditie te bepalen moeten er metingen gedaan worden. De onderdelen van het gebouw die onderhoudsgevoelig zijn worden onderzocht op werking, slijtage en conditie.\n\nUit deze metingen komt een bepaalde conditie van het onderzochte object naar voren. Voldoet deze niet aan de minimale eisen, dan moet er onderhoud gedaan worden aan het object in kwestie.\n\nHet kan zijn dat het resultaat van een onderzoek is dat het object nog in nieuwstaat is, maar het kan ook zo zijn dat het object in zo’n slechte staat verkeerd dat het grote risico’s met zich mee brengt. Er zitten nog 4 mogelijke condities tussen deze uitersten.\n\n<img class=\"size-full wp-image-1635 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/10/conditiegestuurd-onderhoud.jpg\" alt=\"conditie gestuurd onderhoud \" width=\"1000\" height=\"800\" />\n<h2>De conditiemeting</h2>\nOver het algemeen wordt de conditie van een gebouw bepaald door middel van een conditiemeting. Een vastgelegde meet- en registreer methode wordt gebruikt om deze metingen betrouwbaar uit te voeren. Deze meting wordt gedaan door gespecialiseerde inspectiebureaus. Deze stellen de staat vast van het gehele gebouw, elk detail wordt onderzocht op staat en werking. De conditie van het gehele gebouw wordt daarmee een optelsom van al zijn componenten. Dit legt onmiddellijk de tekortkomingen van zo’n algemene conditiemeting vast. Individuele metingen zijn vaak van groter belang dan de algemene staat van het gebouw. De algemene staat van een gebouw kan als goed beoordeeld worden door een conditiemeting, maar dan nog kan bijvoorbeeld de dakgoot veroudering vertonen en binnenkort voor problemen en kosten gaan zorgen.\n\nEen ander soort meting kan u hiervan behoeden, namelijk continue metingen met een Internet of Things toepassing.\n<h2>Conditie gestuurd onderhoud op basis van continue metingen</h2>\nHoe handig zou het zijn wanneer u de conditie van een bepaald object continu kon monitoren? In zo’n geval kunt u conditie gestuurd onderhoud uitvoeren wanneer dit echt nodig is. U voert geen onderhoud uit op basis van voorspellingen, maar op accurate data.\n\nHet zijn altijd bepaalde onderdelen van een gebouw die meer onderhoud vergen dan andere. Misschien is het moeilijk te voorspellen wanneer uitval zal plaatsvinden, maar u wilt ook liever geen onderdelen vervangen die mogelijk nog jaren mee kunnen gaan. Continue metingen geven u niet alleen de mogelijkheid om direct conditie gestuurd onderhoud uit te voeren, maar geeft u ook veel meer informatie over de werking van een bepaald object. Zodoende kunt u een onderhoudsplan samenstellen die veel accurater is, dit kan u direct maar ook in de toekomst kosten besparen.\n<h2>De Thingsway</h2>\nDe Thingsway is een internet of things sensor die de werking van een bepaald object kan meten. Deze werking wordt continu gemonitord, data wordt opgeslagen en kan worden doorgestuurd, nagelezen en geanalyseerd wanneer u dat wilt.\n\nHet grote voordeel van de Thingsway is dat het een basisproduct is die op ieders wens kan worden aangepast, en dit binnen korte tijd. Sensoren houden de conditie van een object constant in de gaten, daarmee zet de Thingsway een nieuwe standaard neer op gebied van conditie gestuurd onderhoud.\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>\n[/et_pb_text][/et_pb_column][/et_pb_row][/et_pb_section]','Conditie gestuurd onderhoud: wat is het? En wat zijn er de voordelen van?','1632','inherit','closed','closed','','250-revision-v1','','','2022-01-31 09:36:06','2022-01-31 09:36:06','',250,'https://thingsway.media2netdev.nl/?p=355',0,'revision','',0),(356,1,'2022-01-31 09:36:08','2022-01-31 09:36:08','Het Internet of Things biedt een grote mogelijkheid om zeer waardevolle gegevens vast te leggen van de werking van grote machines. Daardoor kan het IoT een directe impact hebben op het ontwerpen, beheren en onderhouden van industriële machines. De ontwikkeling van het IoT gaat dusdanig snel dat het nu de tijd lijkt te zijn voor bedrijven in de industriële sector om over te stappen naar een nieuw soort industrieel onderhoud. Een onderhoud waar gebruik wordt gemaakt van IoT, sensoren, interessante data en een analytisch systeem.\n\nHet snel ontwikkelende onderhoudssysteem van het Iot vraagt om een nieuw soort onderhoudsstrategie. Een verbeterde onderhoudsstrategie zorgt voor kostenbesparing en meer efficiëntie. Het resultaat op gebied van inkomsten en kosten zal snel te zien zijn.\n<h2>De huidige manier van industrieel onderhoud</h2>\nOm de grote waarde te kunnen tonen van een IoT-oplossing in industrieel onderhoud is het nodig om de huidige manier van industrieel onderhoud te beschrijven.\n\nIn de industriële sector wordt de huidige manier van onderhoud bepaald aan de hand van beperkte gegevens en toegepast op geïsoleerde activa. Dat wil zeggen dat de werking van één bepaalde machine wordt bekeken tijdens een proefdraai. Deze gegevens worden samengevoegd met de gegevens van de fabrikant. Deze gegevens vormen de basis van het onderhoudsplan voor deze bepaalde machine. Periodiek onderhoud zal uitgevoerd worden volgens dit onderhoudsplan.\n\nAls bedrijf bent u dus afhankelijk van handmatige methoden om voorspellend, preventief en periodiek onderhoud te plegen. Deze methode heeft echter een groot nadeel; het is namelijk gebaseerd op beperkte gegevens en de nauwkeurigheid van de voorspelling laat te wensen over. Om de werking van een bepaalde machine, of een geheel productieproces, goed te monitoren zijn veel meer gegevens nodig.\n\n<img class=\"size-full wp-image-1650 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/10/onderhoud-in-de-industrie.jpg\" alt=\"industrieel onderhoud\" width=\"1000\" height=\"800\" />\n<h2>De toekomst van industrieel onderhoud</h2>\nHet Internet of Things (of IoT) biedt de mogelijkheid aan machines en processen om met elkaar te communiceren via het internet, en natuurlijk met u als bedrijf. Al uw medewerkers kunnen constant digitaal de gegevens inzien van alle operationele processen. Dit biedt u als bedrijf grote kansen op gebied van onderhoud en kostenbesparing, maar ook op commercieel gebied en efficiëntie.\n\nU zou u zich nu af kunnen vragen hoe zo’n IoT-oplossing dan werkt? Een IoT-oplossing is een apparaat dat werkt door middel van sensoren. Deze sensoren monitoren de werking van een bepaald proces, of verandering, in de omgeving. Dat kan gaan om allerlei soorten veranderingen zoals warmte, beweging en druk. Treedt zo’n verandering op dan wordt dat door de sensor omgezet in data en via een directe internetverbinding doorgestuurd. Dit kan worden doorgestuurd naar medewerkers ter plekke, maar ook bijvoorbeeld naar een hoofdkantoor. Dit biedt de mogelijkheid om onmiddellijk actie te ondernemen waar nodig, maar ook voor het goed analyseren van alle gegevens.\n\nEen IoT-oplossing kan worden toegepast om de werking van één bepaalde machine te monitoren, maar ook een geheel productieproces kan gemonitord worden. Het grote voordeel van een IoT-oplossing is de enorme hoeveelheid data die u binnenkrijgt. Dit geeft een veel beter beeld van de werkelijke werking van een proces of van alle activa samen. Met deze gegevens kunt u een veel degelijker onderhoudsplan samenstellen. Een ander voordeel van een IoT-oplossing is het continu monitoren van het proces. Eventuele problemen met machines kunnen hierdoor sneller opgespoord worden en uitval voorkomen. Een Iot-oplossing is daarom de toekomst van industrieel onderhoud.\n<h2>De Thingsway</h2>\nEen voorbeeld van een IoT-oplossing is de Thingsway. Dit is een IoT-sensor die ontwikkeld is door Salland Electronics. De Thingsway is een basisproduct die ook heel goed toepasbaar is in de industriële sector. Het apparaat wordt als het ware aangepast op uw wensen en het te meten proces. Die aanpassingen liggen dan op gebied van de behuizing, de benodigde sensoren en de bevestiging. Salland Electronics kan deze aanpassingen snel ten uitvoer brengen. Hierdoor kan uw bedrijf binnen korte tijd een IoT-oplossing in huis hebben.\n\nDe Thingsway werkt op een batterij die gegarandeerd 10 jaar meegaat.\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\n<h2>Industrieel onderhoud en IoT samengevat</h2>\nHet IoT is de mogelijkheid om uw volledige bedrijf van accurate online gegevens te voorzien. Hiermee kunnen managers verbeteringen aanbrengen op gebied van onderhoud, maar ook op gebied van efficiëntie en kostenbesparing.\n\nHet continu monitoren van een proces of machine geeft een veel beter inzicht. Deze gegevens bieden een kans op een veel efficiënter onderhoudsplan. In plaats van het werken met minimale gegevens van activa en handmatig toezicht, heeft het gehele bedrijf constant inzicht via digitale hardware.\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>','De toekomst van industrieel onderhoud','1648','inherit','closed','closed','','255-revision-v1','','','2022-01-31 09:36:08','2022-01-31 09:36:08','',255,'https://thingsway.media2netdev.nl/?p=356',0,'revision','',0),(357,1,'2022-01-31 09:36:09','2022-01-31 09:36:09','Om het succes van een product op de lange termijn te garanderen, zou een bedrijf zich moeten richten op het optimaliseren van het productieproces. Deze regel gaat op voor elk bedrijf. Voor menig bedrijf geldt echter dat balans vinden tussen kwaliteit en kosten een voortdurende strijd is. Als bedrijf heeft u een aantal wensen; een zo hoog mogelijke vraag, aan deze vraag kunnen voldoen met een hoogwaardig product en het zo laag mogelijk houden van de kosten.\n\nWas dit maar alles waar u mee rekening dient te houden, toch? Want daarnaast heeft u te maken met grondstoffen, leveranciers, loonkosten en winst. Het handhaven van de kosten is niet bepaald makkelijk, maar het is wel de eerste stap op weg naar een optimaal productieproces. Om de kosten van een productieproces te verlagen zijn er een aantal dingen die u kunt doen. We bespreken de belangrijkste.\n<h2>Optimaliseer het productieproces</h2>\nWaar de meeste fabrikanten zich op focussen, is het monitoren van de kosten van een productieproces. In plaats daarvan kunt u het best het gehele proces van productie monitoren. De kosten zijn slechts een deel van het proces. Door het proces als geheel te bekijken kunt u een veel nauwkeuriger beeld krijgen.\n\nEr is veel nodig om een geheel productieproces te monitoren. Vooral het monitoren van apparaten en machines kan nogal een uitdaging zijn. Een IoT-oplossing is zeer geschikt om u daarbij te helpen. Een Internet of Things-oplossing werkt met sensoren en is draadloos aangesloten op het internet. Dit apparaat monitort continu de werking van een proces of machine. Dit geeft u een zeer gedetailleerd beeld van de functie en effectiviteit. De Thingsway is een mooi voorbeeld van zo’n IoT-oplossing. Dit apparaat is op vele manieren in te zetten; in de buitenlucht, maar ook in een industriële omgeving.\n\nHet monitoren en analyseren van uw gehele productieproces geeft u de mogelijkheid om aanpassingen te doen waar nodig is. Misschien op het gebied van kosten, zuiniger gebruik van materiaal of grondstof of efficiëntie van machines. Misschien is het nodig om machines te vervangen of om productie van bepaalde elementen in eigen handen te nemen.\n\nHoe dan ook, om het productieproces te optimaliseren is het nodig om dit gehele proces te monitoren.\n\n<img class=\"size-full wp-image-1655 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/10/productieproces.jpg\" alt=\"productie proces verbeteren\" width=\"1000\" height=\"800\" />\n<h2>Verlaag de kosten van materiaal</h2>\nOm een productieproces te optimaliseren en productiekosten te besparen kunt u eraan werken om de kosten van het materiaal te verlagen. Veel startende bedrijven kiezen voor bepaalde componenten voor hun product, zonder een goed beeld te hebben van de totale kosten.\n\nOm de kosten op materiaal te verlagen kunt u overwegen om bijvoorbeeld het ontwerp te veranderen of naar materialen te zoeken die voordeliger zijn. Zorgt u er echter wel voor dat de nieuwe materialen niet ten koste gaan van de kwaliteit van uw product.\n\nU kunt ook de kosten van materiaal omlaag brengen door te kijken naar efficiëntie van gebruik. Misschien kunt u doen aan recycling van uw product of van materialen die als bijproduct worden weggegooid.\n<h2>Productiviteit van het personeel verbeteren</h2>\nDe personeelsleden die voor u werken zijn onbetaalbaar, maar toch kosten ze u loon. Om een productieproces te optimaliseren en de kosten te verlagen kunt u kijken of u met een kleiner team kunt werken. Misschien is het tijd om verder te automatiseren. Dit mag natuurlijk niet ten koste gaan van de efficiëntie, kwaliteit en nauwkeurigheid.\n\nDaarnaast kunt u de productiviteit van werknemers stimuleren door middel van bonussen en efficiëntere werkschema’s. Maakt u goed gebruik van de capaciteit van het personeel, of kan dat beter?\n\nU kunt ervoor kiezen om de gegevens van een productieproces tijdens het werk via een beeldscherm te tonen. Het blijkt dat dit niet alleen motiverend werkt voor werknemers, maar het zorgt ook voor meer betrokkenheid bij de gehele productie. Daarnaast kan er door werknemers op tijd ingegrepen worden wanneer een proces een defect vertoont. Dit werkt zeer goed voor het optimaliseren van een productieproces.\n\nDit vertonen van accurate informatie wordt gedaan met een Internet of Things-oplossing, zoals de Thingsway.\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\n<h2>Krijg een goed beeld van vraag en aanbod</h2>\nDe kosten van een bedrijf kunnen flink oplopen wanneer het langdurig veel voorraad moet opslaan. Het maakt in zo’n geval niet uit of het om grondstoffen gaat of een compleet product. Als een productieproces geoptimaliseerd is dan wordt overproductie voorkomen. Dit verlaagt alle kosten voor opslag, verzekering en eventueel onderhoud.\n\nZorgt u ervoor dat u produceert op basis van de vraag van de klant. Als u geen nauwkeurig beeld heeft van de vraag dan kan dit overproductie veroorzaken of juist tekorten. Deze tekorten zorgen weer voor extra belasting op machines en personeel. Zorg voor een goede relatie met klanten en leveranciers, hiermee kunt u een duidelijker beeld krijgen van de toekomstige vraag en aanbod. Dat helpt mee met het optimaliseren van een productieproces.\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>','Hoe kunt u een productieproces optimaliseren?','1652','inherit','closed','closed','','257-revision-v1','','','2022-01-31 09:36:09','2022-01-31 09:36:09','',257,'https://thingsway.media2netdev.nl/?p=357',0,'revision','',0),(358,1,'2022-01-31 09:36:10','2022-01-31 09:36:10','Planmatig onderhoud verwijst naar alle onderhoudsactiviteiten die worden gepland en gedocumenteerd. Het uiteindelijke doel van planmatig onderhoud is om storingen en uitval te verminderen. Dit wordt gedaan door middel van een strategie en met efficiënte middelen, zoals onderdelen en mankracht.\n\nEr bestaan twee types planmatig onderhoud. Het eerste type is planmatig preventief onderhoud. Dit richt zich op het onderhouden van machines en objecten voordat er een defect optreedt. Als voorbeeld kunt u een machine nemen waaraan periodiek onderhoud gedaan wordt na 200 draaiuren.\n\nMaar er bestaat ook een vorm van reactief planmatig onderhoud. Dit klinkt echter tegenstrijdig, want het is gebaseerd op het zo snel mogelijk repareren van iets wanneer het kapot gaat, of wanneer een onderdeel vervangen moet worden. Als voorbeeld kunt u denken aan een boormachine waarvan een kapotte boor vervangen moet worden.\n<h2>Planmatig maintenance</h2>\nDe maintenance taken die worden uitgevoerd volgens planmatig onderhoud vinden plaats voordat een probleem zich kan voordoen. Het doel is om ervoor te zorgen dat activa zo lang mogelijk blijft werken, zonder dat deze uitvalt. De strategie voor planmatig onderhoud is gebaseerd op richtlijnen van fabrikant, tijd, gebruik, toestand en voorspellingen op basis van metingen uit het verleden.\n<h2>De voordelen van planmatig onderhoud</h2>\nEen groot voordeel van planmatig onderhoud is dat u weet wat u kunt verwachten. Door onderhoud te plannen weet u welke middelen u nodig hebt op welk moment. Zo kunt u tijd, mankracht en nodige onderdelen beschikbaar stellen wanneer nodig.\n\nDit stelt u ook in staat om uw agenda goed te beheren. Er bestaat onderhoud die u ver van te voren kunt plannen, zoals bijvoorbeeld een set nieuwe banden op een transportvoertuig. Er zijn echter ook onderhoudstaken die kortere plantijd vereisen, zoals een compressor die na 100 uur vervangen moet worden. Door planmatig onderhoud toe te passen kunt u precies zien welke taken er aan komen. Storingen zullen minder optreden, daardoor zijn er minder middelen nodig.\n\nEen ander voordeel van planmatig onderhoud is dat het zorgt voor meer efficiëntie van het maintenance team of bedrijf. Het team of bedrijf weet precies wat er gedaan moet worden en welke onderdelen er nodig zijn. Dit werk kunnen ze vooraf doen. Hierdoor zal het onderhoud sneller en makkelijker gaan wat de efficiëntie van het hele bedrijf ten goede komt.\n\n<img class=\"size-full wp-image-1660 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/10/voordelen-planmatig-onderhoud.jpg\" alt=\"voordelen planmatig onderhoud \" width=\"1000\" height=\"800\" />\n<h2>Reactief planmatig onderhoud</h2>\nReactief planmatig onderhoud vindt plaats wanneer een onderdeel kapot moet gaan voordat het vervangen wordt. Dit soort onderhoud wordt gedaan bij machines of onderdelen die niet cruciaal zijn voor een productieproces, of te wel onderdelen die eenvoudig te vervangen zijn. Zou u deze preventief vervangen dan verspilt u geld, ze zijn niet duur of essentieel in het proces. In plaats van preventief vervangen heeft een bedrijf deze onderdelen ruim op voorraad en wordt het vervangen wanneer nodig. Denk u hierbij aan meetinstrumenten en boren.\n\nDit wordt nog steeds beschouwd als planmatig onderhoud omdat het gereedschap, de apparaten en onderdelen worden geïnventariseerd. Er bestaat een plan om deze te repareren wanneer nodig en voldoende in voorraad te hebben.\n<h2>Hoe kunt u planmatig onderhoud toepassen?</h2>\nEr bestaat geen standaard aanpak voor het toepassen van planmatig onderhoud. Elk bedrijf is anders en heeft zijn eigen plan nodig. Er bestaan echter een aantal basisstappen die u kunt nemen om een goed planmatig onderhoudsplan toe te passen.\n\nAls eerste kunt u het best een goed overzicht maken van alle onderdelen of machines die onderhoud vereisen. In welke categorie passen deze? Gaat het om kritieke onderdelen voor een productieproces? Hebben ze preventief onderhoud nodig, of is reactief voldoende? Door deze analyse te doen kunt u goed bepalen welke machines, objecten of onderdelen de meeste aandacht nodig hebben.\n\nTechnologie gaat de laatste jaren met sprongen vooruit, ook op gebied van planmatig onderhoud. Als eerste kunt u natuurlijk gebruik maken van vele soorten software die u helpen bij het plannen van onderhoud. Deze software maakt het plannen van onderhoud eenvoudiger, zoals het maken van schema’s, werkorders en rapporten. Een goed planprogramma zorgt ervoor dat een maintenance team of bedrijf snel kan reageren en de juiste onderdelen zijn altijd op voorraad.\n\nEen enorme technologische sprong wordt gemaakt door middel van het Internet of Things. Het IoT kan zeer goed van pas komen bij planmatig onderhoud.\n<h2>Planmatig onderhoud met een IoT-oplossing</h2>\nDie kritieke onderdelen, objecten of machines die uw bedrijf draaiende houden, waarom laat u deze niet continu monitoren op de werking ervan? In plaats van het uitvoeren van planmatig periodiek onderhoud zou u dpas onderhoud kunnen plegen wanneer dit echt nodig is. Bovendien voordat zich problemen voordoen.\n\nDe Thingsway is een IoT- sensor dat een bepaald proces monitort. Veranderingen in het proces worden onmiddellijk waargenomen en gemeld via een directe internetverbinding. Dit stelt u in staat om onderhoud te plegen voordat uitval of een storing zich voordoet.\n\nHet continu monitoren zorgt voor enorm veel gegevens. Door het analyseren van deze gegevens krijgt u een nog beter inzicht in de functionaliteit van objecten of apparaten. Zodoende kunt u nog gerichter en efficiënter planmatig onderhoud uitvoeren.\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>\n&nbsp;','Wat is planmatig onderhoud, en wat zijn de voordelen?','1658','inherit','closed','closed','','259-revision-v1','','','2022-01-31 09:36:10','2022-01-31 09:36:10','',259,'https://thingsway.media2netdev.nl/?p=358',0,'revision','',0),(359,1,'2022-01-31 09:36:11','2022-01-31 09:36:11','Door het toepassen van voorspellend onderhoud kunnen bedrijven en fabrikanten de werking van machines beoordelen. Ze kunnen ook storingen analyseren en hierdoor inschatten wanneer de volgende storing zou kunnen optreden. Door de werking te analyseren en te voorspellen, kunt u een onderhoud voortaan van tevoren plannen en u kunt uw voorraad beter beheren. Tevens zult u de efficiëntie van uw bedrijf verhogen doordat u minder last heeft van uitval.\n\nOm de werking van machines te beoordelen en om komende storingen voor te zijn is een goede strategie nodig voor een voorspellend onderhoudsprogramma. U heeft hier effectieve middelen voor nodig, zoals sensormetingen en zeer goede kennis van het systeem. U dient rekening te houden met meerdere factoren zoals:\n<ul>\n 	<li>De gedetecteerde bronnen van storingen en hun frequentie. Bij dergelijke bronnen kunt u denken aan belangrijke onderdelen van een machine.</li>\n 	<li>Gebruik van sensoren om processen te meten. Het aantal sensoren, het type, de locatie en hun betrouwbaarheid hebben invloed op het bepalen van algoritmen.</li>\n 	<li>Hoe verschillende storingen zich vertalen naar waarneembare symptomen. Om zo’n oorzaak-gevolg analyse te kunnen doen zijn sensoren nodig en uitgebreide analyse van data.</li>\n 	<li>Kennis van het gehele systeem. Deze kan afkomstig zijn van systeemanalyses en van experts. Wanneer u goede kennis van het systeem heeft, dan bent u op de hoogte van de werking van de machine, zijn maximale bereik en de specifieke aard van metingen en onderhoud.</li>\n 	<li>Het ultieme doel van uw onderhoudsprogramma, zoals herstel van storingen of het bepalen van een onderhoudsschema.</li>\n</ul>\n<img class=\"size-full wp-image-1663 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/10/voordelen-algoritmen-achterhalen.jpg\" alt=\"algoritmen achterhalen\" width=\"1000\" height=\"800\" />\n<h2>Wat algoritmen kunnen betekenen voor voorspellend onderhoud</h2>\nBij een programma voor voorspellend onderhoud wordt gebruik gemaakt van algoritmen. Deze algoritmen helpen om de data te analyseren die zijn gemeten in een bepaald proces van een bedrijf.\n\nOm de werking van een machine te monitoren, en eventuele storingen op te kunnen sporen, wordt een constante diagnose van gegevens uitgevoerd. Dit wordt conditiebewaking genoemd. Door middel van sensoren worden gegevens verzameld zoals temperatuur, druk, spanningen en trillingen.\n\nEen verandering in een proces wordt een conditie-indicator genoemd. Wanneer een verandering optreedt dan zal het algoritme een diagnose uitvoeren door gegevens te vergelijken met andere momenten van storing of defecte condities. Op basis van de huidige en vroegere staat van de machine wordt een voorspelling gedaan wanneer een storing zal optreden. Door het verzamelen van steeds meer data, kunnen betere prognoses worden gedaan en nieuwe waarden voor conditie-indicatoren worden voorspeld. Deze toekomstige waarden worden gebruikt om uit te rekenen hoe lang een machine zal meegaan en wanneer onderhoud vereist is.\n\nAls voorbeeld kunnen we een versnellingsbak nemen. Via constante metingen van trillingen over een bepaalde tijd kunnen voorspellingen worden gedaan met een algoritme. Het algoritme kan de waarden vergelijken met bepaalde drempelwaarden die goede werking van de versnellingsbak garanderen of wanneer er storing zou kunnen optreden.\n\nVoor een voorspellend onderhoudssysteem worden sensoren gebruikt die een proces monitoren. Deze sensoren zorgen voor enorm veel data. Algoritmen en hardware zoals laptops zorgen ervoor dat werknemers en technici deze gegevens kunnen gebruiken om het feitelijke onderhoud uit te voeren.\n<h2>Gegevens verzamelen om algoritmen te bepalen</h2>\nOm algoritmen te kunnen ontwerpen heeft u data nodig. Een bedrijf moet vaak enorm veel data beheren en verwerken. Dat gaat om gegevens van meerdere machines, processen en sensoren. Deze draaien op verschillende momenten en onder andere omstandigheden. Beschikking hebben tot de volgende soorten gegevens is belangrijk:\n<ul>\n 	<li>Real-time data van normale systeembediening</li>\n 	<li>Real-time data van een systeem dat werkt, maar in een defecte staat</li>\n 	<li>Real-time data van storingen (run-to-failure-gegevens)</li>\n</ul>\nU kunt bijvoorbeeld gegevens hebben via een sensor over de werking van het systeem, zoals temperatuur, druk en trillingen. Dergelijke gegevens worden doorgaans opgeslagen als signaaldata. Het kan ook zijn dat u data heeft in tekst zoals gegevens uit onderhoudsrecords. Deze gegevens worden opgeslagen in bestanden en databases.\n\nNa het verzamelen van de gegevens worden deze geanalyseerd. Belangrijk is om de conditie-indicatoren te bepalen van een proces. Van welke functies in het systeem verandert het gedrag op een voorspelbare manier naarmate het systeem achteruitgaat? Elke functie die het verschil uitmaakt tussen een normale werking of een defecte staat is een conditie-indicator.\n<h2>Conditie-indicatoren monitoren via een IoT-oplossing</h2>\nOm de werking van een proces of machine te monitoren worden sensoren gebruikt. Met een IoT-oplossing, zoals De Thingsway van Salland Electronics, kunt u continu laten monitoren op bepaalde conditie-indicatoren. Bovendien worden deze gegevens rechtstreeks naar u toe gestuurd via een rechtstreekse internetverbinding.\n\nDe Thingsway is een basisproduct dat snel toepasbaar is in uw bedrijf. Afhankelijk van de te meten indicator worden de sensoren aangepast. Ook de behuizing kan worden aangepast zodat deze geschikt is voor de omgeving waarin de sensor wordt ingezet.\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>','Algoritmen achterhalen: waarom is dat bij onderhoud van belang?','1662','inherit','closed','closed','','261-revision-v1','','','2022-01-31 09:36:11','2022-01-31 09:36:11','',261,'https://thingsway.media2netdev.nl/?p=359',0,'revision','',0),(360,1,'2022-01-31 09:36:13','2022-01-31 09:36:13','Conditiemonitoring is een van de meest innovatieve manieren waarop bedrijven in maintenance, maar ook in de productie-industrie, geld kunnen besparen. Conditiemonitoring draait op het principe van voorspellend onderhoud, een proactieve manier om defecte apparatuur te herstellen voordat deze problemen veroorzaken. Defecte machines en kapotte onderdelen kosten bedrijven elk jaar enorm veel geld. Het gaat vaak om hele hoge bedragen, niet alleen waarneembaar in kosten, maar ook in verspilde productiviteit. Dit is erg zonde, vooral omdat het tegenwoordig vermijdbaar is.\n<h2>Conditiemonitoring met een maintenance sensor</h2>\nDe conditie van een object of machine kunt u heel goed laten monitoren door middel van een sensor. Sensoren bestaan in vele types, voor verschillende doeleinden geschikt. Zo bestaan er bijvoorbeeld sensoren die warmte, druk, beweging en luchtvochtigheid meten. Dit zijn slechts enkele voorbeelden, bijna alles kan tegenwoordig gemeten worden met een sensor.\n\nDeze sensoren registreren een verandering in de omgeving. Deze verandering kan een indicator zijn van een komend probleem bij een machine, proces of object. Zo is het bijvoorbeeld in de tuinbouw erg belangrijk hoe hoog de luchtvochtigheid is in een kas, een sensor kan dit meten. In geval van een machine kan het zijn dat de temperatuur van de lagers bepalend is voor de optimale werking. Wordt de temperatuur te hoog, dan registreert de sensor dit en geeft een melding.\n<h2>De mogelijkheden van een maintenance sensor</h2>\nHet Internet-of-Things biedt de mogelijkheid om zo’n melding van een sensor in real-time binnen te krijgen op welke hardware u maar verlangt. Via een directe en draadloze internetverbinding worden gegevens van de sensor gestuurd naar computer, laptop, tablet of smartphone. U kunt onmiddellijk ingrijpen en de storing voor zijn.\n\nEen andere mogelijkheid van een maintenance sensor is het verzamelen van zoveel mogelijk data om de werking van een machine of proces te kunnen optimaliseren. Door het continu monitoren worden enorm veel gegevens verzameld. Door deze aan een analyse te onderwerpen kunnen aanpassingen worden gedaan op gebied van effectiviteit, inzetbaarheid en bezuiniging van grondstoffen.\n<h2>De voordelen van een maintenance sensor</h2>\nWorden de voordelen van een maintenance sensor en conditiemonitoring u al duidelijk? Misschien worden ze nog duidelijker door u redenen te geven waarom voorspellend onderhoud de toekomst is:\n<h3>Lagere onderhoudskosten</h3>\nHet belangrijkste voordeel van conditiemonitoring is de besparing op onderhoudskosten. Hoewel het toepassen van reactief onderhoud goedkoper kan lijken, blijkt het op de lange termijn altijd duurder. Bovendien kunnen defecte machines zorgen voor een rimpeleffect, waardoor andere apparatuur ook defect raakt en verdere schade veroorzaakt. De stilstand van machines wordt vaak veroorzaakt door verborgen interne fouten. Zonder gebruik van een maintenance sensor zijn deze fouten vrijwel onmogelijk op te sporen. Dat is de reden waarom conditiemonitoring een waardevolle investering is voor ieder bedrijf dat waarde hecht aan betrouwbaarheid.\n<h3>Maximale productie</h3>\nMachines die defect zijn en kapotte onderdelen kosten een bedrijf ieder jaar veel uren aan productiviteit. Dit is niet alleen nadelig voor uw winst, het kan ook nadelig zijn voor uw relatie met klanten. Door de conditie van uw machines te bewaken kunt u erop vertrouwen dat u op maximale productiviteit draait. U kunt beter voldoen aan de deadlines van leveringen aan klanten.\n<h3>Levensduur van machines verlengen</h3>\nMachines in de industrie en hoogwaardige onderdelen zijn gemaakt om lang mee te gaan. Het monitoren van de conditie kan zelfs helpen om de levensduur van deze machines en onderdelen te verlengen. Niet alleen zorgt voorspellend onderhoud voor het elimineren van verborgen kosten, ook de gehele productiviteit wordt verhoogd.\n<h3>Prioriteit geven aan onderhoudstaken</h3>\nDoor continu monitoring toe te passen door een maintenance sensor krijgt u real-time gegevens, die bovendien zeer betrouwbaar zijn. Hierdoor kunt u de juiste machines prioriteit geven. Dit kan u helpen om onderhoud juist te plannen, zo bespaart u tijd en geld.\n<h3>Nauwkeurige KPI\'s en analyse</h3>\nEen ander voordeel van zoveel data is dat u analyses kunt toepassen. U kunt uw gehele productieproces analyseren en KPI’s vastleggen. Dit geeft u de kans om weloverwogen beslissingen te nemen, bijvoorbeeld bij het aanschaffen van nieuwe apparatuur of bij het verlengen van contracten.\n<h2>De Thingsway, een maintenance sensor</h2>\nDe Thingsway is een goed voorbeeld van een maintenance sensor. Het grote voordeel van de Thingsway is dat het op vele gebieden in te zetten is, bovendien binnen zeer korte tijd. Salland Electronics heeft de Thingsway ontwikkeld, dit bedrijf uit Zwolle kan u binnen een dag met een geheel IoT-systeem uitrusten. De Thingsway wordt geheel aangepast aan de wensen van uw bedrijf. Ook de internetaansluiting kan door Salland Electronics worden verzorgd. Er kan gebruik gemaakt worden van verschillende grote internetaanbieders.\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>','De mogelijkheden en voordelen van een maintenance sensor','1666','inherit','closed','closed','','263-revision-v1','','','2022-01-31 09:36:13','2022-01-31 09:36:13','',263,'https://thingsway.media2netdev.nl/?p=360',0,'revision','',0),(361,1,'2022-01-31 09:36:15','2022-01-31 09:36:15','Onze moderne wereld is geobsedeerd geraakt door snelheid. De technologische vooruitgang heeft ervoor gezorgd dat we binnen no-time alles kunnen krijgen wat we maar willen. Producten als smartphones worden op dezelfde dag thuis bezorgd, koffie kunt u bestellen via een app en de bankzaken doen we met onze telefoon. Wachten is een woord dat we bijna niet meer kennen. Dat zorgt ervoor dat we steeds ongeduldiger worden.\n\nSnelheid verwachten we ook als het gaat om het gebruik van digitale middelen. Als we ergens toegang toe willen, dan dient dat snel te gebeuren. Een paar seconden wachten is bijna ondraaglijk geworden. Voor een bedrijf betekent dit dat vertraging zelfs schadelijk kan zijn. In de bedrijfswereld dringt de behoefte aan snelheid razendsnel door. Dat geldt zowel voor bedrijven die zich richten op consumenten, maar ook voor business to business markten. Om aan de vraag te voldoen, en om concurrerend te blijven, is snelheid van up-to-date data essentieel geworden. Maintenance en onderhoud is zo’n branche waarvoor data enorm belangrijk is.\n<h2>Real time data bij inspectieonderhoud</h2>\nDe taak van een onderhoudsbedrijf is om de uptime van activa te verhogen, onverwachte uitval te verminderen en het gebruik van middelen maximaal te benutten. Dit alles het liefst met lage onderhoudskosten. Om aan deze eisen te kunnen voldoen, moeten maintenance bedrijven zoeken naar een effectieve manier van werken. Ze zouden als doel moeten hebben om het juiste werk aan de juiste middelen te doen, dit op precies het juiste moment met het juiste gereedschap.\n\nOm dit doel te kunnen bereiken kan een bedrijf gebruik maken van real-time data bij inspectieonderhoud. Steeds meer onderhoudsbedrijven kiezen voor een slimmere onderhoudsstrategie. De mogelijkheid om onmiddellijk data te verzamelen, analyseren en hierop actie ondernemen, betekent voor bedrijven een enorme stap voorwaarts.\n<h2>Voorbeeld van het belang van data bij inspectieonderhoud</h2>\nAls voorbeeld kunnen we een machine noemen die steeds oververhit raakt bij gebruik. Deze machine begeeft het wanneer de oververhitting plaats vindt. Hierdoor ligt de productie stil, wat natuurlijk kostbaar is. Om de uitval te voorkomen wordt een technicus gestuurd om elke 12 uur de temperatuur van een lager te controleren. Indien nodig wordt deze gerepareerd of vervangen. Ondanks deze inzet raakt de lager nog steeds soms oververhit. Het resultaat blijft daarom ook nog steeds stilstand en oplopende kosten.\n\nWanneer u de beschikking zou hebben over real-time data van de temperatuur van de lager, dan zou u de technicus kunnen sturen voordat het probleem zich voordoet. De storing wordt voorkomen, tijd en kosten worden bespaard. Een onderhoudssysteem die real-time data weergeeft zorgt voor up-to-date gegevens. Deze gegevens kunt u eenvoudig op elk scherm aflezen en constant vernieuwen.\n\nReal-time data zijn essentieel om een gedegen en effectief onderhoudsplan te maken.\n<h2>Het belang van data voor het onderhoudsplan</h2>\nAls planner van een onderhoudsplan wilt u natuurlijk ook voorzien worden van data die echt up-to-date is. Een goed onderhoudsschema maken met oude data of via Excel bestanden van een aantal dagen geleden is niet mogelijk. U loopt hierdoor achter de feiten aan, het levert meer werk op en verwarring bij het onderhoudsteam.\n\nWanneer een geheel onderhoudsteam de beschikbaarheid heeft tot real-time data, dan geeft dit ze de mogelijkheid om proactief in te springen waar nodig. Hierdoor wordt ongeplande downtime voorkomen en het gehele proces geoptimaliseerd.\n<h2>Het Internet of Things en data analyse</h2>\nDe opkomst van het Internet of Things heeft gezorgd voor een enorme technologische vooruitgang. Hierdoor wordt meer data verzameld dan ooit tevoren. Van alle bestaande data op de wereld werd 90% in de laatste jaren verzameld. Om deze data goed te kunnen gebruiken is analyse nodig.\n\nDe data die verkregen wordt komt af van IoT-oplossingen. Dit zijn sensoren die continu een bepaald proces monitoren, bijvoorbeeld die lager in de oververhitte machine. Een voorbeeld van zo’n sensor is de Thingsway. Deze werd ontwikkeld door Salland Electronics en is op veel verschillende manieren in te zetten. Er bestaat een Thingsway voor de industriële sector, maar ook een versie die in de buitenlucht wordt gebruikt. Salland Electronics past de sensor aan op de wensen van de klant, ze doen dit binnen een dag. Via de Thingsway kunt u data voor inspectieonderhoud verkrijgen die uw bedrijf een stap verder kan brengen op gebied van effectiviteit en kostenbesparing.\n\nReal-time data is de sleutel tot de toekomst van onderhoud en maintenance. De data is echter pas nuttig wanneer deze goed geanalyseerd en geïnterpreteerd wordt. Uw doel als onderhoudsbedrijf zou moeten zijn om de data bij inspectieonderhoud automatisch te analyseren en bruikbaar te maken voor technici.\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>','Het belang van data bij inspectieonderhoud','1667','inherit','closed','closed','','265-revision-v1','','','2022-01-31 09:36:15','2022-01-31 09:36:15','',265,'https://thingsway.media2netdev.nl/?p=361',0,'revision','',0),(362,1,'2022-01-31 09:36:15','2022-01-31 09:36:15','Veel bedrijven hebben dagelijks te maken met onderhoud. Er bestaan verschillende manieren om onderhoud uit te voeren. Eén van die manieren is preventief onderhoud. Het belangrijkste voordeel van preventief onderhoud heeft te maken met betrouwbaarheid. Door een object of machine preventief in goede staat te houden wordt de kans verkleind dat er slijtage, schade of uitval kan optreden. Dit heeft uiteindelijk positieve gevolgen voor de levensduur van apparaten of objecten.\n<h2>Wat is preventief onderhoud?</h2>\nPreventief onderhoud is een maintenance systeem wat populair is bij veel bedrijven. Het is een systeem waarin bepaalde onderhoudstaken worden gepland om machines, objecten en apparatuur in goede staat te houden. Deze taken worden meestal periodiek gepland of op basis van gebruiksuren. Niet alles heeft immers dezelfde intensieve onderhoudstaken nodig; een bepaalde machine kan na 100 uur onderhoud nodig hebben, een ander object heeft maar één keer per jaar inspectie nodig.\n<h2>Hoe wordt preventief onderhoud toegepast?</h2>\nOm een gedegen preventief onderhoudsplan samen te stellen is het van belang om te bepalen wat uw meest belangrijke apparaten, machines of objecten zijn. Bovendien moet u een goed inzicht hebben in het gehele proces; wat heeft echt baat bij een preventief onderhoudsplan?\n\nEr zijn namelijk bedrijven die vrij veel geld verspillen met een preventief onderhoudsplan. Er worden dan onderhoudstaken uitgevoerd die er niet voor zorgen dat uitval voorkomen wordt. Periodiek onderhoud is vaak een onderdeel van preventief onderhoud. Dit wordt gedaan op basis van voorspellingen. Helaas werkt dit niet altijd in de praktijk. Uitval van machines komt, ondanks periodiek onderhoud, nog steeds voor.\n\nEen Internet of Things oplossing kan u hierbij goed van dienst zijn. Met een IoT-oplossing kunt u uw kritieke processen of de belangrijkste machines en objecten continu laten monitoren. Dit werkt via sensoren; deze melden een probleem voordat dit zorgt voor uitval of storing. Zodoende kunt u onmiddellijk preventief onderhoud uit laten voeren.\n\nNa het bepalen van de apparatuur die kritiek zijn in uw productieproces, is het van belang om de vaardigheid te trainen om de onderhoudstaken uit te voeren. U zou kunnen investeren in een voortdurende opleiding, zodat de vereiste onderhoudstaken effectief worden uitgevoerd. Dit geldt zeker wanneer u kiest voor een IoT-oplossing. Het is namelijk een grote innovatieve stap voorwaarts op gebied van preventief onderhoud.\n\nEen gedegen preventief onderhoudsprogramma houdt ook rekening met de efficiënte inzet van technici. Een gehele afdeling van uw bedrijf zal soepeler en efficiënter werken wanneer de reistijd van technici verkort kan worden. Niet alle machines of apparaten draaien continu. Door onderhoud te plegen wanneer deze niet gebruikt worden beperkt u onderbrekingen.\n\nInspecties zijn een belangrijk onderdeel van regulier preventief onderhoud. U dient deze regelmatig uit te voeren voordat onderdelen kapot gaan. Zodoende kunt u problemen voor zijn en uitval voorkomen. Aanbevolen richtlijnen van fabrikanten en gegevens uit het verleden bepalen hierbij de planning voor onderhoud. Een IoT-oplossing, zoals de Thingsway, biedt u de mogelijkheid om een nog beter inzicht te geven in de werking en mogelijke uitval van een machine of object.\n\n<img class=\"size-full wp-image-1582 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/10/onderhoudsmeting.jpg\" alt=\"onderhoudsmeting en onderhoudsmetingen\" width=\"1170\" height=\"500\" />\n<h2>De voordelen van preventief onderhoud</h2>\nDe voordelen van preventief onderhoud zijn:\n<ul>\n 	<li>Minder uitval van apparatuur</li>\n 	<li>Minder onderbrekingen van productieprocessen</li>\n 	<li>Langere levensduur</li>\n 	<li>Verbeterde efficiëntie</li>\n 	<li>Verhoogde veiligheid op de werkvloer</li>\n</ul>\nWanneer u een gedegen preventief onderhoudsplan heeft, dan kan dit ervoor zorgen dat het u kostenbesparingen op gaat leveren. Machines, apparaten of objecten gaan langer mee, ze werken zuiniger en processen worden minder onderbroken. De betrouwbaarheid van apparaten, of de werking van een systeem, wordt verbeterd. Machines en processen kunnen hierdoor ononderbroken door blijven draaien. Door uitval, storingen en stilstand te voorkomen kunt u aanzienlijke kostenbesparingen doen.\n\nOp de lange termijn zal een gedegen preventief onderhoudsplan ervoor zorgen dat de algehele levensduur van uw apparatuur wordt verlengd. Niet alleen dat, ook de waarde van objecten of machines worden verbeterd. Preventief onderhoud zorgt op den duur voor toename van efficiëntie en bovendien veiligheid. Dat geldt zeker wanneer u kiest om het Internet of Things toe te passen in uw preventief onderhoudsplan.\n<h2>Wat kan de Thingsway betekenen in uw preventief onderhoudsplan?</h2>\nDe Thingsway is een IoT-sensor dat ontwikkeld is door Salland Electronics. Deze sensor kan allerlei verschillende soorten processen monitoren. Dat kan gaan om de werking van een apparaat, maar ook van een voorwerp of object.\n\nVeranderingen in het proces worden onmiddellijk waargenomen en via een mobiele internetverbinding doorgestuurd naar computer, laptop of smartphone. Dit stelt u in de mogelijkheid om in het proces in te grijpen wanneer nodig. Door gebruik te maken van een IoT-oplossing in uw preventief onderhoudsplan, kunt u onderhoud plegen wanneer dit werkelijk nodig is. Geen periodiek onderhoud op basis van verwachtingen, maar onderhoud op basis van up-to-date data.\n\nDe Thingsway is een basisproduct dat aanpasbaar is op elk te meten proces. Salland Electronics kan deze aanpassingen snel bewerkstelligen. Het tilt uw preventief onderhoudsplan naar een hoger niveau en zal zorgen voor meer efficiëntie en kostenverlagingen.\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>','Preventief onderhoud: wat is het? En wat zijn er de voordelen van?','1673','inherit','closed','closed','','267-revision-v1','','','2022-01-31 09:36:15','2022-01-31 09:36:15','',267,'https://thingsway.media2netdev.nl/?p=362',0,'revision','',0),(363,1,'2022-01-31 09:36:16','2022-01-31 09:36:16','Het Internet of Things wordt met de dag populairder. Hoort u de term ook steeds vaker voorbij komen? Wat houdt het eigenlijk in dat IoT? In wezen is het Internet of Things de internetverbinding die gelegd wordt met alledaagse apparaten. Dat klinkt misschien niet indrukwekkend, maar het wordt ook wel gezien als de vierde industriële revolutie.\n\nDe verwarming in uw huis kunt u bedienen met uw smartphone of tablet. Dit kunt u zien als een mooi voorbeeld van het Internet of Things. De ontwikkeling gaat zo snel dat binnen niet zo lange tijd technici de foutmeldingen van machines binnenkrijgen op hun smartwatch, voordat een storing plaatsvindt.\n\nOver de hele wereld staan er al miljarden apparaten aangesloten via het Internet of Things. De groei van de afgelopen jaren komt vanwege de snellere en betrouwbare mobiele netwerken. Om de efficiëntie van een maintenance managementsysteem te verbeteren is het van fundamenteel belang voor een bedrijf om te investeren in het IoT! Monitoring van systemen kan zorgen voor kostenverlaging op gebied van maintenance, en bovendien op gebied van verbruik.\n\nZo kunt u bijvoorbeeld besparen op verlichting, verwarming en ventilatie. Het IoT is echter vooral gericht op het verbeteren van processen van machines en andere activa. Dit kan verbeterd worden door het analyseren van real-time gegevens, automatisering en intelligente besluitvorming.\n<h2>De Thingsway</h2>\nNu kunt u zich afvragen hoe dit IoT dan werkt? Een voorbeeld van een Internet of Things oplossing is de Thingsway. Dit is een apparaat dat is voorzien van bepaalde sensoren. Deze sensoren monitoren een bepaald proces. Dat kan gaan om een machine, of om een object. Veranderingen in het proces die plaatsvinden bij de machine of het object worden geregistreerd, en onmiddellijk doorgestuurd via een draadloze internetverbinding.\n\nDeze gegevens kunnen overal naartoe worden gestuurd, naar het hoofdkantoor, de werkvloer, een computer of smartphone. Deze real-time gegevens stellen u in staat om het maintenance managementsysteem van uw bedrijf naar een hoger plan te tillen. Vraagt u zich af hoe? Hier volgen enkele voorbeelden.\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\n<h2>Beter gebruik van voorspellend onderhoud</h2>\nVoorspellend onderhoud is de voornaamste reden om als bedrijf te investeren in het IoT. In plaats van onderhoud dat gebaseerd is op routine, periodiek onderhoud en het voorkomen van problemen, worden apparaten of objecten continu gemonitord. De IoT-oplossing stelt u op de hoogte wanneer iets vervangen moet worden. Is er een verandering in een omgeving, dan neemt de sensor deze waar en kan een werkorder activeren voordat uitval plaatsvindt of schade ontstaat.\n\nDit werkt effectiviteit in de hand, omdat er alleen onderhoud wordt gedaan wanneer dit echt nodig is. Kosten worden bespaard op gebied van onderdelen en arbeidsuren. Met het Internet of Things neemt voorspellend onderhoud een nieuwe dimensie aan, dat geldt ook voor uw maintenance managementsysteem.\n<h2>Analyse van gegevens in real-time</h2>\nDe Iot technologie zorgt voor meer mogelijkheden om machines met elkaar te laten communiceren. Dit wordt gedaan door middel van data. Wanneer alle machines in een bepaalde fabriek voorzien zijn van sensoren dan levert dit enorm veel data op. Door deze data te analyseren en samen te voegen kan er zeer accuraat voorspellend maintenance management toegepast worden.\n<h2>Zeer nauwkeurige statistieken</h2>\nHet is van groot belang om goed op de hoogte te zijn van de werking, betrouwbaarheid en de prestatie van een object of machine. Hoeveel tijd zit er tussen storingen? Hoe lang duurt het om een machine te repareren? Deze gegevens kunnen automatisch door een IoT-oplossing worden berekend. Eventuele menselijke fouten worden hierdoor vermeden, de gegevens zijn daardoor zeer nauwkeurig.\n<h2>Up-to-date maintenance managementsysteem</h2>\nAls een machine uitvalt, of een object vertoont problemen, dan kunnen deze real-time gegevens worden verzameld en geanalyseerd. Door het systeem kunnen automatisch de opties voor reparatie worden uitgevoerd en naar technici worden gestuurd als werkorder.\n\nDe technicus krijgt alle informatie die nodig is om de machine of het object op de juiste manier te herstellen. Denkt u bij deze informatie aan alle storingsgegevens en omstandigheden op het moment dat de storing zich voordeed. Ook informatie over slijtage, aanbevelingen van de fabrikant en eerdere gegevens van reparaties zijn eenvoudig in te zien door de technicus\n<h2>Een beter inzicht op de nodige voorraad van onderdelen</h2>\nEen maintenance managementsysteem valt of staat bij een effectief voorraadbeheer. Om de uitvaltijd van een machine of object te beperken heeft u genoeg onderdelen nodig. U wilt echter ook niet teveel onderdelen op voorraad hebben. Een magazijn heeft daarom enorm veel baat bij een goed beeld van welke onderdelen werkelijk nodig zijn. Door het continu monitoren van machines en processen, kan na data-analyse een optimale lijst gemaakt worden van de benodigde onderdelen. Hierdoor kunt u kapitaal vrij maken alleen wanneer dit nodig is.\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>','Verbeter uw maintenance management systeem met het Internet of Things','1676','inherit','closed','closed','','269-revision-v1','','','2022-01-31 09:36:16','2022-01-31 09:36:16','',269,'https://thingsway.media2netdev.nl/?p=363',0,'revision','',0),(364,1,'2022-01-31 09:36:17','2022-01-31 09:36:17','Wanneer we praten over tools voor onderhoudstechniek dan denken we nog steeds vaak aan draadkniptangen, moersleutels en een rateltang. Maar de techniek gaat de laatste jaren met sprongen vooruit. Wanneer het preventieve onderhoudsplan van uw bedrijf niet gebruik maakt van sensoren en IoT-oplossingen, dan wordt het misschien tijd om deze op te nemen in uw plan.\n\nVoor bedrijven die werken in de industriële sector is het van groot belang om defecten en storingen op tijd te herkennen en aan te pakken. De opkomst van het Internet of Things (IoT) heeft gezorgd voor veel meer inzichten op dit gebied.\n\nDoor het gebruik van sensoren en geavanceerde technologieën is het makkelijker om gegevens te analyseren. Deze gegevens kunnen onmiddellijk gebruikt en gedeeld worden. Hierdoor vergroot de effectiviteit van de apparatuur en daarmee de productiviteit van het gehele bedrijf.\n\nDoor moderne tools te gebruiken voor onderhoudstechniek, kunt u bijvoorbeeld automatisch werkorders sturen zonder tussenkomst van een mens.\n<h2>Een Internet of Things-oplossing</h2>\nDe moderne tools voor onderhoudstechniek maken gebruik van sensoren. Deze sensoren houden een bepaald proces in de gaten. Is er verandering in de omgeving, dan zal de sensor dit registreren. Een Internet of Things-oplossing is een combinatie van een bepaalde sensor en een directe internetaansluiting.\n\nDeze aansluiting zorgt ervoor dat de sensor de veranderingen in een proces onmiddellijk kan doorsturen naar computer, laptop, smartphone of tablet. Deze mogelijkheid op gebied van onderhoudstechniek is van groot belang om te concurreren op de huidige markt. Als fabrikant wilt u de werking en efficiëntie van elke machine op de fabrieksvloer garanderen.\n<h2>Voorbeelden van tools voor onderhoudstechniek</h2>\nOm u de mogelijkheden te tonen geven we hier een aantal voorbeelden van innovatieve IoT tools voor onderhoudstechniek. Deze zijn allen gericht op het opsporen, verminderen en voorkomen van storingen in een machine.\n<h2>Conditie monitor</h2>\nEen sensor houdt de conditie van een bepaald apparaat in de gaten. Dat kan gaan om de elektrische spanning in een machine, maar ook om bewaking van de temperatuur. Via een internetverbinding worden gegevens continu gedeeld met werknemers. De manager krijgt zo enorm veel data over de prestaties van een apparaat. Zodoende kunt u preventieve beslissingen nemen door medewerkers onmiddellijk aan te sturen, voordat het apparaat uitvalt. Dit kan zelfs met automatische werkorders.\n<h2>Het monitoren van de temperatuur</h2>\nIn bepaalde omgevingen is het van groot belang om de juiste temperatuur te controleren. Denkt u dan bijvoorbeeld aan de farmaceutische industrie, of bij productie van voedingsmiddelen. Een Iot tool voor onderhoudstechniek maakt het mogelijk voor onderhoudstechnici om via hun smartphone de werking van bepaalde motoren te controleren. De sensor kan waarnemingen doen op gebied van temperatuur, stroom en trillingen. Zodoende kan de werking van een geheel proces in de gaten gehouden worden.\n<h2>Monitoren van doorstroom</h2>\nEen IoT-oplossing kan ook de doorstroom van een bepaald proces monitoren. Denkt u dan bijvoorbeeld aan een toevoerbuis voor brandstof. Door dit te monitoren kunt u niet alleen problemen voor zijn, u kunt ook een zeer goed beeld krijgen van het werkelijke gebruik. Zodoende kunt u niet alleen onderhoudskosten verlagen, maar ook zuiniger gaan produceren.\n\n<img class=\"size-full wp-image-1682 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/10/tools-onderhoudstechniek.jpg\" alt=\"tools onderhoudstechniek\" width=\"1000\" height=\"800\" />\n<h2>Moderne communicatie</h2>\nModerne communicatie zorgt ervoor dat voorspellend onderhoud veel efficiënter kan worden ingezet. Het leven van uw technische afdeling, of van het maintenance bedrijf, wordt veel makkelijker door het gebruik van tablets of smartphones, automatische orders en e-mails.\n\nEen geheel proces kan op afstand bewaakt worden, de data wordt opgeslagen en geanalyseerd. Aan de hand van deze gegevens kan voorspellend onderhoud worden uitgevoerd. Dit is een enorm innovatieve tool op gebied van onderhoudstechniek. Door deze tools te gebruiken over een gehele werkvloer kunt u een enorme stap voorwaarts maken op gebied van efficiëntie en kostenbesparing.\n<h2>De Thingsway</h2>\nUitgaande van bovenstaande tools voor onderhoudstechniek kunt u misschien denken dat u voor ieder afzonderlijk proces een andere IoT-oplossing nodig heeft. Gelukkig bestaat er de Thingsway. Dit is een Internet of Things-sensor ontwikkeld door Salland Electronics. Het grote voordeel van de Thingsway is dat deze snel aan te passen is op het te meten proces.\n\nDe Thingsway is een basisproduct dat aangepast kan worden op uw wensen. Salland Electronics installeert voor u de benodigde sensoren en kan de behuizing aanpassen op de omgeving. De Thingsway werkt op een batterij die gegarandeerd 10 jaar meegaat.\n\nZoekt u een innovatieve tool voor onderhoudstechniek? Een tool die de effectiviteit en productiviteit van uw bedrijf zal vergroten? Dan heeft u met de Thingsway een topproduct gevonden. Ook de internetverbinding wordt door Salland Electronics verzorgd. U kunt kiezen uit meerdere bekende providers.\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>','Innovatieve tools voor onderhoudstechniek','1680','inherit','closed','closed','','271-revision-v1','','','2022-01-31 09:36:17','2022-01-31 09:36:17','',271,'https://thingsway.media2netdev.nl/?p=364',0,'revision','',0),(365,1,'2022-01-31 09:36:18','2022-01-31 09:36:18','Het hebben van een goede onderhoudsstrategie is voor elk bedrijf van belang, maar voor sommige bedrijven is het van levensbelang. Dat gaat bijvoorbeeld op als u een productiebedrijf heeft of een bedrijf dat aan maintenance doet. De opkomst van het Internet of Things zorgt voor enorme technologische sprongen, ook op gebied van onderhoud. Predictive maintenance door middel van een IoT-oplossing kan uw bedrijf helpen grote stappen voorwaarts te maken op gebied van efficiëntie en kostenverlaging.\n<h2>Wat is predictive maintenance?</h2>\nPredictive maintenance is het onderhoud waarbij de werking van machines of objecten continu wordt gemonitord. Dit wordt gedaan tijdens normaal gebruik en om de kans op problemen te verlagen. Het constant monitoren heeft meerdere doelen. Het eerste doel is om de frequentie van onderhoud te verminderen. Het tweede doel is om onverwachte storingen te verminderen en het laatste doel is om onnodig preventief onderhoud te voorkomen. Dit te samen zorgt voor het verlagen van onderhoudskosten.\n\nBedrijven die werken volgens predictive maintenance meten continu bepaalde condities in de omgeving van een machine of object, zoals warmte of corrosie. De methoden die gebruikt worden tijdens predictive maintenance zijn onder andere akoestische metingen, metingen van trillingen, geluid, beweging en infrarood. Een geautomatiseerd onderhoudssysteem helpt het bedrijf verder om de data van deze metingen om te zetten in een onderhoudsstrategie.\n\nZo kunt u bijvoorbeeld automatisch een email ontvangen of een werkopdracht versturen wanneer een bepaalde grens overschreden wordt.\n\n<img class=\"size-full wp-image-1686 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/10/predictive-maintenance-wat-is.jpg\" alt=\"predictive maintenance\" width=\"1170\" height=\"500\" />\n<h2>Het verschil tussen predictive maintenance en preventief onderhoud</h2>\nPredictive maintenance en preventief onderhoud zijn twee totaal verschillende manieren van onderhoud. Wilt u de beste onderhoudsstrategie voor uw bedrijf? Dan zult u een balans moeten vinden tussen deze twee manieren. Op basis van de verwachte levensduur van een object wordt preventief onderhoud gepland. Bij predictive maintenance wordt gekeken naar de staat van het object.\n\nEen preventief onderhoudsprogramma wordt meestal samengesteld door de aanbevelingen van een fabrikant samen te voegen met de metingen van een technisch team. Regelmatig metingen uitvoeren zorgt ervoor dat u een redelijk beeld heeft hoe lang iets mee gaat, of wanneer het vervangen dient te worden. Predictive maintenance wordt niet gedaan aan de hand van voorspellingen, maar door middel van up-to-date data.\n<h2>Hoe werkt predictive maintenance?</h2>\nPredictive maintenance werkt door continu de werking en conditie van een object te monitoren. In geval van machines wordt dit gedaan terwijl de apparatuur werkt. De dagelijkse werkzaamheden worden tijdens dit monitoren niet verstoord. Het monitoren van het proces zorgt voor gegevens die voor zeer betrouwbare statistieken kunnen zorgen. Aan de hand van deze statistieken wordt onderhoud gepleegd.\n\nWe kunnen als voorbeeld een auto nemen. De olie van een auto wordt vaak standaard om een bepaalde periode ververst. Met predictive maintenance kunt u monsters van de olie verzamelen en pas olie verversen wanneer dit echt nodig is. Predictive maintenance werkt via verschillende tools, zowel hardware als software. Een apparaat doet metingen aan het proces, en de software zorgt ervoor dat de data omgezet kan worden in beleid of actie.\n<h2>Hoe past u predictive maintenance toe in een onderhoudsprogramma?</h2>\nHet maakt niet uit welk proces er gemeten moet worden; de trillingen in een machine, of de doorstroming van een buis. De tools die gebruikt worden in een geautomatiseerd onderhoudssysteem helpen u om nauwkeurige voorspellingen te doen. Het systeem meldt wanneer het object onderhoud of vervanging nodig heeft.\n\nPredictive maintenance kan het best uitgevoerd worden door middel van een Internet of Things-oplossing. Een IoT-oplossing biedt het beste van twee werelden; continue monitoring van een proces en een internetaansluiting. Hierdoor kunnen alle gegevens van de metingen meteen worden doorgestuurd, geanalyseerd en omgezet worden in automatische orders of later in onderhoudsbeleid.\n\nDe metingen worden uitgevoerd door middel van een apparaat met sensoren. Deze bieden u real-time data die u kunt volgen van welke locatie dan ook. Tevens kunnen deze gegevens doorgestuurd worden naar smartphone of tablet. Dit geeft een bedrijf de mogelijkheid om een zeer goed beeld te krijgen van de werking van een machine en eventueel snel te handelen wanneer nodig.\n\nPredictive maintenance met een IoT-oplossing zorgt ervoor dat u onderhoud beter kunt plannen. Ook kunt u uitval verkorten en de reactietijd op storingen en problemen verbeteren.\n<h2>De Thingsway, een IoT-oplossing</h2>\nDe Thingsway is een IoT-sensor die ontwikkeld is door Salland Electronics. Deze IoT-oplossing is zeer goed in te zetten wanneer uw bedrijf aan predictive maintenance wilt doen. Het voordeel van de Thingsway is zijn multifunctionaliteit. Het apparaat is snel aan te passen aan het te meten object. Dit wordt gedaan door de sensoren en de behuizing naar wens aan te passen.\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>','Wat is predictive maintenance, en hoe werkt het?','1684','inherit','closed','closed','','273-revision-v1','','','2022-01-31 09:36:18','2022-01-31 09:36:18','',273,'https://thingsway.media2netdev.nl/?p=365',0,'revision','',0),(366,1,'2022-01-31 09:36:20','2022-01-31 09:36:20','Ieder bedrijf heeft wel eens last van een storing. Het kan echter voor een flinke kostenpost zorgen wanneer storingen regelmatig optreden. Storingen kunnen niet alleen irritant zijn, ze kunnen de effectiviteit van een bedrijf enorm verstoren. Zou het voor uw bedrijf niet heel fijn zijn wanneer storingen voorkomen kunnen worden, in ieder geval voor een groot deel?\n<h2>Hoe worden storingen meestal voorkomen?</h2>\nOm storingen te voorkomen doet een bedrijf aan onderhoud of het bedrijf besteedt het onderhoud uit aan een externe partij. Dit geldt vooral voor bedrijven die veel te maken hebben met onderhoud, zoals bijvoorbeeld een productiebedrijf dat veel werkt met machines. Het kan ook gaan om bedrijven in vastgoed, zoals een woningcorporatie.\n\nHet soort onderhoud waar de meeste bedrijven aan doen is preventief onderhoud. Een bedrijf zou ook kunnen doen aan reactief onderhoud. Dan wordt onderhoud pas gepleegd wanneer er een melding of klacht binnenkomt. De storing wordt pas op dat moment verholpen. Reactief onderhoud heeft als nadeel dat u regelmatig met storingen te maken zal hebben. U loopt als het ware achter de feiten aan. Bovendien kunt u als bedrijf een deuk oplopen op gebied van betrouwbaarheid en aanzien.\n\nPreventief onderhoud heeft het voordeel dat het storingen voor kan zijn. Aan de hand van aanbevelingen van fabrikanten en historische gegevens van het object kan een onderhoudsplanning worden gemaakt. Er kan een redelijke voorspelling worden gedaan hoe lang iets meegaat, en wanneer er onderhoud gepleegd moet worden om een storing te voorkomen. Om zo’n moment van storing te voorkomen wordt er periodiek onderhoud aan een machine of object uitgevoerd.\n\n<img class=\"size-full wp-image-1690 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/10/storing-voorkomen.jpg\" alt=\"storing en storingen voorkomen\" width=\"1000\" height=\"800\" />\n<h2>Het nadeel van preventief onderhoud om storingen te voorkomen</h2>\nEr zit echter ook een nadeel aan preventief onderhoud. Het is namelijk gebaseerd op voorspellingen en deze voorspellingen zijn gedaan op basis van vrij relevante gegevens. Helaas houden storingen zich niet altijd aan voorspellingen. Storingen komen vooral op onverwachte momenten, soms door factoren die u niet in de hand heeft. Denkt u dan aan veranderingen in de omgeving, bijvoorbeeld weersomstandigheden of door trillingen van een andere machine.\n\nPeriodiek onderhoud kan veel storingen voorkomen wanneer deze volgens een juist plan uitgevoerd wordt. U heeft echter nog steeds te maken met voorspellingen, menselijk handelen en veranderende factoren die u niet in de hand heeft.\n<h2>Storingen voorkomen door predictief onderhoud</h2>\nEen andere manier van onderhoud is predictief onderhoud. Predictief geeft al aan dat het hier ook gaat om onderhoud op basis van voorspellingen, maar deze voorspellingen worden gedaan aan de hand van accurate gegevens die door middel van real-time monitoring verkregen worden.\n\nEen bepaald proces wordt continu gemonitord door middel van een apparaat. Veranderingen in een proces kunnen storingen veroorzaken. Wanneer zo’n verandering optreedt dan geeft het apparaat dit door en kan er onmiddellijk worden ingegrepen. Op zo’n moment wordt er dus onderhoud uitgevoerd, voordat een storing optreedt.\n\nHet apparaat dat dit proces monitort is voorzien van sensoren en een directe internetverbinding. Zo’n apparaat wordt een Internet of Things-oplossing genoemd.\n<h2>Storingen voorkomen door een Internet of Things-oplossing</h2>\nEen Internet of Things-oplossing is dus een apparaat met sensoren in combinatie met een draadloze internetverbinding. Het voordeel van zo’n oplossing is het feit dat deze sensor continu een proces in de gaten houdt en bovendien voor enorm veel gegevens zorgt over de werking van een machine of object. Dit geeft u de mogelijkheid om deze data te analyseren en een nog veel beter beeld te krijgen van het object. Voorspellingen over de werking, of eventuele storingen, kunnen nog exacter worden gedaan.\n\nHet voordeel van de real-time data en de internetverbinding, is dat de gegevens naar iedere locatie kunnen worden gestuurd. U kunt de gegevens naar een computer sturen op het hoofdkantoor, maar ook naar smartphones op de werkvloer. Zo kunnen medewerkers, of een technisch team, snel ingrijpen om een komende storing te voorkomen.\n<h2>De Thingsway</h2>\nEen voorbeeld van een IoT-oplossing is de Thingsway. Dit is een apparaat dat voorzien kan worden met verschillende sensoren. Ieder proces heeft namelijk een ander soort sensor nodig. Sensoren bestaan in veel verschillende soorten, bijvoorbeeld sensoren die warmte, druk, beweging of vocht meten.\n\nSalland Electronics heeft de Thingsway ontwikkeld. Een basisproduct dat snel aan te passen is aan uw wensen. Wilt u de werking van een bepaalde machine meten? De Thingsway bestaat in een industriële versie. Wilt u metingen doen in een buitenlocatie? Dan is ook daar een geschikte Thingsway voor. Aanpassingen worden gedaan aan de behuizing en de benodigde sensoren.\n\nDe Thingsway kan u helpen om storingen te voorkomen. Zodoende kan uw bedrijf stappen maken op gebied van efficiëntie en kostenbesparing.\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>','Storingen voorkomen: hoe doe je dat? En welke mogelijkheden zijn er?','1688','inherit','closed','closed','','275-revision-v1','','','2022-01-31 09:36:20','2022-01-31 09:36:20','',275,'https://thingsway.media2netdev.nl/?p=366',0,'revision','',0),(367,1,'2022-01-31 09:36:22','2022-01-31 09:36:22','Het verzamelen van informatie is voor elk bedrijf belangrijk. Op de hoogte zijn van zoveel mogelijk cijfers zorgt ervoor dat u een goed inzicht heeft in het functioneren van uw bedrijf. Dat geldt voor alle aspecten van uw bedrijfsplan, bijvoorbeeld op gebied van verbruik, kosten, inkomsten en natuurlijk onderhoud.\n\nVoor elk bedrijf is het tevens van belang om een onderhoudsplan te hebben dat goed bij het bedrijf past. Of het onderhoudsplan van uw bedrijf nu gebaseerd is op correctief onderhoud, of op proactief onderhoud, u heeft gegevens nodig om een strategisch plan te kunnen maken. Deze gegevens ten behoeve van onderhoud noemen we onderhoudsdata.\n<h2>Wat is onderhoudsdata?</h2>\nVoor een gedegen onderhoudssysteem heeft u data nodig waar u in de toekomst werkelijk iets aan heeft. In dit systeem zouden in ieder geval de volgende gegevens over een machine of artikel moeten staan:\n<ul>\n 	<li>Wat is gerepareerd of vervangen?</li>\n 	<li>Welke onderdelen zijn bij de reparatie gebruikt?</li>\n 	<li>Wanneer is het vervangen of gerepareerd?</li>\n 	<li>Wat was de reden van de storing?</li>\n</ul>\nOm met deze gegevens een zinvolle analyse te kunnen uitvoeren heeft u een basis hoeveelheid aanvullende data nodig zoals:\n<ul>\n 	<li>Hoe oud was het artikel tot moment van falen?</li>\n 	<li>Wat voor onderdelen zijn er voor de storing tijdens preventief of voorspellend onderhoud vervangen of verwijderd?</li>\n</ul>\n<img class=\"size-full wp-image-1559 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/10/continue-monitoren.jpg\" alt=\"continue monitoren\" width=\"1170\" height=\"500\" />\n<h2>Wat zijn de mogelijkheden van onderhoudsdata?</h2>\nMet deze data kunt u verschillende soorten analyses uitvoeren zoals:\n<ul>\n 	<li>Weibull: dit is een analyse methode die veel gebruikt wordt. Het is namelijk een relatief eenvoudige methode, maar evengoed veelzijdig. U kunt het gedrag van een machine analyseren waardoor u een beter beeld heeft hoe lang de machine mee gaat.</li>\n 	<li>Een betrouwbaarheidsanalyse. Deze wordt ook wel Crow-AMSAA genoemd. Dit is een methode om de veranderingen en de betrouwbaarheid van een machine te bepalen. De datum wanneer een machine zal uitvallen wordt voorspeld.</li>\n 	<li>Een cumulatief frequentiepolygoon is het bepalen van de fouten in een bepaalde tijd. Dit is een relatief simpele manier om data te kunnen analyseren op aantallen en kosten.</li>\n</ul>\nDoor het analyseren van de onderhoudsdata kunt u een beter inzicht krijgen in de werking, of storingen, van machines of artikelen. Dit kan zorgen voor een goed onderhoudsplan en reductie van kosten. Deze analyses zijn echter gedaan op grond van basis gegevens. Wanneer u nog meer data zou hebben, zou u de mogelijkheid hebben om nog betere analyses te maken. Hiermee zou u een zeer duurzaam en efficiënt onderhoudsplan kunnen maken.\n<h2>Veel en interessante onderhoudsdata via het Internet of Things</h2>\nEen machine, onderdeel of object zou u nog veel meer data kunnen opleveren behalve de basisgegevens van een machine of artikel zoals leeftijd, reden van storing en vervangen onderdelen. Zo zou u bijvoorbeeld de staat, werking en het verbruik continu kunnen laten monitoren. Dit continu monitoren kan worden gedaan met een Internet of Things-oplossing.\n\nEen IoT-oplossing is een apparaat dat werkt op sensoren. Deze sensoren houden de verandering in een bepaalde omgeving in de gaten. Dat kan bijvoorbeeld gaan om druk, beweging of warmte, maar er bestaan nog veel meer veranderingen die sensoren kunnen meten. Wanneer een verandering optreedt in een machine of proces, dan wordt dit door de sensor opgepikt en door middel van een internetverbinding rechtstreeks doorgestuurd in de vorm van data.\n\nAls voorbeeld kunnen we een machine noemen waarbij de doorstroming van een bepaalde buis zeer belangrijk is. Raakt deze buis verstopt, dan valt de machine uit. Onderhoud moet dan gepleegd worden, zoals het vervangen van de buis. Oude onderhoudsdata, die u verkreeg via correctief onderhoud, liet zien dat de buis gemiddeld 6 maanden mee ging.\n\nMet een IoT-oplossing wordt de doorstroming van de buis continu gemonitord. Wanneer de buis na 5 maanden vol raakt dan geeft de sensor dit aan u door. U kunt onderhoud plegen voordat de machine vastloopt en eventueel extra schade oploopt. Loopt de buis na 6 maanden nog steeds prima door? Periodiek onderhoud is dan niet nodig.\n\nDit is een eenvoudig voorbeeld van wat onderhoudsdata via een IoT-oplossing voor u kan betekenen.\n<h2>De ThingsWay</h2>\nDe Thingsway is een IoT-sensor dat uw bedrijf van zulke interessante data kan voorzien. Het is een sensor dat in verschillende gebieden in te zetten is. Er bestaat een industriële versie, voor het vergaren van onderhoudsdata op gebied van machines en productie, maar de basis van de Thingsway is echter een product dat aan te passen is voor veel verschillende doeleinden.\n\nDe Thingsway is aan te passen op gebied van behuizing, sensoren en aansluitingen. Ook voor de internetaansluiting kunt u kiezen voor verschillende aanbieders. Meer onderhoudsdata biedt uw bedrijf de mogelijkheid om optimaal te profiteren, kosten te verlagen en uw bedrijf verder te laten groeien.\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>','Wat is onderhoudsdata? En wat kunt u ermee doen?','1692','inherit','closed','closed','','277-revision-v1','','','2022-01-31 09:36:22','2022-01-31 09:36:22','',277,'https://thingsway.media2netdev.nl/?p=367',0,'revision','',0),(368,1,'2022-01-31 09:36:23','2022-01-31 09:36:23','De opkomst van het Internet of Things betekent voor bedrijven soms een gedurfde sprong, maar het is een sprong naar een nieuwe industriële revolutie. Deze manier van werken bespaart bedrijven veel menselijke inspanningen en kosten. Bovendien betekent het een enorme sprong in kwaliteit van een procesbesturing. Nog niet zo lang geleden werden fabrieken en bedrijven in de industriële sector gezien als werkplekken waar nog flink gezwoegd werd. Het Internet of Things heeft gezorgd voor meer veiligheid, efficiëntie en stroomlijning in een geheel productieproces.\n\nEen werkvloer waar gezwoegd wordt doet idyllisch aan, misschien is dat de reden waarom nog niet iedereen het IoT wil omarmen. Een IoT-oplossing, zoals bijvoorbeeld de Thingsway van IoT-ontwikkelaar Salland Electronics, kan drastische veranderingen met zich meebrengen. Grote veranderingen zijn altijd spannend, en soms lastig te overtuigen voor een geheel team of werkvloer. Bent u benieuwd wat een IoT-oplossing kan betekenen voor uw procesautomatisering? Misschien kunnen de volgende voorbeelden u van dienst zijn en overtuigen.\n<h2>Wat kunnen IoT-oplossingen betekenen voor procesautomatisering?</h2>\nIn de industriële markt draait veel om intelligente besturing en controle van het productieproces. Een automatisch proces is ten slotte veel makkelijker dan constant een medewerker van de ene machine naar een andere lopende band te sturen. Procesautomatisering via een computer is veel effectiever.\n\nEen stapje verder dan een geautomatiseerd systeem is het IoT. In plaats van een knop omdraaien en vertrouwen in het systeem, monitort een IoT-oplossing het gehele proces continu. Zo krijgt u veel meer informatie over de werking en besturing van een proces of machine.\n<h2>Hoe verschilt dit met bestaande procesautomatiseringssystemen?</h2>\nEr zitten een aantal verschillen tussen traditionele procesautomatisering en een IoT-oplossing zoals:\n<ul>\n 	<li>Het IoT staat los van uw machines, het werkt via onafhankelijke systemen, sensoren en netwerken.</li>\n 	<li>Een IoT-oplossing gaat verder dan de functies van een bepaalde machine en/of de software.</li>\n 	<li>Wanneer u een IoT-oplossing gebruikt in een industrieel automatiseringsproces dan kunt u meerdere werkplekken met elkaar verbinden. Dit zorgt voor meer harmonie.</li>\n</ul>\n<h2>Een IoT-oplossing werkt draadloos</h2>\nEen draadloos met het internet verbonden systeem maakt het gemakkelijker om een procesbesturing te monitoren in een bepaalde omgeving, bijvoorbeeld wanneer deze omgeving gevaarlijk is. Het kan een probleem zijn wanneer een machine of kraan via een systeem met bedrading zou moeten werken. Vooral als dit de bewegingsvrijheid van een apparaat beïnvloed.\n\nDe draadloze technologie van een IoT-oplossing kan heel nuttig zijn om verfijning toe te passen bij procesautomatisering.\n<h2>Procesbesturing via een IoT-oplossing zorgt voor beheersbare groei</h2>\nHet groeien van een bedrijf heeft natuurlijk voordelen, maar het kan ook nadelen hebben. Zaken doen op hoger niveau zorgt voor extra risico’s, zoals bijvoorbeeld meer verspilling. Het Internet of Things is heel populair bij industrieel automatiseringsexperts, want het zorgt ervoor dat de juiste koers gevaren kan worden. Het continu monitoren zorgt voor enorm veel waardevolle data, waardoor er veel effectiever geproduceerd kan worden. Een vervangend onderdeel is bijvoorbeeld veel eerder bij een machine wanneer een IoT-oplossing een eventueel euvel herkend. Continu monitoren van verbruik geeft u de mogelijkheid om spaarzamer om te gaan met middelen.\n<h2>Een betere procesautomatisering door realtime communicatie</h2>\nEen IoT-oplossing zoals de Thingsway staat constant in contact met het internet. Via sensoren wordt een proces of een machine gemonitord. Deze data kan worden opgeslagen, maar ook direct worden ingezien. Dit kan ter plekke, maar ook op afstand via computer, tablet of smartphone. Dit zorgt voor kortere lijnen binnen een bedrijf. Een medewerker kan op de werkvloer gegevens inzien, maar ook een manager op afstand. Kortere lijnen betekenen minder vertraging.\n<h2>Snellere opsporing van fouten en benodigd onderhoud</h2>\nVerschillende bedrijven gebruiken verschillende manieren van onderhoud. Maintenance of onderhoud is een groot onderdeel van uw dagelijkse werkzaamheden. Doet u aan periodiek onderhoud? Dan bent u overgeleverd aan voorspellingen en een onderhoudsschema. Door middel van een IoT-oplossing kunt u onderhoud plegen, of laten plegen, wanneer dit echt nodig is. Een sensor kan een bepaald proces continu monitoren waardoor eventueel uitval van een machine of vastlopen van een proces snel opgespoord kan worden.\n\nNiet alleen kosten voor onderhoud kunnen zo verminderd worden, de werking van een machine kan veel beter geanalyseerd worden. Dit geeft betere inzichten en zorgt voor meer efficiëntie.\n\nBent u overtuigd van de voordelen die een Internet of Things-oplossing u kan bieden? Kijkt u dan eens naar de mogelijkheden van de Thingsway op gebied van procesautomatisering en procesbesturing.\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>','Procesautomatisering en procesbesturing verbeteren en optimaliseren','1695','inherit','closed','closed','','278-revision-v1','','','2022-01-31 09:36:23','2022-01-31 09:36:23','',278,'https://thingsway.media2netdev.nl/?p=368',0,'revision','',0),(369,1,'2022-01-31 09:36:24','2022-01-31 09:36:24','Sensoren zijn overal terug te vinden; in ons huis, in winkels, ziekenhuizen en op ons werk. Ze zitten in computers en smartphones en zijn een belangrijk onderdeel van Internet of Things- oplossingen. Sensoren bestaan al zeer lange tijd; zo bestaan infrarood sensoren namelijk al sinds het eind van de jaren 40 van de vorige eeuw. Een sensor die veel in ons huis gebruikt wordt kennen we sinds het eind van de jaren 80, de thermostaat. Deze sensor doet constante temperatuurmetingen en we merken er niets van, behalve een aangenaam warm huis. Dit toont aan hoe groot de waarde van sensoren kan zijn op de kwaliteit van ons leven. Sinds de opkomst van het Internet of Things is het gebruik van sensoren enorm gestegen.\n<h2>Wat doen sensoren?</h2>\nSensoren zijn apparaten die detecteren of er een verandering in de omgeving optreedt. Als deze verandering aanwezig is dan reageert de sensor hierop. De input die sensoren krijgen kunnen van verschillende bronnen afkomstig zijn zoals licht, beweging, druk en temperatuur. Wanneer deze sensoren op een netwerk zijn aangesloten, zoals bij een IoT-oplossing, dan kunnen de sensoren waardevolle informatie leveren aan aangesloten apparaten en een systeem die het beheert.\n\nVoor hedendaagse bedrijven zijn sensoren tegenwoordig cruciaal. Een sensor meldt een verandering in een proces. Deze informatie kan voortijdig problemen voorkomen. Hierdoor kunnen bedrijven aan zeer betrouwbaar voorspellend onderhoud doen. Dit voorkomt uitval, stilstand, hoge werkdruk en zorgt voor het verlagen van kosten. Een ander voordeel van een IoT-oplossing met sensoren is dat de gegevens geanalyseerd kunnen worden op trends. Hierdoor kunnen managers of eigenaren een goed inzicht krijgen en betere beslissingen nemen die op feiten gebaseerd zijn. IoT-sensoren zijn daarom heel belangrijk geworden om de efficiëntie te vergroten. Bovendien vergroten ze de veiligheid op de werkvloer.\n\nEr bestaan sensoren in veel verschillende soorten en maten. Sommige worden speciaal aangepast voor het betrokken bedrijf. De sensor bevat dan ingebouwde sensoren die een bepaald proces meten. Een voorbeeld van zo’n IoT-sensor is de Thingsway.\n<h2>De Thingsway</h2>\nDe Thingsway is een IoT-sensor die ingezet kan worden om veel verschillende processen te monitoren. Het product is heel snel aan te passen, daarmee is het een zeer flexibel product. De aanpassingen kunnen gedaan worden op gebied van behuizing en sensoren. Ieder proces vraagt namelijk om een ander soort sensor. De Thingsway is een IoT-oplossing voor bedrijven voor wie onderhoud en maintenance belangrijk is, zoals bijvoorbeeld woningcorporaties. Maar het is ook zeer goed in te zetten in de industriële sector. Temperatuurmetingen zijn namelijk erg belangrijk in de industriële sector, zo’n soort meting kan heel goed uitgevoerd worden door de Thingsway.\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\n\n&nbsp;\n<h2>Temperatuurmetingen</h2>\nHet is begrijpelijk om aan te nemen dat temperatuursensoren worden gebruikt om de temperatuur van een object of omgeving te meten. Het ligt echter wat genuanceerder dan dat. Temperatuursensoren controleren namelijk of een proces binnen een bepaald kader plaatsvindt. Om een proces of systeem goed te laten functioneren is vaak een bepaalde temperatuur nodig. De temperatuurmeting van de sensoren is daarom een soort preventieve toepassing die vooraf kan bepalen of er storing of zelfs gevaar gaat optreden.\n\nDe hoeveelheid warmte in een object wordt gemeten door een temperatuursensor. Veranderingen in de temperatuur worden gedetecteerd, omgezet in data en in geval van een IoT-oplossing via een internetverbinding verstuurd.\n\nDit is bijvoorbeeld bij het gebruik van machines van groot belang. Deze vereisen vaak dat de temperatuur van het apparaat, maar ook van de omgeving, op een standaard niveau ligt. Ook in de landbouw is het belangrijk om temperatuurmetingen uit te voeren. Zo zijn er nog enkele andere sectoren waarvoor een sensor die de temperatuur meet van groot belang is.\n<h2>In welke sectoren zijn temperatuurmetingen belangrijk?</h2>\nTemperatuurmetingen door middel van sensoren wordt in veel sectoren uitgevoerd. Deze sensoren leveren informatie aan een systeem, waardoor de temperatuur van een object, of een omgeving, constant en nauwkeurig kan worden bepaald.\n\nSectoren voor wie dit van groot belang is zijn bijvoorbeeld de eerder genoemde productie-industrie en de landbouw. U kunt zich voorstellen dat bepaalde gewassen het best groeien op een standaard temperatuur. Andere sectoren zijn de farmaceutische- en chemische industrie, en natuurlijk de voedingsmiddelenindustrie. Bij temperatuurmetingen moeten we namelijk niet alleen denken aan warmte en oververhitting, maar natuurlijk ook aan koeling.\n\nTemperatuurmetingen via een IoT-oplossing zoals de Thingsway, bieden de zekerheid die deze industrieën nodig hebben. Nauwkeurige en continue metingen zorgen voor veiligheid, betrouwbaarheid en efficiëntie van het gehele proces.\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>','Temperatuurmetingen met een IoT-oplossing','1698','inherit','closed','closed','','280-revision-v1','','','2022-01-31 09:36:24','2022-01-31 09:36:24','',280,'https://thingsway.media2netdev.nl/?p=369',0,'revision','',0),(370,1,'2022-01-31 09:36:25','2022-01-31 09:36:25','Heeft u ook een tekort aan onderhoudspersoneel? Het tekort aan technisch personeel is een probleem dat niet nieuw is en voor veel bedrijven niet gemakkelijk op te lossen. In de afgelopen jaren hebben verschillende factoren bijgedragen aan dit groeiende probleem. Het goede nieuws is dat er oplossingen bestaan. Een groot probleem kan bijna nooit in een dag worden opgelost, maar een IoT-oplossing kan u al een heel stuk verder brengen.\n<h2>Waardoor is het tekort aan onderhoudspersoneel ontstaan?</h2>\nEr zijn verschillende redenen waarom er in de huidige industrie een tekort aan onderhoudspersoneel is:\n<h2>Meer gepensioneerden dan nieuwe instroom</h2>\nEen belangrijke reden voor het tekort aan onderhoudspersoneel is dat er meer ervaren ouderen met pensioen gaan dan dat er startende werknemers instromen.\nDoor de razendsnelle technologische ontwikkelingen is het nodig om talloze nieuwe functies voor onderhoudstechnici te vervullen. De geavanceerde technologie maakt machines en processen complexer en vereist andere vaardigheden. Dit creëert op zijn beurt de behoefte aan meer specialisatie, waardoor er meer nieuwe vacatures nodig zijn.\n<h2>Studeren gepromoot boven beroepsonderwijs</h2>\nMet de handen werken werd jarenlang niet bepaald gepromoot. Nee, iemand kon maar het best zo lang mogelijk blijven studeren, liefst aan een universiteit of hbo. Het beroepsonderwijs heeft daaronder geleden, de studenten bleven veelal weg. Deze focus heeft geleid tot een vaardigheidskloof tussen generaties, dit betekent dat er veel minder twintigers zijn die de juiste vaardigheden hebben om een technische functie uit te kunnen oefenen.\n<h2>Afnemende belangstelling</h2>\nVeel bedrijven noemen een gebrek aan interesse de grootste reden van het tekort aan technisch personeel. De technische beroepen stonden lang bekend als minder lucratief waardoor de belangstelling aanzienlijk afnam. In deze bedrijfstakken liggen de lonen vaak lager dan in andere takken, daarom wordt het moeilijker om werknemers met het juiste niveau aan te trekken.\n\nEen verouderde en inefficiënte werkomgeving is een andere factor die bijdraagt aan de afnemende belangstelling. Sommige bedrijven werken nog steeds met verouderde methodes en rommelige werkplekken. Nieuwe werknemers voelen zich vaak niet thuis in zo’n omgeving.\n<h2>Oplossingen voor een tekort aan onderhoudspersoneel</h2>\nHet probleem van het tekort aan technisch onderhoudspersoneel is complex. Toch zijn er oplossingen die uw bedrijf kunnen helpen:\n<h2>Investeer in technische training</h2>\nEen belangrijke oplossing waar elk bedrijf gebruik van zou moeten maken is technische training. De technologie gaat continu vooruit, ook op gebied van onderhoud. Een onderhoudsprogramma zou gemoderniseerd kunnen worden door middel van betere software en de inzet van het Internet of Things. Het is daarbij cruciaal om uw onderhoudsteam te trainen en informeren zodat de efficiëntie van hun inzet vergroot wordt.\n\nNieuwkomers op de arbeidsmarkt komen vers van een technische opleiding, ze zullen daarom eerder kiezen voor een bedrijf met een modern onderhoudsprogramma.\n<h2>Investeer in een IoT-oplossing</h2>\nHet Internet of Things zorgt voor een nieuwe industriële revolutie. Steeds meer objecten en machines worden voorzien van sensoren en een internetverbinding. Het voordeel hiervan is dat u als bedrijf continue geïnformeerd wordt over de werking van een proces of apparaat. Kunt u zich voorstellen hoe handig dit kan zijn op gebied van onderhoud?\n\nAls voorbeeld kunnen we een machine nemen dat zeer belangrijk is in uw productieproces. Er wordt daarom regelmatig onderhoud uitgevoerd aan de machine, preventief en bij uitval. Als u de machine voorziet van een sensor dat vitale delen monitort dan bent u eventuele problemen voor, bovendien is er minder periodiek onderhoud nodig. Onderhoud hoeft dan alleen uitgevoerd te worden wanneer de sensor een probleem oppikt en aan u communiceert via de internetverbinding. Dit scheelt vanzelfsprekend veel tijd en inzet van onderhoudspersoneel.\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\n<h2>De Thingsway van Salland Electronics</h2>\nDe Thingsway is een Iot-sensor dat ontwikkeld is door Salland Electronics. Het grote voordeel van de Thingsway is dat deze enorm snel in te zetten is in uw bedrijf. Heeft u een tekort aan onderhoudspersoneel? Morgen kunt u al een IoT-oplossing in handen hebben dat een proces of machine continu monitort. Op die manier kunt u veel efficiënter gebruik maken van uw technische personeel.\n\nDe Thingsway is bijna in alle sectoren in te zetten, niet alleen de productie-industrie, maar ook bijvoorbeeld ook in de vastgoedsector. De sensor is een basisproduct dat snel aangepast kan worden op de wensen van uw bedrijf. Ook de internetverbinding wordt verzorgd door Salland Electronics.\n\nHet Internet of Things is één van de manieren om het tekort aan onderhoudspersoneel op te lossen.\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>','Te kort onderhoudspersoneel: hoe op te lossen?','1720','inherit','closed','closed','','282-revision-v1','','','2022-01-31 09:36:25','2022-01-31 09:36:25','',282,'https://thingsway.media2netdev.nl/?p=370',0,'revision','',0),(371,1,'2022-01-31 09:36:27','2022-01-31 09:36:27','Uitval en stilstand van een machinepark kost bedrijven enorm veel inkomsten. Om dit te voorkomen doen de meeste bedrijven aan preventief onderhoud. Het vermindert namelijk aanzienlijk gepland en ongepland onderhoud. Behalve preventief onderhoud kunt u als bedrijf nog meer doen om uitval van machines te voorkomen.\n<h2>Wat is uitval?</h2>\nUitval of stilstand is elke ongeplande gebeurtenis die de productie voor een bepaalde tijd stopt. Ongeplande stilstand wordt meestal veroorzaakt door menselijke fouten, slecht onderhoud, hardware- of softwarefouten en andere oorzaken zoals slechte prestaties of langzame omschakeling.\n<h2>Tips om uitval van een machinepark te verlagen</h2>\nBent u opzoek naar tips en aandachtspunten om uitval van uw machinepark te verlagen? Onderstaand nemen we tips met u door\n<h2>Voer een risico analyse uit</h2>\nEen risico analyse is de snelste en meest effectieve manier om uitval in de toekomst te verminderen. De veroudering van machines vormt een groot risico in een productieproces. Ondanks dat veel bedrijven moderniseren, wordt er ook nog vaak gebruik gemaakt van apparatuur dat 15 tot 20 jaar oud is. Vaak gaat het dan om verouderde systemen die niet langer door fabrikanten worden ondersteund. Het gevolg is dan dat onderdelen niet beschikbaar meer zijn, of in het buitenland besteld moet worden, wat soms wekenlang kan duren. Een onderdeel dat snel vervangen kan worden betekent het verschil tussen een paar uur stilstand of een paar maanden lang.\n\nVeiligheid en kwaliteit zijn andere risico\'s die van invloed zijn op uw machinepark. Een risico analyse zal problemen en oplossingen aan het licht brengen, zodat u beter voorbereid bent wanneer uitval zich voordoet.\n<h2>Bereken de kosten van uitval</h2>\nEen van de grootste fouten die gemaakt worden bij uitval of stilstand is het niet berekenen van de werkelijke kosten. De echte kosten omvatten verlies van productiviteit van medewerkers, verlies van productie, de besteedde manuren om het probleem te verhelpen, de bijkomende kosten om de machines te repareren en de tijd die u heeft besteed om klanten tevreden te stellen en uw reputatie te verzekeren.\n\nUitval en stilstand moet altijd in geld worden berekend. Het is van vitaal belang omdat de ware kosten u helpen om te focussen op de preventie van toekomstig uitval.\n<h2>Maak gebruik van voorspellend onderhoud</h2>\nDe wereld wordt steeds meer door data gedreven. Ook in de productie industrie maken fabrikanten gebruik van sensoren om uitval op de werkvloer te detecteren, voorkomen en verminderen. Sensoren kunnen veranderingen in een bepaalde ruimte of proces detecteren zoals trillingen, temperatuur, hitte en licht. Dit zijn veranderingen die schade of storing aan een machine kunnen veroorzaken. De sensoren sturen deze gegevens door naar bepaalde hardware, zoals een laptop of smartphone. Zodoende worden managers gewaarschuwd als er iets mis is. Operators van de machine, of een technisch team kan worden aangespoord om de omstandigheden te wijzigen. Dit voorkomt schade en uitval voordat het daadwerkelijk plaatsvindt.\n\nSensoren, zoals bijvoorbeeld de Thingsway van Salland Electronics zijn relatief voordelig. De Thingsway heeft een lange batterijduur en kan gemakkelijk aan elke machine worden bevestigd. Daarom is het zeker een kleine investering waard.\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\n<h2>Maak gebruik van software en data</h2>\nHet is logisch dat software van grote invloed kan zijn op uw inzicht van en controle over een productieproces. Veel bedrijven maken nog steeds gebruik van handmatige methoden om gegevens te verzamelen. Of ze maken gebruik van software dat ongeschikt is voor de taak.\n\nHet is van belang om uw huidige systeem van data verzameling te evalueren. Krijgt u de juiste en relevante informatie? De gegevens zouden de grootste oorzaken moeten aangeven van de uitval. Een geschreven rapport waarin staat dat machine 23 uitviel en twee uur stilstond is geen relevante informatie. Real-time operationele gegevens zijn relevant!\n\nDeze gegevens kunt u verkrijgen door een IoT-systeem in uw bedrijf te laten integreren. Een systeem dat data verzamelt van uw gehele machinepark. Hierdoor kan de fabrikant van een machine exact bepalen wanneer een machine uitvalt. Dit kan vergeleken worden met andere processen in de fabriek om een verband vast te stellen.\n<h2>Zorg dat uw technische onderhoudsteam up-to-date is</h2>\nDe snelle technologische ontwikkelingen zorgen ook op gebied van onderhoud ook voor veel veranderingen. De kans is groot dat u machines gebruikt van verschillende fabrikanten. Het is daarom van groot belang dat uw technische personeel constant getraind wordt en up-to-date blijft.\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>','Uitval machine park verlagen: tips en aandachtspunten','1725','inherit','closed','closed','','284-revision-v1','','','2022-01-31 09:36:27','2022-01-31 09:36:27','',284,'https://thingsway.media2netdev.nl/?p=371',0,'revision','',0),(372,1,'2022-01-31 09:36:28','2022-01-31 09:36:28','Preventief onderhoud van apparatuur is cruciaal om de levensduur van kritische machines te verlengen en de efficiëntie van installaties te maximaliseren. De installaties en machines stellen een bedrijf niet alleen in staat om op grote schaal te produceren, maar ze bepalen ook de winst wanneer dit efficiënt gebeurt. Een machine die uitvalt kan rampzalig zijn voor een bedrijf, omdat dit leidt tot stilstand en hoge kosten. Onderhoud van machines en installaties is daarom van groot belang, maar onderhoud brengt ook kosten met zich mee. Hoe kunt u installaties en machines efficiënt onderhouden? We geven een aantal tips:\n<h2>Voorspellend onderhoud door middel van een sensor</h2>\nDoor de snelheid van slijtage of veroudering te bewaken kan worden bepaald of er reparaties en vervangingen nodig zijn. Om dit te bepalen werd er in het verleden vaak gebruik gemaakt van een periodiek inspectieschema. Daarbij werden vitale delen om de zoveel tijd geïnspecteerd, denk dan aan riemen, kettingen, tandwielen en vloeistoffen.\n\nBedrijven kiezen er steeds vaker voor om vitale delen te laten bewaken door sensoren. Deze houden het proces continu in de gaten waardoor een periodiek inspectieschema niet meer nodig is.\n\n<img class=\"size-full wp-image-1565 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/10/Tools-continue-monitoren.jpg\" alt=\"toosl continue monitoren\" width=\"1170\" height=\"500\" />\n<h2>Houd de procesapparatuur schoon</h2>\nInstallaties en machines bevatten verschillende filters en afdichtingen om werkende componenten schoon te houden. Vervuiling, zoals vetophoping, kan leiden tot een plotselinge storingen en uitval. Water is bovendien een belangrijke bron van vervuiling en corrosie. Om apparaten optimaal te laten presteren moeten daarom afdichtingen en filters regelmatig worden geïnspecteerd.\n\nU kunt dit doen via periodiek onderhoud, maar u kunt er ook voor kiezen om bepaalde filters of afdichtingen continu te laten monitoren met een sensor.\n<h2>Smeer apparatuur regelmatig om de efficiëntie te garanderen</h2>\nSmering speelt een grote rol bij het handhaven van de prestaties van apparatuur. Het zorgt ervoor dat alle bewegende delen soepel blijven werken. Wrijving tussen bewegende delen wordt verminderd door smering, daarom verbetert het de efficiëntie van uw machines en verlengt het de levensduur. Maak gebruik van het juiste smeermiddel, volg daarbij de aanbevelingen van de fabrikant.\n\nOm op het juiste moment te smeren moet al het apparatuur bewaakt worden. U kunt dit laten doen door periodieke inspectie, maar ook door middel van een sensor.\n<h2>Zorg voor een efficiënt onderhoudsschema</h2>\nOm uw machines en installaties in topconditie te houden is onderhoud nu eenmaal nodig. Een efficiënt onderhoudsschema zorgt ervoor dat alle inspecties, reparaties en vervangingen exact op het juiste tijdstip gedaan worden. Natuurlijk het liefst voordat er uitval plaatsvindt.\n\nEen efficiënt onderhoudsschema is een combinatie van reactief en proactief onderhoud. Reactief onderhoud kunt u toepassen op onderdelen die relatief goedkoop zijn en makkelijk te vervangen. Dit gaat om niet vitale onderdelen, wanneer deze stuk gaan dan ligt niet het gehele proces stil.\n\nEr bestaan verschillende vormen van proactief onderhoud waaronder periodiek onderhoud en conditie gestuurd onderhoud. Periodiek onderhoud kunt u het best uit laten voeren op onderdelen waarvan u een goed beeld heeft van de werking en slijtage. De efficiëntie van uw onderhoud kunt u vergroten door middel van conditie gestuurd onderhoud. Daarbij laat u vitale delen monitoren door middel van sensoren. Deze registreren veranderingen in een proces en maken daar melding van zodat u exact op het juiste moment onderhoud kunt laten uitvoeren.\n<h2>Bewaar apparatuur veilig wanneer deze niet in gebruik is</h2>\nWanneer uw machines niet in gebruik zijn, of uw installaties staan een tijd stil, sla deze dan op in een schone omgeving. Dit voorkomt dat ze door vuil of corrosie worden aangetast. Laat apparaten tevens niet lang stilstaan, rust roest. Laat de apparaten daarom regelmatig draaien.\n<h2>Maak gebruik van het Internet of Things</h2>\nIn onze tips werd regelmatig het gebruik van sensoren genoemd. Deze sensoren kunnen u helpen om de efficiëntie van uw onderhoudsprogramma te vergroten. Dat doen ze door continu een proces te monitoren. De sensoren registreren een verandering in een omgeving dat kritiek kan zijn voor het hele proces. Via een directe internetverbinding meldt de sensor dit op een centraal punt, denk dan aan een computer of smartphone. Op dat moment kunt u ingrijpen en een storing of uitval voor zijn.\n\nDe Thingsway is een voorbeeld van zo’n IoT-sensor. Het is een prachtig product dat uw bedrijf kan helpen in het efficiënt onderhouden van uw installaties en machines.\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>','Hoe kan ik mijn installaties en machines efficiënt onderhouden?','1728','inherit','closed','closed','','286-revision-v1','','','2022-01-31 09:36:28','2022-01-31 09:36:28','',286,'https://thingsway.media2netdev.nl/?p=372',0,'revision','',0),(373,1,'2022-01-31 09:36:29','2022-01-31 09:36:29','Eén van de oudste bedrijfstakken in de wereld is verzekeringen. Het idee van het delen van risico’s begon 5000 jaar geleden toen Chinese kooplieden hun vracht over meerdere schepen verdeelden. Natuurlijk bleven er risico’s, maar de kooplieden hadden de verzekering dat hun voorraad niet volledig ten onder zou gaan als een schip zou zinken. Het vervoeren van goederen over zee gebeurt nog steeds en de methode van verzekeren is ook lange tijd niet veel veranderd. De opkomst van het Internet of Things zorgt echter ook in de verzekeringswereld voor een transformatie. Heeft u een bedrijf dat veel te maken heeft met onderhoud? Dan kunt u het best gebruik maken van het IoT om onderhoudsdata vast te leggen.\n<h2>Waar wordt onderhoudsdata voor gebruikt?</h2>\nGegevens die verzameld worden tijdens onderhoud worden over het algemeen gebruikt om de werking van een object of machine te waarborgen. Door het analyseren van deze data kunnen verschillende meerdere essentiële factoren worden bepaald; hoe snel slijtage ontstaat, onder welke omstandigheden een proces het meest efficiënt verloopt, hoe vaak er onderhoud gepleegd moet worden en welke onderdelen vitaal zijn in het gehele proces.\n\nHet verzamelen van deze gegevens heeft echter nog een functie, namelijk als bewijslast voor de verzekering.\n<h2>Onderhoudsdata als bewijslast voor de verzekering</h2>\nOok al doet u als bedrijf alles om problemen te voorkomen, storingen, schade en uitval komt nu eenmaal overal voor. Het valt helaas bijna niet te vermijden. In geval van een storing of uitval heeft u te maken met meerdere partijen: uw klanten die wachten op uw product; de fabrikant van de machine die uitgevallen is of het object dat schade opgelopen heeft, en de verzekeringsmaatschappijen van alle partijen.\n\nAls bedrijf wilt u dat het probleem zo snel mogelijk opgelost wordt. Een storing moet zo snel mogelijk verholpen worden, een defect zo snel mogelijk gerepareerd. Langere stilstand kost u veel geld, het maakt de schade in sommige gevallen groter en doet bovendien uw reputatie niet goed. Ook in geval van de verzekering wilt u het liefst dat alles zo snel mogelijk afgehandeld wordt. Om die afhandeling te sneller te kunnen laten verlopen is het van belang om zo duidelijk mogelijk te hebben wat de reden was van de storing, uitval of bijkomende schade. De schuldige partij kan dan snel worden bepaald.\n\n<img class=\"alignnone size-full wp-image-1671\" src=\"https://thingsway.nl/wp-content/uploads/2020/10/data-inspectie-onderhoud.jpg\" alt=\"inspectie onderhoud\" width=\"1170\" height=\"500\" />\n<h2>Hoe komt u aan real-time onderhoudsdata?</h2>\nAls het goed is worden vitale objecten, machines en hun onderdelen in uw bedrijf bewaakt. Dit doet u door middel van periodieke inspecties en eventueel onderhoud. Dit wordt uitgevoerd door technici of een maintenancebedrijf. Het nadeel van deze methode is dat het bewaken niet continu wordt gedaan. Gegevens worden niet constant gemeten en genoteerd. Hierdoor bent u niet altijd in bezit van real-time en accurate gegevens. Een ander nadeel is dat u nog steeds afhankelijk bent van wat er genoteerd wordt tijdens een inspectie.\n\nHet Internet of Things wordt steeds meer toegepast in het bewaken van machines en processen. Deze worden continu gemonitord door middel van sensoren. Wanneer er een verandering in de omgeving plaatsvindt wat een toekomstig probleem kan opleveren, dan registreert de sensor dit en stuurt deze gegevens onmiddellijk door zodat er ingegrepen kan worden door een operator of onderhoudstechnicus. Het grote voordeel hiervan is dat uitval en stilstand kan worden voorkomen.\n\nHet andere voordeel is dat u de beschikbaarheid heeft over enorm veel real-time data. Door deze data te analyseren kunt u bepalen waarom het probleem zich heeft voorgedaan. Kwam het door fout gebruik van de operator? Was er een verandering in de omgeving van het object waar u niets aan kon doen? Zat er een fabricagefout in de machine? Door middel van sensoren kan alles vastgelegd worden, in real-time.\n<h2>De Thingsway, een Internet of Things sensor</h2>\nDoor Salland Electronics is de Thingsway ontwikkeld. Het is een IoT-sensor dat in veel sectoren toepasbaar is. Heeft u te maken met veel onderhoud? Dan kan de Thingsway een oplossing voor u zijn. Niet alleen voor het monitoren van een proces, maar ook om gegevens vast te leggen die belangrijk kunnen zijn voor uw verzekeringen en eventuele claims.\n\nOok de verzekeraars gaan ook met hun tijd mee. Beslissingen worden steeds vaker genomen op basis van data. Meer efficiëntie zorgt voor lagere kosten, dat geldt voor de verzekeringsmaatschappij en tevens voor uw bedrijf.\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>','Onderhoudsdata gebruiken als bewijslast voor verzekeringen?','1740','inherit','closed','closed','','288-revision-v1','','','2022-01-31 09:36:29','2022-01-31 09:36:29','',288,'https://thingsway.media2netdev.nl/?p=373',0,'revision','',0),(374,1,'2022-01-31 09:36:30','2022-01-31 09:36:30','Het Internet of Things wordt sinds enige jaren volop ingezet om de werking van apparaten en activa van bedrijven te monitoren. Steeds meer machines en objecten worden voorzien van sensoren. Door middel van een directe internetverbinding wordt er data verkregen dat een bedrijf kan helpen om de efficiëntie te vergroten.\n\nWist u dat het Iot ook zeer nuttig kan zijn in het zo veilig mogelijk houden van de werkomgeving? Een veilige werkomgeving is één van de eerste prioriteiten van een bedrijf. U wilt natuurlijk dat uw werknemers zo goed en veilig mogelijk hun werk kunnen doen. Ongevallen op de werkvloer wilt u zoveel mogelijk vermijden. Een veilige werkomgeving creëert u door een goede infrastructuur, goed werkende machines, veilige hulpmiddelen en een strikte regelgeving.\n<h2>Waarom het naleven van de regelgeving belangrijk is</h2>\nDe regelgeving in uw bedrijf heeft u voor goede redenen opgesteld. U wilt dat de productie van uw bedrijf zo efficiënt mogelijk draait. Bovendien wilt u een werkomgeving garanderen waar uw medewerkers zich niet alleen veilig voelen, maar waar ze ook daadwerkelijk veilig zijn. Het naleven van de regels is daarom zeer belangrijk, vooral in een omgeving waar veel gewerkt wordt met machines of zware en instabiele objecten.\n\nEr bestaat nog een andere reden waarom de naleving van de regelgeving belangrijk is, namelijk vanwege verzekeringen en eventuele claims van klanten. Wanneer iemand van uw technische team niet volgens de regels onderhoud heeft gepleegd dan kan niet alleen de veiligheid van medewerkers in het geding komen. Er zouden namelijk ook claims van fabrikanten of klanten kunnen komen in geval van schade, uitval of stilstand. Dit kan voor hoge kosten zorgen voor uw bedrijf en een negatief effect hebben op uw omzet en betrouwbaarheid.\n\n<img class=\"size-full wp-image-1752 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/11/regels-en-regelgeving.jpg\" alt=\"regels en regelgeving \" width=\"1000\" height=\"800\" />\n<h2>Onderhoudsdata gebruiken als bewijslast voor regelgeving</h2>\nHet is duidelijk dat het heel belangrijk is dat iedereen in uw bedrijf werkt volgens de regelgeving. Om de naleving van de regels te controleren wordt er veelal gebruik gemaakt van fysieke controles en steekproeven. Dit zorgt ervoor dat u gegevens heeft over de inzet en naleving van regels door specifieke medewerkers.\n\nU kunt er echter ook voor kiezen om de naleving van de regelgeving continu te laten monitoren, bijvoorbeeld op gebied van onderhoud. De onderhoud van machines of activa is van groot belang, ook daarvoor zijn specifieke regels opgesteld. Dit garandeert de werking, productiviteit, effectiviteit en veiligheid van medewerkers of zelfs eventuele bewoners (bijvoorbeeld in geval van een lift in een flat).\n\nOnderdelen van een machine moeten af en toe gesmeerd worden, de temperatuur van een motor mag niet te hoog worden, slijtage kan voor uitval zorgen en moet worden gerapporteerd, een volle dakgoot kan voor waterschade zorgen. Dit zijn slechts enkele voorbeelden waarom onderhoud gepleegd moet worden, en volgens bepaalde regelgeving. Het juist uitvoeren van deze regels kan gecontroleerd worden door middel van onderhoudsdata.\n<h2>Hoe kunt u onderhoudsdata verkrijgen?</h2>\nEen oude manier van het vergaren van gegevens van onderhoud is via spreadsheets en geschreven notities in bijvoorbeeld een logboek. Dit is echter een vrij algemeen beeld en geeft u vaak niet de actuele toestand van een machine of object. Bovendien komt de notitie van de onderhoudsmedewerker die het onderhoud uitgevoerd heeft. U zou natuurlijk extra controle kunnen laten doen door een andere medewerker. Maar zou het niet veel effectiever zijn wanneer u gebruik maakt van een sensor? Sensoren kunnen exact monitoren of de werking van een proces optimaal verloopt. Wanneer dit niet het geval is, dan is onderhoud nodig en is de regelgeving (mogelijk) niet goed nageleefd.\n<h2>De Thingsway, een IoT-sensor</h2>\nDe Thingsway is een voorbeeld van zo’n sensor. Deze is in staat om allerlei processen te monitoren. Een verandering in de omgeving wordt onmiddellijk door de sensor geregistreerd, deze gegevens worden doorgestuurd via een directe internetverbinding naar een centraal punt (computer, laptop etc.) Na het analyseren van de gegevens kunt u bepalen of de regelgeving is nageleefd.\n\nSalland Electronics is de ontwikkelaar van de Thingsway. Het grote voordeel is dat de Thingsway zeer snel in te zetten is, bovendien in verschillende omgevingen. Er bestaat een Thingsway voor toepassingen in de buitenlucht, maar ook een industriële versie. Binnen een dag kunt u al voorzien zijn van een sensor inclusief internetverbinding. Zodoende kunt u zorgen dat iedereen in uw bedrijf volgens de regels werkt.\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>','Onderhoudsdata gebruiken als bewijslast voor regelgeving','1750','inherit','closed','closed','','290-revision-v1','','','2022-01-31 09:36:30','2022-01-31 09:36:30','',290,'https://thingsway.media2netdev.nl/?p=374',0,'revision','',0),(375,1,'2022-01-31 09:36:31','2022-01-31 09:36:31','[et_pb_section admin_label=\"section\"]\n			[et_pb_row admin_label=\"row\"]\n				[et_pb_column type=\"4_4\"][et_pb_text admin_label=\"Text\"]Door veel managers op het hoogste niveau wordt onderhoud slechts beschouwd als een kostenpost. Daarom worden er door onderhoudsmanagers vaak nieuwe manieren gezocht om de kosten te verlagen. Een kleiner budget zorgt vaak voor een kleiner onderhoudsteam, wat de werkdruk steeds meer vergroot op de leden van dit team. Gelukkig bestaan er een aantal manieren waarop u deze druk kunt weghalen. Daardoor behoudt u onderhoudspersoneel die gemotiveerd en efficiënt blijven werken.\n<h2>Hoe kunt u de druk op onderhoudspersoneel wegnemen?</h2>\nHet eerste wat u kunt doen om de druk weg te halen bij het onderhoudspersoneel is door te zorgen voor een preventief onderhoudsschema dat in balans is en daarmee effectief. Het opstellen hiervan kan soms moeilijker zijn dan u denkt. Het is belangrijk dat het schema gebaseerd is op accurate gegevens. Tevens moeten uw beschikbare middelen objectief bekeken worden.\n\nVoor een effectief preventief onderhoudsschema heeft u onderhoudsdoelen nodig, daarnaast moet u een goede strategie hebben om deze doelen te bereiken. U dient accurate gegevens te hebben van uw activa en inventaris. Daarnaast is het belangrijk om te bepalen wie het meest geschikt is voor welke taak en deze toe te wijzen. Teveel preventief werk inplannen is een valkuil die u het best kunt vermijden. Dit kunt u doen door uw onderhoudsplan te verfijnen met goede hulpmiddelen zoals bijvoorbeeld software.\n\nAls manager is het noodzakelijk om goed te luisteren wanneer onderhoudspersoneel naar u toe komt met vragen of suggesties. Het kan zijn dat een medewerker een goed idee heeft hoe het uitvoeren van een taak vereenvoudigd kan worden, of hoe er efficiënter omgegaan kan worden met de voorraad. Medewerkers die moeite doen om u feedback te geven zullen meer waardering voelen wanneer dit serieus genomen wordt. Uiteindelijk zal dit de motivatie van de medewerker ten goede komen.\n\nUw onderhoudspersoneel zal regelmatig onregelmatigheden opmerken en daardoor voor nuttige gegevens zorgen. Wat hun daarbij kan assisteren zijn hulpmiddelen zoals onderhoudssoftware en sensoren.\n<h2>Verlaag de druk op uw onderhoudspersoneel met sensoren</h2>\nPreventief onderhoud is één van de beste manieren om uitval en storingen van machines te voorkomen. Door deze regelmatig te onderwerpen aan inspectie kunt u problemen voor zijn, zoals bijvoorbeeld slijtage en ingrijpen waar nodig. Om de druk bij uw onderhoudspersoneel weg te nemen kunt u ook kiezen voor een ander soort onderhoud, namelijk conditie gestuurd onderhoud. Dat wil zeggen dat het onderhoudsteam pas aangestuurd wordt wanneer dit echt nodig is.\n\nVoor een optimale werking zijn bepaalde factoren nodig, dat geldt voor machines maar ook voor objecten zoals bijvoorbeeld een dakgoot. Uitval, storing of schade kan plaatsvinden wanneer een machine te heet wordt, of wanneer een dakgoot niet doorstroomt. Om deze indicaties vast te stellen kunt u natuurlijk preventieve inspecties doen, maar het werkt veel effectiever door middel van sensoren.\n\nBij het Internet of Things wordt veel gebruik gemaakt van sensoren. Deze sensoren monitoren continu veranderingen in de omgeving, zoals warmte, druk of beweging. Wanneer een verandering plaats vindt dan registreert de sensor dit, via een rechtstreekse internetverbinding wordt deze verandering gemeld. U ontvangt deze melding en kan ingrijpen voordat een storing, uitval of eventuele schade optreedt.\n<h2>De Thingsway, een Internet of Things-sensor</h2>\nEen Iot-oplossing kan u helpen om de druk bij uw onderhoudspersoneel weg te nemen. De Thingsway is zo’n Iot-oplossing, ontwikkeld door Salland Electronics. Deze sensor is voor veel verschillende toepassingen inzetbaar. Het grote voordeel is dat de Thingsway zeer snel aangepast wordt op uw wensen. Binnen een dag kunt u al voorzien zijn van een sensor inclusief internetverbinding.\n\nHet basismodel kan aangepast worden op gebied van behuizing, aansluiting en natuurlijk de geschikte sensor om veranderingen in de omgeving te meten.\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\n<h2>Wat zijn de voordelen van de druk weghalen?</h2>\nDe voordelen van het wegnemen van de druk op onderhoudspersoneel zijn enorm. Ten eerste zijn er de voordelen voor de werknemers. Deze zullen meer balans hebben in hun schema, daardoor zullen ze gemotiveerder en uitgerust aan het werk gaan. Dat zal de kwaliteit, veiligheid en efficiëntie van het werken verhogen. Dit zal van invloed zijn op de efficiëntie van het gehele bedrijf. Machines en activa die goed werken zorgen voor meer werkplezier en productiviteit.\n\nHet bedrijf zal verder profiteren van de lagere kosten voor onderhoud.\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>[/et_pb_text][/et_pb_column]\n			[/et_pb_row]\n		[/et_pb_section]','De voordelen van verlaagde druk op onderhoudspersoneel','1755','inherit','closed','closed','','292-revision-v1','','','2022-01-31 09:36:31','2022-01-31 09:36:31','',292,'https://thingsway.media2netdev.nl/?p=375',0,'revision','',0),(376,1,'2022-01-31 09:36:33','2022-01-31 09:36:33','In de toekomst zullen steeds meer bedrijven aan voorspellend onderhoud doen via een IoT-oplossing. Voor bedrijven die veel te maken hebben met onderhoud is het lastig om de kosten voor onderhoud laag te houden en tegelijkertijd de beschikbaarheid van activa hoog. Om dit evenwicht te bewaren is een effectief onderhoudsplan nodig. Voorspellend- of conditie gestuurd onderhoud via een IoT-oplossing geeft bedrijven de mogelijkheid om aan regelgeving te voldoen, kosten voor onnodig onderhoud te beperken en storingen, uitval en stilstand te voorkomen.\n<h2>Het verschil tussen preventief en voorspellend onderhoud</h2>\nPreventief onderhoud is onderhoud dat gepland volgens een bepaalde interval periode. Dit onderhoud vindt plaats ongeacht de conditie van de middelen en is bedoeld om defecten te voorkomen. Voorspellend onderhoud vindt plaats wanneer het nodig is, er is een voorspeld risico dat defecten zullen optreden aan machines of objecten.\n\nVoorspellend onderhoud brengt enige investeringen met zich mee, maar zal op de lange termijn winst opleveren omdat onnodig onderhoud niet meer uitgevoerd hoeft te worden.\n<h2>Voorspellend onderhoud in de praktijk</h2>\nIn de praktijk werkt voorspellend onderhoud via IoT zo; de werking van een proces of apparatuur wordt gemeten door middel van continue monitoring. De gegevens worden vastgelegd door sensoren en via een internetverbinding doorgestuurd naar een centraal punt. Na het analyseren van deze gegevens kunnen bedrijven veel betere voorspellingen doen wanneer een machine uit zal vallen, maar ook hoe een proces zo effectief mogelijk verloopt. Dit zijn proactieve stappen die een bedrijf kan nemen om meer controle te houden op een geheel productieproces.\n<h2>Voorspellend onderhoud met de Thingsway</h2>\nDe Thingsway is zo’n IoT-sensor dat ingezet kan worden om voorspellend onderhoud mogelijk te maken. Salland Electronics heeft een flexibel product gemaakt met de Thingsway. Het is namelijk zeer snel aanpasbaar en in te zetten in elke omgeving. Dat in tegenstelling tot veel andere IoT-sensoren die nog wel eens log worden genoemd.\n\nBinnen een dag kunt u al voorzien zijn van een Thingsway, geheel aangepast op het proces dat gemonitord dient te worden.\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\n<h2>Wat zijn de voordelen van het IoT bij onderhoud?</h2>\nDe voordelen van het IoT bij onderhoud zijn:\n• Verlaging van onderhoudskosten;\n• Verhoging van het gebruik van activa;\n• Verlenging van de levensduur;\n• Efficiëntere inzet van personeel;\n• Een veiligere en gezondere werkomgeving.\n<h2>Verlaging van onderhoudskosten</h2>\nAl het onderhoud brengt kosten met zich mee. Bovendien zijn de bijkomende kosten door onverwachte uitval vaak aanzienlijk. Door bepaalde machines of objecten continu te laten monitoren kan een bedrijf geld besparen door problemen voor te zijn en voortaan te voorkomen. IoT-sensoren kunnen nauwkeurige voorspellingen doen over de werking van een proces. De data die verkregen wordt geeft de mogelijkheid om het onderhoudsplan naar een nieuw niveau te tillen.\n<h2>Verhoging van het gebruik van activa</h2>\nHet voorkomen van storingen en uitval zal ongeplande stilstand verlagen. Dit verhoogt logischerwijs het gebruik van uw machines. Bovendien is het niet meer nodig om periodiek onderhoud te plegen, waardoor machines nog minder stil hoeven te staan. Het IoT zorgt ervoor dat u operationeel kunt blijven, de sensoren vormen uw bewakers van het gehele proces.\n<h2>Verlenging van de levensduur</h2>\nHet continu monitoren zorgt voor veel gegevens, daardoor krijgt u een beter inzicht in de werking van uw machines. Hierdoor kunt u storingen beter voorspellen en de kritieke onderdelen identificeren. Het gebruik van activa wordt daardoor niet alleen vergroot, ook de levensduur zal toenemen. Door op tijd onderdelen te vervangen, of het juiste onderhoud te plegen zal slijtage aan machines beperkt blijven.\n<h2>Efficiëntere inzet van personeel</h2>\nDoor gebruik te maken van een IoT- oplossing kunt u uw personeel efficiënter inzetten. De werking van uw middelen wordt met een IoT-oplossing bewaakt door sensoren. Dat geeft een bedrijf de mogelijkheid om beter te plannen en prioriteiten te stellen. Een probleem zorgt er voor dat onderhoudsmedewerkers onverwacht ergens ter plekke moeten komen. Dit zorgt vaak voor vertraging in het productieproces en eist flexibiliteit van andere medewerkers. Misschien moet u personeel verplaatsten van plek, of zelfs extra personeel inhuren.\n\nDoor IoT onderhoud toe te passen worden dit soort problemen vermeden. De inzet van onderhoudsmedewerkers wordt veel effectiever en de uitvaltijd verminderd.\n<h2>Een gezondere en veiligere werkomgeving</h2>\nProblemen met middelen of machines kunnen ook zorgen voor gevaarlijke situaties op de werkvloer. Door gebruik te maken van IoT- sensoren kunnen deze situaties vermeden worden. De sensoren kunnen een proces monitoren en veranderingen in de omgeving registreren en melden. Dit stelt u in staat om mogelijke gevaarlijke situaties voor te zijn. Door het analyseren van gegevens over een langere periode kunnen deze mogelijke gevaarlijke omstandigheden geïdentificeerd worden.\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>','Onderhoud en IoT: wat zijn de mogelijkheden en de voordelen ervan?','1763','inherit','closed','closed','','294-revision-v1','','','2022-01-31 09:36:33','2022-01-31 09:36:33','',294,'https://thingsway.media2netdev.nl/?p=376',0,'revision','',0),(377,1,'2022-01-31 09:36:34','2022-01-31 09:36:34','De kosten voor onderhoud maken voor veel bedrijven een groot deel uit van de totale bedrijfskosten, soms wel 25%. Ongeveer de helft van deze kosten bestaan uit arbeidskosten, dat is de reden waarom efficiency van onderhoud zo belangrijk is. Het verhogen van de efficiency op onderhoud heeft bovendien positieve gevolgen op de betrouwbaarheid van een bedrijf. De prestaties blijven op het juiste niveau, terwijl de kosten voor onderhoud verlaagd worden.\n\nHelaas wordt niet overal even efficiënt gewerkt. Bij het uitvoeren van onderhoudstaken is er vaak sprake van verspilling en inefficiëntie. Dan zijn er bijvoorbeeld onnodig veel mensen met een taak bezig, er moet worden gezocht naar vervangende onderdelen, of technici moeten wachten tot een bepaalde machine vrij komt. Het maakt niet uit of u het onderhoud in eigen beheer heeft of dat u het uitbesteedt, de kosten voor de inefficiëntie komen op uw rekening.\n\nEr zijn verschillende redenen waarom de efficiency van onderhoud niet optimaal is zoals; teveel reactief onderhoud, teveel mankracht in de nachtdienst en een slechte planning.\n<h2>Leunen op reactief onderhoud is inefficiënt</h2>\nHelaas zijn er veel bedrijven die leunen op reactief onderhoud. De focus van deze bedrijven ligt bij een zo hoog mogelijke productie. Pas wanneer een probleem zich voordoet wordt er ingegrepen en onderhoud gepleegd. Eigenlijk is er dan geen sprake van onderhoud, maar reparatie. Een storing of probleem kan door reactief onderhoud nooit worden voorspeld. Dit zorgt ervoor dat onderhoud bijna niet te plannen is, u weet nooit wanneer de problemen zich voordoen. Gevolg hiervan is dat u constant een onderhoudsteam paraat moet hebben.\n\nOm de efficiency te vergroten zou u een gedegen actief onderhoudsplan moeten hebben. Reactief onderhoud zou u moeten beperken tot de middelen die snel vervangbaar zijn.\n\n<img class=\"size-full wp-image-1769 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/11/onderhoud-winst-maken.jpg\" alt=\"onderhoudskosten verlagen\" width=\"960\" height=\"638\" />\n<h2>Veel mankracht in de nachtdienst is inefficiënt</h2>\nVeel bedrijven werken in ploegendiensten, dat geldt ook vaak voor de technici van onderhoudsteams. De gedachte hierachter is dat storingen altijd kunnen plaatsvinden en er dus iemand aanwezig moet zijn. In de praktijk is het echter zo dat 75% van de storingen tijdens de dagdienst gebeuren. Het inzetten van personeel op de juiste werktijden kan de efficiëntie verhogen.\n<h2>Slechte planning zorgt voor inefficiëntie</h2>\nDe kwaliteit van onderhoud wordt voor een groot gedeelte bepaald door een goede planning van onderhoudstaken. Een goed schema zorgt ervoor dat de juiste activa op het juiste moment wordt onderhouden. Bovendien zorgt een efficiënt schema voor balans in de taken van technici en het gaat verspilling tegen. Het onverwacht verplaatsen van mankracht van plek naar plek kost reistijd, personeelskosten en zorgt voor stilstand.\n\nDe efficiency van een bedrijf wordt flink verhoogd door middel van een systematisch onderhoudssysteem. U heeft natuurlijk ook positieve mensen nodig met capaciteiten. Daarnaast kunt u gebruik maken van de technologie om de efficiency op onderhoud te verhogen. Dat kunt u doen door middel van een IoT-oplossing.\n<h2>Meer efficiency door het Internet of Things</h2>\nHet Internet of Things is enorm in opkomst bij bedrijven die veel te maken hebben met onderhoud. De voordelen van het IoT zijn namelijk talrijk. Door systemen, objecten of machines te laten monitoren door sensoren wordt de efficiency van een bedrijf verhoogd. Het kan een bedrijf daardoor veel kosten besparen op gebied van onderhoud.\nStel u heeft een productiebedrijf dat gebruik maakt van machines. Deze machines zijn kritisch voor u, uitval betekent stilstand en kan voor hoge kosten zorgen. Dit is de reden waarom u waarschijnlijk aan periodiek onderhoud doet. U wilt problemen voor zijn door de conditie van de machines in de gaten te houden middels periodieke metingen. Tijdens deze metingen wordt indien nodig onderhoud uitgevoerd.\n\nU zou deze metingen ook kunnen laten uitvoeren door middel van een sensor. De vele voordelen van de sensor zijn dat deze eenmalig kosten met zich meebrengt, continu het proces monitort en problemen meldt voordat deze zich voordoen.\nDit scheelt u veel inzet en reistijd van onderhoudspersoneel, deze worden gerichter ingezet, namelijk pas op momenten dat de sensor een melding geeft.\n<h2>De Thingsway</h2>\nDe Thingsway is een IoT-sensor dat uw bedrijf kan helpen om de efficiency van onderhoud te verhogen. Deze sensor is een basisproduct dat snel aan te passen is op het te meten proces. De aanpassingen worden gedaan op gebied van behuizing, aansluiting en de benodigde sensoren.\n\nBinnen een dag kan Salland Electronics u voorzien van een Thingsway. Maak gebruik van het IoT om de efficiency op onderhoud te verhogen!\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>','Efficiency onderhoud verhogen: hoe doe je dat?','1766','inherit','closed','closed','','296-revision-v1','','','2022-01-31 09:36:34','2022-01-31 09:36:34','',296,'https://thingsway.media2netdev.nl/?p=377',0,'revision','',0),(378,1,'2022-01-31 09:36:35','2022-01-31 09:36:35','Het werven van talent en deze plaatsen op de juiste posities in uw bedrijf is al een opgave op zich. Dat geldt zeker wanneer het gaat om het werven van goed geschoold technisch personeel. Veel bedrijven over de hele wereld worden met deze uitdaging geconfronteerd. Het tekort aan technisch personeel bestaat al een aantal jaar, maar de voorspellingen zijn dat dit tekort de komende jaren alleen maar zal toenemen.\n\nHet is logisch dat dit tekort zorgen baart voor bedrijven die veel te maken hebben met technisch onderhoud. Wanneer een bedrijf niet in staat is om geschoold technisch personeel te werven dan heeft dit gevolgen op de korte termijn, maar ook voor alle vooruitzichten op lange termijn.\n\nGelukkig bestaan er een aantal manieren om het tekort aan technisch personeel in uw bedrijf op te lossen.\n<h2>Maak gebruik van nieuwe technologieën</h2>\nDe technologie op gebied van technisch onderhoud gaat razendsnel. Dat is te danken aan de opkomst van het Internet of Things. Steeds meer apparaten en objecten worden voorzien van sensoren die de werking van een proces continu monitoren. Veranderingen in een proces die eventuele problemen kunnen veroorzaken worden geregistreerd en doorgestuurd via een internetverbinding. Het technisch personeel hoeft pas opgeroepen te worden wanneer deze melding gegeven wordt.\n\nEen voorbeeld van zo’n Iot-sensor is de Thingsway. Deze sensor wordt al door meerdere bedrijven ingezet om de werking van een proces te monitoren. Zo wordt er bijvoorbeeld gebruik gemaakt van de Thingsway om de doorstroming van een dakgoot in de gaten te houden. Maar er bestaat ook een industriële versie van de Thingsway.\n\nDit is een veel effectievere manier van onderhoud plegen, door de enorme stroom aan data krijgt een bedrijf een veel beter inzicht in de werking van een object of apparaat. Periodiek onderhoud kan veel beter gepland worden, voorspellingen kunnen veel nauwkeuriger worden gedaan. Voor het technisch personeel betekent dit dat ze veel gerichter kunnen worden aangestuurd en ingezet. Deze dienen dan wel getraind te worden in het werken met de laatste IoT-technologie.\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\n<h2>Train de bestaande technische medewerkers</h2>\nOm het tekort aan nieuwe technische arbeidskrachten op te vangen, gaan veel bedrijven hun bestaand personeel bijscholen. Zodoende kan het technisch personeel op de hoogte blijven van de nieuwste technologie. Bijscholing kan gedaan worden door middel van een interne opleiding, een deskundige werknemer zou bijvoorbeeld zijn kennis en expertise kunnen delen met anderen. Dit is een goede en goedkope manier om de kennis te verhogen van uw personeel.\n\nU zou de training van uw personeel ook kunnen uitbesteden. Er bestaan verschillende bedrijven die cursussen geven op technisch gebied. Dit is een optie dat wat duurder is en wat meer tijd nodig heeft, maar het zal op den duur zeker zijn vruchten afwerpen. Uw technisch personeel wordt namelijk opgeleid volgens de laatste technologieën en volgens de standaard in de industrie. Nieuw technisch personeel zal tevens sneller kiezen voor een bedrijf dat zijn personeel up-to-date houdt.\n<h2>Huur een maintenance bedrijf in</h2>\nMisschien heeft u altijd uw eigen technisch personeel in dienst gehad? Wanneer u niet meer aan genoeg technisch personeel kunt komen, is het inhuren van een maintenance bedrijf een goede optie. Door gebruik te maken van hun expertise en beschikbaarheid wordt uw eigen flexibiliteit verhoogd. Het onderhoudsbedrijf zou ook kunnen fungeren als ondersteuning van uw eigen technisch personeel.\n\nU kunt er ook voor kiezen om tijdelijk personeel in te huren. Jongere werknemers kiezen er steeds meer voor om freelance te werken. Deze tijdelijke krachten zouden uw bedrijf kunnen helpen zo lang u ze nodig heeft.\n<h2>Ga een samenwerking aan met een onderwijsinstelling in de buurt</h2>\nU zou uw bedrijf kunnen openstellen voor stageplekken voor leerlingen van een technische school in de buurt. Dit betekent dat u constant nieuwe instroom heeft van potentiële werknemers die bovendien goed geschoold zijn. Door de volgende generatie technisch werknemers binnen te halen, kunt u gebruik maken van de kennis van de toekomst.\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>','Gebrek technisch personeel: hoe op te lossen?','1784','inherit','closed','closed','','298-revision-v1','','','2022-01-31 09:36:35','2022-01-31 09:36:35','',298,'https://thingsway.media2netdev.nl/?p=378',0,'revision','',0),(379,1,'2022-01-31 09:36:36','2022-01-31 09:36:36','Zonder dat we het merken worden we steeds meer omringd door sensoren. Het gebeurt overal, in onze werkomgeving, op straat en zelfs bij ons thuis. Deze sensoren zorgen ervoor dat ons leven steeds aangenamer wordt. We hoeven steeds minder zelf te doen, sensoren nemen een bepaalde handelingen van ons over voor ons gemak. Neem als voorbeeld uw thermostaat; niet zo heel lang geleden was u zelf verantwoordelijk voor het regelen van de temperatuur in uw huis, tegenwoordig regelt de thermostaat alles voor u.\n\nSteeds meer apparaten om ons heen nemen onze taken over, dit worden slimme apparaten genoemd. De thermostaat, de koelkast, uw horloge, alles is voorzien van sensoren en een internetaansluiting, alles om het gemak van de mens te dienen. Maar wist u dat er tegenwoordig zelfs slimme gebouwen bestaan?\n<h2>Wat zijn slimme gebouwen?</h2>\nEen slim gebouw is een gebouw dat gebruik maakt van technologie om informatie te delen. Bij de informatie dat gedeeld wordt kunt u denken aan alles wat er in het gebouw gebeurt dat de prestaties van het gebouw bepaald. Aan de hand van deze informatie worden bepaalde processen geautomatiseerd, zoals verwarming, ventilatie en beveiliging.\n\nDe eigenaar van een gebouw heeft aanzienlijke kosten om het gebouw te gebruiken. Dit zijn noodzakelijke uitgaven, maar er wordt vaak onnodig veel kosten gemaakt. Als voorbeeld noemen we lampen die branden op plekken waar dat niet nodig is, ruimtes die onnodig verwarmd worden of deuren die automatisch draaien zonder dat er mensen in de buurt zijn. Gebouwen worden slimmer gemaakt om het gebouw voor de gebruiker aantrekkelijker te maken, maar ook om verspilling van energie tegen te gaan. Zodoende kan efficiënt met energie worden omgegaan en kunnen veel kosten bespaard worden.\n\n<img class=\"size-full wp-image-1789 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/11/slimme-kantoren-en-gebouwen.jpg\" alt=\"slimme kantoren en gebouwen\" width=\"1000\" height=\"800\" />\n<h2>Wat zijn de mogelijkheden voor slimme gebouwen?</h2>\nDe mogelijkheden voor slimme gebouwen zijn enorm. Zo kan de luchtkwaliteit in een gebouw verbeterd worden, dit komt onze gezondheid en productiviteit ten goede. Sensoren kunnen het niveau van CO2 in een ruimte kunnen meten alsmede eventuele schadelijke deeltjes in de lucht. Wanneer de aanwezigheid hiervan te hoog is dan kan de ventilatie aangepast worden.\n\nEr zou tevens gebruik gemaakt kunnen worden van sensoren om voorspellingen te doen op gebied van onderhoud. Sensoren zouden de werking van bepaalde apparaten in de gaten kunnen houden. Als er iets in de omgeving verandert dan meldt de sensor dit zodat onderhoud gepleegd kan worden. U kunt dan denken aan bijvoorbeeld een lift waarvan de deur niet goed sluit, of een verwarmingsketel waarbij ongewenste trillingen worden waargenomen. Niet alleen apparaten kunnen voorzien worden van een sensor, maar bijvoorbeeld ook een dakgoot. Wanneer deze niet goed doorstroomt dan krijgt de beheerder een melding voordat problemen zich voordoen.\n<h2>Van welke tools wordt gebruik gemaakt bij slimme gebouwen?</h2>\nBij een slim gebouw wordt gebruik gemaakt van verschillende tools. Als eerste worden er belangrijke systemen met elkaar verbonden. Door deze met elkaar te laten communiceren wordt een gebouw “slim”. Denkt u dan aan systemen zoals watermeters, stroomvoorziening, pompen etc.\n\nSensoren spelen een grote rol in slimme gebouwen. Ze zorgen ervoor dat gegevens verzameld worden. Aan de hand van deze gegevens worden beslissingen genomen om het gebruik van het gebouw te optimaliseren.\n\nAutomatisering is tevens een groot onderdeel van een slim gebouw. Alle verzamelde data wordt geanalyseerd door een automatisch systeem in het gebouw. Dit gebeurt continu en in real-time. Deze continu monitoring zorgt ervoor dat automatisch aanpassingen gedaan kunnen worden. Aanpassingen die ervoor zorgen dat bepaalde omstandigheden in het gebouw verbeterd worden.\n\nData is een belangrijke tool voor slimme gebouwen. De grote hoeveelheid waardevolle gegevens zorgen ervoor dat er veel effectiever gebruik gemaakt kan worden met middelen en grondstoffen. Gewone gebouwen hebben dit voordeel niet.\n<h2>Gebruik de Thingsway om uw gebouw slimmer te maken</h2>\nOver het algemeen zijn het vooral nieuwe gebouwen die slim zijn. Het gebruik van sensoren en de nodige tools wordt dan al meegenomen bij het ontwerpen van het gebouw. U kunt echter wel degelijk een oud gebouw “slimmer” maken.\n\nZo zou u bijvoorbeeld de Thingsway kunnen inzetten om bepaalde processen in uw gebouw te monitoren. De Thingsway is een IoT-sensor dat ontwikkeld is door Salland Electronics. Het voordeel van deze sensor is dat het multifunctioneel is en bovendien zeer snel aan te passen. Wilt u dat vanaf morgen de lift in een gebouw gemonitord wordt? Dat kan met de Thingsway!\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>','Wat zijn de mogelijkheden en tools van slimme gebouwen?','1787','inherit','closed','closed','','300-revision-v1','','','2022-01-31 09:36:36','2022-01-31 09:36:36','',300,'https://thingsway.media2netdev.nl/?p=379',0,'revision','',0),(380,1,'2022-01-31 09:36:36','2022-01-31 09:36:36','Er bestaat een industrie dat aan veel mensen voorbij gaat; namelijk de koel-vriesindustrie. Toch is dit een bedrijfstak dat enorm belangrijk is in het dagelijks leven. Dankzij de koel-vriesindustrie heeft heel Nederland dagelijks vers eten op hun bord. Ook in de farmaceutische industrie wordt veel gebruik gemaakt van koel- en vrieskasten. De juiste temperatuur bewaken is ook in deze industrie van groot belang.\n\nIn een professionele keuken staat de koelkast centraal. Veel bedrijven zijn afhankelijk van vers voedsel, daarom zijn bedrijfsleiders zich ter terdege bewust van het belang van goede koeling. Vers voedsel is de belangrijkste bron van inkomsten van deze bedrijven, dus koelapparatuur dat betrouwbaar en effectief werkt is van cruciaal belang.\n\nOndernemers kunnen hun klanten vers voedsel bieden door optimale temperaturen te behouden. Wanneer deze temperatuur te veel stijgt of daalt, dan zal voedselbederf optreden. Voor de farmaceutische industrie betekent het controleren van de temperatuur dat de betrouwbaarheid van een proces beheerst wordt. Precisie is van groot belang om gecertificeerde producten te kunnen produceren.\n\nWanneer voedingsmiddelen bedorven raken, voorschriften niet nageleefd worden en apparatuur defect raakt dan zal dit leiden naar verloren inkomsten. Niet alleen dat, het zal reputatieschade opleveren voor een bedrijf, het zorgt voor extra kosten en misschien zelfs boetes.\n<h2>Waarom is onderhoud belangrijk in de koel-vriesindustrie?</h2>\nOm de goede werking van koelapparatuur te garanderen is onderhoud essentieel. De risico’s van het niet onderhouden van deze apparaten zijn:\n<ul>\n 	<li>de machine zal sneller verouderen;</li>\n 	<li>de machine zal meer energie verbruiken dan nodig is;</li>\n 	<li>het koelvermogen van de machine zal afnemen;</li>\n 	<li>veiligheidsnormen en milieu eisen kunnen niet worden nageleefd.</li>\n</ul>\nOm bovenstaande risico’s te vermijden dient er regelmatig onderhoud gepleegd te worden aan koelings- en vriesapparaten. Dit periodiek onderhoud wordt meestal gedaan volgens een bepaald schema en volgens richtlijnen die aangegeven worden door fabrikanten. Deze richtlijnen worden bepaald op basis van ervaringen uit het verleden en door metingen en testen. Aan de hand van deze gegevens worden voorspellingen gedaan hoe lang een machine of onderdeel meegaat en hoe vaak het onderhoud nodig heeft. Het grote nadeel hiervan is dat het nog steeds om voorspellingen gaat, storingen kunnen nog altijd optreden.\n\nEr wordt echter steeds meer gebruik gemaakt van het Internet of Things om de werking van apparaten te monitoren. Ook op gebied van onderhoud kan het Internet of Things u grote voordelen opleveren. Een sensor kan namelijk continu bepaalde indicatoren in de gaten houden.\n\n<img class=\"size-full wp-image-1807 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/11/onderhoud-koel-vries-industrie.jpg\" alt=\"onderhoud koel en vries industrie \" width=\"1000\" height=\"800\" />\n<h2>Maak gebruik van het Internet of Things om efficiënte koeling te garanderen</h2>\nHet Internet of Things heeft voor een nieuwe industriële revolutie gezorgd. Door apparaten en alledaagse objecten te voorzien van sensoren en een directe internetverbinding kunnen bedrijven veel efficiënter werken en kosten voor onderhoud verlagen.\n\nIn de voedingsindustrie en farmaceutische industrie is koeling van het grootste belang. Door de werking van koelingsapparaten te laten monitoren door middel van sensoren bent u als bedrijf gegarandeerd dat de juiste temperatuur gehandhaafd blijft. De sensoren zullen veranderingen in de omgeving onmiddellijk melden via de rechtstreekse internetverbinding. Denkt u dan aan de stijging of daling van de temperatuur, een hoger energieverbruik of ongewenste trillingen in een koelmotor. Zodoende kan onderhoud gepleegd worden voordat kritische waarden bereikt zijn.\n<h2>De Thingsway van Salland Electronics</h2>\nSalland Electronics is een bedrijf uit Zwolle dat Internet of Things oplossingen voor bedrijven verzorgd. Zij hebben de Thingsway ontwikkeld, een IoT-sensor dat zeer snel toepasbaar is voor elk bedrijf, ook in de koel-vriesindustrie.\n\nDe Thingsway is een basisproduct dat zeer snel aan te passen is, u kunt binnen een dag al voorzien zijn van een sensor en internetverbinding. De Thingsway wordt voorzien van de benodigde sensoren, de behuizing wordt aangepast aan de omgeving en het wordt voorzien van de juiste aansluiting. Met de Thingsway heeft u een sensor in uw bedrijf die de werking van uw koelsystemen continu kan monitoren. Dit geeft u de mogelijkheid om kritische temperaturen te bewaken en onderhoud te plegen exact wanneer dat nodig is.\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>','Het belang van onderhoud in de koel- en vriesindustrie','1806','inherit','closed','closed','','302-revision-v1','','','2022-01-31 09:36:36','2022-01-31 09:36:36','',302,'https://thingsway.media2netdev.nl/?p=380',0,'revision','',0),(381,1,'2022-01-31 09:36:38','2022-01-31 09:36:38','Wanneer we het hebben over onderhoud dan denken we al snel aan onderhoud van machines of auto’s. Onderhoud is echter essentieel voor de optimale werking van bijna alles om ons heen, ons huis, onze werkplek, winkels en alles wat zorgt voor een aangenaam leefklimaat in deze ruimtes.\n\nDe technologie waar gebruik van gemaakt wordt om het klimaat in bepaalde ruimtes te optimaliseren wordt klimaattechniek genoemd. Onderhoud is van essentieel belang in vele bedrijfstakken, dus ook in deze specifieke tak. Waarom en hoe kan voorspellend onderhoud door middel van een Internet of Things oplossing daarbij helpen? Dat leest u in dit artikel!\n<h2>Wat is klimaattechniek?</h2>\nAls eerste kijken we naar de branche dat klimaattechniek heet. Het is een brede branche waaronder de volgende takken vallen;\n<ul>\n 	<li>ventilatie en luchtbehandeling;</li>\n 	<li>verwarming;</li>\n 	<li>koeltechniek;</li>\n 	<li>meet en regeltechniek.</li>\n</ul>\nKlimaattechniek omvangt alle techniek dat invloed uitoefent op het klimaat in bepaalde binnenruimtes. Apparaten zorgen ervoor dat de juiste temperatuur aangehouden wordt, ze zorgen voor de juiste luchtvochtigheid en verse lucht. Voorbeelden van klimaattechniek zijn alle verwarmingssystemen, airconditioners, luchtbevochtigers maar ook koelsystemen.\n\nOm te zorgen voor een prettig klimaat in een woonruimte zijn verschillende technieken nodig. Als eerste moet er bepaald worden wat het huidige klimaat is. Hierna moeten ongewenste invloeden beperkt of voorkomen worden, zoals bijvoorbeeld tocht of lekkages. Vervolgens wordt bepaald wat voor installatie nodig is om het gewenste klimaat te bereiken. Dezelfde procedure wordt toegepast op werkruimtes.\n<h2>Het belang van onderhoud bij klimaattechniek</h2>\nBij klimaattechniek wordt zeer veel gebruik gemaakt van apparaten en systemen. Deze systemen zorgen ervoor dat een bepaalde ruimte niet alleen prettig is om in te vertoeven, ze zorgen tevens voor een veilige en gezonde ruimte. In sommige gevallen is het in stand houden van de juiste omstandigheden van essentieel belang. U kunt dan denken aan het in stand houden van de juiste temperatuur en vochtigheid in kassen, of aan koeling in de voedings- en farmaceutische industrie. Een apparaat dat niet goed werkt kan zorgen voor grote productieproblemen en uiteindelijk voor hoge kosten.\n\nOm de veilige werking van deze systemen te garanderen is regelmatig onderhoud absoluut noodzakelijk. Tijdens dit onderhoud worden vooral de belangrijkste componenten gecontroleerd. Onderdelen worden gereinigd en opnieuw juist afgesteld. Belangrijke componenten die zorgen voor een correcte werking zijn onder andere motoren en filters. Tijdens periodiek onderhoud worden de filters gecontroleerd en eventueel vervangen wanneer nodig.\n\n<img class=\"size-full wp-image-1812 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/11/klimaattechniek.jpg\" alt=\"klimaattechniek\" width=\"1000\" height=\"800\" />\n<h2>Hoe het Internet of Things kan helpen bij klimaattechniek</h2>\nOver het algemeen wordt er gebruik gemaakt van periodiek onderhoud om de werking van klimaatsystemen te garanderen. Een vast onderhoudsschema wordt gevolgd dat is bepaald volgens de richtlijnen van fabrikanten. Deze geven aan hoe vaak een apparaat onderhoud nodig heeft. Dit heeft echter enige nadelen, in de meeste gevallen blijkt onderhoud namelijk niet nodig te zijn. Dan werken motoren nog prima volgens de richtlijnen en filters zijn nog niet aan vervanging toe. Toch wordt dit onderhoud gedaan om storingen en problemen voor te zijn. Dit is niet erg effectief en brengt onnodige kosten met zich mee.\n\nVoorspellend onderhoud met gebruik van een Internet of Things-oplossing is een andere manier van onderhoud uitvoeren. Waarschijnlijk weet u precies welke componenten essentieel zijn voor de werking van een apparaat. U kunt de werking van deze componenten laten monitoren door middel van een IoT-sensor. Het grote voordeel van zo’n sensor is dat deze een directe internetverbinding heeft. Wanneer er veranderingen optreden in de omgeving van het proces dan meldt de sensor dit direct. U ontvangt een melding zodat onderhoud direct gepleegd kan worden. Dit is een veel effectievere manier van onderhoud omdat u precies op het juiste moment ingrijpt, onnodig filters vervangen is verleden tijd.\n<h2>De Thingsway, een IoT-oplossing</h2>\nWilt u ervoor zorgen dat de juiste vochtigheid in uw kas wordt gehandhaafd? Wilt u een gezond leefklimaat op uw kantoor? Is koeling voor uw bedrijf van essentieel belang? Om deze factoren te garanderen wordt er waarschijnlijk veelvuldig onderhoud gepleegd aan de klimaatsystemen.\n\nDe Thingsway kan u daarbij helpen, dit is een IoT-sensor dat ontwikkeld is door Salland Electronics. Het grote voordeel van de Thingsway is dat deze snel aan te passen is op uw wensen. Aanpassingen worden gedaan op gebied van benodigde sensor, behuizing en aansluiting. Na installatie zal de Thingsway continu een proces monitoren, eventuele veranderingen worden via de internetverbinding onmiddellijk gemeld.\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>','Het belang van onderhoud bij klimaattechniek','1811','inherit','closed','closed','','304-revision-v1','','','2022-01-31 09:36:38','2022-01-31 09:36:38','',304,'https://thingsway.media2netdev.nl/?p=381',0,'revision','',0),(382,1,'2022-01-31 09:36:39','2022-01-31 09:36:39','[et_pb_section fb_built=\"1\" admin_label=\"section\" _builder_version=\"3.22\"][et_pb_row admin_label=\"row\" _builder_version=\"3.25\" background_size=\"initial\" background_position=\"top_left\" background_repeat=\"repeat\"][et_pb_column type=\"4_4\" _builder_version=\"3.25\" custom_padding=\"|||\" custom_padding__hover=\"|||\"][et_pb_text admin_label=\"Text\" _builder_version=\"4.9.0\" background_size=\"initial\" background_position=\"top_left\" background_repeat=\"repeat\" hover_enabled=\"0\" sticky_enabled=\"0\"]<p>Elk jaar zorgen arbeidsongevallen voor (blijvend) letsel bij werknemers, sommige ongevallen hebben zelfs een fatale afloop. Een bedrijf wil er vanzelfsprekend alles aan doen om dit te voorkomen, daarom wordt er veel gedaan aan de werkomstandigheden, moeten werkvoorschriften nageleefd worden en moeten arbeidsmiddelen regelmatig gekeurd worden. De werkomstandigheden en een verantwoordelijke productiecultuur heeft u zelf in de hand. Het keuren van de arbeidsmiddelen kunt u verbeteren door middel van de Thingsway, een Internet of Things sensor.</p>\n<h2>Wat is het Internet of Things (IoT)?</h2>\n<p>Het Internet of Things (IoT) zorgt voor een vrije stroom aan informatie tussen mensen, computers, machines en objecten. Het IoT verbindt alles in een omgeving met elkaar en zorgt dat informatie gedeeld wordt door middel van real-time communicatie. Deze communicatie zorgt voor meer beschikbare informatie, dit kan ervoor zorgen dat de veiligheid op de werkplek verbetert wordt.</p>\n<p>De informatieverstrekking bij het Internet of Things werkt via sensoren. Deze sensoren registreren veranderingen in een bepaalde omgeving. Er bestaan veel verschillende sensoren, allen voor verschillende doeleinden. Zo bestaan er bijvoorbeeld sensoren die warmte kunnen registreren, maar ook trillingen, druk en beweging. Dit zijn slechts enkele voorbeelden. Bijna alles valt te meten door middel van een sensor. Het voordeel van het IoT is dat deze sensoren zijn voorzien van een directe internetverbinding. Dit geeft de sensor de mogelijkheid om continu data door te sturen van een bepaald proces.</p>\n<h2>De Thingsway</h2>\n<p>De Thingsway is een IoT-sensor, ontwikkeld door Salland Electronics. Iot-sensoren kunnen nog wel eens logge apparaten zijn. Het grote voordeel van de Thingsway is dat het een basisproduct is dat zeer snel aangepast kan worden. Daardoor is het een zeer flexibel product dat voor veel verschillende toepassingen geschikt is. De basis wordt aangepast op het te meten of monitoren object en uw specifieke wensen. Dit kan al binnen een dag aangepast worden zodat u snel gebruik kunt maken van een IoT-oplossing.</p>\n<p><img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" /></p>\n<h2>Wat kan de Thingsway betekenen bij het keuren van arbeidsmiddelen?</h2>\n<p>Door middel van de Thingsway kunt u de werking van arbeidsmiddelen laten monitoren. Er bestaan verschillende manieren waarop gevaar kan ontstaan voor de gezondheid van uw medewerkers bijvoorbeeld door middel van gas.</p>\n<p>U wilt het natuurlijk zo snel mogelijk weten wanneer ergens een gaslek is zodat u maatregelen kunt nemen. Door middel van een IoT-oplossing kunt u dat doen. Sensoren die koolmonoxide detecteren bestaan al jaren. Het bijkomende voordeel van het IoT is dat u veel meer informatie ontvangt behalve de melding van koolmonoxide. De sensoren zijn namelijk in staat om concentraties te meten op verschillende plaatsen, zo weet u dat er een lek is, maar ook precies waar.</p>\n<p>Warmte en trillingen kunnen andere indicatoren zijn die kunnen zorgen voor een gevaarlijke situatie. Ook deze indicatoren kunnen gemeten worden door middel van sensoren. Wanneer er ongewenste veranderingen in de omgeving zijn dat wordt dit onmiddellijk door de Thingsway geregistreerd en gemeld via de directe internetverbinding. Door deze melding kunt u ingrijpen voordat gevaarlijke situaties ontstaan die letsel kunnen veroorzaken.</p>\n<p>Er is nog een groot voordeel van een IoT-oplossing zoals de Thingsway. Het keuren van arbeidsmiddelen doet u niet alleen voor de veiligheid, maar ook om de effectiviteit van uw middelen te waarborgen. Door gebruik te maken van de Thingsway kunt u ook deze effectiviteit vergroten.</p>\n<h2>Effectiviteit van arbeidsmiddelen en voorspellend onderhoud</h2>\n<p>Door het continue monitoren zorgt de Thingsway voor een enorme hoeveelheid data. Door deze data te analyseren kunt u een veel beter beeld krijgen van de werking van uw arbeidsmiddelen. Dat geeft u de mogelijkheid om een proces effectiever te laten verlopen. Misschien werkt een machine veel effectiever onder bepaalde omstandigheden. Een sensor meet de omstandigheden continu, dus u krijgt een zeer betrouwbaar beeld van de werking onder alle omstandigheden.</p>\n<p>Een Internet of Things oplossing geeft u tevens de mogelijkheid om voorspellend onderhoud toe te passen. Eigenlijk worden uw arbeidsmiddelen continu gekeurd door middel van de sensoren. Dit neemt de verplichting weg om eens in de zoveel tijd de machine stil te leggen om periodiek onderhoud te plegen. Veranderingen in de omgeving kunnen indicatoren zijn van een komende storing of uitval van de machine. Deze veranderingen worden geregistreerd door de Thingsway.</p>\n<p>Door uw arbeidsmiddelen continu te monitoren kan Thingsway uw bedrijf helpen op gebied van effectiviteit en veiligheid.</p>\n<h2>Vrijblijvend contact</h2>\n<p>Met het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!</p>\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n<p><strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong></p>\n</div>[/et_pb_text][/et_pb_column][/et_pb_row][/et_pb_section]','Keuren van arbeidsmiddelen: tips en tools','1819','inherit','closed','closed','','306-revision-v1','','','2022-01-31 09:36:39','2022-01-31 09:36:39','',306,'https://thingsway.media2netdev.nl/?p=382',0,'revision','',0),(383,1,'2022-01-31 09:36:41','2022-01-31 09:36:41','Bij de gedachte aan een onderhoudstechnicus zullen veel mensen nog steeds denken aan een man in een blauwe overal vol olievlekken. In zijn hand heeft hij een gereedschapskist dat vol zit met sleutels en tangen. Dit is een nostalgisch beeld waar we maar moeilijk van af komen. Een onderhoudsmedewerker zal altijd wel een koffer met tangen en sleutels bij zich dragen, maar de laatste jaren is de manier van onderhoud uitvoeren enorm veranderd. De technologie gaat met grote sprongen vooruit, er wordt steeds meer gebruik gemaakt van apparatuur, computers en digitale systemen. We kunnen dit gerust de engineering van onderhoud noemen.\n<h2>Engineering van onderhoud</h2>\nEngineering van onderhoud wordt toegepast om de apparatuur van een bedrijf optimaal te kunnen laten werken, de betrouwbaarheid en beschikbaarheid wordt daarbij verhoogd. Door steeds meer gebruik te maken van verschillende apparaten, systemen en procedures wordt de mate waarin onderhoud gepleegd wordt effectiever. Dit zorgt voor een verlaging van de kosten voor onderhoud.\n\nDoor de toename van productieapparatuur, machines, systemen en infrastructuur wordt onderhoud steeds belangrijker. Alles wordt misschien wat gebruik betreft steeds makkelijker, maar om te onderhouden wordt alles steeds complexer. Dat is de reden waarom er steeds meer behoefte is aan geschoold technisch onderhoudspersoneel. Onderhoud is voor bedrijven vaak een grote kostenpost, maar tegelijkertijd een onmisbare. Het is bedoeld om ervoor te zorgen dat een bedrijf zijn doelen kan behalen. Activa zou maximaal beschikbaar moeten zijn tegen de laagste kosten. Engineering van onderhoud moet hiervoor zorgen, samen met de kennis en kunde van de moderne onderhoudsmonteur.\n<h2>Wat engineering betekent voor de onderhoudsmedewerker</h2>\nDe moderne onderhoudsmonteur moet beschikken over enorm veel kennis. Natuurlijk moet hij de basiskennis hebben van de werking van apparatuur en machines en tevens hoe deze te repareren indien een storing optreedt. Verder moet hij een goede kennis hebben op gebied van statistiek, kansberekening en op de hoogte zijn van de laatste technologieën. Zijn communicatievaardigheden moeten tevens in orde zijn en hij moet snel beslissingen kunnen maken.\n\nVerantwoordelijkheden van de onderhoudstechnici zijn onder andere:\n<ul>\n 	<li>Zorg voor naleving van het onderhoudssysteem.</li>\n 	<li>Storingen die zich vaker voordoen analyseren.</li>\n 	<li>Schattingen maken van kosten en alternatieven bedenken.</li>\n 	<li>Reserveonderdelen beheren.</li>\n 	<li>Beoordelen wanneer apparatuur vervangen moet worden.</li>\n 	<li>Benodigde gereedschap beoordelen.</li>\n 	<li>Juiste vaardigheden bezitten.</li>\n 	<li>Controleren, repareren en rapporteren van de werking van apparatuur.</li>\n</ul>\n<h2>Het IoT, de nieuwe industriële revolutie</h2>\nDe opkomst van het Internet of Things heeft voor een nieuwe industriële revolutie gezorgd. Steeds meer machines, apparaten en alledaagse objecten worden voorzien van sensoren en aangesloten op het internet. Dit heeft grote voordelen op gebied van onderhoud en betekent voor bedrijven een goede kans om zo effectief mogelijk te kunnen produceren.\n\nDoor middel van een sensor kan de werking van een bepaald proces continu gemonitord worden. Treden er veranderingen op in de omgeving wat de werking van het proces negatief kan beïnvloeden dan zal de sensor dit via de rechtstreekse internetverbinding melden. Deze melding kan binnenkomen op een centraal punt, zoals een computer. Het kan echter ook gestuurd worden naar de smartphone van de onderhoudsmedewerker. Deze kan dan direct in actie komen en onderhoud plegen waar nodig. Onderhoud via een Internet of Things-oplossing is een vorm van voorspellend onderhoud.\n\nEen ander voordeel van een Internet of Things-oplossing is de enorme hoeveelheid data dat het oplevert. De sensor monitort een systeem continu, dit levert heel veel gegevens op. Door deze gegevens te analyseren krijgt een bedrijf een veel beter beeld van de werking van een systeem. Voorspellingen kunnen veel beter worden gedaan, bijvoorbeeld wanneer een storing zal optreden. Dit is belangrijk voor de onderhoudstechnicus, maar ook voor de fabrikant van de machine. Dit is hoe sensoren helpen bij de engineering van onderhoud.\n<h2>De Thingsway, een IoT-sensor</h2>\nHet Internet of Things zorgt voor grote vooruitgang bij engineering van onderhoud. Een IoT-sensor dat kan worden gebruikt om een onderhoudsprogramma te optimaliseren is de Thingsway. Dit is een sensor dat toepasbaar is voor veel bedrijfstakken. Er bestaat een Thingsway voor gebruik in de buitenlucht, maar er is ook een industriële versie.\nSalland Electronics is de ontwikkelaar van de Thingsway. Binnen een dag kan het bedrijf u voorzien van een Thingsway inclusief internetconnectie. De sensor kan geheel naar uw wens worden aangepast, dit hangt af van het te meten proces. De Thingsway betekent een nieuwe stap op gebied van engineering van onderhoud.\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>','Hoe het IoT helpt bij de engineering van onderhoud','1822','inherit','closed','closed','','308-revision-v1','','','2022-01-31 09:36:41','2022-01-31 09:36:41','',308,'https://thingsway.media2netdev.nl/?p=383',0,'revision','',0),(384,1,'2022-01-31 09:36:42','2022-01-31 09:36:42','Kunt u zich nog herinneren dat u moest inbellen als u het internet wilde gebruiken? Hoort u de irritante toon nog? Het laden van een pagina duurde een uur en als het eenmaal geladen was, dan wilde iemand anders in het gezin een email sturen. Dit is niet eens zo heel lang geleden, namelijk aan het eind van de jaren 90.\n\nDe ontwikkelingen zijn de laatste jaren razendsnel gegaan. Het internet is nu overal om ons heen en we hebben er ook direct toegang toe. We doen er werkelijk alles mee, we kijken video’s, we delen foto’s en onze mening, luisteren muziek en checken het laatste nieuws. Als we heel eerlijk zijn kunnen we zeggen dat we erg veel tijd verspillen op het internet.\n\nSinds een aantal jaar wordt er niet alleen door mensen gebruik gemaakt van het internet, veel apparaten en andere alledaagse dingen hebben nu ook hun eigen internetaansluiting. Dit wordt ook wel het Internet of Things genoemd.\n<h2>Wat is het Internet of Things?</h2>\nHet Internet of Things is een netwerk waarbij alledaagse apparaten worden voorzien van sensoren en een internetverbinding. Wasmachines, horloges, industriële machines, maar ook objecten als dakgoten zijn voorzien van een internetconnectie. Hierdoor kunnen deze apparaten verbinding met ons, maar ook elkaar maken en gegevens uitwisselen.\n\nDe achterliggende gedachte van het Internet of Things is om het leven van ons te vergemakkelijken. Door apparaten te laten communiceren kunnen processen veel effectiever verlopen. Dit is de reden waarom het Internet of Things wordt ook wel de nieuwe industriële revolutie genoemd. Niet alleen machines of apparaten worden hierdoor slimmer, ook bij gebouwen wordt het Internet of Things ingezet om deze slimmer te maken.\n<h2>Slimme gebouwen en het IoT</h2>\nHet Internet of Things zorgt sinds korte tijd ook voor grote veranderingen bij gebouwen. Het biedt namelijk grote kansen om veel effectiever met middelen om te gaan. Bovendien kan het IoT helpen om de productiviteit van werknemers te vergroten.\n\nEr bestaan veel verschillende processen die nodig zijn om een gebouw goed te laten functioneren, verwarming, koeling, verlichting, elektra, etc. Helaas wordt er in reguliere gebouwen veel hiervan verspild, bijvoorbeeld door alle lampen die aanstaan in kamers waar het niet nodig is. Door gebruik te maken van sensoren kan deze verspilling tegen worden gegaan. Hierdoor wordt de effectiviteit dus verhoogd en de kosten verlaagd.\n\nAl deze processen zorgen ook voor een bepaald leefklimaat. Het leefklimaat is van groot belang voor bewoners of werknemers om prettig te kunnen leven of goed te kunnen functioneren. De juiste temperatuur, een gezonde lucht en zuurstofgehalte. Sensoren kunnen ervoor zorgen dat de optimale omstandigheden aangehouden worden.\n<h2>Hoe wordt gebruik gemaakt worden van het IoT bij slimme gebouwen?</h2>\nEr bestaan twee verschillende manieren waarop het Internet of Things gebruikt wordt om gebouwen slim te maken. De typische manier waarop aan gebouw beheersing wordt gedaan is door afzonderlijke sensoren (met hun eigen gateway) te gebruiken om verwarming, koeling, verlichting etc. aan te sturen.\n\nEr bestaan echter ook hypermoderne gebouwen waar er door middel van software gezorgd dat alle afzonderlijke sensoren met elkaar kunnen communiceren en samenwerken. Zo ontstaat er een echt zelfdenkend en slim gebouw. Op dit moment wordt deze manier van het Internet of Things inzetten vooral gedaan bij grote nieuwbouw projecten zoals bijvoorbeeld bedrijfspanden en ziekenhuizen. Het is echter een kwestie van tijd dat alle nieuwbouw woningen slim zullen worden.\n<h2>De Thingsway</h2>\nEen voorbeeld van een IoT-sensor is de Thingsway. Van deze sensor wordt op dit moment al gebruik gemaakt om gebouwen slimmer te maken. Een bepaalde versie van de Thingsway monitort namelijk de werking van een dakgoot. Wanneer de doorstroming van de dakgoot vermindert, dan zal de Thingsway dit vaststellen en melden via de internetverbinding. Door deze melding kan er aan onderhoud gedaan worden zodat er geen verstoppingen, overstromingen en schadeposten ontstaan.\n\nDit is slechts één manier waarop de Thingsway in te zetten is, het grote voordeel van de Thingsway is namelijk dat het een basisproduct is dat zeer snel aangepast kan worden. Binnen een dag kan ontwikkelaar Salland Electronics een Thingsway op maat van uw bedrijf verzorgen. Zodoende kunt u uw gebouwen slimmer maken en effectiever gebruik maken van al uw middelen.\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>','IoT bij slimme gebouwen: de mogelijkheden','1835','inherit','closed','closed','','310-revision-v1','','','2022-01-31 09:36:42','2022-01-31 09:36:42','',310,'https://thingsway.media2netdev.nl/?p=384',0,'revision','',0),(385,1,'2022-01-31 09:36:43','2022-01-31 09:36:43','De weegschaal is een stukje techniek dat al duizenden jaren bestaat. Het wegen werd in de prehistorie gedaan met de hand, maar toen de mens eenmaal aan ruilhandel ging doen was het belangrijk om de waarde van voorwerpen met elkaar te kunnen afwegen. Om eerlijk te kunnen ruilen moest de exacte hoeveelheid van producten zoals graan en melk gemeten kunnen worden.\n\nWeegschalen werden al vanaf de tijd van de Egyptenaren gebruikt, zo’n 7000 jaar geleden. Om het gewicht te kunnen bepalen werd een balans gebruikt met een contragewicht. Zo werd de weegschaal een onmisbaar voorwerp voor de mensheid. Tegenwoordig is de weegtechniek nog steeds erg belangrijk, niet alleen voor particulieren, maar ook in verschillende industrieën. De weegschaal is sinds de Egyptenaren enorm veranderd en verbeterd, maar nooit zoveel als de afgelopen jaren met de opkomst van sensoren en het Internet of Things. De moderne technologische vooruitgang zorgt ervoor dat de weegtechniek grote sprongen maakt in efficiëntie.\n<h2>In welke industrieën zijn weegtechnieken belangrijk?</h2>\nDe meeste mensen hebben thuis een weegschaal staan, vaak onder een laag stof verstopt in een kast of lade. Voor veel industrieën is de weegschaal echter een onmisbaar stukje techniek, voorbeeld hiervan is bijvoorbeeld de productie-industrie. Bij het verpakken van voedingsmiddelen, goederen, farmaceutische middelen en chemicaliën is het van groot belang dat exact het juiste gewicht bepaald wordt. Een bedrijf wil natuurlijk niet teveel of te weinig van hun product leveren.\n\nWeegtechnieken zijn ook zeer belangrijk in de vrachtsector. Het is heel belangrijk om vrachtwagens, boten en vliegtuigen op de juiste manier te beladen. Dit zorgt er namelijk voor dat een voertuig goed in balans is en veilig op weg kan. Bovendien rijdt, vaart of vliegt een voertuig dan een stuk zuiniger.\n\nOm goed het gewicht te kunnen bepalen worden er in deze bedrijfssectoren gebruik gemaakt van weegsensoren.\n<h2>Weegtechnieken en het Internet of Things</h2>\nEen weegsensor wordt ook wel eens een loadcell of krachtsensor genoemd. Het is een elektronisch apparaat dat trek- en compressiekracht omzet in een elektrisch signaal. Deze sensoren worden meestal gebruikt om het gewicht van iets te bepalen, maar ze kunnen ook gebruikt worden om de spanning op iets te bepalen (zoals de spanning op een touw of katrol).\n\nWeegsensoren verschillen van ontwerp en specifieke functie, maar ze meten allen de weerstand of vervorming binnen de sensor. Hierdoor wordt de grootte van trek- en drukkrachten bepaald. De farmaceutische industrie, de auto-industrie, de voedingsindustrie en de productie-industrie kunnen allen profiteren van deze weegtechnieken, mede dankzij het Internet of Things.\n\nVeel IoT-toepassingen maken gebruik van weegsensoren. Mooie voorbeelden hiervan zijn het bepalen van het gewicht in magazijnen en afvalmonitoring op afstand. Voor een magazijn betekent het dat exact bepaald wordt hoeveel er nog van een bepaald product op voorraad is. In geval van afval monitoring kan bepaald worden of een afvalbak vol is en dus geleegd moet worden.\n\n<img class=\"size-full wp-image-1840 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/11/weegtechnieken-iot.jpg\" alt=\"weegtechnieken iot\" width=\"1920\" height=\"1080\" />\n<h2>De mogelijkheden van weegtechniek en het IoT</h2>\nDe bovenstaande voorbeelden zijn slechts enkele vormen die mogelijk zijn binnen de weegtechniek en het IoT. Weegsensoren en IoT-toepassingen worden ook ingezet bij het laden van vracht. Medewerkers kunnen in real-time alle beladingsgegevens digitaal aflezen.\n\nDankzij sensoren en het IoT kan er ook in de productie-industrie veel sneller gewogen en daardoor geproduceerd worden. Door hun unieke ontwerp kunnen deze weegschalen fijne producten zoals medicijnen, muesli of suiker razendsnel wegen. Sensoren, systemen, data en hulpmiddelen zoals tablets nemen bovendien de kans weg op menselijke fouten.\n\nHet vergaren van gegevens is de belangrijkste taak binnen de weegtechniek. Het biedt de mogelijkheid om op de hoogte te blijven van elke verandering. Veranderingen kunnen hierna geanalyseerd worden en beleid erop aangepast. De moderne weegschalen zijn voorzien van een internetverbinding. Dit geeft bedrijven de mogelijkheid om toegang te krijgen tot exacte gegevens zonder er fysiek bij aanwezig te hoeven zijn. Dit komt de efficiëntie van ieder bedrijf ten goede!\n<h2>De Thingsway</h2>\nHet wegen met contragewichten is lang voorbij. De moderne weegtechniek werkt met sensoren en een IoT-toepassing. Voor veel verschillende bedrijfstakken kan dit voor meer efficiëntie zorgen en verlaging van de kosten.\n\nDe Thingsway is een sensor die een bedrijf daarbij zou kunnen helpen. Deze IoT-sensor werd ontwikkeld door Salland Electronics. De Thingsway is een basisproduct dat eenvoudig aan te passen is, binnen een dag kan de Thingsway van een weegsensor worden voorzien. Zodoende kunt u zeer snel gebruik maken van zijn voordelen.\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>','Weegtechnieken en IoT: waarom belangrijk? En wat zijn de mogelijkheden?','1838','inherit','closed','closed','','312-revision-v1','','','2022-01-31 09:36:43','2022-01-31 09:36:43','',312,'https://thingsway.media2netdev.nl/?p=385',0,'revision','',0),(386,1,'2022-01-31 09:36:45','2022-01-31 09:36:45','We hebben een nieuw tijdperk bereikt, ook als we het hebben over gebouwen. Onderdak bieden en ons warm en droog houden was jarenlang het grootste doel van een huis of kantoor. Tegenwoordig moet een gebouw alle diensten leveren die wij als gebruikers wensen. Dankzij de razendsnelle evolutie van de technologie kunnen deze wensen vervuld worden. Gebouwen moeten de gebruikers niet alleen maximaal comfort brengen, een gebouw moet ook zo zuinig, milieuvriendelijk en efficiënt mogelijk zijn. Ondanks al deze wensen is het doel om tijdens de levensduur van een gebouw de kosten zo laag mogelijk te houden.\n\nJuist door gebouwen slimmer te maken kan het juiste evenwicht gevonden worden tussen deze doelen. De tijd van slimme gebouwen is daarom aangebroken.\n<h2>Wat is een slim gebouw?</h2>\nIn een slim gebouw wordt gebruik gemaakt van technologie om gegevens te delen over de systemen die plaatsvinden in een gebouw. Na het analyseren van deze gegevens kunnen bepaalde processen geautomatiseerd worden. U kunt dan denken aan beveiliging, verwarming en verlichting. Het doel is om een gebouw zo optimaal mogelijk te gebruiken op gebied van comfort, duurzaamheid en efficiëntie.\n\nEen beheerder van een gebouw heeft jaarlijks flinke kosten. Vanzelfsprekend zijn deze onafwendbaar en noodzakelijk om een gebouw draaiend te houden, maar helaas wordt er vaak veel geld verspild. Lampen blijven branden zonder dat het nodig is, ruimtes worden onnodig verwarmd of geventileerd, zo zijn er veel voorbeelden te noemen van verspilling. Eén van de grote doelen van een slim gebouw is om deze kosten te besparen. Een gebouw slimmer maken noemt men ook wel gebouw automatiseringen.\n\n<img class=\"size-full wp-image-1844 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/11/gebouw-automatiseringen.jpeg\" alt=\"gebouw automatiseringen\" width=\"1158\" height=\"1500\" />\n<h2>Gebouw automatiseringen</h2>\nSinds de opkomst van het Internet of Things en zijn enorme mogelijkheden komen er steeds meer bedrijven die aan gebouw automatiseringen doen. Dit zijn bedrijven die installaties ontwerpen en plaatsen in gebouwen. Niet alleen nieuwbouw projecten worden slimmer gebouwd, ook steeds meer eigenaren en beheerders van oudere panden kiezen ervoor om het gebouw te laten automatiseren.\n\nNiet alleen het ontwerpen en plaatsen van deze installaties is belangrijk om een gebouw slimmer te maken, een ander belangrijk aspect is het onderhoud.\n<h2>Onderhoudstoepassingen voor gebouw automatiseringen</h2>\nDe installaties die gebruikt worden voor intelligente gebouw automatisering worden steeds complexer. De prestaties van deze installaties moeten optimaal zijn, om dit te kunnen bereiken moeten de juiste meet- en regelsystemen aangebracht worden. Wanneer de regelingen en metingen kloppen dan is het comfort in het gebouw optimaal, de installaties presteren naar wens en het verbruik van energie is zo laag mogelijk.\n\nOm dit te kunnen bereiken zijn verschillende toepassingen van onderhoud nodig. Zo dienen alle installaties regelmatig onderhouden en gecontroleerd te worden volgens een periodiek systeem. Tijdens dit onderhoud zou regulier onderhoud gepleegd moeten worden zoals het afstellen van pompen en kleppen. Maar er zou ook gekeken moeten worden of alle meters optimaal ingesteld zijn, of alle software up-to-date is en of storingen nog automatisch gemeld worden.\n\nOm deze storingen te laten melden kan gebruik gemaakt worden van voorspellend onderhoud door middel van een IoT-toepassing.\n<h2>Voorspellend onderhoud met een IoT-toepassing</h2>\nHet uitvoeren van onderhoud is van groot belang bij gebouw automatiseringen. Om alle systemen in een gebouw optimaal te laten draaien is regelmatig onderhoud vereist. Helaas kan een onderhoudsmedewerker niet constant lijfelijk aanwezig zijn om alle systemen in de gaten houden. Sensoren bieden hiervoor de oplossing.\n\nOm een kritisch onderdeel van een installatie te monitoren wordt er steeds vaker gebruik gemaakt van IoT-sensoren. Deze monitoren continu de omgeving van een bepaald proces. Vinden hier veranderingen plaats dan wordt dit geconstateerd en in real-time gemeld via een rechtstreekse internetverbinding. De onderhoudsmedewerker kan na het ontvangen van deze melding onmiddellijk onderhoud plegen. Onderhoud dat gepleegd wordt door middel van een IoT-sensor wordt voorspellend onderhoud genoemd. De sensor voorspelt namelijk storingen voordat deze plaatsvinden.\n<h2>De Thingsway</h2>\nDe Thingsway is een Internet of Things sensor dat ingezet wordt voor voorspellend onderhoud. Bepaalde systemen zijn kritisch in een gebouw dat geautomatiseerd is, daarom moet er regelmatig onderhoud aan gepleegd worden. Deze installaties kunt u laten monitoren door de Thingsway.\n\nHet grote voordeel van de Thingsway is zijn snelle inzetbaarheid. Ontwikkelaar Salland Electronics kan u al in een dag voorzien van een Thingsway. Het basisproduct wordt razendsnel aan uw wensen aangepast. Deze sensor kan u helpen om voorspellend onderhoud uit te voeren. Zo wordt niet alleen het gebouw slimmer en effectiever, maar ook de onderhoudstoepassingen.\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>','Gebouw automatiseringen en de toepassingen van onderhoud','1843','inherit','closed','closed','','314-revision-v1','','','2022-01-31 09:36:45','2022-01-31 09:36:45','',314,'https://thingsway.media2netdev.nl/?p=386',0,'revision','',0),(387,1,'2022-01-31 09:36:46','2022-01-31 09:36:46','Lekkages zijn een veel voorkomend probleem bij vooral oudere gebouwen. Op den duur kunnen lekkages voor veel grotere problemen zorgen, zeker wanneer de oorzaak niet goed aangepakt wordt. Dit kan voor hoge kosten zorgen voor de eigenaren van huizen, kantoren of gebouwen. In dit artikel kunt u lezen waardoor de meeste lekkages ontstaan en hoe u gebouwen kunt beveiligen tegen lekkages.\n<h2>Waardoor ontstaan lekkages aan huizen en gebouwen?</h2>\nEr bestaan verschillende oorzaken voor lekkages, maar de meest voorkomende zijn:\n<h2>Een reparatie leidt naar grotere problemen</h2>\nRegelmatig gebeurt het dat een lekkage optreedt en alleen het gevolg wordt aangepakt. De noodreparatie wordt uitgevoerd zodat tijdelijk de problemen verholpen zijn. De oorzaak van de lekkage wordt echter vergeten. Daardoor zullen lekkages terugkeren en soms verergeren.\n<h2>Lekkage door achterstallig onderhoud</h2>\nAchterstallig onderhoud is één van de belangrijkste oorzaken van lekkages. Bij achterstallig onderhoud kunt u denken aan het niet vervangen van oude dakbedekking, het niet vernieuwen van afdichtingen of verouderde loodslabben.\n\n<img class=\"size-full wp-image-1849 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/11/lekkage-door-gebrekkig-onderhoud.jpg\" alt=\"lekkage \" width=\"626\" height=\"352\" />\n<h2>Lekkages door onzorgvuldige renovaties</h2>\nTijdens renovaties worden nieuwe delen soms niet goed aangesloten op het bestaande pand. U kunt dan denken aan bijvoorbeeld nieuwe kozijnen. Wanneer de waterkeringen niet meer goed passen op de nieuwe kozijnen dan kan er lekkage ontstaan.\n<h2>Lekkages door oude leidingen</h2>\nDe waterleidingen kunnen ook voor lekkages zorgen, vooral wanneer deze verouderd zijn. Het gebeurt in Nederland niet zo vaak meer maar in een lange koude periode kunnen zelfs nieuwe leidingen bevriezen en kapot gaan.\n\nAndere lekkages door waterleidingen worden veroorzaakt door de combinatie van inwendige corrosie en waterdruk. De corrosie zorgt voor zure omstandigheden in de leidingen, daardoor ontstaan gaten en scheurtjes in de leiding. Een breuk of lek is het gevolg, maar het water kan hier ook moeilijk langs bewegen waardoor de waterdruk voor meer problemen zorgt.\n<h2>Lekkages door regenpijpen en dakgoten</h2>\nDakgoten en regenpijpen zorgen voor het afvoeren van regenwater. Wanneer deze niet meer goed functioneren dan kunnen er lekkages ontstaan in grote delen van een gebouw. Dakgoten dienen jaarlijks schoongemaakt te worden en de doorstroom van regenpijpen moet gecontroleerd worden.\n<h2>Wat kunt u doen om lekkages te voorkomen?</h2>\nOm lekkages te voorkomen kunt u het volgende doen:\n<ul>\n 	<li>Wanneer er een renovatie plaatsvindt dan is een goed plan nodig waarin aandacht besteed wordt aan het correct aansluiten van nieuwe bouwdelen aan de oude.</li>\n 	<li>Een noodreparatie van een lekkage is een noodreparatie. Er moet altijd een vervolg op zijn, de oorzaak moet gevonden en opgelost worden.</li>\n 	<li>Maak een gedegen onderhoudsplan dat meerdere jaren omvat. De kritische onderdelen van een pand kunt u monitoren, onderhouden en vervangen wanneer nodig. Kritische onderdelen kunnen zijn: dakgoot, dak, leidingen, afdichtingen etc.</li>\n 	<li>Laat deze kritische onderdelen monitoren door middel van een Internet of Things-oplossing.</li>\n</ul>\n<h2>Gebouwen, kantoren en huizen beveiligen tegen lekkage</h2>\nEén van de beste manieren om lekkages te voorkomen is door regelmatig onderhoud te plegen. De kritische onderdelen moeten daarbij worden gecontroleerd en eventueel onderhouden. U heeft daarvoor een goed onderhoudsplan nodig. Om problemen voor te zijn dient u namelijk goed te weten hoe vaak deze kritische onderdelen onderhoud nodig hebben.\n\nU kunt er ook voor kiezen om een IoT-oplossing in te zetten om een gebouw te beveiligen tegen lekkage. Een Internet of Things-oplossing werkt door middel van sensoren en een internetverbinding. De sensor monitort continu de werking van een bepaald proces. Wanneer er veranderingen optreden in dat proces dan worden deze gegevens direct via de internetverbinding doorgestuurd naar een laptop, computer of smartphone. Na het ontvangen van de melding kan er onderhoud gepleegd worden voordat problemen zoals lekkages ontstaan.\n<h2>De Thingsway</h2>\nDe Thingsway is zo’n Internet of Things-oplossing. Het is een product dat kan worden ingezet om allerlei soorten processen te monitoren. Voor bedrijven die veel te maken hebben met onderhoud kan de Thingsway een belangrijke oplossing zijn. Het continu monitoren van de Thingsway kunt u zien als voorspellend onderhoud. Het zorgt voor een effectiever onderhoudsbeleid en verlaagt daarmee aanzienlijk de kosten.\n\nOp dit moment wordt de Thingsway al ingezet voor het beveiligen tegen lekkages. Er is namelijk een versie van de Thingsway die de doorstroom van dakgoten monitort. Wanneer deze doorstroom niet optimaal is dan geeft de Thingsway een melding. Onderhoud kan onmiddellijk gepleegd worden voordat problemen, zoals lekkages, zich voordoen.\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>','Gebouw, kantoren en huizen beveiligen tegen lekkage','1847','inherit','closed','closed','','316-revision-v1','','','2022-01-31 09:36:46','2022-01-31 09:36:46','',316,'https://thingsway.media2netdev.nl/?p=387',0,'revision','',0),(388,1,'2022-01-31 09:36:47','2022-01-31 09:36:47','Onderhoud is voor veel bedrijven enorm belangrijk, ook voor bedrijven in de installatiebranche. In dit artikel leest u waarom onderhoud zo belangrijk is voor deze bedrijven, maar tevens hoe het Internet of Things daarbij kan helpen.\n<h2>Wat houdt de installatiebranche in?</h2>\nIn de installatiebranche werken bedrijven die technische installaties aanleggen en bovendien onderhouden. Als voorbeelden kunnen we bedrijven noemen in de woningbouw, utiliteitsbouw en in de industrie. Een installatie wordt ontworpen door een installatiebedrijf, maar in sommige gevallen ook door een technisch bureau of door een technische afdeling van een opdrachtgever.\n\nDeze installaties worden aangelegd en onderhouden door een installateur of installatiemonteur. Dit zijn verzamelnamen voor medewerkers in verschillende technische takken. U kunt dan denken aan elektriciens, loodgieters en cv-monteurs.\nDe werkzaamheden van de installateur hangen af van de taken van het bedrijf. Enkele voorbeelden van de werkzaamheden van een installateur zijn:\n<h2>Het belang van onderhoud in de installatiebranche</h2>\nZoals u leest is het aanleggen van een installatie slechts een klein deel van de taken van een installateur. Onderhoud is voor bedrijven in de installatiebranche één van de belangrijkste taken. Een installatie kan nog zo goed aangelegd zijn, het zal niet goed functioneren wanneer er daarna geen onderhoud aan gepleegd wordt.\n\nCv-ketels, airconditionings, liften, koelinstallaties, het heeft allemaal onderhoud nodig om een veilige en efficiënte werking te garanderen. Alle onderdelen zijn nu eenmaal aan slijtage onderhevig. Het is daarom belangrijk voor deze bedrijven om een gedegen onderhoudsplan te hebben. In dit plan kunt u het best gebruik maken van verschillende soorten onderhoud; reactief onderhoud op onderdelen die niet kritisch zijn en makkelijk vervangbaar, periodiek onderhoud en voorspellend onderhoud.\n\nPeriodiek onderhoud wordt gedaan op basis van voorspellingen uit het verleden en volgens aanwijzingen van fabrikanten. Deze fabrikanten weten door testen vrij goed te voorspellen hoelang een bepaald onderdeel of een apparaat meegaat en hoe vaak er dus onderhoud gepleegd moet worden. De installateurs werken dagelijks met deze onderdelen en apparaten, hun rapportage en ervaringen dienen ook meegenomen te worden in de voorspellingen voor periodiek onderhoud.\n\nVoorspellend onderhoud is een andere vorm van onderhoud. Het kan een bedrijf helpen om een nadeel van periodiek onderhoud weg te nemen; namelijk onverwachte storingen aan of uitval van installaties. Voorspellend onderhoud wordt gedaan door middel van Internet of Things- toepassingen.\n\n<img class=\"size-full wp-image-1856 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/11/onderhoud-installatiebranche.jpg\" alt=\"belang van onderhoud in de installatiebranche\" width=\"1000\" height=\"800\" />\n<h2>De mogelijkheden van het IoT in de installatiebranche</h2>\nEen bedrijf in de installatiebranche weet vaak precies welke onderdelen van installaties kritisch zijn voor het veilig en effectief functioneren van een installatie. Gaat zo’n onderdeel kapot dan valt het gehele proces stil of er wordt mogelijk schade veroorzaakt aan de gehele installatie. Dit is de reden waarom deze onderdelen regelmatig gecontroleerd, vervangen en schoongemaakt worden.\n\nOm de effectiviteit van uw installatiebedrijf te vergroten zou u gebruik kunnen maken van een IoT-oplossing om deze onderdelen te monitoren. Bij het Internet of Things wordt gebruik gemaakt van sensoren. Deze sensoren meten continu bepaalde veranderingen in de omgeving, dat gaan om beweging, gas, licht, warmte etc. Deze veranderingen kunnen indicatoren zijn van slijtage en dus toekomstige storingen en uitval. Wanneer zo’n verandering plaatsvindt dan wordt dit via een directe internetverbinding naar een centraal punt gestuurd. Dat kan gaan om een laptop, computer of de smartphone van één van uw installatie medewerkers.\n\nDeze kan onderhoud plegen exact op het juiste moment, voordat zich een storing voordoet. De sensor neemt de periodieke onderhoudstaak weg van de installatiemonteur. Dit zorgt voor een veel effectiever onderhoudsplan.\n<h2>De Thingsway</h2>\nEen mooi voorbeeld van zo’n IoT-sensor is de Thingsway. Dit is een sensor dat voor veel verschillende toepassingen in de installatiebranche geschikt is. Deze sensor is namelijk eenvoudig en snel aan te passen aan de werkzaamheden en wensen van uw bedrijf. Bij aanpassingen die gedaan worden aan het basisproduct moet u denken aan de benodigde sensoren, de behuizing en de aansluiting. Salland Electronics, de ontwikkelaar van de Thingsway, kan al deze aanpassingen binnen een dag doen. Zodoende heeft u razendsnel een IoT-oplossing in uw bedrijf die u van dienst zal zijn bij het onderhoud van installaties.\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>','Het belang van onderhoud in de installatiebranche','1855','inherit','closed','closed','','319-revision-v1','','','2022-01-31 09:36:47','2022-01-31 09:36:47','',319,'https://thingsway.media2netdev.nl/?p=388',0,'revision','',0),(389,1,'2022-01-31 09:36:48','2022-01-31 09:36:48','IoT is een afkorting van het Internet of Things. Dit is een systeem waarbij allerlei alledaagse objecten met elkaar worden verbonden via het internet. U kunt dan denken aan computers, machines en apparaten, maar ook aan bijvoorbeeld dakgoten. Deze objecten kunnen zonder de tussenkomst van de mens met elkaar communiceren.\nAndere dagelijkse voorbeelden van Internet of Things-toepassingen zijn een hartimplantaat bij een persoon, een dier met een bio chip-ontvanger of een auto met sensoren om de bestuurder te waarschuwen voor gladde wegen of een lage bandenspanning. Voorwaarde voor een IoT-toepassing is dat het object een eigen IP-adres heeft en daardoor onafhankelijk gegevens over een netwerk kan verzenden.\n\nEr wordt steeds meer gebruik gemaakt van het IoT door bedrijven in verschillende bedrijfstakken. Het IoT helpt bedrijven om efficiënter te draaien, klanten beter te kunnen helpen, betere besluiten te kunnen nemen en voor het vergroten van de waarde.\n<h2>Hoe het IoT werkt</h2>\nEen IoT-toepassing bestaat uit verschillende slimme onderdelen zoals processors, sensoren en hardware voor communicatie. Deze onderdelen worden gebruikt om informatie uit de omgeving te halen, verzamelen, verzenden en om op te reageren. De gegevens die verzameld worden door sensoren worden gedeeld door middel van een gateway. Deze stuurt gegevens naar een cloud waar ze geanalyseerd kunnen worden.\n\nIn sommige IoT-systemen communiceren apparaten met elkaar en reageren zelf op de data die ze van elkaar krijgen. Het meeste werk in een IoT-systeem wordt dus gedaan door de apparaten, menselijke tussenkomt is vaak niet nodig. Natuurlijk kunnen mensen wel met deze apparaten communiceren, bijvoorbeeld wanneer ze ingesteld worden of wanneer toegang tot gegevens verkregen moet worden.\n\nDe specifieke IoT-toepassingen bepalen wat voor connectie en netwerk het best werkt voor de communicatie. Binnen het IoT wordt ook vaak gebruik gemaakt van kunstmatige intelligentie (AI). Hierbij leren machines zelf hoe een bepaald proces beter kan verlopen en past zich aan.\n<h2>Waarom is het IoT belangrijk?</h2>\nHet Internet of Things is een hulpmiddel voor mensen om slimmer en tegelijkertijd eenvoudiger te kunnen leven. Behalve het slimmer maken van huizen en apparaten om ons heen, is het IoT heel belangrijk voor bedrijven. Het IoT zorgt ervoor dat bedrijven continu real-time informatie krijgen over hun systemen. Dit biedt de mogelijkheid om een gedetailleerd inzicht te krijgen in bepaalde processen, hoe machines werken, productie, onderhoud en logistiek.\n\nMeerdere processen binnen een bedrijf kunnen met het IoT geautomatiseerd worden. Dit helpt een bedrijf om de arbeidskosten te verlagen. Andere positieve gevolgen zijn het tegengaan van verspilling, het verbeteren van de dienstverlening en het vergroten van efficiëntie op gebied van productie en onderhoud.\n\nHet Internet of Things wordt gezien als één van de belangrijkste technologieën van de afgelopen jaren. De verwachting is dat het niet alleen bepalend zal worden in ons dagelijks leven, maar ook voor de concurrerende positie van bedrijven.\n<h2>De invloed van het IoT op onderhoud</h2>\nBijna alle bedrijven hebben te maken met onderhoud, want alles om ons heen is nu eenmaal onderhevig aan slijtage. Om de werking van bepaalde processen te garanderen is onderhoud nodig. Of het nu gaat om een lift, een productiemachine of een dakgoot, door omstandigheden kunnen er storingen optreden in een proces.\n\nOm storingen en uitval te voorkomen wordt er aan onderhoud gedaan. Een veel gebruikte vorm is periodiek onderhoud. Deze vorm van onderhoud wordt gedaan op basis van instructies van fabrikanten en door gebruik van informatie uit het verleden. Hierdoor kunnen voorspellingen worden gedaan hoe vaak en wanneer een bepaald object onderhoud nodig heeft voordat het uitvalt.\n\nHet nadeel hiervan is dat storingen evengoed onverwacht kan plaatsvinden. Dit zou voorkomen kunnen worden door gebruik te maken van een IoT-toepassing zoals de Thingsway.\n<h2>De Thingsway</h2>\nDe Thingsway is een IoT-systeem dat voor veel verschillende toepassingen inzetbaar is. U kunt de Thingsway inzetten om een bepaald onderdeel te monitoren dat essentieel is in een bepaald proces.\nSensoren in de Thingsway houden eventuele veranderingen in een omgeving continu in de gaten. Als deze optreden dan zal de Thingsway via een directe internetverbinding een signaal geven waardoor u in kunt grijpen voordat storingen of problemen zich voordoen.\nEen ander groot voordeel is dat u door het continu monitoren een veel beter beeld krijgt van het gehele proces. Hierdoor kunt u aanpassingen doen die de efficiëntie van onderhoud zullen vergroten.\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>','Wat is de betekenis van IoT?','1948','inherit','closed','closed','','321-revision-v1','','','2022-01-31 09:36:48','2022-01-31 09:36:48','',321,'https://thingsway.media2netdev.nl/?p=389',0,'revision','',0),(390,1,'2022-01-31 09:36:49','2022-01-31 09:36:49','Bijna in elke bedrijfsbranche wordt gesproken over hoe het Internet of Things zorgt voor een revolutie op de markt. Deze gesprekken worden vooral gevoerd bij grote bedrijven, die over voldoende kapitaal beschikken om mee te gaan in deze revolutie. MKB bedrijven beschikken vaak over minder tot beperkte middelen, toch kan het IoT ook deze bedrijven helpen. De inzet van het IoT zal er voor MKB bedrijven echter iets anders uitzien.\n<h2>De voordelen van het IoT</h2>\nDe voordelen van het IoT zijn zo goed als eindeloos, veel bedrijfsleiders zullen u dat weten te vertellen. Helaas kan niet ieder bedrijf profiteren van alle voordelen van het IoT, omdat het hoge kosten met zich mee kan brengen. Toch kunnen MKB bedrijven met beperkte middelen ook veel baat hebben bij een IoT-toepassing.\n\nWat het IoT voor uw bedrijf kan betekenen is afhankelijk van uw bedrijfstak en de beschikbare middelen. De voordelen die u als MKB bedrijf kunt krijgen van een IoT-toepassing vallen in twee categorieën; efficiëntie en verlaging van kosten.\n<h2>Voorbeelden van het IoT voor MKB bedrijven</h2>\nDoor arbeidsprocessen te vereenvoudigen en te stroomlijnen kunt u de efficiëntie in uw bedrijf vergroten. Een IoT-apparaat kan u daarbij helpen. Planning en andere administratieve taken kosten vaak veel van uw tijd, door deze te automatiseren kunt u de productiviteit binnen het bedrijf verhogen. Dit kunt u doen door deze taken te laten uitvoeren door bijvoorbeeld Google Assistant, een virtuele assistent. Uw werknemers kunnen zich daardoor concentreren op belangrijkere taken.\n\nHeeft u een MKB-bedrijf dat veel met magazijnbeheer te maken heeft? Het IoT is dan zeer geschikt voor u om de efficiëntie te vergroten. Door gebruik te maken van sensoren kunnen uw medewerkers alle goederen volgen en vinden in het magazijn.\n\nOver het algemeen zorgen IoT-toepassingen ervoor dat het leven van medewerkers, bewoners of gebruikers gemakkelijker wordt gemaakt. Ook voor MKB bedrijven kan dit leiden tot een hogere productiviteit. Een ander groot voordeel van IoT voor het MKB is de verlaging van kosten. Een Internet of Things versie van een alledaags apparaat kan op langere termijn voor aanzienlijke besparingen zorgen. Denkt u dan bijvoorbeeld aan een slimme thermostaat.\n\nHet IoT is tevens zeer effectief op gebied van voorspellend onderhoud, daarom is het een populaire toepassing geworden voor veel bedrijven. Wanneer u als bedrijf voorspellend onderhoud toepast, dan kunt u storingen en defecten aan machines en apparaten voorspellen voordat de problemen zich voordoen.\n\nVoorspellend onderhoud wordt gedaan door middel van sensoren, deze houden continu machines in de gaten. Hierdoor kan onderhoud uitgevoerd worden wanneer het echt nodig is. Het IoT helpt hiermee een bedrijf om reparaties en stilstand te voorkomen, dit scheelt enorm in de kosten.\n<h2>Toepassen van het IoT in het MKB</h2>\nDe revolutionaire technologie van het IoT is niet alleen geschikt voor grote bedrijven, maar kan ook MKB bedrijven dezelfde voordelen bieden. Deze kunnen dat echter vaak niet op dezelfde schaal toepassen. Sommige MKB bedrijven kiezen niet voor een IoT-toepassing, omdat ze zorgen hebben over de aanschaf- en installatiekosten. Grote bedrijven hebben daarbij een voordeel, maar ook voor MKB bedrijven bestaan er oplossingen en mogelijkheden zonder grote risico’s. Het is daarbij belangrijk om als bedrijf te bepalen wat de kritieke onderdelen of processen zijn in uw bedrijf.\n<h2>Wat kan een MKB bedrijf met het IoT?</h2>\nOm als MKB bedrijf op een goede manier gebruik te maken van het IoT, dient u te bepalen waar uw behoeften liggen. Waar zitten de inefficiënties in uw bedrijf? Door deze te bepalen kunt u op een gerichte manier een investering doen door een IoT-toepassing te implementeren. Is het gebruik van elektriciteit één van de grote kostenposten in uw bedrijf? Dan kunt u bijvoorbeeld gebruiken maken van slimme lampen of een slimme thermostaat. Is een bepaalde machine essentieel voor uw bedrijf? Laat deze dan monitoren door een IoT-sensor.\n<h2>De Thingsway, een IoT-sensor</h2>\nDe Thingsway is een IoT-sensor dat ontwikkeld is door Salland Electronics. Deze sensor heeft een aantal grote voordelen:\n• De sensor is makkelijk en snel aan te passen aan de wensen van uw bedrijf;\n• Binnen een dag kunt u een sensor in uw bedrijf hebben;\n• De Thingsway is een voordelig product.\n\nDoor deze voordelen is de Thingsway een zeer toegankelijk en geschikt product voor een MKB bedrijf. Wilt u als MKB bedrijf profiteren van de mogelijkheden van het IoT? Dan is de Thingsway het geschikte product voor u!\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>','Wat kan IoT voor een ZZP\'er en MKB bedrijf betekenen?','1951','inherit','closed','closed','','323-revision-v1','','','2022-01-31 09:36:49','2022-01-31 09:36:49','',323,'https://thingsway.media2netdev.nl/?p=390',0,'revision','',0),(391,1,'2022-01-31 09:36:57','2022-01-31 09:36:57','De naam duikt steeds vaker op en we maken er ongemerkt steeds meer gebruik van, maar toch klinkt voor velen de term “Internet of Things” nog als een onbekende toekomstvisie. Het Internet of Things is simpelweg het concept van het verbinden van alledaagse dingen aan het internet, waardoor ze in staat zijn om onderling te communiceren. Het principe achter dit idee is niet nieuw. Voorheen werd het Machine-to-Machine genoemd, maar het IoT is veel groter dan dat.\n\nZonder dat we er bewust van zijn, is het aantal verbonden dingen in onze wereld enorm groot geworden en de vraag neemt alleen maar toe. De waarde van de markt in IoT producten en toepassingen groeit daardoor explosief. In dit artikel kunt u lezen van het IoT precies is en geven we u enkele voorbeelden van IoT toepassingen in de wereld.\n<h2>Wat is het IoT en wat is dat ding dan precies?</h2>\nUw computer en uw smartphone zijn voor u bekende dingen die met het internet verbonden zijn. Het Internet of Things gaat verder dan dat, want het gaat om het woord dingen. Alledaagse dingen die nu voorzien worden van een internetverbinding kunnen apparaten, machines en systemen zijn, maar ook objecten zoals een brug, weg of dakgoot. Door de internetverbinding kunnen deze met elkaar communiceren, met als ultieme doel het leven van mensen te versimpelen en effectiever te maken.\n<h2>Hoe maken IoT-toepassingen verbinding met elkaar?</h2>\nOm verbinding te maken met het internet wordt er binnen het IoT gebruik gemaakt van verschillende soorten netwerken zoals:\n<h2>Mobiel netwerk</h2>\nSmartphones hebben gezorgd voor een enorme groei van het IoT want ze zijn een soort assistent geworden van andere apparaten, zonder ingebouwde internetnetconnectie. U kunt dan denken aan persoon weegschalen, fitness-meters en smarthome-apparaten. Deze zijn afhankelijk van de smartphone om zich met het internet te verbinden.\nHet Internet of Things is een grote reden waarom het 5G netwerk opgezet wordt. 5G kan namelijk aan veel meer apparaten connectiviteit bieden dan 4G.\n<h2>Het WiFi-netwerk</h2>\nWe maken steeds meer gebruik van slimme apparaten in ons huis, dit zijn de duidelijkste voorbeelden van het IoT om ons heen. Denkt u maar eens aan een slimme thermostaat, slimme luidsprekers, slimme koelkasten en een videodeurbel. Deze apparaten maken gebruik van uw WIFI-netwerk om uit zichzelf te kunnen functioneren.\n<h2>Vast internet</h2>\nVeel bedrijven in de productie-industrie maken nog steeds gebruik van vast internet om de connectie van hun IoT-toepassingen te waarborgen. Dit wordt echter steeds vaker vervangen door IoT-sensoren met een eigen gateway.\n<h2>Voorbeelden van IoT toepassingen</h2>\nWe hebben al enkele voorbeelden genoemd hoe het Internet of Things steeds meer in ons dagelijks leven aanwezig is. De meeste toepassingen gaan echter ongemerkt zoals bij de volgende voorbeelden:\n<h2>Slimme afvalverwerking in steden</h2>\nAfval wordt afgehaald op een vaste dag in de maand, toch? Helaas niet erg praktisch. Steeds meer gemeentes maken gebruik van het IoT om afval op te halen wanneer het nodig is, dus wanneer de containers vol zijn.\n\n<img class=\"size-full wp-image-1957 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/12/iot-toepassing-bij-afvalverwerking.jpg\" alt=\"iot toepassing\" width=\"1920\" height=\"1080\" />\n<h2>Slimme gebouwen</h2>\nHet IoT is de ideale manier om ons leven makkelijker en aangenamer te maken in gebouwen. Een klein voorbeeld daarvan is een slimme thermostaat. Deze kan voor u regelen dat het op het juiste moment aangenaam is in uw huis. Grote voorbeelden worden gebruikt in grotere gebouwen. IoT-toepassingen zorgen ervoor dat kantoren, ziekenhuizen, fabrieken maar ook hele woningcomplexen ‘slim’ worden. Het gebouw zorgt zelf voor de juiste temperatuur, voor een gezond leefklimaat en dat er zuinig met stroom wordt omgegaan.\n<h2>IoT en de invloed op bedrijven</h2>\nHet IoT heeft voor veel bedrijven gezorgd voor een nieuwe industriële revolutie. Door systemen, machines en objecten te monitoren met sensoren kan een bedrijf een veel beter inzicht krijgen in een proces. Dit kan veel positieve gevolgen hebben voor de effectiviteit van een bedrijf, wat zorgt voor een hogere winst. Om concurrent te blijven als bedrijf is het van groot belang om mee te gaan in de wereld van het IoT.\n\nEen voorbeeld van zo’n sensor is de Thingsway. Deze kan ingezet worden voor veel verschillende IoT-toepassingen. Op dit moment monitort een Thingsway sensor de werking van een dakgoot. Door dit continu te monitoren weet de eigenaar van het pand precies wanneer onderhoud gepleegd moet worden, voordat problemen zich voordoen. Dit is slechts een voorbeeld van de mogelijkheden van de Thingsway. Het is een basisproduct dat zeer snel aan te passen is op uw wensen en het te meten proces.\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>','Voorbeelden van IoT toepassingen','1956','inherit','closed','closed','','325-revision-v1','','','2022-01-31 09:36:57','2022-01-31 09:36:57','',325,'https://thingsway.media2netdev.nl/?p=391',0,'revision','',0),(392,1,'2022-01-31 09:51:09','2022-01-31 09:51:09','Waar IoT bij uitstek geschikt voor is, is predictive maintenance. Nog veel service afdelingen werken op basis van periodiek onderhoud of op basis van storingsmeldingen. Het is mogelijk door toepassing van sensoren of uitlezen van informatie, te voorspellen wanneer er een storing kan optreden door bijvoorbeeld slijtage van een bepaald onderdeel of toename van onbalans trillingen. Door het aanbrengen van detectiveniveaus kan automatisch een melding gegenereerd worden en bijvoorbeeld een onderhoudsbezoek worden gepland, voordat een machine uitvalt. Dit geeft een enorme efficiency en een hogere klanttevredenheid. Er kan al gauw 20-30% aan kosten worden bespaard met predictive maintenance.','Predictive maintenance','','inherit','closed','closed','','199-revision-v1','','','2022-01-31 09:51:09','2022-01-31 09:51:09','',199,'https://thingsway.media2netdev.nl/?p=392',0,'revision','',0),(393,1,'2022-01-31 09:51:09','2022-01-31 09:51:09','[et_pb_section fb_built=\"1\" _builder_version=\"4.5.6\" _module_preset=\"default\"][et_pb_row _builder_version=\"4.5.6\" _module_preset=\"default\" hover_enabled=\"0\"][et_pb_column type=\"4_4\" _builder_version=\"4.5.6\" _module_preset=\"default\"][et_pb_text _builder_version=\"4.5.6\" _module_preset=\"default\" hover_enabled=\"0\"]<p>In de loop van de jaren is de projectaanpak ook flink veranderd. IoT succesvol toepassen binnen een onderneming is vaak een strategische keuze en kan voordelen bieden voor de hele bedrijfsketen. De juiste procesaanpak is cruciaal om tot succesvolle IoT implementaties te komen, vooral bij grotere organisaties. Beginnen met een zg. stakeholder (belanghebbenden) analyse om de functionele eisen boven tafel te halen, is een goede eerste stap. Vergeet daarbij vooral ook niet te kijken naar de voordelen van de klant van de klant. Een grote valkuil is te veel in een keer te willen, het is daarom belangrijk prioriteiten aan te brengen en een roadmap te ontwikkelen. Koppelen aan business cases helpen daar enorm bij, aangezien snel inzichtelijk is wat het meeste rendement oplevert, de zg. quick wins. Regelmatig maken wij mee dat de klant het heeft over big data, app’s voor jan en alleman terwijl er nog geen product aan het internet hangt en data genereert. Het is niet altijd noodzakelijk<ins cite=\"mailto:Emma%20Tuininga\" datetime=\"2020-03-20T13:33\">,</ins> maar een Proof of Concept in de beginfase is te overwegen om IoT tastbaar te maken voor beslissers of de ontwikkelrisico’s te reduceren. Het traject van eerste inventarisatie tot bestek (specificaties), noemen wij de conceptfase. Na de conceptfase start de ontwerpfase, waarbij hoe verder het ontwikkeltraject vordert de wijzigingskosten toenemen. Dat in tegenstelling tot de risico’s die in de conceptfase het hoogst zijn.</p>\n[/et_pb_text][/et_pb_column][/et_pb_row][/et_pb_section]','Aanpak IoT projecten','','inherit','closed','closed','','200-revision-v1','','','2022-01-31 09:51:09','2022-01-31 09:51:09','',200,'https://thingsway.media2netdev.nl/?p=393',0,'revision','',0),(394,1,'2022-01-31 09:51:10','2022-01-31 09:51:10','[et_pb_section][et_pb_row][et_pb_column type=\"4_4\"][et_pb_text]\n\n<strong>Klantcase VConsyst, de ondergrondse containers</strong>\n\nVrijwel sinds de oprichting van <strong>Salland</strong>Electronics hebben wij ons beziggehouden met systemen die op afstand beheerd moesten worden. Een van onze eerste klanten was VConsyst uit Genemuiden<ins cite=\"mailto:Emma%20Tuininga\" datetime=\"2020-03-20T11:35\">,</ins> leverancier van ondergrondse containers.  Deze ondergrondse containers moesten op afstand kunnen communiceren door de invoering van Diftar midden jaren 90. Diftar staat voor gedifferentieerd tariefstelsel. Diftar was geïnitieerd omdat gemeentes wilden overschakelen naar het principe van de vervuiler betaald. De burger moest dus gaan betalen voor de hoeveelheid afval dat wordt aangeboden. Voor de ondergrondse containers moest er dus een registratie en toegangsverleningssysteem komen om dat mogelijk te maken. Wij hebben destijds voor VConsyst 30 pilotsystemen ontwikkeld. Doel was demonstreren van het systeem op een beurs en in het verlengde daarvan het kunnen houden van eerste pilots. Het systeem was gebaseerd op een PC/104 board, modem, dragerprint en een maatwerk bedieningspaneel. Op locatie moest netspanning en een vaste dataverbinding aangelegd worden. Hierdoor was het mogelijk om de systemen uit te lezen om bijvoorbeeld het aantal stortingen per gezin te registeren en het systeem te voorzien van een zg. whitelist. Een whitelist bevat de pasnummers van de bewoners die op een locatie mogen storten. Aan de hand van het aantal stortingen werd er gefactureerd. Een van de eerste gemeente was Apeldoorn, daar werden 250 containers geplaatst. De WMS I was de eerste generatie toegangsverleningssystemen voor de ondergrondse containers van VConsyst. Tot en met de 4<sup>e</sup> generatie (WMS IV), werd gewerkt met een vaste voeding en een bedrade dataverbinding.\n\nIn dezelfde periode van de opkomst van Diftar vonden de ontwikkelingen plaats van het mobiele gsm-communicatienetwerk. Onder andere 2G was uitermate geschikt voor machine-to-machine (M2M) oplossingen. Rond 2003 is besloten om de 5<sup>e</sup> generatie WMS-systemen te gaan ontwikkelen op basis van een batterijvoeding en communicatie via het 2G GSM mobiele netwerk. Deze keuze werd ook ingegeven door het feit dat de kosten voor het aanleggen van een netspanning en dataverbinding op locatie in de loop der jaren fors opliepen. In 2005 zijn deze systemen voor het eerst geïntroduceerd. Dat ging niet zonder slag of stoot, het toepassen van speciale lithium batterijen en communicatie via het 2G netwerk hebben de nodige hoofdbrekens gekost. Ook het goed beveiligen van de batterijen en de juiste antenne lay-out hebben tot de nodige leermomenten geleid. Omdat de M2M markt in ontwikkeling was ging het werken met de telecomproviders en uitrol procedures met vallen en opstaan<ins cite=\"mailto:Emma%20Tuininga\" datetime=\"2020-03-22T12:08\">.</ins> Om een klein voorbeeld te geven, de M2M SIMS’s moesten door de provider geleverd worden zonder pincode. Echter week dat af van de normale procedure en werd er regelmatig met en zonder een pincode geleverd (de welbekende 0000). Dit had tot gevolg dat op locatie met een mobiel toestel de pincode van de SIM handmatig uitgezet moest worden. Voordat dit vastgesteld was, waren al meer dan 250 systemen in het veld geleverd, met dus veel extra werk als gevolg.\n\nNa 2006 deed de Chiplock generatie zijn intrede (CL-x.x)<ins cite=\"mailto:Emma%20Tuininga\" datetime=\"2020-03-20T11:59\">.</ins> Deze kwam met een batterij en zonnecel uitvoering, beide voorzien van een revolutionaire nieuw display technolog<ins cite=\"mailto:Emma%20Tuininga\" datetime=\"2020-03-20T11:58\">i</ins>e, namelijk een bistabiel LCD display (de technische benaming is Chlorestic Liquid Crystal ChLCD). Het bistabiele display is extreem energiezuinig, want alleen bij verandering van de tekst is energie nodig en de tekst<ins cite=\"mailto:Emma%20Tuininga\" datetime=\"2020-03-20T12:01\"> blijft</ins> staan als er geen spanning aanwezig is. Met name het verlengen van de levensduur van de batterij vraagt om energiezuinige oplossingen. Onder andere door toenemende concurrentie moest de total cost of ownership (TCO) omlaag.\n\nInmiddels is de nieuwste generatie op de markt gekomen onder de aanduiding CL-4.0. De kenmerken van deze generatie zijn; energie efficiënt en modulaire opzet. Het bi-stabiele display is vervangen door een kleuren LCD. Door de voortschrijdende stand der techniek is het verbruik van dit type displays sterk verlaagt. Tevens zijn er meerdere leveranciers, dus geen vendor lock en met een gunstigere total cost of ownership. Door de modulaire opzet van het systeem is deze toekomstbestendiger. Voor met name de mobiele communicatie kan snel omgeschakeld worden naar de nieuwste ontwikkelingen, zoals bijvoorbeeld MTE-M of NB-IoT. Het systeem heeft bluetooth draadloze communicatie<ins cite=\"mailto:Emma%20Tuininga\" datetime=\"2020-03-20T12:06\">,</ins> waardoor het in bedrijfstellen, onderhoud en diagnose ter plaatse, veel efficiënter verloopt. Het systeem is tevens geschikt gemaakt voor betalen met je smartphone. Naast de gekozen hardware modulariteit kennen wij al jaren modulaire software in de vorm van herbruikbare bouwblokken, wij noemen dat atomic embedded modules (AEM). Door de modulaire opzet, is het mogelijk snel varianten van het huidige systeem te maken, bijvoorbeeld een uitgeklede versie waardoor de time-to-market wordt verkleind. Een ander voordeel zijn de lagere ontwikkelrisico’s door hergebruik van hard- en softwaremodules.\n\nDe ontwikkelingen gedaan voor VConsyst de afgelopen 23 jaar laten mooi zien hoe de techniek zich ontwikkelt en de generaties elkaar opvolgen. Van eerste generatie, naar energiezuinig en draadloos, naar verlagen TCO en modulaire bouwblokken met als doel flexibiliteit en het verlagen van de time-to-market.\n\n[/et_pb_text][/et_pb_column][/et_pb_row][/et_pb_section]','Klantcase VConsyst','','inherit','closed','closed','','201-revision-v1','','','2022-01-31 09:51:10','2022-01-31 09:51:10','',201,'https://thingsway.media2netdev.nl/?p=394',0,'revision','',0),(395,1,'2022-01-31 09:51:11','2022-01-31 09:51:11','Veel IoT projecten mislukken omdat men te veel in een keer wil, technisch is er veel mogelijk. Een goede start met een IoT project is een brede inventarisatie van de wensen en eisen en dan een roadmap te ontwikkelen. Dit is cruciaal om de juiste verwachtingen te managen en een realistische aanpak voor implementatie, uitgangspunt zijn vaak de achterliggende business cases. Zet een stip aan de horizon waar je naar toe wilt, maar begin met de \"quick wins\". Een fictief voorbeeld: stel je bent een leverancier van snack automaten aan de professionele zakelijke branche. Je stip aan de horizon kan zijn om de afnemers, die vaak meerdere automaten hebben staan, inzicht te geven in de prestaties en gebruik van de automaten om de behoefte  van de medewerkers beter af te stemmen op het aanbod. Daar kan van alles bij komen kijken, bv een cloud voor de klant, apps voor de beheerder, office manager, inkoop. Als de automaat nog niet aan het internet hangt, zou een eerste stap kunnen zijn om de service te verbeteren op basis van gebruik en niet op basis van periodiek onderhoud. Hiermee kun je naar voorspelbaar onderhoud, waardoor de efficiency van je service afdeling vaak met meer dan 20% kan verbeteren. Een volgende stap in de roadmap zou kunnen zijn de bevoorrading van de automaten te automatiseren. Je weet dan ook de hardlopers en kunt spelen met alternatieve producten zoals bijvoorbeeld gezonde snacks. Dat zou bijvoorbeeld in een diensten model gegoten worden, waarbij de klant compleet ontzorgd  worden. Door data analyse met bijvoorbeeld Articial Intelligence kan per regio, land, werelddeel een betere afstemming van het aanbod plaatsvinden op basis van cultuur en trends.','Roadmapping','','inherit','closed','closed','','202-revision-v1','','','2022-01-31 09:51:11','2022-01-31 09:51:11','',202,'https://thingsway.media2netdev.nl/?p=395',0,'revision','',0),(396,1,'2022-01-31 09:51:11','2022-01-31 09:51:11','Inmiddels is het fenomeen Internet of Things (IoT) een ingeburgerd begrip geworden. Eigenlijk bestaat IoT al zolang data op afstand heen en weer gestuurd kan worden. Midden jaren negentig is door het mobiele netwerk de verdere basis gelegd voor IoT, alleen was dat toen beter bekend als Machine to Machine (M2M) communicatie. Door de opkomst van het internet met IP-standaardisatie, maar ook in combinatie met de opkomst van mobiele netwerken, heeft de Internet of Things een grote vlucht genomen. Wij vinden het nu heel normaal overal ter wereld met ons mobieltje, tablet of laptop onderling te communiceren en data te versturen, waar en wanneer wij maar willen. IoT ontwikkelt zich op dezelfde manier, alleen gaat het daarbij niet om smartphones of tablets maar om objecten, sensoren, producten, machines etc. Binnen het wereldwijde mobiele netwerk zijn speciale frequentiebanden voor objecten (things) gereserveerd, zodat geprofiteerd kan worden van de bestaande bewezen infrastructuur. IoT via het mobiele netwerk lift dus automatisch mee met bijvoorbeeld de volgende stap van 4G naar 5G. Een ander fenomeen waardoor IoT een vlucht heeft genomen zijn de ontwikkelingen binnen de elektronica-industrie. De eerste voorloper van de transistor, de elektronenbuis, zag zijn introductie al in 1907. In 1947 is de eerst werkende transistor in Bell labs gerealiseerd. De transistor is weer de basis voor IC integrated circuits, in de volksmond ook wel chips genoemd. IC’s worden in vele elektronische producten gebruikt als bijvoorbeeld computers, smartphones maar ook thermostaten, automobielen etc. Volgens de wet van Moore verdubbelt het aantal transistors per mm<sup>2</sup> elk jaar. Wat wij daar van merken is dat computers en elektronische producten steeds krachtiger worden met een toenemende geheugencapaciteit. Ter illustratie, een gemiddelde iPhone heeft 100.000 meer rekenkracht dan de ruimtecapsule Apollo 11 uit 1969. Naast een toenemende rekenkracht, zijn de IC’s ook steeds energiezuiniger geworden, waardoor systemen steeds langer op batterijen autonoom kunnen functioneren of door zonnecellen gevoed kunnen worden. Elektronica wordt zelfs zo zuinig dat sensorsystemen gevoed kunnen worden met energie uit de omgeving<ins cite=\"mailto:Emma%20Tuininga\" datetime=\"2020-03-20T11:33\">,</ins> zoals RF-straling, thermo energie of licht. Deze technologie zal de komende jaren doorzetten en IoT nog meer een boost geven.','IoT: oude wijn in nieuwe zakken.','','inherit','closed','closed','','203-revision-v1','','','2022-01-31 09:51:11','2022-01-31 09:51:11','',203,'https://thingsway.media2netdev.nl/?p=396',0,'revision','',0),(397,1,'2022-01-31 09:51:13','2022-01-31 09:51:13','<strong>Ons eigen platform, The ThingsWay</strong>\n\nAl onze ervarin<img class=\"alignright\" src=\"https://www.sallandelectronics.nl/assets/media/logothingsway-v0-2.png\" alt=\"\" width=\"386\" height=\"135\" />gen van de afgelopen jaren hebben wij geïnventariseerd en deze hebben geleid tot een eigen platform voor IoT. <strong>Salland</strong>Electronics brengt dit op de markt onder de naam ThingsWay. The ThingsWay is een samentrekking van Things en Gateway en combineert diverse sensoren, in- en uitgangen met directe communicatie naar het mobiele netwerk. Hierdoor is een gateway overbodig. Bedrijven kunnen heel snel aan de slag met IoT en ons streven is<ins cite=\"mailto:Emma%20Tuininga\" datetime=\"2020-03-20T12:11\">: </ins>“<em>connected in one day”</em>. De ThingsWay is snel aan te passen aan de wensen en eisen van de klant. Als basis is een print ontwikkeld dat modulair uitbreidbaar is. Deze basisprint kan in een eigen behuizing ingezet worden, maar is ook beschikbaar in verschillende uitvoeringen Zo is er als eerste variant een waterdichte uitvoering voor buiten applicaties. Er is ook een Industriële uitvoering beschikbaar voor DIN-rail montage met veel meer aansluitmogelijkheden. Uniek is dat de ThingsWay vanuit de basis opzet energiezuinig is ontworpen waardoor jarenlange werking op een batterij gegarandeerd is. Tot ons dienstenpakket hoort ook het regelen van de SIM’s voor datacommunicatie. De door <strong>Salland</strong>Electronics geleverde SIM<ins cite=\"mailto:Emma%20Tuininga\" datetime=\"2020-03-20T13:21\">’</ins>s zijn een multi-provider<ins cite=\"mailto:Emma%20Tuininga\" datetime=\"2020-03-20T13:21\">,</ins> waardoor de bereikbaarheid en kosten zo gunstig mogelijk zijn voor de klant. Op deze manier hebben wij grip op het communicatie pad vanaf de cloud tot en met de ThingsWay. Voor dataverwerking en visualisatie in een cloud omgeving werken wij samen met Docksters<ins cite=\"mailto:Emma%20Tuininga\" datetime=\"2020-03-20T13:21\">,</ins> onderdeel van X-ICT uit Zwolle. Met dit totaalpakket is <strong>Salland</strong>Electronics in staat de complete keten van cloud tot en met connectiviteit voor een klant te verzorgen.','Het IoT platform ThingsWay','','inherit','closed','closed','','204-revision-v1','','','2022-01-31 09:51:13','2022-01-31 09:51:13','',204,'https://thingsway.media2netdev.nl/?p=397',0,'revision','',0),(398,1,'2022-01-31 09:51:13','2022-01-31 09:51:13','Bijna alles waar we mee werken, of dagelijks mee te maken hebben, heeft onderhoud nodig. Dat gaat niet alleen om uw huis of auto, dat gaat ook om wegen, koffiezetapparaten op het werk en draaideuren bij een winkel.\n\nHet is daarom niet vreemd dat er veel bedrijven bestaan in maintenance en onderhoud. Heeft u ook zo’n bedrijf, of werkt u bij een bedrijf die aan maintenance doet? De kans is dan groot dat u van tijd tot tijd tegen bepaalde problemen aanloopt die helaas regelmatig terugkomen. Voor deze pijnpunten zou toch een oplossing zou moeten zijn?\n<h2>De problemen van maintenance en onderhoud</h2>\nNeem als voorbeeld dat u bedrijfsleider bent van een woningcorporatie; deze corporatie verhuurt appartementen aan particulieren. Die appartementencomplexen hebben periodiek onderhoud nodig, zoals bijvoorbeeld het dak of de dakgoten. Daarom laat u één keer in de zoveel tijd de goten nakijken. Dit levert u kosten op aan mankracht, maar ook aan eventueel materiaal. Toch blijkt onderhoud niet altijd nodig te zijn.\n\nOp andere momenten blijkt dat u te laat bent met maintenance aan de goten. Dan blijken ze eerder dan verwacht dicht geslipt te zijn met vuil en bladeren. Dit heeft gezorgd voor een overstroming en schade aan de regenpijp en het dak. Dit is niet slechts bij één appartementencomplex gebeurt, maar bij maar liefst 5 complexen. Het resultaat; u heeft een enorme piek in uw agenda en flinke onverwachte kosten wat schade betreft.\n\nDit is slechts een voorbeeld van een probleem waar een bedrijf, dat aan onderhoudsdienstverlening doet, tegen aan kan lopen. Over het algemeen liggen deze problemen op gebied van onverwachte pieken in de agenda en kosten. Wilt u meer controle hebben op uw kosten en uw planning? Dan is er voor u nu een oplossing ontwikkeld; zijn naam is De Thingsway.\n<h2>Wat is De Thingsway?</h2>\nDe Thingsway is een sensor die op de markt gebracht is door Salland Electronics. De naam komt voort uit een samenvoeging van Things en Gateway. Het is een Internet of Things product waarin diverse sensoren gecombineerd worden met in- en uitgangen die zorgen voor een directe verbinding met een mobiel netwerk. Dit zorgt ervoor dat een gateway overbodig is.\n\nDe Thingsway is een basisproduct dat snel aan te passen is op de activiteiten en wensen van uw bedrijf. Daarmee kunt u razendsnel aan de slag. Dit basisproduct kan natuurlijk in een eigen behuizing geplaatst worden, maar er zijn meerdere uitvoeringen mogelijk. De eerste variant van The Thingsway is geplaatst in een waterdichte behuizing, waardoor deze buiten gebruikt kan worden, zoals in regenpijpen. Het berekent daarmee de doorstroom van regen, waardoor eventuele verstoppingen vroeg geconstateerd kunnen worden. Dit is één van de voorbeelden van de mogelijkheden van de Thingsway.\n\nEen industriële uitvoering is tevens beschikbaar. Deze is geschikt voor zogenaamde DIN-rail montage en is voorzien van meer aansluitmogelijkheden.\n\nWat uniek is aan de Thingsway is dat het product energiezuinig ontworpen is. De energie komt van een batterij die jarenlange werking (10 jaar) garandeert.\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"voordelen thingsway\" width=\"416\" height=\"294\" />\n<h2>Wat zijn de voordelen van de Thingsway?</h2>\nBehalve dat het een energiezuinig product is, kan de Thingsway u als bedrijf veel voordelen opleveren wat betreft onderhoud en maintenance. Heeft u een bedrijf in onderhoudsdienstverlening en maintenance en wilt u de kosten hiervan reduceren? De Thingsway kan u daarbij heel goed van dienst zijn.\n\nZoals eerder genoemd liggen de pijnpunten voor bedrijven die doen aan maintenance in het feit dat u van te voren niet weet waar of wanneer zich problemen gaan voordoen. Denk dan aan regenpijpen die verstoppen, of koffiezetapparaten die vastlopen doordat een buis vastgelopen is. Deze problemen zorgen niet alleen voor schade en de nodige kosten, ze zorgen er ook voor dat periodieke controle nodig is, ook al is onderhoud misschien niet vereist.\n\nDoor het continue meten van een bepaalde doorstroom of druk middels bepaalde sensoren, kunt u monitoren waar en wanneer maintenance wel vereist is. Dit scheelt u kosten in schade en manuren, maar ook in ongewenste pieken in uw agenda. De Thingsway kunt u daarmee ook zien als een preventief onderhoudsproduct. Door het analyseren van de metingen kunt u tevens in de toekomst onderhoud beter plannen.\n\nSalland Electronics regelt voor u ook de SIM’s voor communicatie van data. Deze SIMS’s zijn zogenaamde Multi providers, dit garandeert de bereikbaarheid en zorgt voor gunstige kosten. Dit totaalpakket met Thingsway, Cloud en connectiviteit zorgt ervoor dat Salland Electronics u een ideaal totaalpakket kan bieden.\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>','De voordelen van Thingsway in maintenance en onderhoud','','inherit','closed','closed','','205-revision-v1','','','2022-01-31 09:51:13','2022-01-31 09:51:13','',205,'https://thingsway.media2netdev.nl/?p=398',0,'revision','',0),(399,1,'2022-01-31 09:51:14','2022-01-31 09:51:14','Wanneer u eigenaar of manager bent van een bedrijf of instelling, dan is de kans groot dat u regelmatig te maken heeft met periodiek onderhoud. Het kan ook zijn dat u werkt in een branche waar maintenance een belangrijk onderdeel is van uw werkzaamheden.\n\nHet nadeel van periodiek onderhoud is dat het concept gebaseerd is op voorspellingen. Hoe lang zal een machine of object mee gaan? Wanneer moet een bepaald onderdeel van een machine vervangen worden? Om de hoeveel tijd moet er onderhoud gepleegd worden aan een dakgoot? De planning van deze werkzaamheden wordt bepaald door richtlijnen van fabrikanten aan te houden, door zelf te experimenteren en door middel van onderhoudsgegevens uit het verleden van de machine of het object.\n\nHet analyseren van al deze gegevens bepalen mede de interval tussen tijdsstippen van periodiek onderhoud. De werking van een machine/object wordt als het ware gemonitord. Dit monitoren gebeurt echter op bepaalde momenten en wordt uitgevoerd door een persoon. Het zou veel effectiever zijn wanneer een bepaalde machine continu gemonitord wordt. Niet door een persoon, want dat zou veel kosten met zich meebrengen. Nee, door middel van een apparaat, die metingen uitvoert en deze bovendien verwerkt in bepaalde data. Door middel van het analyseren van deze data kunt u een veel beter beeld krijgen van de werking en eventuele te verwachte storing. Dit zou uw bedrijf de ideale mogelijkheid geven om kosten te reduceren. Die mogelijkheid bestaat door middel van een IoT-oplossing.\n<h2>Internet of Things -oplossingen</h2>\nDe Internet of Things (IoT) wordt gezien als de next step in technologie. Het helpt ondernemers, bedrijven en branches om niet alleen efficiënter te werken, maar ook veiliger en duurzamer. Door het continu monitoren van objecten krijgt u meer informatie en daarmee inzichten. Dit kan u helpen om onderhoud gerichter te plannen, maar ook om schade en storingen te voorkomen.\n\nDe onderliggende gedachte van IoT is dat er meer machines, producten of objecten aan het internet zijn aangesloten dan mensen. Deze machines krijgen dus een internetverbinding, waardoor ze op afstand gemonitord kunnen worden.\n<h2>Hoe gaat monitoren op afstand in zijn werk?</h2>\nIn de Internet of Things wereld wordt veel gebruik gemaakt van sensoren. Een apparaat met sensoren wordt aangebracht op een machine of object. Deze sensoren doen continu metingen, dit wordt omgezet in data. Doordat het apparaat met sensoren ook voorzien is van een internetconnectie, kan deze data onmiddellijk verstuurd worden.\n\nDe gegevens kunnen daardoor op afstand bekeken worden op een smartphone, computer of tablet. De internetconnectie kan worden verkregen via verschillende netwerken. Ieder Internet of Things bedrijf geeft u daar verschillende mogelijkheden in.\n\nVerkoopt of verhuurt uw bedrijf bijvoorbeeld volautomatische koffiemachines voor bedrijven? Misschien verzorgt u daar dan ook het onderhoud voor? Koffiemachines hebben enorm veel onderhoud nodig, daar bent u als geen ander van op de hoogte. Het vullen van de bekers, koffie, melk, suiker etc. vergt al vaak dagelijkse aandacht, dat valt over het algemeen te plannen. Schade of uitval valt moeilijker te voorspellen en te plannen, behalve wanneer er sensor wordt geplaatst in de machine. Dit kunt u bijvoorbeeld doen op een buis die regelmatig voor problemen zorgt. Sensoren meten de doorstroming, data wordt doorgestuurd, en constante monitoring op afstand geeft u een beter inzicht in de werking van de machine. Hierdoor kunt u in de toekomst uitval en schade voorkomen.\n\nDit is slechts één voorbeeld van monitoren op afstand.\n<h2>De Thingsway, een maatwerksensor voor uw bedrijf</h2>\nEen voorbeeld van een Internet of Things-sensor is de Thingsway. Dit is een sensor die ontwikkeld is door Salland Electronics, een Internet of Things-bedrijf gevestigd in Zwolle. Het grote voordeel van de Thingsway is zijn multifunctionaliteit; het is namelijk een sensor die op veel manieren in te zetten is.\n\nDe Thingsway kan worden aangepast op de specialistische activiteiten van uw bedrijf, daarmee krijgt u een maatwerksensor in handen. Het maatwerk wat vooraf gedaan moet worden gaat onder andere om de manier van installeren. Een sensor op een machine in een fabriekshal heeft nu eenmaal een andere bevestiging nodig dan een sensor boven een draaideur. En zo geldt dat voor alle objecten of machines. Het overige maatwerk gaat om de verschillende soorten sensoren; verschillende processen vragen om verschillende sensoren. Dit maatwerk kan echter door Salland Electronics razendsnel gedaan worden. Zo kunt u in no-time gebruik maken van monitoren op afstand.\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"voordelen thingsway\" width=\"416\" height=\"294\" />\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>','Monitoren op afstand','','inherit','closed','closed','','207-revision-v1','','','2022-01-31 09:51:14','2022-01-31 09:51:14','',207,'https://thingsway.media2netdev.nl/?p=399',0,'revision','',0),(400,1,'2022-01-31 09:51:15','2022-01-31 09:51:15','Misschien zijn we ons er niet meer van bewust, maar onze maatschappij draait op machines. Van het moment dat ’s morgens je wekker gaat, tot je weer naar bed gaat; de hele dag hebben we met machines te maken. Koffiezetter, verwarmingsketel, auto’s, bussen, liften, roltrap, brug over de snelweg, televisie; de hele dag lang werken er machines om ons heen. We zijn er grotendeels afhankelijk van. Deze machines hebben allemaal onderhoud nodig om een goede werking te garanderen.\n\nNiet alleen machines hebben regelmatig onderhoud nodig, ook gebouwen, wegen en zelfs ons lijf kan soms best een onderhoudsbeurt gebruiken. We zitten niet voor niets regelmatig bij de tandarts, toch? Alles is nu eenmaal aan slijtage onderhevig, dat valt niet te vermijden. We weten echter helaas nooit precies wanneer onderhoud nodig is. Vaak zijn we te laat, en is er een gaatje in een kies ontstaan, of een tand afgebroken. Dat is de reden waarom er regelmatig periodiek onderhoud uitgevoerd wordt, vaak door mensen of bedrijven die daar gespecialiseerd in zijn. Maar ook voor zo’n bedrijf zou het heel handig kunnen zijn om onderhoud voorspelbaar te maken.\n<h2>Maintenance en onderhoud voorspelbaar maken</h2>\nNeem als voorbeeld dat u bedrijfsleider bent van een onderhoudsbedrijf, dat aan liftonderhoud doet. Deze hebben periodiek onderhoud nodig, zodat mensen gebruik kunnen maken van een werkende en betrouwbare lift. Dit is de reden waarom u één keer in de zoveel tijd een bepaalde lift aan een controle onderwerpt. Dit zorgt voor kosten aan mankracht, maar mogelijk ook aan materiaal. Onderhoud is echter niet altijd nodig wanneer deze periodiek wordt uitgevoerd.\n\nHet kan ook zijn dat u te laat bent met het onderhouden van een bepaalde lift. Dan is de lift uitgevallen, of er zitten bijvoorbeeld mensen vast. Op zo’n moment kan er geen gebruik gemaakt worden van deze lift. Dit kan erg vervelend zijn voor de bewoners van een flat, denk bijvoorbeeld eens aan oudere bewoners van een bejaardenhuis. Hier biedt u service voor, en daar bestaat uw bedrijf voor, maar het vraagt wel om veel flexibiliteit, een piek in uw agenda, de nodige mankracht en natuurlijk bijkomende schadekosten.\n\nHier wordt slechts een voorbeeld gegeven van de problemen waar een bedrijf tegen aan kan lopen. Of u nu een bedrijf heeft dat doet aan onderhoudsdienstverlening, of u bent bedrijfsleider van een bedrijf die veel met machines te maken heeft; u heeft er ongetwijfeld regelmatig mee te maken. Het zou toch heel handig voor u zijn wanneer er een apparaat zou bestaan dat aan voorspellend onderhoud doet? Welnu, dat apparaat bestaat, het heet de Thingsway.\n<h2>Wat is De Thingsway?</h2>\nDe basis van De Thingsway is een product voorzien van verschillende sensoren in een behuizing. De eerste variant van de Thingsway heeft een waterdichte behuizing, hierdoor kan het gebruikt worden in situaties in de buitenlucht. Denk dan aan bijvoorbeeld het meten van de doorstroming van dakgoten en regenpijpen. Door deze doorstroming continu te meten kan er op tijd ingegrepen worden wanneer deze doorstroming minder wordt. Dit is een teken dat de dakgoot vervuild is geraakt, waardoor de doorstroom minder wordt. Onderhoud is nu nodig en kan op dit moment gepland worden. Dit is slechts een voorbeeld van de mogelijkheden van de Thingsway.\n\nDe Thingsway is een sensor dat snel aan te passen is op alle wensen en activiteiten van uw bedrijf. Zo bestaat er ook een variant die geschikt is voor industrieel gebruik. Heeft u een bedrijf dat veel te maken heeft met onderhoud en maintenance? Of maakt u in uw bedrijf veel gebruik van machines? Dan is de Thingsway een oplossing in voorspellend onderhoud voor u.\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"voordelen thingsway\" width=\"416\" height=\"294\" />\n<h2>Voorspellend onderhoud met de Thingsway</h2>\nDe Thingsway is op de markt gebracht door Salland Electronics, een bedrijf werkzaam in Internet of Things oplossingen. De naam Thingsway is een samenvoeging van Things en Gateway. Het product Thingsway is een letterlijke samenvoeging van een IOT oplossing gecombineerd met een gateway. Het product is voorzien van in- en uitgangen die een directe verbinding met een mobiel netwerk mogelijk maken. Hierdoor bevat het product diverse sensoren en bovendien een eigen gateway.\n\nDoor het continu meten van een bepaalde doorstroom of druk middels bepaalde sensoren, monitort de Thingsway waar en wanneer maintenance vereist is. Dit kunt u zien als voorspellend onderhoud en maakt periodiek onderhoud onnodig. Dit kan flink wat kosten schelen, in manuren, maar ook in schade. Niet alleen dat, maar het scheelt u ook ongewenste pieken in uw agenda. Daarmee kunt u de Thingsway zien als een voorspellend en preventief onderhoudsproduct. In de toekomst kunt u het nodige onderhoud eenvoudig plannen door het analyseren van de metingen.\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>','Voorspellend onderhoud','','inherit','closed','closed','','209-revision-v1','','','2022-01-31 09:51:15','2022-01-31 09:51:15','',209,'https://thingsway.media2netdev.nl/?p=400',0,'revision','',0),(401,1,'2022-01-31 09:51:16','2022-01-31 09:51:16','De wereld draait tegenwoordig grotendeels op computers en machines. Dit zou een ideale combinatie kunnen zijn wanneer u een bedrijf heeft dat veel met machines werkt, of een bedrijf dat aan maintenance doet. Het nadeel van machines is dat ze altijd op een moment uitvallen wanneer u dat niet kunt gebruiken. Dan zijn er weer mensenhanden nodig, en de onvermijdbare kosten om deze uitval op te lossen.\n<h2>De gevolgen van uitval voor uw bedrijf</h2>\nDe gevolgen van uitval kunnen voor uw bedrijf groot zijn. Dit is afhankelijk van wat de schade is, welke machine ermee opgehouden is en hoe snel het te herstellen is. Tot die tijd zou bijvoorbeeld uw productie stil kunnen liggen, kunnen bewoners niet hun appartement in, of blijft een brug of weg afgesloten.\n\nDit vergt veel flexibiliteit van uw bedrijf en werknemers, het zorgt voor een grotere belasting op uw werknemers en bovendien kunnen de kosten van deze uitval wel eens flink oplopen. Het kan zijn dat iets simpel op te lossen is, maar over het algemeen valt schade altijd tegen. Soms is het zelfs nodig een compleet nieuwe machine aan te schaffen.\n<h2>Hoe kunt u uitval voorkomen?</h2>\nOver het algemeen wordt uitval van machines, productie of service voorkomen door periodiek onderhoud. Deze wordt één keer in de zoveel tijd uitgevoerd, daar weet u alles van als u in de maintenance zit of als u een bedrijf heeft die een onderhoudsbedrijf inhuurt.\n\nOnderhoud wordt in deze gevallen standaard uitgevoerd, soms is dit nodig, maar niet altijd. Het nadeel van maintenance is dat het plannen van onderhoud moeilijk is; uitval valt maar lastig te voorspellen. Zou het geen oplossing voor uw bedrijf zijn als de werking of doorstroming continue gemonitord wordt? Gelukkig bestaat die oplossing sinds kort, zijn naam is de Thingsway.\n<h2>Wat is de Thingsway?</h2>\nSalland Electronics heeft een sensor op de markt gebracht met de naam Thingsway. De naam is een samenvoeging van Things en Gateway. Salland Electronics werkt aan IOT oplossingen voor bedrijven, de Thingsway is één van deze oplossingen. Dit kan een uitkomst zijn wanneer u regelmatig te maken heeft met uitval. De Thingsway is een product waarin meerdere sensoren een combinatie vormen met in- en uitgangen. Deze in- en uitgangen zorgen voor een directe verbinding met een mobiel netwerk. Daardoor is een extra gateway overbodig.\n\nDe Thingsway sensor is een basisproduct dat snel is aan te passen zodat het geschikt is voor metingen waar u deze wenst. Zodoende kunt u snel voorzien zijn van een Thingsway. De basis Thingsway heeft een eigen behuizing, maar het kan in vele uitvoeringen worden geplaatst. De eerste Thingsway zit in een waterdichte behuizing, omdat deze gebruikt wordt bij metingen in de buitenlucht, zoals het monitoren van de doorstroming van regenwater.\n\nMaar de Thingsway is tevens heel goed inzetbaar in de industriële markt. Er is namelijk ook een industriële uitvoering beschikbaar. Deze is geschikt gemaakt voor zogenaamde DIN-rail montage en heeft meer aansluitmogelijkheden.\n\nHet energiezuinige ontwerp is uniek aan de Thingsway. De energie wordt geleverd door een Li-SOCL2 AA batterij die een 100% dekking over 10 jaar garandeert.\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\n<h2>Wat kan de Thingsway voor uw bedrijf betekenen?</h2>\nHeeft u een bedrijf dat regelmatig te maken heeft met uitval van machines, diensten of service? Dit wilt u toch het liefst voorkomen? Dit kan door het continue monitoren van bepaalde objecten die gevoelig kunnen zijn voor uitval of schade. De Thingsway meet een bepaalde doorstroom of druk door middel van meerdere sensoren. Zodoende kunt u monitoren waar en ook wanneer onderhoud gewenst is. Voorkomen is beter dan genezen. Dit kan u veel uitval schelen, verlaagt uw kosten en verhoogt uw flexibiliteit. De Thingsway kan gezien worden als een soort preventief onderhoudsproduct. In de toekomst kunt u de maintenance en de te verwachtte kosten plannen door middel van het analyseren van de metingen.\n\nSalland Electronics kan u een ideaal totaalpakket bieden met de Thingsway, Cloud en connectiviteit. Salland Electronics regelt namelijk voor u ook de zogenaamde SIMS’s voor communicatie van data. Dit zijn Multi providers, de bereikbaarheid wordt hierdoor gegarandeerd en het houdt de kosten gunstig.\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>','Uitval voorkomen in uw bedrijf?','','inherit','closed','closed','','211-revision-v1','','','2022-01-31 09:51:16','2022-01-31 09:51:16','',211,'https://thingsway.media2netdev.nl/?p=401',0,'revision','',0),(402,1,'2022-01-31 09:51:17','2022-01-31 09:51:17','Alles om ons heen slijt of is aan onderhoud onderhevig. Van sommige apparaten accepteren we dat, dan kopen we gewoon een nieuwe. Niet alles is echter snel, eenvoudig en goedkoop te vervangen. Dit is de reden waarom we bijvoorbeeld bepaalde dingen in en aan ons huis regelmatig onderhouden, zoals de verwarmingsketel, de kozijnen en de dakgoot. Soms doen we dit zelf, maar vaak laten we het ook uitbesteden aan gespecialiseerde onderhoudsbedrijven. Deze bedrijven voeren dan periodiek onderhoud uit.\n\nHeeft u een bedrijf in onderhoud en maintenance? Werkt u voor een bedrijf dat veel gebruik maakt van machines? Of heeft uw bedrijf regelmatig te maken met het nodige onderhoud, zoals bijvoorbeeld een woningcorporatie? Dan zult u waarschijnlijk erkennen dat periodiek onderhoud nuttig is, maar niet de absolute oplossing biedt bij het voorkomen van schade door slijtage. Continue monitoring zou een effectiever middel zijn.\n<h2>De nadelen van periodiek onderhoud</h2>\nDe nadelen van periodiek onderhoud liggen in de kosten voor mankracht, en in het feit dat nuttig onderhoud maar moeilijk te plannen is. Eigenlijk weten we nooit wanneer er schade zal ontstaan, of wanneer een machine ermee op zal houden. Periodiek onderhoud wordt uitgevoerd om schade voor te zijn, door bijvoorbeeld preventief bepaalde onderdelen te vervangen, door iets schoon te maken, of om eventuele slijtage vast te stellen. Dit, door mensenhanden uitgevoerd onderhoud, is een middel wat tot een bepaalde hoogte effectief is. Want schade komt vaak onverwacht, en soms worden onderdelen onnodig vervangen. Helaas valt niet alles te voorspellen zonder constante gegevens, dit kan zorgen voor hoge en onverwachte kosten.\n\nHet zou echter veel effectiever werken wanneer een apparaat of een proces continu gemonitord wordt.\n<h2>De voordelen van continue monitoring</h2>\nContinue monitoring van een machine, apparaat of een bepaald proces zorgt ervoor dat er op tijd kan worden ingegrepen wanneer dit nodig is. Zodoende is de kans groter dat eventuele schade voorkomen kan worden.\n\nPeriodiek onderhoud wordt ingezet omdat het onmogelijk is om alles in de gaten te blijven houden door mankracht. Dat zou immers een enorme kostenpost opleveren. Wanneer je continue monitoring zou kunnen inzetten door middel van een apparaat, of een sensor, dan zou dit u enorm in de kosten schelen voor periodiek onderhoud en eventuele onverwachte schade.\n<h2>Continue monitoring met de Thingsway</h2>\nDe Thingsway is een Internet of Things product, geproduceerd door Salland Electronics. Door het constant meten van een bepaalde druk of doorstroom, monitort het product of onderhoud nodig is. Deze continue monitoring zorgt dus voor een soort voorspellend onderhoud, dit maakt periodiek onderhoud zo goed als onnodig. Dit is aantrekkelijk voor ieder bedrijf dat te maken heeft met regelmatig maintenance, of dat nu is aan machines, gebouwen of apparaten.\n\nDe Thingsway is een product dat is voorzien van bepaalde sensoren in een bepaalde behuizing. De eerste Thingsway heeft een waterdichte variant, hierdoor kan deze buiten gebruikt worden. Op dit moment wordt het ingezet in dakgoten van gebouwen. Door deze doorstroming constant in de gaten te houden kan er onderhoud gedaan worden wanneer nodig. Wanneer de dakgoten vervuild zijn geraakt zal de doorstroming verminderen. Dit zal door de verschillende sensoren opgepikt worden en middels data en een gateway gecommuniceerd worden. Onderhoud kan nu gepland en gepleegd worden. Dit is een van de voorbeelden van hoe de Thingsway in te zetten is.\n\nDe Thingsway is een zogenaamd basisproduct. Vanuit deze basis is de Thingsway snel aan te passen met sensoren (en eventueel behuizing) die het best geschikt zijn voor continue monitoring bij uw bedrijf. Uw wensen en activiteiten bepalen uw Thingsway, daarmee is de Thingsway een zeer flexibel en snel in te zetten IOT product. Ook voor gebruik op industrieel gebied bestaat er een Thingsway variant. Deze is voorzien van meerdere aansluitmogelijkheden en is geschikt voor zogenaamde DIN-rail montage.\n\nDe Thingsway is een energiezuinig ontworpen product. De energie komt van een Li-SOCL 2 AA batterij die zorgt voor 100% dekking over een periode van maar liefst 10 jaar.\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\n<h2>Een totaalpakket bij Salland Electronics</h2>\nVoor communicatie van data regelt producent Salland Electronics voor u de SIM’s. Dit zijn Multi providers die zorgen voor bereikbaarheid. Middels dit totaalpakket, inclusief Thingsway, Cloud en connectiviteit, heeft u een ideaal totaalpakket tegen gunstige kosten.\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>\n&nbsp;','De voordelen van continue monitoring','','inherit','closed','closed','','213-revision-v1','','','2022-01-31 09:51:17','2022-01-31 09:51:17','',213,'https://thingsway.media2netdev.nl/?p=402',0,'revision','',0),(403,1,'2022-01-31 09:51:18','2022-01-31 09:51:18','Het IOT (Internet of Things) bedrijf Salland Electonics heeft een product ontwikkeld die u voortaan kan helpen met het voorkomen van schade. Dit product heeft de naam Thingsway gekregen. Het werkt door middel van sensoren die constant een bepaald proces in de gaten kan houden.\n\nDit product kan een ideale oplossing zijn voor veel verschillende soorten bedrijven, instanties en corporaties.\n<h2>Voor welke bedrijven is de Thingsway aantrekkelijk?</h2>\nDe Thingsway kan een heel aantrekkelijk product zijn voor bedrijven die veel te maken hebben met onderhoud (of maintenance). Denk daarbij aan bedrijven die onderhoudsdiensten aanbieden, zoals bijvoorbeeld machineonderhoud, koffiemachine-onderhoud en onderhoud van liften of roltrappen. Ook bedrijven die veel met machines werken hebben zeer regelmatig te maken met onderhoud alsmede schade.\n\nAndere instanties die veel aan onderhoud doen zijn woningcorporaties. Het onderhouden van gebouwen is nu een doorgaand proces. Waar gewoond wordt, wordt geleefd en daar vind logischerwijs slijtage plaats.\n\nDit zijn slechts enkele voorbeelden van bedrijven die veel te maken hebben met maintenance en onderhoud. Wat deze bedrijven verder gemeen hebben is het feit dat ze van tijd tot tijd te maken hebben met schade. Deze schade kan de nodige gevolgen hebben voor uw bedrijf.\n<h2>Gevolgen van schade</h2>\nDe gevolgen van schade zijn op het oog duidelijk. Er is een defect opgetreden in een proces, een machine werkt niet meer, een dak is lek, of een draaideur gaat niet meer open. Zo’n verstoring van een proces moet verholpen worden door middel van onderhoud. Dat zorgt ten eerste voor kosten in mankracht, de persoon die het probleem gaat verhelpen moet immers betaald worden.\n\nTen tweede zorgt het voor kosten in het verhelpen van het probleem. Soms gaat het slechts om een klein probleem, maar het zal ook regelmatig voorkomen dat de schade groter is. Dan moet er bijvoorbeeld een duur onderdeel vervangen worden, of er moet een gehele nieuwe machine aangeschaft worden. Dit zijn bijkomende schadekosten die u toch liever zou willen vermijden.\n\nSchade staat helaas bijna nooit op zichzelf. Vaak gaat het nooit om één onderdeel dat defect is geraakt. Wanneer een proces verstoort wordt door een defect dan heeft dit vaak effect op het gehele systeem. Als voorbeeld kunt u denken aan een dakgoot, wanneer deze verstopt raakt dan zal er een overstroming ontstaan. Dit zal niet alleen voor schade zorgen aan de goot of regenpijp, maar mogelijk ook aan het dak, of misschien zelfs wel aan het interieur van bewoners.\n\nAndere gevolgen van schade zijn misschien minder zichtbaar, maar zijn wel degelijk aanwezig. Heeft u een bedrijf dat veel met machines werkt, dan zal een defecte machine negatieve gevolgen hebben op het productieproces. Tevens zijn er gevolgen voor de belasting van andere machines, maar ook werknemers.\n\nEen ander minder zichtbaar gevolg van schade zijn de hoge kosten voor verzekeringen alsmede het aangaan van contracten voor maintenance en onderhoud. Maintenance en periodiek onderhoud is op dit moment namelijk de manier om schade te voorkomen. Maar het kan anders, beter en eenvoudiger.\n<h2>Schade voorkomen door middel van de Thingsway</h2>\nDe Thingsway is misschien wel de manier om schade te voorkomen. Via sensoren houdt de Thingsway een bepaald proces in de gaten. Het kan dan gaan om de doorstroom van een buis, hoeveel bezoekers er door een winkeldeur lopen, of de afvoer van water door een sluis. De sensoren in de Thingsway, en tevens zijn behuizing, zijn heel snel aanpasbaar. Hierdoor kan het product voor zeer veel doeleinden gebruikt worden.\n\nHet voordeel van de Thingsway is dat deze een proces continu in de gaten houdt. Op zo’n manier wordt verstoring van een doorstroom onmiddellijk geconstateerd en kan mogelijke schade voorkomen worden.\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\n<h2>Continue monitoring</h2>\nHet nadeel van periodiek onderhoud zit al in de benaming: periodiek. Eén keer in de zoveel tijd wordt er een machine, een object of proces aan een controle onderworpen. Onderhoud wordt gedaan waar nodig; er wordt schoongemaakt, of de nodige onderdelen worden vervangen. Het valt echter maar moeilijk te voorspellen wanneer er schade zal ontstaan. Natuurlijk wordt er gelet op belemmering van een proces of eventuele slijtage, maar om uitval of schade te voorspellen is constante observatie nodig.\n\nDit is onmogelijk door middel van mankracht uit te voeren. Om iets continu te laten monitoren en bovendien via data inzicht te houden op het proces is een IOT oplossing nodig. Die IOT oplossing bestaat nu, het heet de Thingsway. De Thingsway kan voor veel verschillende bedrijven de oplossing zijn om schade te voorkomen, en daarmee kosten te reduceren.\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>','Schade voorkomen','','inherit','closed','closed','','215-revision-v1','','','2022-01-31 09:51:18','2022-01-31 09:51:18','',215,'https://thingsway.media2netdev.nl/?p=403',0,'revision','',0),(404,1,'2022-01-31 09:51:19','2022-01-31 09:51:19','Als u dit leest dan is de kans groot dat u de term monitoring kent. Kent u deze term niet, of bent u er nog vrij onbekend mee, dan is hier een eenvoudige uitleg:\n\nMonitoring is het proces waarbij een machine of apparaat connectie maakt met internet om gegevens te verzamelen en te interpreteren.\n\nBij IoT- oplossingen wordt veel gebruik gemaakt van monitoring. IoT staat voor Internet of Things, daarbij worden alledaagse dingen, zoals producten, of machines, met een internet connectie voorzien. Op zo’n manier kunnen deze op afstand gemonitord worden. Dit wordt gedaan om eventuele problemen voor te zijn, processen te verbeteren of machines up te daten.\n\nHeeft u zich wel eens afgevraagd hoe dit werkt? Hoe wordt er verbinding gemaakt met machines of sensoren? En hoe worden die gedeeld en geanalyseerd? Wat zijn die tools voor monitoring, en hoe werkt het in de praktijk?\n<h2>Integratie</h2>\nDe eerste stap bij monitoring is om een internetconnectie te leggen tussen uw machine en de meetapparatuur. IoT bedrijven maken vaak gebruik van zogenaamde gateway’s om deze connectie te kunnen leggen. Daarna kan het bedrijf verbinding leggen via wifi, ethernet, USB en / of mobiel.\n<h2>Data overdragen en opslaan</h2>\nNu er verbinding is gelegd met internet, is het tijd om de data over te dragen. Door de kracht van het internet stromen gegevens continu van een aangesloten machine naar een bepaalde externe server (beveiligd). Door deze data naar een server te sturen, kunt u toegang krijgen tot analytische gegevens, informatie, grafieken en rapporten.\n\n<img class=\"alignnone size-full wp-image-1417\" src=\"https://thingsway.nl/wp-content/uploads/2020/09/Screenshot-2019-11-14-at-15.28.28.png\" alt=\"monitoren onderhoud \" width=\"3814\" height=\"2108\" />\n<h2>Gegevens kunnen worden weergegeven</h2>\nU kunt de gegevens inzien en analyseren, maar u zou ze ook bijvoorbeeld op de werkvloer kunnen weergeven. De gegevens kunt u weergeven via computers, een monitor of zelfs via smartphones en tablets.\n<h2>Productieverhoging</h2>\nDoor de gegevens in realtime aan uw werknemers te laten zien, krijgen uw medewerkers meer inzicht in de machines waarmee ze dagelijks werken. Hierdoor kunnen ze eerder ingrijpen in geval van een storing of onverwacht probleem. Maar het kan ook goed werken om de efficiëntie en productie te verhogen.\n<h2>Het analyseren van gegevens</h2>\nEen IoT oplossing biedt u de mogelijkheid om zowel realtime gegevens in te zien, maar ook gegevens en rapportage uit het verleden. Hierdoor kunnen managers of supervisors ter plekke de gegevens analyseren om betere en weloverwogen beslissingen te nemen.\n<h2>Meer productie, efficiëntie en kosten reductie</h2>\nDe productie en efficiëntie zal naar verwachting toenemen wanneer u de mogelijkheid heeft om de prestaties van machines of objecten te monitoren en analyseren. U kunt beslissingen nemen die gebaseerd zijn op data, niet op gevoel of verwachtingen. Zo kunt u bijvoorbeeld werktijden verbeteren, onderhoud beter plannen, uitvaltijd beperken, en nauwkeurigere offertes maken. Bovendien kunt u schade beperken, dit zal de kosten reduceren en bovendien de productie verhogen.\n\nDit is hoe monitoring van machines of van een bepaald object werkt via een IoT oplossing. Nu kunt u zich nog afvragen hoe deze metingen worden gedaan? Waar komen de gegevens vandaan? Bij tools die ingezet worden voor monitoring wordt veel gebruik gemaakt van verschillende sensoren.\n<h2>De Thingsway</h2>\nEen mooi voorbeeld van een tool voor monitoring is de Thingsway. Dit is een product van Salland Electronics. De Thingsway is ontwikkeld om verschillende metingen mee te kunnen doen, bijvoorbeeld hoeveel mensen er door een deur lopen of hoeveel water er afgevoerd wordt. Dit wordt gedaan via sensoren, deze zijn aan te passen op het bedoelde gebruik van de Thingsway. Bepaalde details van de basis Thingsway kunnen worden aangepast, zodat deze ingezet kan worden om specifieke metingen bij uw bedrijf vast te leggen.\n\nHet grootste voordeel van de Thingsway is dat deze details snel kunnen worden toegepast. Zodoende kunt u binnen zeer korte tijd een IoT oplossing voor uw bedrijf in handen hebben.\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\n<h2>Voor wat voor bedrijven is de Thingsway aantrekkelijk?</h2>\nDe Thingsway is zeer aantrekkelijk voor branches en bedrijven die veel te maken hebben met onderhoud. Denkt u dan aan bedrijven die aan onderhoudsdienstverlening doen, bedrijven die veel met machines werken, of bijvoorbeeld woningbouwverenigingen. Als u de kosten van onderhoud wilt reduceren, dan kan de Thingsway een ideale oplossing voor u zijn.\n\nDe Thingsway is ontwikkeld door Salland Electronics, een bedrijf dat zich specialiseert in innovatieve en grensverleggende IoT- oplossingen.\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>','Welke tools zijn er om continue te kunnen monitoren?','','inherit','closed','closed','','217-revision-v1','','','2022-01-31 09:51:19','2022-01-31 09:51:19','',217,'https://thingsway.media2netdev.nl/?p=404',0,'revision','',0),(405,1,'2022-01-31 09:51:20','2022-01-31 09:51:20','Periodiek machine onderhoud houdt de activiteiten in die worden uitgevoerd op een machine, dit volgens een bepaald tijdsinterval. Een goede werking behouden van de machine is het doel van periodiek machine onderhoud.\n<h2>Periodiek machine onderhoud in een werkstroom</h2>\nPeriodiek machine onderhoud wordt vaak volgens een bepaalde werkstroom uitgevoerd. Als eerste wordt een machine geselecteerd, daarna worden de historische gegevens van het uitgevoerde maintenance geanalyseerd. Aan de hand van deze gegevens wordt de beste interval bepaald om onderhoud te doen. Tijdens de periodieke controle wordt de machine aangezet en laat de controleur deze draaien onder normale condities. Hierna wordt bepaald of de machine aan onderhoud toe is en wordt deze uitgevoerd.\n<h2>Waarom onderhoud aan machines nodig is</h2>\nSlijtage aan machines valt nu eenmaal niet te vermijden, dit zorgt ervoor dat machines er een keer voorgoed mee op zullen houden. Gelukkig gebeurt dit niet van de ene op de andere dag. Integendeel zelfs, moderne machines die voor productie worden ontworpen worden duurzaam gemaakt. Daardoor kunnen ze heel lang meegaan, lang genoeg om tijdens de levensduur te bepalen hoe vaak er periodiek onderhoud nodig is.\n\nPeriodiek machine onderhoud is een manier van maintenance waarbij onderhoudstaken op vastgezette tijden moeten worden gedaan, dit terwijl de machine draait. Periodiek machine onderhoud wordt van tevoren gepland en uitgevoerd, ongeacht problemen of schade aan de machine.\n\nMet de historische gegevens die bekend zijn van een elke specifieke machine wordt de frequentie van het onderhoud bepaald. Fabrikanten van machines kunnen vaak kalenderschema’s voorstellen om controle op een machine uit te voeren. Hierbij worden vaak algemene richtlijnen opgesteld hoe vaak een bepaalde machine onderhoud nodig heeft per kalenderjaar.\n<h2>Hoe effectief is periodiek machine onderhoud?</h2>\nDe effectiviteit van periodiek onderhoud is gebaseerd op de aanname dat het vastlopen of kapot gaan van een machine voorspeld kan worden. Door de historische gegevens te analyseren van een machine, en door eventuele richtlijnen te volgen van een producent, wordt een periode bepaald waarin verwacht wordt dat de machine zonder problemen zal werken. Periodiek onderhoud aan de machine wordt gedaan voordat er een storing op zal treden, dat is althans de bedoeling.\n\nDeze historische gegevens worden veelal verkregen door periodieke metingen of experimenten. Er zit echter een nadeel aan deze periodieke metingen of experimenten. Periodiek is tijdsgebonden, net als een experiment. Een IoT oplossing, waarin een bepaalde machine continue gemonitord wordt, zal veel meer betrouwbare informatie opleveren.\n<h2>Voorbeelden van periodiek onderhoud</h2>\nPeriodiek machine onderhoud kan vaak vervangings- en reparatieproblemen oplossen. Voorbeelden van de werkzaamheden die tijdens dit onderhoud gedaan worden zijn:\n<ul>\n 	<li>Vervangen van smeerolie</li>\n 	<li>Lagervet controleren</li>\n 	<li>Filters vervangen</li>\n 	<li>Roest verwijderen</li>\n 	<li>Controle van druk- en temperatuurmeters</li>\n</ul>\nMachines die constant gebruikt worden hebben het voordeel dat de mate van slijtage op deze machines vrij nauwkeurig voorspeld kan worden. Je weet ten slotte ook van auto’s goed te voorspellen wanneer het olie ververst moet worden.\n\nVoor machines die minder vaak gebruikt worden geldt echter dat eventuele problemen minder voorspelbaar zijn, en daardoor periodiek onderhoud minder effectief is. Ook in zo’n geval zou een IoT oplossing veel effectiever kunnen zijn.\n<h2>Voordelen en nadelen van periodiek machine onderhoud</h2>\nHet voordeel van het doen van periodiek machine onderhoud is dat er geen extra apparaten nodig zijn om aan te geven wanneer een machine onderhoud nodig heeft. De kosten om periodieke schema’s vast te stellen zijn laag.\n\nHet nadeel van periodiek machine onderhoud is dat er een risico bestaat dat de uitgevoerde werkzaamheden op de machine onnodig waren. Een schatting uit de industriële sector geeft aan dat 30% van alle periodieke machine onderhoud slechts preventief was en daarmee dus onnodig werd uitgevoerd.\n\nEen ander nadeel van het uitvoeren van periodiek machine onderhoud is dat een storing op elk willekeurig moment kan optreden. Er zijn nu eenmaal bepaalde storingen die moeilijk voorspelbaar zijn, sommige onderdelen houden zich niet altijd aan de verwachtte slijtagetijd.\n<h2>Periodiek machine onderhoud in het kort</h2>\nBij periodiek onderhoud wordt er vanuit gegaan dat defecten aan machines in de loop van de tijd voorspeld kunnen worden. Het is een strategie van maintenance op basis van historische gegevens en/of specificaties van een producent. Periodiek onderhoud werkt vooral minder effectief bij machines die gevoeliger zijn voor storingen.\n<h2>Voorspellend onderhoud</h2>\nVoor alle machines geldt dat voorspellend onderhoud een effectievere manier is van maintenance. Voorspellend onderhoud kan worden gedaan door middel van een IoT-oplossing. Dat komt er in de praktijk op neer dat de werking van een bepaalde machine continu in de gaten wordt gehouden. Dit levert veel meer data en informatie op. Zo wordt het voorspellen van onderhoud een stuk betrouwbaarder.\n\nEen voorbeeld van een IoT-oplossing is de Thingsway. Dit is een maatwerksensor die de werking van een bepaalde machine continu in de gaten houdt. Door gegevens van de Thingsway te analyseren kan niet alleen schade worden voorkomen, maar het nodige machine onderhoud is daardoor ook beter te plannen.\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>','Voor- en nadelen van periodiek machine onderhoud','','inherit','closed','closed','','219-revision-v1','','','2022-01-31 09:51:20','2022-01-31 09:51:20','',219,'https://thingsway.media2netdev.nl/?p=405',0,'revision','',0),(406,1,'2022-01-31 09:51:21','2022-01-31 09:51:21','Als we iets hebben geleerd van de afgelopen boerenprotesten en de CO2 kwestie, dan is het wel dat alles tegenwoordig gemeten wordt, en dat cijfers enorm belangrijk zijn. We zijn er vaak niet van bewust in het dagelijks leven, maar voor bijna elk bedrijf geldt het oude spreekwoord: meten is weten. Zolang u iets niet kunt meten in het productieproces van uw bedrijf, kunt u het niet beheren. Elke fabrikant die zijn bedrijf naar een hoger niveau wil tillen, moet accurate en relevante gegevens en statistieken kunnen verzamelen en analyseren.\n\nIn de industrie draait alles om cijfers. De juiste statistieken kunnen u helpen om zwakke plekken en knelpunten in het productieproces te vinden. Dit geeft u informatie en de nodige inzichten om het bedrijf te blijven verbeteren en verfijnen. Om metingen in de industrie goed uit te voeren moet systematisch gewerkt worden. Informatie moet op de juiste manier verzameld worden, bovendien is er een gedegen proces nodig om deze informatie te analyseren en hierop een beleid in uitvoering te brengen.\n<h2>Voorbeelden van metingen in de industrie</h2>\nIn de industriële wereld worden veel verschillende metingen uitgevoerd. Allen vooral ten gunste van productie, efficiëntie en reductie van kosten. Dit zijn 5 voorbeelden van metingen die veel in de industrie gedaan worden:\n<h2>Productie cyclustijd</h2>\nDe cyclustijd is de totale tijd van de start tot het einde van een productieproces. Tijdens de productie meet het de tijd dat een product nodig heeft om alle machines, processen en cycli te doorlopen om een compleet product te worden.\n<h2>Omschakeltijd</h2>\nOmschakeling is het proces waarbij een lijn of machine wordt omgezet van het ene product naar het andere. Deze statistiek meet dus eenvoudig de tijd die nodig is om deze omschakeling te maken.\n<h2>Doorvoer</h2>\nDit is een van de eenvoudigste, maar belangrijkste, statistieken in productie. Het meet het gemiddelde aantal eenheden dat wordt geproduceerd op een machine, lijn, eenheid of fabriek gedurende een bepaalde tijdsperiode.\n\n<img class=\"size-full wp-image-1574 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/10/metingen-industrie.jpg\" alt=\"voordelen van meten in de industrie\" width=\"1000\" height=\"800\" />\n<h2>Capaciteitsbenutting</h2>\nMedewerkers in de operatie zijn vaak dol op deze gegevens, omdat deze aangeven hoeveel van de totale productiecapaciteit op een bepaald moment wordt gebruikt. In andere woorden; in welke mate wordt aan het potentiële niveaus voldaan?\n<h2>Overall Equipment Effectiveness (OEE)</h2>\nOEE is een analyse van efficiëntie en productiviteit en wordt wereldwijd erkend als een belangrijke prestatie maatstaf. OEE beoordeelt kwaliteit, snelheid en rusttijd, en kan worden gebruikt om de algehele effectiviteit van een apparaat of een volledige productielijn aan te geven.\n<h2>Metingen voor de werking van machines</h2>\nWat opvalt aan alle bovenstaande soorten metingen is dat deze allen zijn gericht op productiviteit, niet op de daadwerkelijke werking of slijtage van een bepaalde machine. Toch is de werking van machines van essentieel belang in een productieproces. Om uitval te voorkomen worden er wel degelijk metingen gedaan aan een machine, ook wordt er periodiek onderhoud gedaan. Tijdens dit onderhoud wordt een machine gebruikt onder de normale omstandigheden en gemonitord. Uit dit onderhoud komen verschillende gegevens: de werking van de machine in kwestie; de verwachtte tijd dat de machine nog mee zal gaan; de eventuele nodige reparaties; en de onderdelen die de komende tijd misschien vervangen zullen moeten worden.\n\nEen andere manier om de werking van machines te monitoren is door middel van continue metingen. Dit kan worden gedaan door middel van een Internet of Things- toepassing. Dit is een apparaat dat is voorzien van sensoren. Deze sensoren meten constant de werking van de machine. Deze gegevens kunnen worden verstuurd via een internetverbinding en op afstand worden beoordeeld en geanalyseerd.\n<h2>De voordelen van continue metingen in de industrie</h2>\nPeriodiek onderhoud is één van de grootste methoden in de industrie om de werking van machines te garanderen. Er zitten echter enkele nadelen aan periodiek onderhoud. Het eerste nadeel is het feit dat periodiek onderhoud gebaseerd is op voorspellingen. Hoe lang een machine echt mee gaat, of wanneer er uitval is, valt eigenlijk niet te voorspellen. Het andere nadeel is dat onderhoud, of het vervangen van onderdelen, misschien helemaal niet nodig is. Dit heeft kosten meegebracht doordat de machine stil lag, door mankracht en bijkomende kosten aan materiaal.\n\nDoor de werking van een machine continue te monitoren kan uitval of het nodige onderhoud veel beter voorspeld worden. Meer meten betekent meer cijfers, meer data betekent meer statistieken en betrouwbare informatie. Dit kan voor een efficiënter productieproces zorgen.\n<h2>De Thingsway voor metingen in de industrie</h2>\nDe Thingsway is een Internet of Things- sensor die geschikt is voor metingen in de industrie. Het is een apparaat dat op alle gebieden metingen zou kunnen uitvoeren, hiervoor worden simpelweg verschillende sensoren aangepast op het doel van de meting. Denkt u dan bijvoorbeeld aan temperatuursensoren, lichtsensoren, druksensoren, of geleidingssensoren.\n\nDoor de Thingsway in te zetten in uw bedrijf krijgt u een beter inzicht in de werking van een bepaalde machine. Dit zorgt voor een efficiënter gebruik van de machine, het kan uitval voorkomen en bovendien weet u precies wanneer maintenance echt nodig is.\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>','Voordelen van metingen in de industrie','','inherit','closed','closed','','221-revision-v1','','','2022-01-31 09:51:21','2022-01-31 09:51:21','',221,'https://thingsway.media2netdev.nl/?p=406',0,'revision','',0),(407,1,'2022-01-31 09:51:23','2022-01-31 09:51:23','Slimme koelkasten, een spiegelreflex camera en een fitnesshalsband voor honden zijn slechts enkele voorbeelden van alledaagse dingen die met internet worden verbonden als onderdeel van het zogenaamde Internet of Things (IoT).\n\nDoor machines in fabrieken en objecten te verbinden met het internet zou er een vierde industriële revolutie kunnen plaatsvinden. Het is zelfs zo dat experts voorspellen dat aan het eind van 2020 meer dan de helft van alle nieuwe bedrijven op het IoT zullen draaien, en dat is voor een goede reden. Het Internet of Things biedt namelijk een bedrijf de ideale mogelijkheid om zeer efficiënt te werken doordat het gehele proces continu gemonitord wordt. Dit monitoren gebeurt door middel van sensors.\n<h2>Wat is het Internet of Things?</h2>\nDe term IoT omvat in de breedste zin alles wat met internet te maken heeft. De term wordt echter steeds meer gebruikt om zelf communicerende objecten mee te definiëren. Het Internet of Things bestaat uit apparaten en objecten die met elkaar zijn verbonden.\n\nDoor deze aan het internet verbonden apparaten te combineren met een geautomatiseerd systeem, kan informatie verzameld worden, daarna geanalyseerd en in eventuele actie omgezet. Op zo’n manier kan er geleerd worden van een bepaald proces. Dit geeft de mogelijkheid voor meer efficiëntie in de toekomst, alsmede reducering van kosten.\n\nEen Internet of Things-toepassing draait op een apparaat, een netwerk en data. Via een afgesloten internetverbinding wordt deze data gecommuniceerd. Dit kan gedaan worden via verschillende netwerken. Deze communicatie tussen apparaten zorgt voor een wereld die meer verbonden is.\n\nDe metingen die gedaan worden binnen het IoT worden gedaan via sensoren.\n<h2>Wat is een sensor?</h2>\nEen IoT-toepassing begint met een apparaat met sensors. Sensors bestaan al heel lang, de eerste sensoren werden namelijk uitgevonden in de 19de eeuw. Daarom worden ze al heel lang door bedrijven gebruikt. Met de komst van het Internet of Things is de rol van sensoren echter enorm gegroeid.\n\nEen sensor is een apparaat dat een bepaalde input van de omgeving detecteert en daarop reageert. Deze specifieke input kan bijvoorbeeld licht zijn, maar ook warmte, beweging, vocht of druk. Dit zijn slechts enkele voorbeelden van mogelijke verschijnselen in een omgeving. De reactie van de sensor wordt output genoemd. Meestal is dat een signaal dat of rechtstreeks naar een voor mensen leesbaar display wordt gestuurd, of elektronisch via een netwerk naar een externe display.\n\nEen Internet of Things sensor kunt u zien als de hardware dat ter plekke word gebruikt om gegevens uit een bepaalde omgeving te verzamelen.\n<h2>Type sensors</h2>\nIoT-sensors kunnen tegenwoordig op vrijwel alles worden aangesloten, maar elke IoT-oplossing vraagt om een specifiek type sensor. Dit zijn enkele voorbeelden van de meest gebruikte IoT-sensortypen en waarvoor ze in te zetten zijn:\n<h2>Temperatuursensoren</h2>\nTemperatuursensoren worden veel gebruikt bij IoT- toepassingen. De juiste temperatuur handhaven is vaak cruciaal voor een productieproces. Door het bewaken van deze temperatuur op afstand met een Internet of Things sensor kan onderhoud voorspeld worden; dit vermindert mogelijke uitval en daarmee kosten. Temperatuursensors worden tevens ingezet in industrieën als de voedingsindustrie en de farmaceutische industrie. Koeling is in deze sectoren van het grootste belang.\n\n<img class=\"size-full wp-image-1578 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/10/meting-temperatuur-iot.jpg\" alt=\"temperatuur meting iot oplossing\" width=\"1000\" height=\"800\" />\n<h2>Niveausensoren</h2>\nEen goed voorbeeld van waar niveau sensoren worden gebruikt is de afvalverwerking. Containers en vuilnisbakken worden pas geleegd wanneer deze een bepaald niveau bereikt hebben. Niveau sensoren worden ook vaak gebruikt om het niveau aan te geven in een bepaalde tank, zoals olie of brandstof.\n<h2>Versnellingsmeter sensoren</h2>\nBij het bewaken van een voertuig, zoals een fiets of auto, kan het meten van versnelling erg nuttig zijn. Versnellingsmeter sensoren worden echter ook gebruikt om ongewenste trillingen in machines te detecteren.\n<h2>Vochtigheidssensoren</h2>\nHet meten van vocht in een bepaalde omgeving is essentieel voor veel productieprocessen, waaronder farmaceutische productie en de productie van papier. Ook in kassen worden vochtsensoren veel gebruikt. U kunt zich voorstellen dat het juiste niveau van vocht zeer belangrijk is voor het groeien van gewassen.\n<h2>De Thingsway</h2>\nDe technologie op gebied van Internet of Things-toepassingen gaat razendsnel. Tot voor kort kenden IoT- sensorapparaten wat beperkingen, deze lagen vooral op het gebied van vorm, batterijduur en inzetbaarheid. Maar er wordt steeds vaker ingesprongen op de wensen van de klant. Een voorbeeld van zo’n IoT-sensorapparaat is de Thingsway.\n\nHet voordeel van de Thingsway is het feit dat het inzetbaar is voor veel verschillende doeleinden. Het kan aangepast worden op de wensen van de klant. Zo kan het basisconcept van de Thingsway aangepast worden met een behuizing voor metingen buiten, maar ook voor industriële toepassingen. Andere aanpassingen die kunnen worden gedaan liggen op gebied van installatie en wat voor soort metingen uitgevoerd moeten worden. Hierop worden de benodigde sensoren aangepast.\n\nSalland Electronics, producent van de Thingsway, kan deze aanpassingen razendsnel voor u bewerkstelligen. Een ander groot voordeel van de Thingsway is de batterijduur, deze gaat maar liefst 10 jaar mee.\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>','Hoe werken Internet of Things sensoren?','','inherit','closed','closed','','223-revision-v1','','','2022-01-31 09:51:23','2022-01-31 09:51:23','',223,'https://thingsway.media2netdev.nl/?p=407',0,'revision','',0),(408,1,'2022-01-31 09:51:23','2022-01-31 09:51:23','Bijna alle bedrijven hebben te maken met onderhoud. Alles om ons heen is immers onderhevig aan slijtage en dient daarom onderhouden te worden. Niet alleen machines zijn onderhevig aan onderhoud, maar natuurlijk ook gebouwen en infrastructuur. Voor uw bedrijf kan dat bijvoorbeeld betekenen dat u alle machines regelmatig periodiek laat onderhouden, dit om uitval en schade te voorkomen. Het kan ook zijn dat u werkt voor een maintenance bedrijf. In alle gevallen geldt dat u veel baat heeft bij een goed onderhoudssysteem. Een goede strategie voor een onderhoudssysteem wordt bepaald door de juiste onderhoudsmetingen toe te passen. Dit zorgt ervoor dat onderhoud beter te voorspellen is. Zo kan efficiëntie worden vergroot en kosten worden gereduceerd.\n<h2>Wat wordt gezien als onderhoud?</h2>\nU kunt onderhoud zien als alle nodige activiteiten die het doel hebben om een bepaald object in een goed werkende conditie te houden of brengen. Dit om te zorgen dat het object zijn functionaliteit behoud. Het waarborgen van de functionaliteit is nodig om eventuele negatieve gevolgen tegen te gaan zoals:\n<ul>\n 	<li>Een onveilige situatie. Dit kan bijvoorbeeld zorgen voor schade aan lichaam of gebouw.</li>\n 	<li>Een ongezonde situatie. Wanneer iets niet goed functioneert, dan kan dat gevolgen hebben voor mens, dier en milieu.</li>\n 	<li>Een object wordt onbruikbaar.</li>\n 	<li>Een object wordt minder duurzaam. Zo kan een defect in een machine zorgen voor hogere kosten aan stroom of mankracht.</li>\n 	<li>Afname van comfort. Vermindering van functionaliteit kan ervoor zorgen dat een proces minder prettig wordt, of een minder goed gevoel geeft. Denk bijvoorbeeld aan een lift die schokkend naar boven of beneden gaat.</li>\n 	<li>Een slechtere uitstraling van een object. Een overstromende dakgoot zorgt niet alleen voor directe problemen, het zorgt bovendien onmiddellijk voor een slecht onderhouden aanblik.</li>\n</ul>\nDe functionaliteit van een object kan geleidelijk minder worden door slijtage, maar het kan ook op een bepaald moment onmiddellijk verloren gaan. Het uitvoeren van onderhoud, en onderhoudsmetingen, kan uw bedrijf helpen om uitval van functionaliteit tegen te gaan.\n<h2>Wat voor soorten onderhoud bestaan er?</h2>\nEr bestaan verschillende soorten onderhoud, deze zijn onder te verdelen in drie categorieën:\n<ul>\n 	<li>Reactief onderhoud</li>\n 	<li>Proactief onderhoud</li>\n 	<li>Additief onderhoud</li>\n</ul>\nReactief onderhoud wordt gedaan wanneer iemand bijvoorbeeld een klacht heeft. Service onderhoud wordt uitgevoerd en eventuele gebreken worden hersteld.\n\nProactief onderhoud wordt gedaan wanneer u bekend bent met een object, zoals een gebouw of machine. Een machine wordt preventief onderhouden om defecten te voorkomen, dit wordt gedaan door middel van periodiek onderhoud. Dit wordt ook wel eens planmatig onderhoud genoemd, omdat het vaak gebaseerd is op een onderhoudsplan.\n\nAdditief onderhoud wordt gedaan op basis van een strategie of plan. Dit is een toevoeging op het reguliere onderhoud.\n<h2>De voorspelbaarheid van onderhoud</h2>\nWanneer u een keuze maakt voor een onderhoudssysteem, dan wilt u vooral dat het te verwachten onderhoud zo goed mogelijk te voorspellen is. Voor u als bedrijf zorgt dit voor lagere lasten; niet alleen op gebied van onderhoud, maar ook op gebied van kosten. Een goed onderhoudssysteem zorgt voor een hoge voorspelbaarheid van uitval en fouten die kunnen optreden in een systeem of object. Voor een klant zorgt een gedegen onderhoudssysteem voor vertrouwen, een gevoel van veiligheid en duurzaamheid.\n\nHet voorspellen van onderhoud wordt gedaan door middel van onderhoudsmetingen, veelal tijdens periodiek onderhoud. Het nadeel van periodiek onderhoud is het feit dat het nog steeds een momentopname is. Natuurlijk kan er door middel van periodiek onderhoud over een langere periode een redelijke voorspelling van te verwachten onderhoud worden gedaan. Uit deze gegevens, en de eventuele richtlijnen van de fabrikant, kunt u een redelijk gedegen onderhoudssysteem vastleggen. De voorspelbaarheid kan echter verhoogd worden door middel van continue onderhoudsmetingen.\n<h2>Hogere voorspelbaarheid door continue onderhoudsmetingen</h2>\nOnderhoudsmetingen die continu worden uitgevoerd zorgen voor een veel beter beeld van de werking, slijtage en eventueel te verwachten problemen van een bepaald object. U krijgt namelijk veel meer data en over een veel langere periode. Zo’n continue onderhoudsmeting kan worden uitgevoerd op bijna elk object, of dat nu gaat om een machine, een deur of een dakgoot.\n\nContinu metingen kunnen worden gedaan door middel van een IOT-toepassing. IOT staat voor internet of things. Dit betekent dat het meetsysteem bestaat uit één of meerdere bepaalde sensoren in combinatie met een internetconnectie. Zodoende kunnen gegevens constant worden doorgezonden en geanalyseerd.\n\nEen goed voorbeeld van zo’n onderhoudsmeting-systeem is de Thingsway. Dit product is ontwikkeld door Salland Electronics. De Thingsway is dusdanig ontworpen dat het eenvoudig aan te passen is, speciaal op het object/systeem wat gemeten dient te worden.\n\nEen internet of things oplossing zoals de Thingsway kan reactief onderhoud voorkomen. Bovendien kunt u een heel goed onderhoudssysteem samenstellen dankzij de onderhoudsmetingen en de gegevens die de Thingsway u levert.\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>','Onderhoudsmetingen: wat is daar het nut van?','','inherit','closed','closed','','226-revision-v1','','','2022-01-31 09:51:23','2022-01-31 09:51:23','',226,'https://thingsway.media2netdev.nl/?p=408',0,'revision','',0),(409,1,'2022-01-31 09:51:27','2022-01-31 09:51:27','Het welzijn van machines heeft een enorme impact op de algehele efficiëntie van een bedrijf. Dat is de reden waarom onderhoud zo belangrijk is. Om de concurrentie voor te blijven moeten fabrikanten en producenten gebruik maken van de nieuwste technologie. Nadeel is dat het hoge kosten met zich meebrengt. Hoe kunt u innoveren, concurrerend blijven en tegelijkertijd besparen op onderhoudskosten? Om u te helpen volgen hier enkele manieren waarmee u de onderhoudskosten niet alleen kunt verlagen, maar tevens de strategie mee kunt verbeteren.\n<h2>Veiligheid staat voorop!</h2>\nBesparen op de kosten voor onderhoud en stilstand verminderen wordt vaak in verband gebracht met minder veiligheid en service. Dit is echter onjuist! Om de onderhoudskosten te verlagen moet er worden gewerkt aan een hogere efficiëntie. Dat betekent een betere strategie en planning. Door een betere planning kan er gerichter gewerkt worden, wat de veiligheid zal vergroten.\n<h2>Fouten en storingen analyseren</h2>\nOm een onderhoudsprogramma te verbeteren dient u een beter beeld te krijgen van de gegevens van onderhoudsstoringen. Door deze te leren begrijpen kunt u ze effectief maken als kritieke prestatie indicatoren.\n<h2>Beperk reactief onderhoud</h2>\nReactief onderhoud wordt ook wel storingsonderhoud genoemd. Het betekent dat er pas reparaties worden gedaan wanneer een machine is uitgevallen of een object defect is.\n\nOp het eerste gezicht lijkt dit een manier om de kosten te verlagen, u vervangt pas een onderdeel wanneer deze echt defect is. In de praktijk zal dit op de lange duur echter voor hogere kosten zorgen. Deze strategie zou u moeten beperken tot apparaten die niet kritiek zijn en onderdelen die makkelijk vervangbaar zijn.\n<h2>Hou een doel voor ogen</h2>\nDankzij de enorme sprongen op gebied van technologie kunnen onderhoudsbedrijven veel beter doelen stellen en resultaten bijhouden. Om te besparen op onderhoudskosten zal een bedrijf zich moeten concentreren op een specifiek doel. Door een doel te stellen worden uw inspanningen meetbaar gemaakt.\n<h2>Optimaliseer het beheer van uw voorraad</h2>\nAls manager van een onderhoudsbedrijf of onderhoudsteam bent u verantwoordelijk om de kosten voor onderhoud te beheersen en uitval tijd zo laag mogelijk te houden.\n\nIn de industriële sector is het belangrijk om de werking van apparatuur te waarborgen, het gehele proces dient zo efficiënt mogelijk te draaien. De beste manier om dit doel te bereiken is door een strategische organisatie en voorraad van reserveonderdelen. Voor veel bedrijven blijkt het beheren van reserveonderdelen een enorme kopzorg. Wanneer de voorraad van een bedrijf niet optimaal is zal dit zorgen voor hogere kosten.\n\n<img class=\"alignnone size-full wp-image-1586\" src=\"https://thingsway.nl/wp-content/uploads/2020/10/voorraad.jpeg\" alt=\"voorraad beheer \" width=\"1880\" height=\"1254\" />\n<h2>Maak gebruik van Total Productive Maintenance</h2>\nDe algehele prestaties van een bedrijf zullen verbeteren door middel van routine- en preventieve onderhoud strategieën. Bovendien zal dit de uitval van machines beperken. Een van de meest gebruikte methoden is Total Productive Maintenance (TPM). Dit is een methode die zich richt op beheersing van de werkplek. Hierdoor wordt toegankelijkheid, betrouwbaarheid en efficiëntie gegarandeerd.\n\nTPM helpt om storingen op te lossen, minder fouten te maken, en vertragingen te voorkomen. Dit alles zorgt voor grotere prestaties. Het is gebleken dat bedrijven die aan dit beleid doen hun kosten aanzienlijk weten te verlagen.\n<h2>Onderhoudsgegevens bijhouden</h2>\nBij veel bedrijven wordt nog van oude technieken gebruik gemaakt om te rapporteren. Denkt u dan aan logboeken, pen en papier en Excel-documenten. In het verleden zullen die misschien voor u gewerkt hebben, maar ze nemen veel tijd in beslag en zijn vatbaar voor fouten. Bovendien heeft u nu beschikking over veel meer gegevens.\n\nNiet alleen op gebied van rapporteren bestaat er nieuwe technologie, ook om deze gegevens te analyseren zijn er sprongen gemaakt op technologisch gebied. Wanneer u geen gebruik maakt van deze technologie dan loopt u het risico dat u vitale data over het hoofd ziet.\n\nTegenwoordig bestaat er software voor onderhoud waarmee een bedrijf rapportage kan automatiseren. De software stelt u in staat om u op specifieke gegevens te richten. Dit is een veel efficiëntere manier om uw machines, apparatuur of processen mee te volgen.\n<h2>Maak gebruik van de Thingsway om onderhoudskosten te besparen</h2>\nGegevens verzamelen is dus heel belangrijk voor een bedrijf om onderhoudskosten te kunnen besparen. Om deze data van machines, of van een proces, te kunnen verzamelen heeft u een sensor nodig die de machine continu monitort. Dankzij het Internet-of-Things bestaan er tegenwoordig sensoren die niet alleen zorgen voor deze monitoring, de gegevens worden tevens in real-time naar u doorgestuurd. Dit kan dankzij een draadloze internetverbinding.\n\nDe Thingsway van Salland Electronics is zo’n handig IoT-systeem wat ervoor kan zorgen dat u de kosten voor het onderhoud aanzienlijk kunt verlagen. U kunt de Thingsway inzetten om storingen te detecteren voordat deze plaatsvinden. Zodoende kunt u onderhoud plegen wanneer dit werkelijk nodig is. Dit zorgt voor maximaal gebruik van machine en onderdelen.\n\nTevens geeft de Thingsway u de kans om enorm veel data te verzamelen. Dit geeft een veel beter beeld van de optimale werking van een machine.\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>','Hoe kunt u besparen op onderhoudskosten?','','inherit','closed','closed','','228-revision-v1','','','2022-01-31 09:51:27','2022-01-31 09:51:27','',228,'https://thingsway.media2netdev.nl/?p=409',0,'revision','',0),(410,1,'2022-01-31 09:51:28','2022-01-31 09:51:28','Wat als een onderdeel u zelf kan vertellen wanneer het moet worden gerepareerd of vervangen? Dankzij een continue verzameling van gegevens, monitoring en toepassing van geavanceerde analyses kan dit. Voorspellend onderhoud biedt bedrijven de mogelijkheid om de betrouwbaarheid te verhogen en de operationele efficiëntie te verbeteren. De ontwikkeling van het Internet-of-Things gaat razendsnel. Industriële machines worden gemonitord door middel van sensoren, deze zijn voorzien van een directe internetverbinding. De door de sensoren verzamelde data wordt hierna in de cloud geanalyseerd. Het is een soort industrieel internet dat bedrijven kansen biedt voor enorme winsten op gebied van productiviteit.\n\nDe machines die worden uitgerust met een groeiend aantal elektronische sensoren kunnen veel meer zien, horen en voelen dan ooit tevoren. Deze enorme hoeveelheden gegevens moeten worden geanalyseerd, dit wordt gedaan door middel van geavanceerde algoritmen. Deze algoritmen zorgen voor inzichten die bedrijven in staat stellen om machines of processen op geheel nieuwe en efficiëntere manieren te gebruiken. Voorspellend onderhoud kan worden uitgevoerd wanneer dit echt nodig is.\n<h2>De voordelen van voorspellend onderhoud</h2>\nVoorspellend onderhoud is een manier van een proactief onderhoudsplan. Voorheen werd voorspellend onderhoud gedaan op basis van metingen en gegevens van periodiek onderhoud, historische gegevens van storingen en gebruiksaanwijzingen van fabrikanten. Aan de hand van deze verzamelde gegevens kon een redelijke voorspelling worden gedaan wanneer een machine of object onderhoud nodig had. Dit had echter een groot nadeel, het gaat in dit geval namelijk om voorspellingen uit het verleden, op basis van relatief weinig gegevens.\n\nEen ander soort voorspellend onderhoud heeft zijn intrede gedaan dankzij de opkomst van het Internet-of-Things. Een IoT-toepassing is een apparaat dat gebruik maakt van sensoren in combinatie met een rechtstreekse internetverbinding. Dit geeft de mogelijkheid om apparaten, maar ook objecten en processen, continu te laten monitoren. Het monitoren heeft twee grote voordelen; ten eerste geeft het u de mogelijkheid om een storing voor te zijn. De IoT-toepassing geeft u een waarschuwing voordat een probleem zich voordoet. Het andere voordeel is dat het continu monitoren zorgt voor enorm veel data. Zoveel gegevens bieden u de kans om een veel beter beeld te krijgen van de werking van een machine of proces.\n<h2>Analyse van maintenance data</h2>\nDe gegevens die verkregen worden via het monitoren van een machine of proces kunt u zien als maintenance data. De IoT-toepassing vormt een deel van uw onderhoudsteam of het maintenance bedrijf wat u inhuurt. De sensoren zorgen voor de monitoring en sturen de gegevens door via de internetverbinding. Het analyseren van de maintenance data kan het best worden gedaan via software en zogenaamde algoritmen. Hiermee kan de optimale werking van een machine of proces worden bepaald. Dit geeft een bedrijf de mogelijkheid om de efficiëntie te vergroten en kosten te besparen. Machines, onderdelen en grondstoffen kunnen maximaal worden benut.\n<h2>De Thingsway</h2>\nDe Thingsway is een IoT-apparaat dat op vele gebieden kan worden ingezet. De Thingsway is een basisproduct dat zeer snel aan te passen is op de wensen van een bedrijf. De aanpassingen die gedaan moeten worden liggen op het gebied van behuizing, montering en de benodigde sensoren. Elk proces heeft namelijk een andere sensor nodig.\n\nDe Thingsway is ontwikkeld door Salland Electronics, zij kunnen u binnen een dag voorzien van een IoT-sensor, inclusief internetverbinding. Zodoende kunt u een analyse van maintenance data uitvoeren. Dit geeft ook u de kans om aan voorspellend onderhoud te doen. Bovendien biedt het u de mogelijkheid om kosten te besparen en de efficiëntie naar een hoger plan te tillen.\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>','Analyse van maintenace data','','inherit','closed','closed','','230-revision-v1','','','2022-01-31 09:51:28','2022-01-31 09:51:28','',230,'https://thingsway.media2netdev.nl/?p=410',0,'revision','',0),(411,1,'2022-01-31 09:51:29','2022-01-31 09:51:29','Voor veel bedrijven is het van groot belang om maximaal te kunnen produceren onder de meest effectieve omstandigheden. Helaas gaat er wel eens iets mis tijdens een productieproces van een bedrijf, denk maar eens aan de terugroep acties van bepaalde automerken zoals Tesla. Dit kan een bedrijf tonnen geld kosten. Dit is de reden waarom bedrijven in bijvoorbeeld de luchtvaartindustrie, autofabrikanten en productie-industrie een grote uitdaging hebben om die effectiviteit en maximale inzet van middelen te garanderen. Dit wordt gedaan door de kritieke activa in zo goed mogelijke staat te houden. Tegelijkertijd is het doel om de kosten van onderhoud en reparaties te minimaliseren.\n<h2>Kosten minimaliseren door het Internet-of-Things</h2>\nOm deze kosten te reduceren zouden de oorspronkelijke redenen van defecten en storingen geïdentificeerd moeten kunnen worden zonder menselijke metingen en testen. Hieraan kan voldaan worden dankzij Internet-of-Things toepassingen in de industrie. Steeds meer apparatuur, robots en voertuigen worden aan een server aangesloten. Dit maakt het voor een bedrijf eenvoudiger, goedkoper en praktischer om fouten op te sporen.\n\nHet vroegtijdig opsporen van eventuele problemen helpt een bedrijf om een maintenanceteam effectiever in te zetten. Bovendien wordt er maximaal gebruik gemaakt van onderdelen en apparatuur. Om kritische factoren te bepalen die een storing voorspellen worden gegevens verzameld als bouwjaar, merk, model, garantie en aanwijzingen van fabrikant. Dat zijn gegevens die nog vrij gestructureerd zijn. Andere gegevens zijn vaak minder gestructureerd, zoals logboek gegevens van metingen, onderhoudsrapporten en foutmeldingen.\n\nDeze gegevens worden gebruikt om voorspellend onderhoud uit te voeren. Dit is een onderhoudsstrategie om te voorspellen wanneer een werkende machine defect zal raken. Onderhoud zal uitgevoerd worden voordat dit gebeurt. Wanneer er gebruik gemaakt wordt van een Iot-toepassing kan voorspellend onderhoud uitgevoerd worden aan de hand van real-time data.\n<h2>Voordelen van Data Science bij voorspellend onderhoud</h2>\nEr zijn vele voordelen aan het toepassen van data science bij voorspellend onderhoud. Enkele voordelen zijn:\n<ul>\n 	<li>Het minimaliseert de onderhoudskosten. Er wordt geen tijd verspild aan te voorzichtig en tijdsgebonden onderhoud. Apparatuur wordt vervangen wanneer nodig.</li>\n 	<li>Uitvaltijd wordt verminderd. Door aan voorspellend onderhoud te doen een Iot-oplossing, kunt u toekomstige storingen en defecten voor zijn. Onvoorziene problemen kunnen uw bedrijf niet meer in gevaar brengen.</li>\n 	<li>Analyse van de oorzaken. Door gegevens van de Iot-oplossing te analyseren, kunt u beter de oorzaak van storingen opsporen. Samen met fabrikanten kan het rendement en de effectiviteit van een machine verbeterd worden.</li>\n 	<li>Effectieve inzet van personeel. Geen onnodige reparaties of periodiek onderhoud zorgt voor een efficiëntere inzet van technisch personeel.</li>\n 	<li>Een defect of storing herstellen betekent vaak juridische of garantie kosten. Deze kosten kunnen verminderd worden wanneer storingen voorkomen worden.</li>\n</ul>\nVeel grote bedrijven maken al gebruik van de voordelen van het Internet-of-Things in combinatie met voorspelbaar onderhoud. Een machinestoring komt vaak plotseling en onverwacht. Dit kan de reputatie en het aanzien van een bedrijf ruïneren. Het kan leiden naar hoge kosten, contractboetes en minder inkomsten door stilstand. Met gebruik van een Iot-oplossing en data science kunnen al deze problemen voorkomen worden.\n<h2>Verzamel data met de Thingsway</h2>\nMisschien vraagt u zich nu af hoe dat nu in zijn werk gaat, zo’n Internet-of-Things oplossing. De Thingsway is een voorbeeld van een Iot-oplossing. Dit is een apparaat dat is voorzien van bepaalde sensoren en een directe, draadloze internetverbinding. Deze sensoren monitoren continu veranderingen in de omgeving van een object of machine. Deze veranderingen kunnen zijn warmte, beweging, druk etc. Er bestaan veel verschillende soorten sensoren, bijna alle veranderingen zijn hierdoor meetbaar.\n\nWanneer zo’n verandering optreedt zal de sensor dit registreren en onmiddellijk communiceren via data aan bepaalde hardware. Dat kan gaan om computer, laptop of de smartphone van iemand van het onderhoudsteam. Data science zorgt er vanaf dit moment voor dat u de voordelen van voorspelbaar onderhoud kunt toepassen.\n\nDe Thingsway is ontwikkeld door Salland Electronics. Deze Iot-oplossing is zeer snel toepasbaar en op meerdere gebieden. Er bestaat een Thingsway voor de industriële sector, maar er is ook een Thingsway die op buitenlocaties wordt ingezet. Het basisproduct kan binnen een dag door Salland Electronics worden aangepast zodat het in te zetten is in uw bedrijf. Zodoende kunt u binnen korte tijd werken aan meer effectiviteit en kostenbesparingen. Dat alles door middel van data science en voorspelbaar onderhoud.\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>','De voordelen van data sience voor voorspellend onderhoud','','inherit','closed','closed','','232-revision-v1','','','2022-01-31 09:51:29','2022-01-31 09:51:29','',232,'https://thingsway.media2netdev.nl/?p=411',0,'revision','',0),(412,1,'2022-01-31 09:51:31','2022-01-31 09:51:31','Het Internet-of-Things, misschien heeft u er wel eens van gehoord? Het wordt ook wel de nieuwe industriële revolutie genoemd. Het is de afgelopen jaren enorm in opkomst. Voor bedrijven is het de mogelijkheid om efficiënter te werken en daarmee concurrerend te blijven. Bedrijven die veel te maken hebben met onderhoud investeren vaak in het IoT. Waarom? Omdat een Iot-oplossing kan zorgen voor het reduceren van onderhoudskosten.\n<h2>Het doel van onderhoud</h2>\nWanneer we denken aan onderhoud, dan denken we al snel aan het repareren van machines of objecten. Onderhoud betekent echter veel meer. Om een bedrijf gezond te houden is een onderhoudsstrategie nodig die als doel heeft om zo veel mogelijk uitval en schade te voorkomen. Dit zorgt ervoor dat een bedrijf geen stilstand heeft, waardoor de kosten op gebied van arbeidsuren, reparaties en onderdelen laag blijven. Dit zorgt voor meer effectiviteit en een algeheel beter lopend proces.\n<h2>De verschillende manieren van onderhoud</h2>\nEr bestaan veel verschillende manieren van onderhoud. U kunt er voor kiezen om alleen maar reactief onderhoud te plegen. U reageert dan slechts op klachten van bijvoorbeeld bewoners of automatische meldingen van een machine. Onderhoud wordt in zo’n geval alleen gepleegd wanneer iets defect is. Dit heeft flinke nadelen, want u loopt achter de feiten aan. Een reactief onderhoudsplan zorgt er niet voor dat de werking van een proces of machine zo goed mogelijk gewaarborgd blijft. Onderdelen zullen stuk gaan, uitval van machines blijft onvermijdelijk. Reactief onderhoud is een strategie die alleen geschikt is voor onderdelen die niet kritiek zijn in een proces. Denkt u dan aan onderdelen die relatief goedkoop zijn en tevens makkelijk te vervangen.\n\nDe tegengestelde manier van reactief onderhoud is proactief onderhoud. Wanneer u als bedrijf aan proactief onderhoud doet, dan past u strategieën toe die er toe dienen om omstandigheden te creëren die ertoe leiden dat de werking van een bepaald proces zo lang mogelijk gewaarborgd blijft. Een goed voorbeeld van proactief onderhoud is periodiek onderhoud. In geval van periodiek onderhoud wordt onderhoud gepleegd volgens een vastgestelde interval van tijd. Deze tijd wordt bepaald door voorspellingen hoe lang een bepaalde machine, of onderdeel, zal meegaan. Deze voorspellingen worden gedaan op basis van metingen, historische gegevens en aanwijzingen van fabrikanten. Periodiek onderhoud is een vrij goede en betrouwbare manier van onderhoud, het is een soort voorspelbaar onderhoud. Er is echter een manier van voorspelbaar onderhoud dat nog effectiever is vanwege meer en betrouwbaardere data.\n\n<img class=\"alignnone size-full wp-image-1599\" src=\"https://thingsway.nl/wp-content/uploads/2020/10/onderhoud-kosten-reduceren-scaled.jpg\" alt=\"reduceren onderhoudskosten\" width=\"2560\" height=\"1707\" />\n<h2>Voorspelbaar onderhoud dankzij het IoT</h2>\nDankzij het Internet-of-Things kan er aan een nieuwe vorm van voorspelbaar onderhoud worden gedaan. We hebben het dan namelijk over voorspelbaar onderhoud op basis van real-time data. Het Internet-of-Things kunt u zien als de mogelijkheid om alle kritieke onderdelen van uw bedrijf continu te laten monitoren. Voor dit monitoren heeft u geen mensen ter plekke nodig. Via een directe internetverbinding worden gegevens van het proces doorgestuurd naar hardware naar uw keus. Dat kan gaan om een computer, laptop of smartphone.\n\nAls voorbeeld kunnen we een machine nemen die regelmatig oververhit. Daardoor ontstaat een storing en heeft u uitval van de machine. Dit levert u kosten op, niet alleen om de machine weer te repareren, maar ook kosten voor stilstand, onderdelen en arbeidsuren. Misschien krijgt u zelfs te maken met juridische kosten, wanneer u bijvoorbeeld een bestelling niet kunt leveren.\n\nU kunt de machine laten monitoren door een IoT-apparaat. Deze is voorzien van sensoren die het proces continu in de gaten houden. Wanneer de warmte verandert, en dus oververhitting zou kunnen plaatsvinden, dan geven de sensoren dit onmiddellijk door. Een technische dienst, of zelfs iemand die ter plaatse met de machine werkt, kan ingrijpen voordat de storing optreedt.\n<h2>Onderhoudskosten reduceren met de Thingsway</h2>\nDe Thingsway is zo’n IoT-apparaat dat ingezet kan worden voor voorspelbaar onderhoud. Dit is een apparaat dat ontwikkeld is door Salland Electronics. Het grote voordeel van de Thingsway is dat het voor veel toepassingen geschikt gemaakt kan worden. Aanpassingen aan het basisontwerp worden gedaan aan de hand van uw wensen en het te meten proces. Denkt u dan aan aanpassingen als de behuizing, verschillende sensoren en aansluiting.\n\nEen IoT-sensor zoals de Thingsway is de nieuwe manier van voorspelbaar onderhoud. Het geeft u de mogelijkheid om onderhoudskosten te reduceren. Niet alleen door in te grijpen in een proces voordat schade of uitval ontstaat. Op den duur zal de vele data u ook meer inzichten bieden in de werking van een machine, onderdeel of proces. Door goede analyses te doen kunt u bijvoorbeeld kosten reduceren door een efficiëntere inzet van middelen. Ook kosten op gebied van verbruik van grondstoffen en onderdelen kunnen gereduceerd worden.\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>','Onderhoudskosten reduceren met de Thingsway','','inherit','closed','closed','','234-revision-v1','','','2022-01-31 09:51:31','2022-01-31 09:51:31','',234,'https://thingsway.media2netdev.nl/?p=412',0,'revision','',0),(413,1,'2022-01-31 09:51:32','2022-01-31 09:51:32','Om een bedrijf te laten groeien is het regelmatig onderhouden van de activa een must. Onderhoud wordt door bedrijven gedaan om de prestaties te optimaliseren. Het doel is om zo min mogelijk uitval te hebben, dit kan leiden naar betere prestaties van activa, maar ook een effectiever productieproces.\n\nBij het woord onderhoud denken velen aan repareren. Onderhoud richt zich echter meer op het opvolgen van een strategisch plan. Een onderhoudsproces volgens een bepaalde methode, dat als doel heeft om de werking van machines, apparatuur of objecten te optimaliseren. Onderhoud is dus veel meer dan alleen repareren. Om een goed lopend bedrijf te hebben is het van belang om meer tijd en inspanning te spenderen aan onderhoud, dan aan reparaties.\n\nDe opkomst van het Internet-of-Things zorgt ook voor grote stappen op gebied van innovatie in de wereld van onderhoud en maintenance. Dit biedt bedrijven de mogelijkheid om hun onderhoudsplan, en daarmee het gehele bedrijf, naar een hoger niveau te tillen.\n<h2>Hoe zet u data analyse in bij onderhoud?</h2>\nHet Internet-of-Things is overal om ons heen, ook al beseffen we ons dat niet. Veel apparaten in ons huis, op ons werk en op straat zijn voorzien van sensoren en een internetconnectie. Dit geeft deze apparaten de mogelijkheid om met ons, maar ook met elkaar, te communiceren.\n\nHet Internet-of-Things is ook zeer goed in te zetten voor onderhoud. Door een IoT-apparaat te gebruiken om een proces of machine te monitoren, krijgt een bedrijf beschikking over enorm veel data. De sensoren houden continu een bepaald proces in de gaten. Veranderingen in dit proces worden via de directe internetverbinding doorgestuurd. Deze data kan daarna worden geanalyseerd. Een analyse kan er bijvoorbeeld voor zorgen dat u een storing voor bent, maar het heeft nog meer voordelen.\n\n<img class=\"size-full wp-image-1604 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/10/onderhoud-data-analyse.jpg\" alt=\"onderhoud data analyse\" width=\"1000\" height=\"800\" />\n<h2>Voordelen van data analyse bij onderhoud op korte termijn</h2>\nIeder proces heeft bepaalde omstandigheden nodig om goed te blijven verlopen. Veranderingen in de omgeving van dit proces kunnen ervoor zorgen dat storingen optreden. Een machine kan bijvoorbeeld vastlopen, omdat de warmte in een ruimte te hoog wordt. Een doorstroom van water in een dakgoot kan stoppen, omdat de goot volgeraakt is met bladeren.\n\nDeze veranderingen kunnen worden geregistreerd door sensoren. Er bestaan veel verschillende sensoren, er bestaan sensoren die warmte meten, maar ook druk, beweging etc.\n\nNa het bepalen van de belangrijke indicator in een proces (druk, warmte, beweging etc.), kan het proces continu gemonitord worden door een Iot-oplossing. Het voordeel hiervan op korte termijn is dat de sensor onmiddellijk een melding zal geven wanneer deze verandering optreedt. Zodoende kan een monteur of technisch team in actie komen, voordat een machine in storing gaat of er schade ontstaat.\n\nAls voorbeeld in de praktijk kunnen we de dakgoot nemen. Een sensor houdt de doorstroom van de dakgoot in de gaten. Neemt de doorstroom af vanwege bladeren in de goot, dan geeft de sensor onmiddellijk een melding. Onderhoud kan uitgevoerd worden voordat de goot overloopt en er schade ontstaat aan goot en/of huizen.\n<h2>Voordelen van data analyse bij onderhoud op lange termijn</h2>\nBehalve dit grote voordeel op korte termijn, wat u al flink in de kosten zal kunnen schelen, zijn er ook voordelen op de lange termijn. Het continu monitoren van een proces geeft u namelijk enorm veel betrouwbare data. Onderhoud wordt meestal gebaseerd op instructies van fabrikanten, gegevens uit het verleden en metingen tijdens onderhoud. Deze factoren bepalen de voorspellingen voor toekomstig onderhoud.\n\nEen IoT-oplossing geeft u in de loop der tijd veel meer informatie, bovendien is deze data up-to-date. Veel meer data zorgt voor een veel beter beeld in de werking van een machine of proces. Aan de hand van dit betrouwbaarder beeld kunt u eventueel aanpassingen doen wat betreft de optimale werking van een machine en verbetering van een proces of product. Tevens kan het op den duur zorgen voor meer effectiviteit, door zuiniger om te gaan met grondstoffen, onderdelen en arbeidsuren.\n<h2>Data verzamelen via de Thingsway</h2>\nOm data te kunnen analyseren, heeft u data nodig. Deze gegevens kunt u verkrijgen door een IoT-oplossing in te zetten. Een mooi voorbeeld van een Iot-oplossing is de Thingsway. Dit is een samenstelling van de termen Internet-of-Things en gateway.\n\nDe Thingsway is een Iot-oplossing die zeer snel in te zetten is in uw bedrijf. Het is een basisproduct waarvan details snel aangepast kunnen worden, zodat u binnen korte tijd metingen kunt doen in uw bedrijf die u van de nodige data kan voorzien. Bij deze details kunt u denken aan behuizing, sensoren en aansluitmogelijkheden. De Thingsway biedt u de ideale mogelijkheid om data analyse in te zetten bij onderhoud. Dit zal zorgen voor verlaging van de kosten en een efficiënter werkend bedrijf.\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>','De voordelen van data analyse inzetten bij onderhoud','','inherit','closed','closed','','236-revision-v1','','','2022-01-31 09:51:32','2022-01-31 09:51:32','',236,'https://thingsway.media2netdev.nl/?p=413',0,'revision','',0),(414,1,'2022-01-31 09:51:32','2022-01-31 09:51:32','Onderhoud is een belangrijke factor om de kwaliteit van een bedrijf te waarborgen. In sommige gevallen bepaalt het zelfs het succes van een bedrijf op de lange termijn. Wanneer een bedrijf niet aan onderhoud doet, of minimaal, dan kan dit instabiliteit veroorzaken. De productie kan voor een gedeelte, of volledig, onderbroken worden. Machines die defect zijn, of een algehele storing, zal voor de meeste bedrijven een kostbare aangelegenheid worden. Dit geldt niet alleen voor bedrijven die veel werken met machines, het geldt ook voor onderhoudsbedrijven en vastgoed eigenaren, zoals woningcorporaties.\n\nEen storing zorgt voor meerdere problemen en kosten. Zo zal de productie stil liggen, arbeidskosten zullen stijgen, u heeft kosten op gebied van reparaties en onderdelen. Bovendien komen daar regelmatig bijkomende kosten bij door schade en eventuele juridische kosten. Dit zijn slechts enkele voorbeelden waar een bedrijf in de loop van de tijd mee te maken krijgt, zeker wanneer deze geen betrouwbaar onderhoudsplan heeft. Dankzij de opkomst van het Internet of Things, heeft u juist nu de mogelijkheid om een zeer accuraat onderhoudsplan op te stellen.\n<h2>De verschillende soorten onderhoud</h2>\nUw bedrijf kan op meerdere manieren aan onderhoud doen. Wanneer u een gedegen onderhoudsplan heeft dan zal dit een combinatie zijn van verschillende vormen van onderhoud. De verschillende vormen van onderhoud kunnen globaal worden ingedeeld in twee vormen; reactief onderhoud en proactief onderhoud. In geval van reactief onderhoud wordt er pas onderhoud gepleegd wanneer er een storing of defect is opgetreden. U reageert op een melding van een machine of klacht van bijvoorbeeld een bewoner. Het nadeel hiervan is dat u achter de feiten aanloopt. Dit soort onderhoud kunt u het best toepassen op makkelijk vervangbare en niet kostbare onderdelen.\n\nDe andere vorm van onderhoud is proactief onderhoud. Van proactief onderhoud bestaan meerdere vormen zoals preventief, periodiek en planmatig onderhoud. Deze vormen van onderhoud zou u kunnen zien als voorspellend onderhoud. De onderhoudswerkzaamheden worden namelijk gedaan op basis van voorspellingen. Gegevens als aanwijzingen van fabrikant, ervaringen en metingen uit het verleden bepalen de planning van dit onderhoud. Dit zijn altijd gegevens uit het verleden, bovendien kunt u pas echt een gedegen plan opstellen wanneer u veel gegevens heeft van een machine of object. Dit is de reden waarom er nog steeds storingen voorkomen, ondanks preventief en periodiek onderhoud. Dankzij het Internet-of-Things is dat nu op te lossen, namelijk door voorspellend onderhoud toe te passen op basis van real-time data.\n<h2>Voorspellend onderhoud op basis van real-time data</h2>\nDe laatste jaren is het Internet-of-Things enorm in opkomst in de industrie, maar ook bij bedrijven die veel met maintenance te maken hebben. Het Internet-of-Things biedt namelijk enorme mogelijkheden op gebied van onderhoud en monitoring van machines en objecten. Heeft u geen idee wat het Internet-of-Things is? Eenvoudig uitgelegd kunt u het IoT zien als slimme apparaten die gegevens verzamelen. Zonder het misschien te beseffen treft u ze overal om u heen aan; in de thermostaat, in magnetrons, koelkasten etc.\n\nEen Internet-of-Things-systeem kan ook heel goed toegepast worden voor bedrijven die met onderhoud te maken hebben. Stel dat u een object of machine heeft dat van groot belang is voor uw bedrijf, of er is een onderdeel dat regelmatig defect raakt. Dit zou u kunnen laten monitoren door een Iot-systeem. Dit is een apparaat dat is voorzien van sensoren en een directe internetverbinding. Het monitoren gebeurt continu, dit levert enorm veel gegevens op. Veranderingen in de omgeving worden door de sensor geregistreerd en via de directe internetverbinding verstuurt naar computer, laptop of smartphone. Deze veranderingen kunnen betekenen dat een storing zal optreden, u wordt daarom vooraf gewaarschuwd. U kunt dit zien als voorspellend onderhoud door middel van real-time gegevens via het Iot-systeem.\n<h2>Voordelig datasysteem in één dag geïnstalleerd</h2>\nSalland Electronics heeft de Thingsway ontwikkeld. De Thingsway is een Iot-apparaat dat op veel gebieden van onderhoud in te zetten is. Het nadeel van de meeste Iot-systemen is dat ze log zijn wat inzetbaarheid betreft. Vaak duurt het erg lang voordat een systeem ontwikkeld is.\n\nHet voordeel van de Thingsway is dat het een soort ‘kant en klaar’ product is. Aanpassingen die gedaan moeten worden aan het apparaat hangen af van uw wensen en het te meten proces. Deze aanpassingen worden razendsnel door Salland Electronics uitgevoerd. U kunt zelfs binnen een dag voorzien zijn van een voordelig datasysteem. Ook de internetverbinding wordt door Salland Electronics verzorgd. U kunt kiezen uit verschillende bekende providers.\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>','Voordelig datasysteem in één dag geïnstalleerd','','inherit','closed','closed','','238-revision-v1','','','2022-01-31 09:51:32','2022-01-31 09:51:32','',238,'https://thingsway.media2netdev.nl/?p=414',0,'revision','',0),(415,1,'2022-01-31 09:51:33','2022-01-31 09:51:33','Er zijn veel bedrijven die met onderhoudsactiviteiten te maken hebben. Dan kan het gaan om productiebedrijven die veel met machines werken en maintenance bedrijven, maar ook vastgoedbedrijven, zoals woningcorporaties. Er bestaan verschillende strategieën om onderhoud toe te passen, een voorbeeld hiervan is preventief onderhoud. Helaas zorgt preventief onderhoud er niet voor dat storingen nooit meer voorkomen. Wanneer er een storing plaatsvindt bij een machine, object of proces, dan is het verstandig om een storingsanalyse uit te voeren.\n<h2>Wat is een storingsanalyse?</h2>\nEen storingsanalyse is een onderzoek dat gedaan wordt om achter de oorzaak van de storing te komen. Het uiteindelijke doel van het onderzoek is om maatregelen te kunnen nemen die ten eerste het probleem oplossen en ten tweede storingen in de toekomst voorkomen. In vrijwel alle takken van de productie-industrie worden storingsanalyses gedaan om defecten aan machines, objecten en producten in de toekomst te voorkomen. Een storingsanalyse wordt tevens uitgevoerd om mens en milieu te beschermen tegen potentieel gevaarlijke situaties.\n<h2>Redenen om een storingsanalyse uit te voeren</h2>\nHet uitvoeren van een storingsanalyse biedt voor een bedrijf een aantal voordelen. Enkele voordelen hiervan zijn financiële voordelen, juridische en voordelen die met de veiligheid te maken hebben. De resultaten die uit de storingsanalyse komen kunnen namelijk zorgen voor bepaalde inzichten en mogelijkheden. We bespreken de belangrijkste.\n<h2>Inzicht in de hoofdoorzaak van de storing</h2>\nHet fundamentele onderdeel van een storingsanalyse uitvoeren is om erachter te komen wat de hoofdoorzaak van de storing is. Tijdens de storingsanalyse wordt gezocht naar gegevens die kunnen vaststellen waarom de storing is opgetreden. Was het een gevolg van een fabricagefout, een materiaalfout, slijtage of fout gebruik van het object?\n<h2>Hoe kunt u storingen voortaan voorkomen?</h2>\nWanneer de oorzaak van de storing is vastgesteld, dan kunnen er maatregelen genomen worden om te zorgen dat het probleem niet meer op zal treden. Corrigerende maatregelen kunnen zijn; gebruik van andere onderdelen, meer preventief onderhoud en verbetering van het productieproces.\n\n<img class=\"alignnone size-full wp-image-1612\" src=\"https://thingsway.nl/wp-content/uploads/2020/10/voordelen-storingsanalyse.jpeg\" alt=\"storingsanalyse \" width=\"1880\" height=\"1251\" />\n<h2>Verbeteren van toekomstige producten en processen</h2>\nDankzij een goed inzicht in de storing van een proces of machine, kunt u het productieproces verbeteren, maar ook het ontwerp van een machine of product. Dit zorgt voor meer effectiviteit, omdat het probleem zich niet meer voordoet, maar ook voor lagere kosten. Denkt u dan aan de kosten voor het vervangen van onderdelen en de tijd van uitval. Vergeet u ook niet eventuele kostbare juridische stappen of de reputatie van uw bedrijf.\n<h2>Voorkom kosten door defecten en eventuele boetes</h2>\nStoringen kunnen kostbaar zijn. Dat kunnen kosten zijn door uitval, onderhoud en stilstand van de productie. Juridische kosten kunnen zelfs een gevolg zijn van een storing. Door een storingsanalyse te laten uitvoeren kunt u zulke problemen voorkomen. Tevens kunt u voorkomen dat mogelijke storingen in de toekomst optreden.\n<h2>U voldoet aan de normen voor producten en activa</h2>\nEen storingsanalyse kan u in de toekomst helpen om aan normen te voldoen voor een bepaald productieproces, voor componenten, producten en machines.\n<h2>De aansprakelijkheid voor de storing bepalen</h2>\nEen storingsanalyse laat u vooral uitvoeren om de hoofdoorzaak te bepalen. Wanneer u achter de hoofdoorzaak gekomen bent, dan kunt u ook de aansprakelijkheid voor de storing bepalen. Helaas is dit soms nodig in gevallen van storingen. Dit kan u beschermen tijdens eventuele rechtszaken, maar kan ook in gerechtelijke procedures gebruikt worden om uw gelijk te krijgen.\n<h2>Hoe wordt een storingsanalyse uitgevoerd?</h2>\nEen storingsanalyse wordt uitgevoerd wanneer de storing heeft plaatsgevonden. Technici zullen zoeken naar de defecten en na analyse bepalen waardoor de storing heeft plaatsgevonden. U heeft dus altijd te maken met gegevens die achteraf geïnterpreteerd worden. Zou het bepalen van de oorzaak van een storing niet eenvoudiger zijn wanneer u beschikt over real-time data die u later kunt analyseren? Sterker nog, zou het niet nog handiger zijn wanneer u beschikt over real-time data die ervoor zorgt dat een storing voorkomen kan worden?\n\nZo’n storingsanalyse zou u kunnen laten uitvoeren door middel van een Internet-of-Things oplossing.\n<h2>De Thingsway, een IoT-oplossing</h2>\nDe Thingsway is een IoT-oplossing die in te zetten is vele takken van onderhoud en productie. Via sensoren kan de Thingsway bepaalde processen continu monitoren. Dit zorgt voor enorm veel data en inzichten in de werking, of eventuele storing, van een proces of product. Wanneer er veranderingen optreden in dit proces, dan zullen de sensoren dit waarnemen. Via een rechtstreekse internetverbinding worden deze real-time gegevens verstuurd.\n\nDeze enorme hoeveelheid data geeft na het analyseren een veel beter inzicht in de werking en de eventuele reden van de storing. Een storing kan zelfs voorkomen worden wanneer de Thingsway wordt ingezet om een kritiek proces te monitoren.\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>','Wat is een storingsanalyse, en wat zijn de mogelijkheden?','','inherit','closed','closed','','240-revision-v1','','','2022-01-31 09:51:33','2022-01-31 09:51:33','',240,'https://thingsway.media2netdev.nl/?p=415',0,'revision','',0),(416,1,'2022-01-31 09:51:34','2022-01-31 09:51:34','Veel bedrijven zijn op zoek naar het antwoord op de volgende vraag: ‘Hoe kunnen we toch onze onderhoudskosten verlagen?’\n\nEen bedrijf kan wat omzet betreft heel goed draaien, maar wanneer de onderhoudskosten heel hoog zijn dan drukt dat flink op de winstmarges. Een bedrijf kan pas bloeien wanneer de onderhoudskosten goed in bedwang worden gehouden. Heeft u een bedrijf dat veel te maken heeft met onderhoud, zoals een productiebedrijf, een woningcorporatie of een maintenance bedrijf? Dan kunt u vast wel wat slimme tips gebruiken om de onderhoudskosten te verlagen. Wilt u besparen? Begin dan vandaag nog!\n<h2>Het doel van onderhoud</h2>\nHet doel van onderhoud is om de volledige beschikbaarheid van apparatuur, voorzieningen, objecten en faciliteiten te garanderen. Dit tegen optimale kosten en onder een aanvaardbare standaard van kwaliteit, veiligheid voor mensen en milieu.\n\nOm te voldoen aan al deze aspecten werkt een bedrijf met een gedegen onderhoudsplan. Voor een bedrijf dat veel te maken heeft met vastgoed of bouwkundig onderhoud, is het van belang om proactief onderhoud te voeren. Proactief onderhoud zorgt ervoor dat u niet achter de feiten aanloopt. U heeft kennis van zaken van uw vastgoed en gebouwen en maakt daar een onderhoudsplan voor. Bedrijven die veel te maken hebben met maintenance van machines voeren storingsafhankelijk en preventief onderhoud uit.\n\nDeze manieren van onderhoud zijn de meest gangbare manieren om de kosten van onderhoud zo laag mogelijk te houden. Toch kunt u zeker nog meer doen om de onderhoudskosten te verlagen. We geven u vijf tips.\n<h2>Tip 1: Storingen voorkomen</h2>\nDe logische eerste tip om de onderhoudskosten te verlagen is door middel van het voorkomen van storingen. Dit is niet alleen vanwege de hoge kosten voor het repareren van een defect, maar het kan ook de activiteiten van een bedrijf vertragen of zelfs stilleggen.\n\nHoe kunt u storingen voorkomen? U doet vanzelfsprekend al aan preventief onderhoud, maar heeft u daar echt een goede strategie voor? Een geautomatiseerd systeem voor uw onderhoudswerkzaamheden biedt u een ideale manier om alle nodige handelingen op gebied van onderhoud goed te volgen, beoordelen en plannen.\n<h2>Tip 2: Gedegen beheer van uw inventaris</h2>\nLigt de gemiddelde tijd voor een reparatie in uw bedrijf hoog? Een reden hiervoor kan zijn dat u niet genoeg reserveonderdelen in uw voorraad heeft. U kunt dit oplossen door meer reserveonderdelen aan te schaffen; vaak kunt u aantrekkelijke prijzen afspreken met leveranciers als u onderdelen in bulk aanschaft.\n\nEen ander manier van besparen op onderdelen is door ervoor te zorgen dat reserveonderdelen verwisselbaar zijn. Het is erg handig wanneer verschillende onderdelen op meerdere machines of objecten te gebruiken zijn. Een fabrikant zal ook eerder technische hulp bieden wanneer al uw onderdelen (of machines) van hem afkomstig zijn.\n<h2>Tip 3: Train uw team</h2>\nDe kans is groot dat u voor onderhoud een technisch team heeft of een maintenance bedrijf inhuurt. Om de onderhoudskosten te verlagen zou u uw gehele team kunnen trainen in de technische werking van een machine. Dit zorgt ervoor dat eventuele storingen veel eerder kunnen worden opgemerkt en zelfs verholpen. Hierdoor zal uitval van productie verholpen worden en bovendien kostbare en tijdrovende reparaties vermeden.\n\n<img class=\"alignnone size-full wp-image-1616\" src=\"https://thingsway.nl/wp-content/uploads/2020/10/team-trainen-scaled.jpg\" alt=\"verlagen onderhoudskosten\" width=\"2560\" height=\"1707\" />\n<h2>Tip 4: Verlengen van garanties of verzekeringen</h2>\nHelaas werkt niets voor altijd en feilloos. Alles is nu eenmaal aan slijtage onderhevig. Daarom is het zeer verstandig om de duurste apparatuur of de meest kwetsbare onderdelen te verzekeren. Ook kunt u vaak bij fabrikanten de garantie verlengen van sommige onderdelen of machines.\n\nOm te bepalen welke onderdelen van een gebouw of machines van een bedrijf het belangrijkst of meest kwetsbaar zijn, zou u het onderhoudsteam kunnen raadplegen. Deze hebben vaak het beste inzicht op de werking en slijtage. U kunt er zelfs voor kiezen om slechts enkele specifieke onderdelen te verzekeren. Een juist beeld krijgen van de kwetsbare en kostbare onderdelen en deze verzekeren, of de garantie verlengen, kan u flink wat onderhoudskosten schelen.\n<h2>Tip 5: Kies voor een IoT-oplossing</h2>\nOm een goed beeld te krijgen van een onderdeel, machine of object is het niet nodig om ze persoonlijk te analyseren met pen en papier op schoot. De werking van een bepaald voorwerp, en het nodige onderhoud om deze werking te garanderen, wordt voorspeld aan de hand van gegevens. Ten eerste de gegevens van de leverancier en daarnaast door middel van ervaring en periodiek onderhoud.\n\nEen veel beter inzicht in de werking van een voorwerp krijgt u door middel van een Internet of Things-oplossing. Dit is een apparaat die continu de werking van een object monitort via sensoren. Via een internet verbinding worden deze gegevens doorgegeven, waarna ze geanalyseerd kunnen worden. Dit geeft een zeer nauwkeurig inzicht in de werking, slijtage en eventueel uitval van een object.\n\nEen mooi voorbeeld van zo’n IoT-oplossing is de Thingsway van Salland Electronics.\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>','De 5 beste tips voor het verlagen van onderhoudskosten','','inherit','closed','closed','','242-revision-v1','','','2022-01-31 09:51:34','2022-01-31 09:51:34','',242,'https://thingsway.media2netdev.nl/?p=416',0,'revision','',0),(417,1,'2022-01-31 09:51:36','2022-01-31 09:51:36','Er is een enorme opmars bezig in het verzamelen van interessante data. Data is belangrijk voor elk bedrijf of elke instelling. Voldoende data kan ervoor zorgen dat u goed inzicht heeft in de werking van een object, maar ook in de productiviteit en effectiviteit van een object, of zelfs uw gehele bedrijf. Interessante informatie wordt over het algemeen verzameld door het observeren van een bepaald proces of object, zoals tijdens een steekproef, controle of onderhoud.\n\nHet Internet of Things heeft een wereld aan mogelijkheden blootgelegd op gebied van het verzamelen van interessante data. Een continu proces van verzamelen van data zorgt voor veel meer informatie. Dit biedt mogelijkheden die tot voor kort ondenkbaar waren.\n<h2>Wat is een IoT-oplossing?</h2>\nWat is het Internet of Things? Waarop wordt deze revolutie op gebied van verzamelen van transparante en interessante data voortgestuwd? Op een eenvoudige manier kan een IoT-oplossing worden uitgelegd als ‘een apparaat met sensoren dat verbinding maakt met het internet’.\n\nDeze sensoren kunnen een proces monitoren, interessante data verzamelen en deze gegevens in realtime sturen waar u maar wilt. Dat kan naar een werknemer op de werkvloer, maar bijvoorbeeld ook naar het hoofdkantoor van uw bedrijf. Deze gegevens kunnen geanalyseerd worden, of gecombineerd met gegevens van andere objecten, magazijnen of fabrieken. Dit kan over de hele wereld gecommuniceerd worden en geeft u de ideale mogelijkheid om goed op de hoogte te blijven van al uw producten, processen en benodigd onderhoud.\n<h2>De Thingsway</h2>\nEen IoT-oplossing die zulke interessante informatie kan verzamelen is de Thingsway. Dit is een basis IoT- sensor die op vele manieren kan worden ingezet. Zo kan de Thingsway bijvoorbeeld in de buitenlucht worden ingezet om metingen uit te voeren aan dakgoten. Maar de Thingsway is ook voor industriële doeleinden in te zetten, bijvoorbeeld om continue metingen te verrichten aan de werking van een apparaat of machine.\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\n<h2>Wat voor interessante data wordt verzameld?</h2>\nEen IoT-oplossing werkt dus via sensoren. Een sensor kunt u zien als een kunstmatig zintuig. Een IoT-apparaat monitort via een sensor veranderingen in de omgeving en deze informatie wordt verzameld. Als voorbeeld kunnen we bijvoorbeeld de warmte in een omgeving meten; dit fysieke getal wordt omgezet in een signaal. De metingen in de fysieke omgeving worden vertaald in data en gestuurd naar een digitaal apparaat. Niet alleen warmte kan worden gemeten door sensoren, maar ook beweging, geluid, druk, locatie, vochtigheid, etc. Al deze data kunt u onmiddellijk aflezen, maar ook naar een computer, smartphone of tablet sturen. Zodoende kunt u de gegevens bekijken waar u maar wilt.\n\nNu vraagt u zich misschien af waarom deze data zo interessant is? Meten is weten, zo luid het spreekwoord. Door het verzamelen van dit soort interessante data kunt u als bedrijf een flinke stap voorwaarts maken. Het kan zorgen voor meer effectiviteit en flinke kostenverlagingen.\n<h2>Wat kunt u doen met deze interessante data?</h2>\nHet verzamelen van interessante data via een IoT-oplossing, zoals de Thingsway, kan heel interessant zijn op verschillende gebieden. Op deze wijze kunt u bijvoorbeeld de werking van een machine zeer goed leren kennen. Hoe werkt de machine het zuinigst of meest effectief? Wat is de maximale capaciteit? Wanneer kan er storing verwacht worden? Is onderhoud echt nodig? Op welke temperatuur slaat de machine vast?\n\nPeriodiek onderhoud wordt vaak gepleegd op basis van voorspellingen van de leverancier en door onderhoudsmetingen. Een IoT-oplossing zorgt ervoor dat u continu informatie verzameld. Dit zorgt voor veel meer data en een beter inzicht in de werking van een machine, een object of proces.\n\nOok op gebied van productie en verbruik is data heel belangrijk. Na het analyseren van de metingen heeft u een zeer gedetailleerd beeld van een productieproces en weet u precies hoeveel er verbruikt wordt. Dit geeft u de mogelijkheid om eventueel aanpassingen te doen waar dat nodig is. Dit kan leiden naar een effectievere inzet van personeel, verbruik van materiaal en plegen van onderhoudswerkzaamheden.\n\nHet verzamelen van interessante data via een IoT-oplossing is de manier om uw bedrijf te moderniseren en automatiseren. Vooral als u een bedrijf heeft die veel te maken heeft met maintenance en onderhoud, kan het verzamelen van interessante data heel lucratief zijn. Heeft u zo’n bedrijf? Kijkt u eens naar de mogelijkheden van de Thingsway en wat dit voor uw bedrijf kan betekenen.\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>','Verzamel interessante data met de Thingsway','','inherit','closed','closed','','244-revision-v1','','','2022-01-31 09:51:36','2022-01-31 09:51:36','',244,'https://thingsway.media2netdev.nl/?p=417',0,'revision','',0),(418,1,'2022-01-31 09:51:36','2022-01-31 09:51:36','Een van de grote uitdagingen van een bedrijf is om achter de exacte cijfers van verbruik te komen. Welke machines verbruiken het meest, hoeveel precies, en onder welke omstandigheden? Als bedrijf wilt u natuurlijk goed op de hoogte zijn van deze cijfers, zodat u efficiënter zou kunnen gaan produceren. Niet alleen vanwege de kosten, maar ook vanwege milieuredenen. Tegenwoordig is het heel belangrijk om er als bedrijf voor te zorgen dat het productieproces zo min mogelijk belastend is voor het milieu. De CO2 afdruk van een bedrijf verlagen is één van de prioriteiten.\n\nDe exacte cijfers van verbruik achterhalen kan lastig zijn, vooral wanneer een pand groeit, of als er nieuwe machines of voorraden bijkomen. Wat moet er gemeten worden, wanneer en waar?\n\nBedrijven die kennis en inzicht hebben in hun verbruik hebben een grotere productiviteit. Deze kennis en inzicht worden verkregen door middel van metingen en monitoring. Niet alleen de productiviteit is hoger, maar ook de betrokkenheid van medewerkers wordt groter door het tonen van exacte cijfers. Dit is belangrijk voor u als bedrijf om concurrerend te blijven.\n\nWilt u de efficiëntie van uw bedrijf op het gebied van verbruik verbeteren? Dan moet het verbruik van apparaten en machines ter plekke gemeten worden, en bovendien continu. Dit kan op industrieel gebied, maar ook op gebied van dienstverlening en maintenance. Slimme automatisering neemt steeds meer toe, in alle professionele takken. Dit zorgt voor een beter inzicht en grotere efficiëntie, van manager tot de werkvloer.\n<h2>Efficiënter werken door monitoring</h2>\nUit ervaring blijkt dat wanneer er actief gewerkt wordt aan het efficiënter maken van een proces dit 8% extra besparingen oplevert. Dit komt vanwege het op tijd detecteren van eventuele storingen in de werking van een machine of een productie proces.\n\nWanneer een machine continu gemonitord wordt kan een operator, een productieteam of een onderhoudsbedrijf snel in actie komen wanneer een machine storing vertoont, of data vertoont die naar een eventuele storing kunnen leiden.\n\nContinue monitoring kan worden gedaan via een IoT- oplossing, IoT staat voor Internet-of-Things. Een sensor die verbonden is met het internet houdt het gehele proces constant in de gaten. Zodoende kan het verbruik van een machine of apparaat zeer exact gemeten worden.\n<h2>Verbruik meten van machines en apparaten</h2>\nHet verbruik meten van een machine of apparaat via een Internet-of-Things-oplossing kan op veel verschillende manieren gedaan worden. Het soort apparaat, de machine of datgene wat gemeten moet worden, bepaalt wat voor soort sensor er nodig is. Sensoren bestaan in veel verschillende soorten; temperatuursensoren, druksensoren, lichtsensoren en versnellingssensoren zijn slechts enkele voorbeelden.\n\nEen of meerdere sensoren van een IOT-oplossing meten continu het verbruik van een machine. Deze gegevens worden doorgegeven via een internet aansluiting. Deze gegevens kunnen direct worden ingezien, maar ook achteraf worden geanalyseerd. Een voorbeeld van zo’n IoT-sensor is de Thingsway.\n<h2>De Thingsway</h2>\nDe Thingsway is een IoT-sensor die ontwikkeld is door Salland Electronics. Deze sensor kan worden ingezet om veel soorten metingen uit te voeren. Speciaal voor metingen van machines is er ook een industriële versie beschikbaar. Deze is geschikt gemaakt voor DIN-rail montage, bovendien is het voorzien van meerdere aansluitmogelijkheden. De Thingsway kan heel snel aangepast worden op de wensen en werkzaamheden van uw bedrijf. Gecombineerd met het energiezuinige ontwerp (de batterij gaat gegarandeerd 10 jaar mee), krijgt u een product die van grote waarde kan zijn voor de efficiëntie van uw bedrijf.\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\n<h2>Gebruik maken van de gegevens</h2>\nHet gebruik maken van een IoT-oplossing geeft u de mogelijk om op een zeer precieze manier het verbruik te meten van een apparaat of machine. U krijgt relevante gegevens van verbruik en door deze te monitoren en te analyseren krijgt u de mogelijkheid om het productieproces te optimaliseren. Door meer inzicht in verbruik kunt u eventueel aanpassingen doen in het productieproces, tevens kunt u verandering van gedrag van een machine leren begrijpen en hierop uw beleid aanpassen. Dit geldt op gebied van productie, maar ook op gebied van onderhoud.\n\nHet meten en monitoren van het verbruik is cruciaal voor bedrijven die hun efficiëntie en productie willen verbeteren. Voor industriële bedrijven, maar ook voor bedrijven in maintenance, geldt dat het meten van verbruik en het verminderen daarvan geen optie meer is, maar een vast onderdeel van het beleidsplan. Een IoT-oplossing zoals de Thingsway, kan u helpen om uw plannen uit te voeren.\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>','Waarom is verbruik meten van groot belang voor uw bedrijf','','inherit','closed','closed','','246-revision-v1','','','2022-01-31 09:51:36','2022-01-31 09:51:36','',246,'https://thingsway.media2netdev.nl/?p=418',0,'revision','',0),(419,1,'2022-01-31 09:51:37','2022-01-31 09:51:37','Flitsende moderne technologieën halen de krantenkoppen, maar er is een stille revolutie gaande op het gebied van metingen van gewicht. De digitale evolutie van de weegschaal kan een revolutie betekenen voor verschillende takken van de industrie. Weegschalen ondergaan een razendsnelle opmars die zorgt voor snellere en efficiëntere metingen van gewicht.\n\nDe bescheiden weegschaal kennen we allemaal, vaak weggestopt in de badkamer of in de keuken. Het is echter een onmisbaar item voor verschillende professionele takken zoals horeca, landbouw, industrie en (lucht)havens. Tot kort geleden waren metingen van gewicht een vergeten stukje technologie, maar het Internet of Things (IoT) zorgt voor een moderne versie van de traditionele metingen van gewicht. Het beter kunnen beheren van dagelijkse weeg taken biedt bedrijven de mogelijkheid om in positieve zin het bedrijf te transformeren. Er is een snelle technologische opmars bezig op gebied van het meten van gewicht. Dit zorgt voor snellere en efficiëntere metingen. Maar hoe werken die metingen van gewicht via een IoT-oplossing eigenlijk?\n<h2>Hoe worden IoT-metingen van gewicht uitgevoerd?</h2>\nEen IoT-oplossing die gewicht metingen uitvoert zijn voorzien van een sensor. Zo’n sensor wordt een Load Cell genoemd, deze zet fysieke kracht om in elektrische signalen. Door middel van een draadloze aansluiting met het internet kunnen deze elektrische gegevens doorgegeven worden in vorm van data. Deze gegevens bieden de mogelijkheid om, waar u ook wilt, gegevens in te zien en te analyseren.\n\nEen voorbeeld van een IoT-oplossing is de Thingsway, deze werd ontwikkeld door Salland Electronics. Het grote voordeel van de Thingsway is zijn multifunctionaliteit; het is een basisproduct die aan te passen is naar de wensen van elk bedrijf. Binnen korte tijd kan de behuizing, maar kunnen ook de type sensoren, aangepast worden op het te meten object. Zo kan de Thingsway dus ook ingezet worden om metingen van gewicht uit te voeren. U kunt de Thingsway zien als een slimme weegschaal.\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\n<h2>Nieuwe normen door gebruik van slimme weegschalen</h2>\nMetingen van gewicht worden gedaan om de gebruiker gegevens te laten verzamelen. Door deze gegevens te analyseren kunnen wijzigingen worden gedaan, indien nodig. Controle op gewicht kan essentieel zijn, of dat nu gaat om de gezondheid van iemand, het beladen van vracht of het verzenden van pakketten.\n\nDoor draadloos verbonden weegschalen zijn bedrijven beter in staat om de gegevens te bekijken zonder er fysiek in aanraking mee te komen. Deze gegevens kunnen eenvoudig worden verwerkt in tabellen en grafieken. Deze beschikbare informatie geeft u de mogelijkheid om weloverwogen beslissingen te maken. Dit komt ten goede aan de controle van kwaliteit, efficiëntie, automatisering, verspilling van goederen, onderhoud en kostenreductie.\n<h2>Het voordeel van een dynamische weegschaal</h2>\nEen dynamische weegschaal weegt een bepaald object wanneer het in beweging is. Dit werkt door de combinatie van een beweging sensor en een sensor voor metingen van gewicht. Dit kan heel handig zijn wanneer u bijvoorbeeld een wagenpark heeft. Een dynamische weegschaal is veel efficiënter dan een continue weegschaal; er is geen handmatige bediening meer vereist.\n\nWerkt u in een industrie waar metingen van gewicht worden gedaan op bewegende objecten? Dan is een dynamische weegschaal de perfecte oplossing voor u.\n<h2>Metingen van gewicht van bagage en passagiers</h2>\nOok in de luchtvaart is het van groot belang om metingen van gewicht uit te voeren. Iedereen weet dat de bagage tijdens het inchecken wordt gewogen. Dit is van belang omdat het gewicht van een vliegtuig onder andere bepaalt hoeveel brandstof er in het vliegtuig moet. Meer gewicht betekent nu eenmaal meer brandstof en meer kosten. Brandstofkosten liggen ook in de luchtvaart hoog, bovendien is het ook voor de luchtvaart van belang om de CO2-uitstoot te verlagen.\n\nDit is de reden waarom er in de luchtvaart wordt gesproken over de plannen om passagiers te gaan wegen. Zodoende krijgt de maatschappij een veel beter en betrouwbaar beeld van het totale gewicht. Op zo’n manier kan de maatschappij exact uitrekenen hoeveel brandstof er nodig is. Dit verlaagt de kosten aanzienlijk.\n\nNatuurlijk zullen de maatschappijen u niet vragen om in bijzijn van iedereen naast uw bagage te gaan staan. Een discrete IoT-oplossing die metingen uitvoert op uw gewicht kan daarop het antwoord zijn. Een meting van gewicht die onmiddellijk, maar discreet, in data aan de maatschappij geleverd wordt.\n\n<img class=\"alignnone size-full wp-image-1630\" src=\"https://thingsway.nl/wp-content/uploads/2020/10/meting-gewicht-scaled.jpg\" alt=\"gewicht metingen industrie \" width=\"2560\" height=\"1920\" />\n<h2>Metingen van gewicht in terminals en machine-industrie</h2>\nTijdens het laden en lossen van goederen kan een gewichtsmeting via een IoT-oplossing van grote waarde zijn. Door nieuwe technologieën kunnen weegschalen op hoge snelheden materialen en goederen nauwkeurig afmeten. Dit zorgt voor een betere beheersing van alle goederen; menselijke fouten kunnen hierdoor worden verminderd.\n\nOok in de machine-industrie worden steeds meer IoT-oplossingen toegepast. Zo worden bijvoorbeeld laders voorzien van weeg technologie, deze systemen geven de bestuurder continu informatie over het proces. Dit zorgt ervoor dat een vrachtwagen iedere keer geladen wordt met het juiste gewicht.\n\nU kunt veel efficiënter werken wanneer u de mogelijkheid heeft om constant nauwkeurig te kunnen laden. Dit zorgt voor bovendien voor meer productiviteit. U medewerkers kunnen eenvoudig realtime gegevens inzien die accuraat zijn.\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>','Gewicht meten en monitoren','','inherit','closed','closed','','248-revision-v1','','','2022-01-31 09:51:37','2022-01-31 09:51:37','',248,'https://thingsway.media2netdev.nl/?p=419',0,'revision','',0),(420,1,'2022-01-31 09:51:38','2022-01-31 09:51:38','[et_pb_section][et_pb_row][et_pb_column type=\"4_4\"][et_pb_text]\n\nAlle gebouwen zijn onderhevig aan slijtage en moeten daarom onderhouden worden. Installaties, daken, betonvloeren, kozijnen; helaas bestaat er niets wat voor altijd mee gaat. Ook kan het zo zijn dat bewoners of gebruikers van een bepaald gebouw andere wensen hebben. In zo’n geval dient er onderhoud gepleegd te worden om deze wensen in veranderingen om te zetten.\n\nOm gebouwen gedegen te kunnen onderhouden is een onderhoudsplan nodig. Hierin staan onderhoudsplannen voor de toekomst (zoals het vervangen van een dak) en er staan mogelijke toekomstige investeringen in, zoals bijvoorbeeld zonnepanelen. Wat natuurlijk ook in het plan staat is regelmatig terugkerend onderhoud, zoals het schilderen van kozijnen. Zo’n onderhoudsplan wordt opgesteld door een bouwkundige. Aan de hand van een meting van de conditie van het betreffende gebouw, en de eventuele wensen van gebruikers, bewoners, beheerders of eigenaren, wordt een planning gemaakt voor een bepaald aantal jaren. Dit soort onderhoud wordt conditie gestuurd onderhoud genoemd, dit is een vorm van proactief onderhoud.\n<h2>De voordelen van proactief onderhoud</h2>\nBent u eigenaar of beheerder van een bepaald gebouw? Dan kunt u er natuurlijk voor kiezen om alleen onderhoud te plegen wanneer dit echt nodig is, bijvoorbeeld na een klacht van een bewoner, of wanneer een bepaald deel van het gebouw een defect vertoont. Maar dit heeft veel nadelen, u loopt als het ware achter de feiten aan.\n\nEen proactieve houding als beheerder of eigenaar zorgt ervoor dat u eventuele defecten voor bent, tevens draagt het bij aan de waarde en betrouwbaarheid van uw bedrijf en het gevoel van veiligheid voor bewoners of gebruikers. De actieve houding is de reden waarom dit proactief onderhoud genoemd wordt, een onderdeel daarvan is conditie gestuurd onderhoud.\n<h2>Wat houdt conditie gestuurd onderhoud in?</h2>\nDe conditie van een bepaald object (gebouw) bepaalt wat voor onderhoud er direct, of in de toekomst, uitgevoerd moet worden. Dit is in eenvoudige woorden uitgelegd wat conditie gestuurd onderhoud is. Om deze conditie te bepalen moeten er metingen gedaan worden. De onderdelen van het gebouw die onderhoudsgevoelig zijn worden onderzocht op werking, slijtage en conditie.\n\nUit deze metingen komt een bepaalde conditie van het onderzochte object naar voren. Voldoet deze niet aan de minimale eisen, dan moet er onderhoud gedaan worden aan het object in kwestie.\n\nHet kan zijn dat het resultaat van een onderzoek is dat het object nog in nieuwstaat is, maar het kan ook zo zijn dat het object in zo’n slechte staat verkeerd dat het grote risico’s met zich mee brengt. Er zitten nog 4 mogelijke condities tussen deze uitersten.\n\n<img class=\"size-full wp-image-1635 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/10/conditiegestuurd-onderhoud.jpg\" alt=\"conditie gestuurd onderhoud \" width=\"1000\" height=\"800\" />\n<h2>De conditiemeting</h2>\nOver het algemeen wordt de conditie van een gebouw bepaald door middel van een conditiemeting. Een vastgelegde meet- en registreer methode wordt gebruikt om deze metingen betrouwbaar uit te voeren. Deze meting wordt gedaan door gespecialiseerde inspectiebureaus. Deze stellen de staat vast van het gehele gebouw, elk detail wordt onderzocht op staat en werking. De conditie van het gehele gebouw wordt daarmee een optelsom van al zijn componenten. Dit legt onmiddellijk de tekortkomingen van zo’n algemene conditiemeting vast. Individuele metingen zijn vaak van groter belang dan de algemene staat van het gebouw. De algemene staat van een gebouw kan als goed beoordeeld worden door een conditiemeting, maar dan nog kan bijvoorbeeld de dakgoot veroudering vertonen en binnenkort voor problemen en kosten gaan zorgen.\n\nEen ander soort meting kan u hiervan behoeden, namelijk continue metingen met een Internet of Things toepassing.\n<h2>Conditie gestuurd onderhoud op basis van continue metingen</h2>\nHoe handig zou het zijn wanneer u de conditie van een bepaald object continu kon monitoren? In zo’n geval kunt u conditie gestuurd onderhoud uitvoeren wanneer dit echt nodig is. U voert geen onderhoud uit op basis van voorspellingen, maar op accurate data.\n\nHet zijn altijd bepaalde onderdelen van een gebouw die meer onderhoud vergen dan andere. Misschien is het moeilijk te voorspellen wanneer uitval zal plaatsvinden, maar u wilt ook liever geen onderdelen vervangen die mogelijk nog jaren mee kunnen gaan. Continue metingen geven u niet alleen de mogelijkheid om direct conditie gestuurd onderhoud uit te voeren, maar geeft u ook veel meer informatie over de werking van een bepaald object. Zodoende kunt u een onderhoudsplan samenstellen die veel accurater is, dit kan u direct maar ook in de toekomst kosten besparen.\n<h2>De Thingsway</h2>\nDe Thingsway is een internet of things sensor die de werking van een bepaald object kan meten. Deze werking wordt continu gemonitord, data wordt opgeslagen en kan worden doorgestuurd, nagelezen en geanalyseerd wanneer u dat wilt.\n\nHet grote voordeel van de Thingsway is dat het een basisproduct is die op ieders wens kan worden aangepast, en dit binnen korte tijd. Sensoren houden de conditie van een object constant in de gaten, daarmee zet de Thingsway een nieuwe standaard neer op gebied van conditie gestuurd onderhoud.\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>\n[/et_pb_text][/et_pb_column][/et_pb_row][/et_pb_section]','Conditie gestuurd onderhoud: wat is het? En wat zijn er de voordelen van?','','inherit','closed','closed','','250-revision-v1','','','2022-01-31 09:51:38','2022-01-31 09:51:38','',250,'https://thingsway.media2netdev.nl/?p=420',0,'revision','',0),(421,1,'2022-01-31 09:51:39','2022-01-31 09:51:39','Hoe hoog de kwaliteit ook is van een bepaald product, alles is nu eenmaal aan slijtage onderhevig. Het gevolg van slijtage is dat er defecten kunnen optreden, of dat nu gaat om een machine of om een object. Deze defecten kunnen meestal worden verholpen met een nieuw onderdeel, maar ook dikwijls is een volledige vervanging nodig. Dit heeft kosten als gevolg; kosten voor een nieuw product, maar ook kosten voor het vervangen en onderhoud.\n\nOm enigszins controle te houden op de kosten die slijtage veroorzaken, heeft ieder bedrijf te maken met onderhoud. Uw bedrijf kan dit onderhoud zelf uitvoeren door een technisch team, of u kunt een maintenance bedrijf inhuren om het onderhoud voor u uit te voeren. Onderhoud kan op verschillende manieren worden uitgevoerd; een van die manieren is correctief onderhoud.\n<h2>Wat is correctief onderhoud?</h2>\nEr wordt gesproken van correctief onderhoud wanneer er onderhoud gepleegd wordt na een melding van een probleem door een medewerker of deskundig persoon. Dit kan gaan om een melding van een medewerker die het probleem tijdens het werk constateert, maar het probleem kan natuurlijk ook geconstateerd worden door iemand van de technische dienst. Onderhoud dat gepleegd wordt na een automatische storingsmelding wordt ook correctief onderhoud genoemd.\n\nTijdens correctief onderhoud worden alleen de problemen opgelost die hebben gezorgd voor schade of uitval. Het kan ook gaan om problemen die voor een gevaarlijke situatie zorgen. Dit correctief onderhoud wordt gepleegd door een technisch team van uw eigen bedrijf, of door een externe partij zoals een maintenance bedrijf.\n\nOm een duidelijk beeld te krijgen van wat correctief onderhoud kan inhouden schetsen we hier een aantal voorbeelden:\n<ul>\n 	<li>Een spoedreparatie wordt uitgevoerd, bijvoorbeeld wanneer er een lift is uitgevallen en er mensen in vastzitten.</li>\n 	<li>Er is sprake van service herstel wanneer er een bepaalde service van een bedrijf is uitgevallen, bijvoorbeeld de beeldschermen op een treinstation.</li>\n 	<li>Een reparatie is het meest duidelijke voorbeeld van correctief onderhoud; iets wordt gerepareerd om de functionaliteit te herstellen.</li>\n 	<li>Wanneer een apparaat of proces nog wel werkt, maar niet optimaal, dan wordt de performance herstelt. Dit is vaak een software probleem.</li>\n 	<li>Slijtage kan er tevens voor zorgen dat een apparaat of object nog goed functioneert, maar de kwaliteit van gebruik gaat achteruit. U kunt hierbij denken aan een ongewenste trilling in een machine of apparaat.</li>\n</ul>\n<img class=\"size-full wp-image-1643 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/10/correctief-onderhoud-nadelen-ervan.jpg\" alt=\"correctief onderhoud\" width=\"1000\" height=\"800\" />\n<h2>Wat zijn de nadelen van correctief onderhoud?</h2>\nVeel bedrijven zien de nadelen van correctief onderhoud helaas niet in. Echter kleven er toch heel wat nadelen aan vast, we sommen ze voor u op:\n\nDit zijn de nadelen van correctief onderhoud:\n<h3>Lastiger in te plannen</h3>\nMet correctief onderhoud is alleen gerichte actie vereist op defecten in installaties of machines. Dit werkt reactief en daarom is het moeilijk om de agenda’s te vullen.\n<h3>Ontevreden klanten</h3>\nVeel bedrijven zijn afhankelijk van bepaalde machines of iets dergelijks. Als iets vervolgens niet werkt vanwege een storing dan leidt dat vaak tot erg veel frustratie. Frustratie die voorkomen kan worden wanneer er aan voorspellend onderhoud wordt gedaan.\n<h3>Gemiste omzet</h3>\nEr zijn veel bedrijven die werken met machines op afstand. Deze machines zijn omzetmakers die continue moeten draaien. Het tijdelijk stilstaan van deze machines kost dus platgezegd geld. Iets wat veel ondernemers willen voorkomen!\n\n<img class=\"size-full wp-image-1645 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/10/correctief-onderhoud-plegen.jpg\" alt=\"correctief onderhoud \" width=\"1000\" height=\"800\" />\n<h2>Voordelen correctief onderhoud</h2>\nCorrectief heeft echter ook een paar voordelen. We nemen ze in het kort met je door.\n<h3>Soms de beste oplossing</h3>\nEr zijn bedrijven die veel geld en tijd investeren in een preventieve onderhoudsstrategie. Voor andere bedrijven geldt dat dit meer kosten met zich meebrengt dan correctief onderhoud toepassen wanneer dat nodig is.\n<h3>Op korte termijn lagere kosten</h3>\nTot het moment dat er iets mis gaat heeft u veel minder kosten en zorgen. Zolang alles werkt, heeft u geen onderhoudskosten.\n<h3>Geen ingewikkeld onderhoudsplan nodig</h3>\nPas actie ondernemen wanneer een probleem zich voordoet vereist geen strategisch onderhoudsplan.\n<h2>Van correctief naar voorspellend onderhoud</h2>\nWanneer u correctief onderhoud samenbrengt met een IoT-oplossing, dan combineert u deze voordelen met continue monitoring.\n\nCorrectief onderhoud wordt toegepast na een melding van medewerker, technici of na een automatische storingsmelding. Zo’n automatische storingsmelding wordt gedaan via sensoren, deze registreren een verandering in de omgeving en werking van een proces.\n\nEen IoT-oplossing is een apparaat dat ook werkt met sensoren, maar dan gecombineerd met een internetverbinding. Dit geeft het voordeel dat het gehele proces niet alleen gemonitord wordt door sensoren, maar dat u als bedrijf ook continu inzicht heeft in de werking. Via een computer, smartphone of tablet kunt u de werking in de gaten houden. Dit constante inzicht zorgt ervoor dat slijtage, veranderingen in omgeving of mogelijke defecten vroegtijdig kunnen worden opgespoord.\n<h2>De Thingsway van Salland Electronics</h2>\nKlinkt het voor u aanlokkelijk, zo’n IoT-oplossing? De Thingsway is een IoT-apparaat die toepasbaar is op veel verschillende gebieden. U kunt daarbij denken aan een industriële omgeving, maar ook op het gebied van vastgoed is de Thingsway zeer goed in te zetten. Op dit moment wordt de Thingsway namelijk gebruikt om de werking van dakgoten te monitoren.\n\nDe Thingsway is een basisproduct die aan te passen is zoals u hem wenst; natuurlijk aangepast op het te meten object of apparaat. De Thingsway maakt voorspelbaar correctief onderhoud mogelijk. Een nieuwe term op gebied van onderhoud?\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>','Correctief onderhoud: wat is het? Welke nadelen heeft het?','','inherit','closed','closed','','252-revision-v1','','','2022-01-31 09:51:39','2022-01-31 09:51:39','',252,'https://thingsway.media2netdev.nl/?p=421',0,'revision','',0),(422,1,'2022-01-31 09:51:40','2022-01-31 09:51:40','Het Internet of Things biedt een grote mogelijkheid om zeer waardevolle gegevens vast te leggen van de werking van grote machines. Daardoor kan het IoT een directe impact hebben op het ontwerpen, beheren en onderhouden van industriële machines. De ontwikkeling van het IoT gaat dusdanig snel dat het nu de tijd lijkt te zijn voor bedrijven in de industriële sector om over te stappen naar een nieuw soort industrieel onderhoud. Een onderhoud waar gebruik wordt gemaakt van IoT, sensoren, interessante data en een analytisch systeem.\n\nHet snel ontwikkelende onderhoudssysteem van het Iot vraagt om een nieuw soort onderhoudsstrategie. Een verbeterde onderhoudsstrategie zorgt voor kostenbesparing en meer efficiëntie. Het resultaat op gebied van inkomsten en kosten zal snel te zien zijn.\n<h2>De huidige manier van industrieel onderhoud</h2>\nOm de grote waarde te kunnen tonen van een IoT-oplossing in industrieel onderhoud is het nodig om de huidige manier van industrieel onderhoud te beschrijven.\n\nIn de industriële sector wordt de huidige manier van onderhoud bepaald aan de hand van beperkte gegevens en toegepast op geïsoleerde activa. Dat wil zeggen dat de werking van één bepaalde machine wordt bekeken tijdens een proefdraai. Deze gegevens worden samengevoegd met de gegevens van de fabrikant. Deze gegevens vormen de basis van het onderhoudsplan voor deze bepaalde machine. Periodiek onderhoud zal uitgevoerd worden volgens dit onderhoudsplan.\n\nAls bedrijf bent u dus afhankelijk van handmatige methoden om voorspellend, preventief en periodiek onderhoud te plegen. Deze methode heeft echter een groot nadeel; het is namelijk gebaseerd op beperkte gegevens en de nauwkeurigheid van de voorspelling laat te wensen over. Om de werking van een bepaalde machine, of een geheel productieproces, goed te monitoren zijn veel meer gegevens nodig.\n\n<img class=\"size-full wp-image-1650 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/10/onderhoud-in-de-industrie.jpg\" alt=\"industrieel onderhoud\" width=\"1000\" height=\"800\" />\n<h2>De toekomst van industrieel onderhoud</h2>\nHet Internet of Things (of IoT) biedt de mogelijkheid aan machines en processen om met elkaar te communiceren via het internet, en natuurlijk met u als bedrijf. Al uw medewerkers kunnen constant digitaal de gegevens inzien van alle operationele processen. Dit biedt u als bedrijf grote kansen op gebied van onderhoud en kostenbesparing, maar ook op commercieel gebied en efficiëntie.\n\nU zou u zich nu af kunnen vragen hoe zo’n IoT-oplossing dan werkt? Een IoT-oplossing is een apparaat dat werkt door middel van sensoren. Deze sensoren monitoren de werking van een bepaald proces, of verandering, in de omgeving. Dat kan gaan om allerlei soorten veranderingen zoals warmte, beweging en druk. Treedt zo’n verandering op dan wordt dat door de sensor omgezet in data en via een directe internetverbinding doorgestuurd. Dit kan worden doorgestuurd naar medewerkers ter plekke, maar ook bijvoorbeeld naar een hoofdkantoor. Dit biedt de mogelijkheid om onmiddellijk actie te ondernemen waar nodig, maar ook voor het goed analyseren van alle gegevens.\n\nEen IoT-oplossing kan worden toegepast om de werking van één bepaalde machine te monitoren, maar ook een geheel productieproces kan gemonitord worden. Het grote voordeel van een IoT-oplossing is de enorme hoeveelheid data die u binnenkrijgt. Dit geeft een veel beter beeld van de werkelijke werking van een proces of van alle activa samen. Met deze gegevens kunt u een veel degelijker onderhoudsplan samenstellen. Een ander voordeel van een IoT-oplossing is het continu monitoren van het proces. Eventuele problemen met machines kunnen hierdoor sneller opgespoord worden en uitval voorkomen. Een Iot-oplossing is daarom de toekomst van industrieel onderhoud.\n<h2>De Thingsway</h2>\nEen voorbeeld van een IoT-oplossing is de Thingsway. Dit is een IoT-sensor die ontwikkeld is door Salland Electronics. De Thingsway is een basisproduct die ook heel goed toepasbaar is in de industriële sector. Het apparaat wordt als het ware aangepast op uw wensen en het te meten proces. Die aanpassingen liggen dan op gebied van de behuizing, de benodigde sensoren en de bevestiging. Salland Electronics kan deze aanpassingen snel ten uitvoer brengen. Hierdoor kan uw bedrijf binnen korte tijd een IoT-oplossing in huis hebben.\n\nDe Thingsway werkt op een batterij die gegarandeerd 10 jaar meegaat.\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\n<h2>Industrieel onderhoud en IoT samengevat</h2>\nHet IoT is de mogelijkheid om uw volledige bedrijf van accurate online gegevens te voorzien. Hiermee kunnen managers verbeteringen aanbrengen op gebied van onderhoud, maar ook op gebied van efficiëntie en kostenbesparing.\n\nHet continu monitoren van een proces of machine geeft een veel beter inzicht. Deze gegevens bieden een kans op een veel efficiënter onderhoudsplan. In plaats van het werken met minimale gegevens van activa en handmatig toezicht, heeft het gehele bedrijf constant inzicht via digitale hardware.\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>','De toekomst van industrieel onderhoud','','inherit','closed','closed','','255-revision-v1','','','2022-01-31 09:51:40','2022-01-31 09:51:40','',255,'https://thingsway.media2netdev.nl/?p=422',0,'revision','',0),(423,1,'2022-01-31 09:51:41','2022-01-31 09:51:41','Om het succes van een product op de lange termijn te garanderen, zou een bedrijf zich moeten richten op het optimaliseren van het productieproces. Deze regel gaat op voor elk bedrijf. Voor menig bedrijf geldt echter dat balans vinden tussen kwaliteit en kosten een voortdurende strijd is. Als bedrijf heeft u een aantal wensen; een zo hoog mogelijke vraag, aan deze vraag kunnen voldoen met een hoogwaardig product en het zo laag mogelijk houden van de kosten.\n\nWas dit maar alles waar u mee rekening dient te houden, toch? Want daarnaast heeft u te maken met grondstoffen, leveranciers, loonkosten en winst. Het handhaven van de kosten is niet bepaald makkelijk, maar het is wel de eerste stap op weg naar een optimaal productieproces. Om de kosten van een productieproces te verlagen zijn er een aantal dingen die u kunt doen. We bespreken de belangrijkste.\n<h2>Optimaliseer het productieproces</h2>\nWaar de meeste fabrikanten zich op focussen, is het monitoren van de kosten van een productieproces. In plaats daarvan kunt u het best het gehele proces van productie monitoren. De kosten zijn slechts een deel van het proces. Door het proces als geheel te bekijken kunt u een veel nauwkeuriger beeld krijgen.\n\nEr is veel nodig om een geheel productieproces te monitoren. Vooral het monitoren van apparaten en machines kan nogal een uitdaging zijn. Een IoT-oplossing is zeer geschikt om u daarbij te helpen. Een Internet of Things-oplossing werkt met sensoren en is draadloos aangesloten op het internet. Dit apparaat monitort continu de werking van een proces of machine. Dit geeft u een zeer gedetailleerd beeld van de functie en effectiviteit. De Thingsway is een mooi voorbeeld van zo’n IoT-oplossing. Dit apparaat is op vele manieren in te zetten; in de buitenlucht, maar ook in een industriële omgeving.\n\nHet monitoren en analyseren van uw gehele productieproces geeft u de mogelijkheid om aanpassingen te doen waar nodig is. Misschien op het gebied van kosten, zuiniger gebruik van materiaal of grondstof of efficiëntie van machines. Misschien is het nodig om machines te vervangen of om productie van bepaalde elementen in eigen handen te nemen.\n\nHoe dan ook, om het productieproces te optimaliseren is het nodig om dit gehele proces te monitoren.\n\n<img class=\"size-full wp-image-1655 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/10/productieproces.jpg\" alt=\"productie proces verbeteren\" width=\"1000\" height=\"800\" />\n<h2>Verlaag de kosten van materiaal</h2>\nOm een productieproces te optimaliseren en productiekosten te besparen kunt u eraan werken om de kosten van het materiaal te verlagen. Veel startende bedrijven kiezen voor bepaalde componenten voor hun product, zonder een goed beeld te hebben van de totale kosten.\n\nOm de kosten op materiaal te verlagen kunt u overwegen om bijvoorbeeld het ontwerp te veranderen of naar materialen te zoeken die voordeliger zijn. Zorgt u er echter wel voor dat de nieuwe materialen niet ten koste gaan van de kwaliteit van uw product.\n\nU kunt ook de kosten van materiaal omlaag brengen door te kijken naar efficiëntie van gebruik. Misschien kunt u doen aan recycling van uw product of van materialen die als bijproduct worden weggegooid.\n<h2>Productiviteit van het personeel verbeteren</h2>\nDe personeelsleden die voor u werken zijn onbetaalbaar, maar toch kosten ze u loon. Om een productieproces te optimaliseren en de kosten te verlagen kunt u kijken of u met een kleiner team kunt werken. Misschien is het tijd om verder te automatiseren. Dit mag natuurlijk niet ten koste gaan van de efficiëntie, kwaliteit en nauwkeurigheid.\n\nDaarnaast kunt u de productiviteit van werknemers stimuleren door middel van bonussen en efficiëntere werkschema’s. Maakt u goed gebruik van de capaciteit van het personeel, of kan dat beter?\n\nU kunt ervoor kiezen om de gegevens van een productieproces tijdens het werk via een beeldscherm te tonen. Het blijkt dat dit niet alleen motiverend werkt voor werknemers, maar het zorgt ook voor meer betrokkenheid bij de gehele productie. Daarnaast kan er door werknemers op tijd ingegrepen worden wanneer een proces een defect vertoont. Dit werkt zeer goed voor het optimaliseren van een productieproces.\n\nDit vertonen van accurate informatie wordt gedaan met een Internet of Things-oplossing, zoals de Thingsway.\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\n<h2>Krijg een goed beeld van vraag en aanbod</h2>\nDe kosten van een bedrijf kunnen flink oplopen wanneer het langdurig veel voorraad moet opslaan. Het maakt in zo’n geval niet uit of het om grondstoffen gaat of een compleet product. Als een productieproces geoptimaliseerd is dan wordt overproductie voorkomen. Dit verlaagt alle kosten voor opslag, verzekering en eventueel onderhoud.\n\nZorgt u ervoor dat u produceert op basis van de vraag van de klant. Als u geen nauwkeurig beeld heeft van de vraag dan kan dit overproductie veroorzaken of juist tekorten. Deze tekorten zorgen weer voor extra belasting op machines en personeel. Zorg voor een goede relatie met klanten en leveranciers, hiermee kunt u een duidelijker beeld krijgen van de toekomstige vraag en aanbod. Dat helpt mee met het optimaliseren van een productieproces.\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>','Hoe kunt u een productieproces optimaliseren?','','inherit','closed','closed','','257-revision-v1','','','2022-01-31 09:51:41','2022-01-31 09:51:41','',257,'https://thingsway.media2netdev.nl/?p=423',0,'revision','',0),(424,1,'2022-01-31 09:51:42','2022-01-31 09:51:42','Planmatig onderhoud verwijst naar alle onderhoudsactiviteiten die worden gepland en gedocumenteerd. Het uiteindelijke doel van planmatig onderhoud is om storingen en uitval te verminderen. Dit wordt gedaan door middel van een strategie en met efficiënte middelen, zoals onderdelen en mankracht.\n\nEr bestaan twee types planmatig onderhoud. Het eerste type is planmatig preventief onderhoud. Dit richt zich op het onderhouden van machines en objecten voordat er een defect optreedt. Als voorbeeld kunt u een machine nemen waaraan periodiek onderhoud gedaan wordt na 200 draaiuren.\n\nMaar er bestaat ook een vorm van reactief planmatig onderhoud. Dit klinkt echter tegenstrijdig, want het is gebaseerd op het zo snel mogelijk repareren van iets wanneer het kapot gaat, of wanneer een onderdeel vervangen moet worden. Als voorbeeld kunt u denken aan een boormachine waarvan een kapotte boor vervangen moet worden.\n<h2>Planmatig maintenance</h2>\nDe maintenance taken die worden uitgevoerd volgens planmatig onderhoud vinden plaats voordat een probleem zich kan voordoen. Het doel is om ervoor te zorgen dat activa zo lang mogelijk blijft werken, zonder dat deze uitvalt. De strategie voor planmatig onderhoud is gebaseerd op richtlijnen van fabrikant, tijd, gebruik, toestand en voorspellingen op basis van metingen uit het verleden.\n<h2>De voordelen van planmatig onderhoud</h2>\nEen groot voordeel van planmatig onderhoud is dat u weet wat u kunt verwachten. Door onderhoud te plannen weet u welke middelen u nodig hebt op welk moment. Zo kunt u tijd, mankracht en nodige onderdelen beschikbaar stellen wanneer nodig.\n\nDit stelt u ook in staat om uw agenda goed te beheren. Er bestaat onderhoud die u ver van te voren kunt plannen, zoals bijvoorbeeld een set nieuwe banden op een transportvoertuig. Er zijn echter ook onderhoudstaken die kortere plantijd vereisen, zoals een compressor die na 100 uur vervangen moet worden. Door planmatig onderhoud toe te passen kunt u precies zien welke taken er aan komen. Storingen zullen minder optreden, daardoor zijn er minder middelen nodig.\n\nEen ander voordeel van planmatig onderhoud is dat het zorgt voor meer efficiëntie van het maintenance team of bedrijf. Het team of bedrijf weet precies wat er gedaan moet worden en welke onderdelen er nodig zijn. Dit werk kunnen ze vooraf doen. Hierdoor zal het onderhoud sneller en makkelijker gaan wat de efficiëntie van het hele bedrijf ten goede komt.\n\n<img class=\"size-full wp-image-1660 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/10/voordelen-planmatig-onderhoud.jpg\" alt=\"voordelen planmatig onderhoud \" width=\"1000\" height=\"800\" />\n<h2>Reactief planmatig onderhoud</h2>\nReactief planmatig onderhoud vindt plaats wanneer een onderdeel kapot moet gaan voordat het vervangen wordt. Dit soort onderhoud wordt gedaan bij machines of onderdelen die niet cruciaal zijn voor een productieproces, of te wel onderdelen die eenvoudig te vervangen zijn. Zou u deze preventief vervangen dan verspilt u geld, ze zijn niet duur of essentieel in het proces. In plaats van preventief vervangen heeft een bedrijf deze onderdelen ruim op voorraad en wordt het vervangen wanneer nodig. Denk u hierbij aan meetinstrumenten en boren.\n\nDit wordt nog steeds beschouwd als planmatig onderhoud omdat het gereedschap, de apparaten en onderdelen worden geïnventariseerd. Er bestaat een plan om deze te repareren wanneer nodig en voldoende in voorraad te hebben.\n<h2>Hoe kunt u planmatig onderhoud toepassen?</h2>\nEr bestaat geen standaard aanpak voor het toepassen van planmatig onderhoud. Elk bedrijf is anders en heeft zijn eigen plan nodig. Er bestaan echter een aantal basisstappen die u kunt nemen om een goed planmatig onderhoudsplan toe te passen.\n\nAls eerste kunt u het best een goed overzicht maken van alle onderdelen of machines die onderhoud vereisen. In welke categorie passen deze? Gaat het om kritieke onderdelen voor een productieproces? Hebben ze preventief onderhoud nodig, of is reactief voldoende? Door deze analyse te doen kunt u goed bepalen welke machines, objecten of onderdelen de meeste aandacht nodig hebben.\n\nTechnologie gaat de laatste jaren met sprongen vooruit, ook op gebied van planmatig onderhoud. Als eerste kunt u natuurlijk gebruik maken van vele soorten software die u helpen bij het plannen van onderhoud. Deze software maakt het plannen van onderhoud eenvoudiger, zoals het maken van schema’s, werkorders en rapporten. Een goed planprogramma zorgt ervoor dat een maintenance team of bedrijf snel kan reageren en de juiste onderdelen zijn altijd op voorraad.\n\nEen enorme technologische sprong wordt gemaakt door middel van het Internet of Things. Het IoT kan zeer goed van pas komen bij planmatig onderhoud.\n<h2>Planmatig onderhoud met een IoT-oplossing</h2>\nDie kritieke onderdelen, objecten of machines die uw bedrijf draaiende houden, waarom laat u deze niet continu monitoren op de werking ervan? In plaats van het uitvoeren van planmatig periodiek onderhoud zou u dpas onderhoud kunnen plegen wanneer dit echt nodig is. Bovendien voordat zich problemen voordoen.\n\nDe Thingsway is een IoT- sensor dat een bepaald proces monitort. Veranderingen in het proces worden onmiddellijk waargenomen en gemeld via een directe internetverbinding. Dit stelt u in staat om onderhoud te plegen voordat uitval of een storing zich voordoet.\n\nHet continu monitoren zorgt voor enorm veel gegevens. Door het analyseren van deze gegevens krijgt u een nog beter inzicht in de functionaliteit van objecten of apparaten. Zodoende kunt u nog gerichter en efficiënter planmatig onderhoud uitvoeren.\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>\n&nbsp;','Wat is planmatig onderhoud, en wat zijn de voordelen?','','inherit','closed','closed','','259-revision-v1','','','2022-01-31 09:51:42','2022-01-31 09:51:42','',259,'https://thingsway.media2netdev.nl/?p=424',0,'revision','',0),(425,1,'2022-01-31 09:51:43','2022-01-31 09:51:43','Door het toepassen van voorspellend onderhoud kunnen bedrijven en fabrikanten de werking van machines beoordelen. Ze kunnen ook storingen analyseren en hierdoor inschatten wanneer de volgende storing zou kunnen optreden. Door de werking te analyseren en te voorspellen, kunt u een onderhoud voortaan van tevoren plannen en u kunt uw voorraad beter beheren. Tevens zult u de efficiëntie van uw bedrijf verhogen doordat u minder last heeft van uitval.\n\nOm de werking van machines te beoordelen en om komende storingen voor te zijn is een goede strategie nodig voor een voorspellend onderhoudsprogramma. U heeft hier effectieve middelen voor nodig, zoals sensormetingen en zeer goede kennis van het systeem. U dient rekening te houden met meerdere factoren zoals:\n<ul>\n 	<li>De gedetecteerde bronnen van storingen en hun frequentie. Bij dergelijke bronnen kunt u denken aan belangrijke onderdelen van een machine.</li>\n 	<li>Gebruik van sensoren om processen te meten. Het aantal sensoren, het type, de locatie en hun betrouwbaarheid hebben invloed op het bepalen van algoritmen.</li>\n 	<li>Hoe verschillende storingen zich vertalen naar waarneembare symptomen. Om zo’n oorzaak-gevolg analyse te kunnen doen zijn sensoren nodig en uitgebreide analyse van data.</li>\n 	<li>Kennis van het gehele systeem. Deze kan afkomstig zijn van systeemanalyses en van experts. Wanneer u goede kennis van het systeem heeft, dan bent u op de hoogte van de werking van de machine, zijn maximale bereik en de specifieke aard van metingen en onderhoud.</li>\n 	<li>Het ultieme doel van uw onderhoudsprogramma, zoals herstel van storingen of het bepalen van een onderhoudsschema.</li>\n</ul>\n<img class=\"size-full wp-image-1663 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/10/voordelen-algoritmen-achterhalen.jpg\" alt=\"algoritmen achterhalen\" width=\"1000\" height=\"800\" />\n<h2>Wat algoritmen kunnen betekenen voor voorspellend onderhoud</h2>\nBij een programma voor voorspellend onderhoud wordt gebruik gemaakt van algoritmen. Deze algoritmen helpen om de data te analyseren die zijn gemeten in een bepaald proces van een bedrijf.\n\nOm de werking van een machine te monitoren, en eventuele storingen op te kunnen sporen, wordt een constante diagnose van gegevens uitgevoerd. Dit wordt conditiebewaking genoemd. Door middel van sensoren worden gegevens verzameld zoals temperatuur, druk, spanningen en trillingen.\n\nEen verandering in een proces wordt een conditie-indicator genoemd. Wanneer een verandering optreedt dan zal het algoritme een diagnose uitvoeren door gegevens te vergelijken met andere momenten van storing of defecte condities. Op basis van de huidige en vroegere staat van de machine wordt een voorspelling gedaan wanneer een storing zal optreden. Door het verzamelen van steeds meer data, kunnen betere prognoses worden gedaan en nieuwe waarden voor conditie-indicatoren worden voorspeld. Deze toekomstige waarden worden gebruikt om uit te rekenen hoe lang een machine zal meegaan en wanneer onderhoud vereist is.\n\nAls voorbeeld kunnen we een versnellingsbak nemen. Via constante metingen van trillingen over een bepaalde tijd kunnen voorspellingen worden gedaan met een algoritme. Het algoritme kan de waarden vergelijken met bepaalde drempelwaarden die goede werking van de versnellingsbak garanderen of wanneer er storing zou kunnen optreden.\n\nVoor een voorspellend onderhoudssysteem worden sensoren gebruikt die een proces monitoren. Deze sensoren zorgen voor enorm veel data. Algoritmen en hardware zoals laptops zorgen ervoor dat werknemers en technici deze gegevens kunnen gebruiken om het feitelijke onderhoud uit te voeren.\n<h2>Gegevens verzamelen om algoritmen te bepalen</h2>\nOm algoritmen te kunnen ontwerpen heeft u data nodig. Een bedrijf moet vaak enorm veel data beheren en verwerken. Dat gaat om gegevens van meerdere machines, processen en sensoren. Deze draaien op verschillende momenten en onder andere omstandigheden. Beschikking hebben tot de volgende soorten gegevens is belangrijk:\n<ul>\n 	<li>Real-time data van normale systeembediening</li>\n 	<li>Real-time data van een systeem dat werkt, maar in een defecte staat</li>\n 	<li>Real-time data van storingen (run-to-failure-gegevens)</li>\n</ul>\nU kunt bijvoorbeeld gegevens hebben via een sensor over de werking van het systeem, zoals temperatuur, druk en trillingen. Dergelijke gegevens worden doorgaans opgeslagen als signaaldata. Het kan ook zijn dat u data heeft in tekst zoals gegevens uit onderhoudsrecords. Deze gegevens worden opgeslagen in bestanden en databases.\n\nNa het verzamelen van de gegevens worden deze geanalyseerd. Belangrijk is om de conditie-indicatoren te bepalen van een proces. Van welke functies in het systeem verandert het gedrag op een voorspelbare manier naarmate het systeem achteruitgaat? Elke functie die het verschil uitmaakt tussen een normale werking of een defecte staat is een conditie-indicator.\n<h2>Conditie-indicatoren monitoren via een IoT-oplossing</h2>\nOm de werking van een proces of machine te monitoren worden sensoren gebruikt. Met een IoT-oplossing, zoals De Thingsway van Salland Electronics, kunt u continu laten monitoren op bepaalde conditie-indicatoren. Bovendien worden deze gegevens rechtstreeks naar u toe gestuurd via een rechtstreekse internetverbinding.\n\nDe Thingsway is een basisproduct dat snel toepasbaar is in uw bedrijf. Afhankelijk van de te meten indicator worden de sensoren aangepast. Ook de behuizing kan worden aangepast zodat deze geschikt is voor de omgeving waarin de sensor wordt ingezet.\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>','Algoritmen achterhalen: waarom is dat bij onderhoud van belang?','','inherit','closed','closed','','261-revision-v1','','','2022-01-31 09:51:43','2022-01-31 09:51:43','',261,'https://thingsway.media2netdev.nl/?p=425',0,'revision','',0),(426,1,'2022-01-31 09:51:44','2022-01-31 09:51:44','Conditiemonitoring is een van de meest innovatieve manieren waarop bedrijven in maintenance, maar ook in de productie-industrie, geld kunnen besparen. Conditiemonitoring draait op het principe van voorspellend onderhoud, een proactieve manier om defecte apparatuur te herstellen voordat deze problemen veroorzaken. Defecte machines en kapotte onderdelen kosten bedrijven elk jaar enorm veel geld. Het gaat vaak om hele hoge bedragen, niet alleen waarneembaar in kosten, maar ook in verspilde productiviteit. Dit is erg zonde, vooral omdat het tegenwoordig vermijdbaar is.\n<h2>Conditiemonitoring met een maintenance sensor</h2>\nDe conditie van een object of machine kunt u heel goed laten monitoren door middel van een sensor. Sensoren bestaan in vele types, voor verschillende doeleinden geschikt. Zo bestaan er bijvoorbeeld sensoren die warmte, druk, beweging en luchtvochtigheid meten. Dit zijn slechts enkele voorbeelden, bijna alles kan tegenwoordig gemeten worden met een sensor.\n\nDeze sensoren registreren een verandering in de omgeving. Deze verandering kan een indicator zijn van een komend probleem bij een machine, proces of object. Zo is het bijvoorbeeld in de tuinbouw erg belangrijk hoe hoog de luchtvochtigheid is in een kas, een sensor kan dit meten. In geval van een machine kan het zijn dat de temperatuur van de lagers bepalend is voor de optimale werking. Wordt de temperatuur te hoog, dan registreert de sensor dit en geeft een melding.\n<h2>De mogelijkheden van een maintenance sensor</h2>\nHet Internet-of-Things biedt de mogelijkheid om zo’n melding van een sensor in real-time binnen te krijgen op welke hardware u maar verlangt. Via een directe en draadloze internetverbinding worden gegevens van de sensor gestuurd naar computer, laptop, tablet of smartphone. U kunt onmiddellijk ingrijpen en de storing voor zijn.\n\nEen andere mogelijkheid van een maintenance sensor is het verzamelen van zoveel mogelijk data om de werking van een machine of proces te kunnen optimaliseren. Door het continu monitoren worden enorm veel gegevens verzameld. Door deze aan een analyse te onderwerpen kunnen aanpassingen worden gedaan op gebied van effectiviteit, inzetbaarheid en bezuiniging van grondstoffen.\n<h2>De voordelen van een maintenance sensor</h2>\nWorden de voordelen van een maintenance sensor en conditiemonitoring u al duidelijk? Misschien worden ze nog duidelijker door u redenen te geven waarom voorspellend onderhoud de toekomst is:\n<h3>Lagere onderhoudskosten</h3>\nHet belangrijkste voordeel van conditiemonitoring is de besparing op onderhoudskosten. Hoewel het toepassen van reactief onderhoud goedkoper kan lijken, blijkt het op de lange termijn altijd duurder. Bovendien kunnen defecte machines zorgen voor een rimpeleffect, waardoor andere apparatuur ook defect raakt en verdere schade veroorzaakt. De stilstand van machines wordt vaak veroorzaakt door verborgen interne fouten. Zonder gebruik van een maintenance sensor zijn deze fouten vrijwel onmogelijk op te sporen. Dat is de reden waarom conditiemonitoring een waardevolle investering is voor ieder bedrijf dat waarde hecht aan betrouwbaarheid.\n<h3>Maximale productie</h3>\nMachines die defect zijn en kapotte onderdelen kosten een bedrijf ieder jaar veel uren aan productiviteit. Dit is niet alleen nadelig voor uw winst, het kan ook nadelig zijn voor uw relatie met klanten. Door de conditie van uw machines te bewaken kunt u erop vertrouwen dat u op maximale productiviteit draait. U kunt beter voldoen aan de deadlines van leveringen aan klanten.\n<h3>Levensduur van machines verlengen</h3>\nMachines in de industrie en hoogwaardige onderdelen zijn gemaakt om lang mee te gaan. Het monitoren van de conditie kan zelfs helpen om de levensduur van deze machines en onderdelen te verlengen. Niet alleen zorgt voorspellend onderhoud voor het elimineren van verborgen kosten, ook de gehele productiviteit wordt verhoogd.\n<h3>Prioriteit geven aan onderhoudstaken</h3>\nDoor continu monitoring toe te passen door een maintenance sensor krijgt u real-time gegevens, die bovendien zeer betrouwbaar zijn. Hierdoor kunt u de juiste machines prioriteit geven. Dit kan u helpen om onderhoud juist te plannen, zo bespaart u tijd en geld.\n<h3>Nauwkeurige KPI\'s en analyse</h3>\nEen ander voordeel van zoveel data is dat u analyses kunt toepassen. U kunt uw gehele productieproces analyseren en KPI’s vastleggen. Dit geeft u de kans om weloverwogen beslissingen te nemen, bijvoorbeeld bij het aanschaffen van nieuwe apparatuur of bij het verlengen van contracten.\n<h2>De Thingsway, een maintenance sensor</h2>\nDe Thingsway is een goed voorbeeld van een maintenance sensor. Het grote voordeel van de Thingsway is dat het op vele gebieden in te zetten is, bovendien binnen zeer korte tijd. Salland Electronics heeft de Thingsway ontwikkeld, dit bedrijf uit Zwolle kan u binnen een dag met een geheel IoT-systeem uitrusten. De Thingsway wordt geheel aangepast aan de wensen van uw bedrijf. Ook de internetaansluiting kan door Salland Electronics worden verzorgd. Er kan gebruik gemaakt worden van verschillende grote internetaanbieders.\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>','De mogelijkheden en voordelen van een maintenance sensor','','inherit','closed','closed','','263-revision-v1','','','2022-01-31 09:51:44','2022-01-31 09:51:44','',263,'https://thingsway.media2netdev.nl/?p=426',0,'revision','',0),(427,1,'2022-01-31 09:51:45','2022-01-31 09:51:45','Onze moderne wereld is geobsedeerd geraakt door snelheid. De technologische vooruitgang heeft ervoor gezorgd dat we binnen no-time alles kunnen krijgen wat we maar willen. Producten als smartphones worden op dezelfde dag thuis bezorgd, koffie kunt u bestellen via een app en de bankzaken doen we met onze telefoon. Wachten is een woord dat we bijna niet meer kennen. Dat zorgt ervoor dat we steeds ongeduldiger worden.\n\nSnelheid verwachten we ook als het gaat om het gebruik van digitale middelen. Als we ergens toegang toe willen, dan dient dat snel te gebeuren. Een paar seconden wachten is bijna ondraaglijk geworden. Voor een bedrijf betekent dit dat vertraging zelfs schadelijk kan zijn. In de bedrijfswereld dringt de behoefte aan snelheid razendsnel door. Dat geldt zowel voor bedrijven die zich richten op consumenten, maar ook voor business to business markten. Om aan de vraag te voldoen, en om concurrerend te blijven, is snelheid van up-to-date data essentieel geworden. Maintenance en onderhoud is zo’n branche waarvoor data enorm belangrijk is.\n<h2>Real time data bij inspectieonderhoud</h2>\nDe taak van een onderhoudsbedrijf is om de uptime van activa te verhogen, onverwachte uitval te verminderen en het gebruik van middelen maximaal te benutten. Dit alles het liefst met lage onderhoudskosten. Om aan deze eisen te kunnen voldoen, moeten maintenance bedrijven zoeken naar een effectieve manier van werken. Ze zouden als doel moeten hebben om het juiste werk aan de juiste middelen te doen, dit op precies het juiste moment met het juiste gereedschap.\n\nOm dit doel te kunnen bereiken kan een bedrijf gebruik maken van real-time data bij inspectieonderhoud. Steeds meer onderhoudsbedrijven kiezen voor een slimmere onderhoudsstrategie. De mogelijkheid om onmiddellijk data te verzamelen, analyseren en hierop actie ondernemen, betekent voor bedrijven een enorme stap voorwaarts.\n<h2>Voorbeeld van het belang van data bij inspectieonderhoud</h2>\nAls voorbeeld kunnen we een machine noemen die steeds oververhit raakt bij gebruik. Deze machine begeeft het wanneer de oververhitting plaats vindt. Hierdoor ligt de productie stil, wat natuurlijk kostbaar is. Om de uitval te voorkomen wordt een technicus gestuurd om elke 12 uur de temperatuur van een lager te controleren. Indien nodig wordt deze gerepareerd of vervangen. Ondanks deze inzet raakt de lager nog steeds soms oververhit. Het resultaat blijft daarom ook nog steeds stilstand en oplopende kosten.\n\nWanneer u de beschikking zou hebben over real-time data van de temperatuur van de lager, dan zou u de technicus kunnen sturen voordat het probleem zich voordoet. De storing wordt voorkomen, tijd en kosten worden bespaard. Een onderhoudssysteem die real-time data weergeeft zorgt voor up-to-date gegevens. Deze gegevens kunt u eenvoudig op elk scherm aflezen en constant vernieuwen.\n\nReal-time data zijn essentieel om een gedegen en effectief onderhoudsplan te maken.\n<h2>Het belang van data voor het onderhoudsplan</h2>\nAls planner van een onderhoudsplan wilt u natuurlijk ook voorzien worden van data die echt up-to-date is. Een goed onderhoudsschema maken met oude data of via Excel bestanden van een aantal dagen geleden is niet mogelijk. U loopt hierdoor achter de feiten aan, het levert meer werk op en verwarring bij het onderhoudsteam.\n\nWanneer een geheel onderhoudsteam de beschikbaarheid heeft tot real-time data, dan geeft dit ze de mogelijkheid om proactief in te springen waar nodig. Hierdoor wordt ongeplande downtime voorkomen en het gehele proces geoptimaliseerd.\n<h2>Het Internet of Things en data analyse</h2>\nDe opkomst van het Internet of Things heeft gezorgd voor een enorme technologische vooruitgang. Hierdoor wordt meer data verzameld dan ooit tevoren. Van alle bestaande data op de wereld werd 90% in de laatste jaren verzameld. Om deze data goed te kunnen gebruiken is analyse nodig.\n\nDe data die verkregen wordt komt af van IoT-oplossingen. Dit zijn sensoren die continu een bepaald proces monitoren, bijvoorbeeld die lager in de oververhitte machine. Een voorbeeld van zo’n sensor is de Thingsway. Deze werd ontwikkeld door Salland Electronics en is op veel verschillende manieren in te zetten. Er bestaat een Thingsway voor de industriële sector, maar ook een versie die in de buitenlucht wordt gebruikt. Salland Electronics past de sensor aan op de wensen van de klant, ze doen dit binnen een dag. Via de Thingsway kunt u data voor inspectieonderhoud verkrijgen die uw bedrijf een stap verder kan brengen op gebied van effectiviteit en kostenbesparing.\n\nReal-time data is de sleutel tot de toekomst van onderhoud en maintenance. De data is echter pas nuttig wanneer deze goed geanalyseerd en geïnterpreteerd wordt. Uw doel als onderhoudsbedrijf zou moeten zijn om de data bij inspectieonderhoud automatisch te analyseren en bruikbaar te maken voor technici.\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>','Het belang van data bij inspectieonderhoud','','inherit','closed','closed','','265-revision-v1','','','2022-01-31 09:51:45','2022-01-31 09:51:45','',265,'https://thingsway.media2netdev.nl/?p=427',0,'revision','',0),(428,1,'2022-01-31 09:51:46','2022-01-31 09:51:46','Veel bedrijven hebben dagelijks te maken met onderhoud. Er bestaan verschillende manieren om onderhoud uit te voeren. Eén van die manieren is preventief onderhoud. Het belangrijkste voordeel van preventief onderhoud heeft te maken met betrouwbaarheid. Door een object of machine preventief in goede staat te houden wordt de kans verkleind dat er slijtage, schade of uitval kan optreden. Dit heeft uiteindelijk positieve gevolgen voor de levensduur van apparaten of objecten.\n<h2>Wat is preventief onderhoud?</h2>\nPreventief onderhoud is een maintenance systeem wat populair is bij veel bedrijven. Het is een systeem waarin bepaalde onderhoudstaken worden gepland om machines, objecten en apparatuur in goede staat te houden. Deze taken worden meestal periodiek gepland of op basis van gebruiksuren. Niet alles heeft immers dezelfde intensieve onderhoudstaken nodig; een bepaalde machine kan na 100 uur onderhoud nodig hebben, een ander object heeft maar één keer per jaar inspectie nodig.\n<h2>Hoe wordt preventief onderhoud toegepast?</h2>\nOm een gedegen preventief onderhoudsplan samen te stellen is het van belang om te bepalen wat uw meest belangrijke apparaten, machines of objecten zijn. Bovendien moet u een goed inzicht hebben in het gehele proces; wat heeft echt baat bij een preventief onderhoudsplan?\n\nEr zijn namelijk bedrijven die vrij veel geld verspillen met een preventief onderhoudsplan. Er worden dan onderhoudstaken uitgevoerd die er niet voor zorgen dat uitval voorkomen wordt. Periodiek onderhoud is vaak een onderdeel van preventief onderhoud. Dit wordt gedaan op basis van voorspellingen. Helaas werkt dit niet altijd in de praktijk. Uitval van machines komt, ondanks periodiek onderhoud, nog steeds voor.\n\nEen Internet of Things oplossing kan u hierbij goed van dienst zijn. Met een IoT-oplossing kunt u uw kritieke processen of de belangrijkste machines en objecten continu laten monitoren. Dit werkt via sensoren; deze melden een probleem voordat dit zorgt voor uitval of storing. Zodoende kunt u onmiddellijk preventief onderhoud uit laten voeren.\n\nNa het bepalen van de apparatuur die kritiek zijn in uw productieproces, is het van belang om de vaardigheid te trainen om de onderhoudstaken uit te voeren. U zou kunnen investeren in een voortdurende opleiding, zodat de vereiste onderhoudstaken effectief worden uitgevoerd. Dit geldt zeker wanneer u kiest voor een IoT-oplossing. Het is namelijk een grote innovatieve stap voorwaarts op gebied van preventief onderhoud.\n\nEen gedegen preventief onderhoudsprogramma houdt ook rekening met de efficiënte inzet van technici. Een gehele afdeling van uw bedrijf zal soepeler en efficiënter werken wanneer de reistijd van technici verkort kan worden. Niet alle machines of apparaten draaien continu. Door onderhoud te plegen wanneer deze niet gebruikt worden beperkt u onderbrekingen.\n\nInspecties zijn een belangrijk onderdeel van regulier preventief onderhoud. U dient deze regelmatig uit te voeren voordat onderdelen kapot gaan. Zodoende kunt u problemen voor zijn en uitval voorkomen. Aanbevolen richtlijnen van fabrikanten en gegevens uit het verleden bepalen hierbij de planning voor onderhoud. Een IoT-oplossing, zoals de Thingsway, biedt u de mogelijkheid om een nog beter inzicht te geven in de werking en mogelijke uitval van een machine of object.\n\n<img class=\"size-full wp-image-1582 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/10/onderhoudsmeting.jpg\" alt=\"onderhoudsmeting en onderhoudsmetingen\" width=\"1170\" height=\"500\" />\n<h2>De voordelen van preventief onderhoud</h2>\nDe voordelen van preventief onderhoud zijn:\n<ul>\n 	<li>Minder uitval van apparatuur</li>\n 	<li>Minder onderbrekingen van productieprocessen</li>\n 	<li>Langere levensduur</li>\n 	<li>Verbeterde efficiëntie</li>\n 	<li>Verhoogde veiligheid op de werkvloer</li>\n</ul>\nWanneer u een gedegen preventief onderhoudsplan heeft, dan kan dit ervoor zorgen dat het u kostenbesparingen op gaat leveren. Machines, apparaten of objecten gaan langer mee, ze werken zuiniger en processen worden minder onderbroken. De betrouwbaarheid van apparaten, of de werking van een systeem, wordt verbeterd. Machines en processen kunnen hierdoor ononderbroken door blijven draaien. Door uitval, storingen en stilstand te voorkomen kunt u aanzienlijke kostenbesparingen doen.\n\nOp de lange termijn zal een gedegen preventief onderhoudsplan ervoor zorgen dat de algehele levensduur van uw apparatuur wordt verlengd. Niet alleen dat, ook de waarde van objecten of machines worden verbeterd. Preventief onderhoud zorgt op den duur voor toename van efficiëntie en bovendien veiligheid. Dat geldt zeker wanneer u kiest om het Internet of Things toe te passen in uw preventief onderhoudsplan.\n<h2>Wat kan de Thingsway betekenen in uw preventief onderhoudsplan?</h2>\nDe Thingsway is een IoT-sensor dat ontwikkeld is door Salland Electronics. Deze sensor kan allerlei verschillende soorten processen monitoren. Dat kan gaan om de werking van een apparaat, maar ook van een voorwerp of object.\n\nVeranderingen in het proces worden onmiddellijk waargenomen en via een mobiele internetverbinding doorgestuurd naar computer, laptop of smartphone. Dit stelt u in de mogelijkheid om in het proces in te grijpen wanneer nodig. Door gebruik te maken van een IoT-oplossing in uw preventief onderhoudsplan, kunt u onderhoud plegen wanneer dit werkelijk nodig is. Geen periodiek onderhoud op basis van verwachtingen, maar onderhoud op basis van up-to-date data.\n\nDe Thingsway is een basisproduct dat aanpasbaar is op elk te meten proces. Salland Electronics kan deze aanpassingen snel bewerkstelligen. Het tilt uw preventief onderhoudsplan naar een hoger niveau en zal zorgen voor meer efficiëntie en kostenverlagingen.\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>','Preventief onderhoud: wat is het? En wat zijn er de voordelen van?','','inherit','closed','closed','','267-revision-v1','','','2022-01-31 09:51:46','2022-01-31 09:51:46','',267,'https://thingsway.media2netdev.nl/?p=428',0,'revision','',0),(429,1,'2022-01-31 09:51:47','2022-01-31 09:51:47','Het Internet of Things wordt met de dag populairder. Hoort u de term ook steeds vaker voorbij komen? Wat houdt het eigenlijk in dat IoT? In wezen is het Internet of Things de internetverbinding die gelegd wordt met alledaagse apparaten. Dat klinkt misschien niet indrukwekkend, maar het wordt ook wel gezien als de vierde industriële revolutie.\n\nDe verwarming in uw huis kunt u bedienen met uw smartphone of tablet. Dit kunt u zien als een mooi voorbeeld van het Internet of Things. De ontwikkeling gaat zo snel dat binnen niet zo lange tijd technici de foutmeldingen van machines binnenkrijgen op hun smartwatch, voordat een storing plaatsvindt.\n\nOver de hele wereld staan er al miljarden apparaten aangesloten via het Internet of Things. De groei van de afgelopen jaren komt vanwege de snellere en betrouwbare mobiele netwerken. Om de efficiëntie van een maintenance managementsysteem te verbeteren is het van fundamenteel belang voor een bedrijf om te investeren in het IoT! Monitoring van systemen kan zorgen voor kostenverlaging op gebied van maintenance, en bovendien op gebied van verbruik.\n\nZo kunt u bijvoorbeeld besparen op verlichting, verwarming en ventilatie. Het IoT is echter vooral gericht op het verbeteren van processen van machines en andere activa. Dit kan verbeterd worden door het analyseren van real-time gegevens, automatisering en intelligente besluitvorming.\n<h2>De Thingsway</h2>\nNu kunt u zich afvragen hoe dit IoT dan werkt? Een voorbeeld van een Internet of Things oplossing is de Thingsway. Dit is een apparaat dat is voorzien van bepaalde sensoren. Deze sensoren monitoren een bepaald proces. Dat kan gaan om een machine, of om een object. Veranderingen in het proces die plaatsvinden bij de machine of het object worden geregistreerd, en onmiddellijk doorgestuurd via een draadloze internetverbinding.\n\nDeze gegevens kunnen overal naartoe worden gestuurd, naar het hoofdkantoor, de werkvloer, een computer of smartphone. Deze real-time gegevens stellen u in staat om het maintenance managementsysteem van uw bedrijf naar een hoger plan te tillen. Vraagt u zich af hoe? Hier volgen enkele voorbeelden.\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\n<h2>Beter gebruik van voorspellend onderhoud</h2>\nVoorspellend onderhoud is de voornaamste reden om als bedrijf te investeren in het IoT. In plaats van onderhoud dat gebaseerd is op routine, periodiek onderhoud en het voorkomen van problemen, worden apparaten of objecten continu gemonitord. De IoT-oplossing stelt u op de hoogte wanneer iets vervangen moet worden. Is er een verandering in een omgeving, dan neemt de sensor deze waar en kan een werkorder activeren voordat uitval plaatsvindt of schade ontstaat.\n\nDit werkt effectiviteit in de hand, omdat er alleen onderhoud wordt gedaan wanneer dit echt nodig is. Kosten worden bespaard op gebied van onderdelen en arbeidsuren. Met het Internet of Things neemt voorspellend onderhoud een nieuwe dimensie aan, dat geldt ook voor uw maintenance managementsysteem.\n<h2>Analyse van gegevens in real-time</h2>\nDe Iot technologie zorgt voor meer mogelijkheden om machines met elkaar te laten communiceren. Dit wordt gedaan door middel van data. Wanneer alle machines in een bepaalde fabriek voorzien zijn van sensoren dan levert dit enorm veel data op. Door deze data te analyseren en samen te voegen kan er zeer accuraat voorspellend maintenance management toegepast worden.\n<h2>Zeer nauwkeurige statistieken</h2>\nHet is van groot belang om goed op de hoogte te zijn van de werking, betrouwbaarheid en de prestatie van een object of machine. Hoeveel tijd zit er tussen storingen? Hoe lang duurt het om een machine te repareren? Deze gegevens kunnen automatisch door een IoT-oplossing worden berekend. Eventuele menselijke fouten worden hierdoor vermeden, de gegevens zijn daardoor zeer nauwkeurig.\n<h2>Up-to-date maintenance managementsysteem</h2>\nAls een machine uitvalt, of een object vertoont problemen, dan kunnen deze real-time gegevens worden verzameld en geanalyseerd. Door het systeem kunnen automatisch de opties voor reparatie worden uitgevoerd en naar technici worden gestuurd als werkorder.\n\nDe technicus krijgt alle informatie die nodig is om de machine of het object op de juiste manier te herstellen. Denkt u bij deze informatie aan alle storingsgegevens en omstandigheden op het moment dat de storing zich voordeed. Ook informatie over slijtage, aanbevelingen van de fabrikant en eerdere gegevens van reparaties zijn eenvoudig in te zien door de technicus\n<h2>Een beter inzicht op de nodige voorraad van onderdelen</h2>\nEen maintenance managementsysteem valt of staat bij een effectief voorraadbeheer. Om de uitvaltijd van een machine of object te beperken heeft u genoeg onderdelen nodig. U wilt echter ook niet teveel onderdelen op voorraad hebben. Een magazijn heeft daarom enorm veel baat bij een goed beeld van welke onderdelen werkelijk nodig zijn. Door het continu monitoren van machines en processen, kan na data-analyse een optimale lijst gemaakt worden van de benodigde onderdelen. Hierdoor kunt u kapitaal vrij maken alleen wanneer dit nodig is.\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>','Verbeter uw maintenance management systeem met het Internet of Things','','inherit','closed','closed','','269-revision-v1','','','2022-01-31 09:51:47','2022-01-31 09:51:47','',269,'https://thingsway.media2netdev.nl/?p=429',0,'revision','',0),(430,1,'2022-01-31 09:51:48','2022-01-31 09:51:48','Wanneer we praten over tools voor onderhoudstechniek dan denken we nog steeds vaak aan draadkniptangen, moersleutels en een rateltang. Maar de techniek gaat de laatste jaren met sprongen vooruit. Wanneer het preventieve onderhoudsplan van uw bedrijf niet gebruik maakt van sensoren en IoT-oplossingen, dan wordt het misschien tijd om deze op te nemen in uw plan.\n\nVoor bedrijven die werken in de industriële sector is het van groot belang om defecten en storingen op tijd te herkennen en aan te pakken. De opkomst van het Internet of Things (IoT) heeft gezorgd voor veel meer inzichten op dit gebied.\n\nDoor het gebruik van sensoren en geavanceerde technologieën is het makkelijker om gegevens te analyseren. Deze gegevens kunnen onmiddellijk gebruikt en gedeeld worden. Hierdoor vergroot de effectiviteit van de apparatuur en daarmee de productiviteit van het gehele bedrijf.\n\nDoor moderne tools te gebruiken voor onderhoudstechniek, kunt u bijvoorbeeld automatisch werkorders sturen zonder tussenkomst van een mens.\n<h2>Een Internet of Things-oplossing</h2>\nDe moderne tools voor onderhoudstechniek maken gebruik van sensoren. Deze sensoren houden een bepaald proces in de gaten. Is er verandering in de omgeving, dan zal de sensor dit registreren. Een Internet of Things-oplossing is een combinatie van een bepaalde sensor en een directe internetaansluiting.\n\nDeze aansluiting zorgt ervoor dat de sensor de veranderingen in een proces onmiddellijk kan doorsturen naar computer, laptop, smartphone of tablet. Deze mogelijkheid op gebied van onderhoudstechniek is van groot belang om te concurreren op de huidige markt. Als fabrikant wilt u de werking en efficiëntie van elke machine op de fabrieksvloer garanderen.\n<h2>Voorbeelden van tools voor onderhoudstechniek</h2>\nOm u de mogelijkheden te tonen geven we hier een aantal voorbeelden van innovatieve IoT tools voor onderhoudstechniek. Deze zijn allen gericht op het opsporen, verminderen en voorkomen van storingen in een machine.\n<h2>Conditie monitor</h2>\nEen sensor houdt de conditie van een bepaald apparaat in de gaten. Dat kan gaan om de elektrische spanning in een machine, maar ook om bewaking van de temperatuur. Via een internetverbinding worden gegevens continu gedeeld met werknemers. De manager krijgt zo enorm veel data over de prestaties van een apparaat. Zodoende kunt u preventieve beslissingen nemen door medewerkers onmiddellijk aan te sturen, voordat het apparaat uitvalt. Dit kan zelfs met automatische werkorders.\n<h2>Het monitoren van de temperatuur</h2>\nIn bepaalde omgevingen is het van groot belang om de juiste temperatuur te controleren. Denkt u dan bijvoorbeeld aan de farmaceutische industrie, of bij productie van voedingsmiddelen. Een Iot tool voor onderhoudstechniek maakt het mogelijk voor onderhoudstechnici om via hun smartphone de werking van bepaalde motoren te controleren. De sensor kan waarnemingen doen op gebied van temperatuur, stroom en trillingen. Zodoende kan de werking van een geheel proces in de gaten gehouden worden.\n<h2>Monitoren van doorstroom</h2>\nEen IoT-oplossing kan ook de doorstroom van een bepaald proces monitoren. Denkt u dan bijvoorbeeld aan een toevoerbuis voor brandstof. Door dit te monitoren kunt u niet alleen problemen voor zijn, u kunt ook een zeer goed beeld krijgen van het werkelijke gebruik. Zodoende kunt u niet alleen onderhoudskosten verlagen, maar ook zuiniger gaan produceren.\n\n<img class=\"size-full wp-image-1682 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/10/tools-onderhoudstechniek.jpg\" alt=\"tools onderhoudstechniek\" width=\"1000\" height=\"800\" />\n<h2>Moderne communicatie</h2>\nModerne communicatie zorgt ervoor dat voorspellend onderhoud veel efficiënter kan worden ingezet. Het leven van uw technische afdeling, of van het maintenance bedrijf, wordt veel makkelijker door het gebruik van tablets of smartphones, automatische orders en e-mails.\n\nEen geheel proces kan op afstand bewaakt worden, de data wordt opgeslagen en geanalyseerd. Aan de hand van deze gegevens kan voorspellend onderhoud worden uitgevoerd. Dit is een enorm innovatieve tool op gebied van onderhoudstechniek. Door deze tools te gebruiken over een gehele werkvloer kunt u een enorme stap voorwaarts maken op gebied van efficiëntie en kostenbesparing.\n<h2>De Thingsway</h2>\nUitgaande van bovenstaande tools voor onderhoudstechniek kunt u misschien denken dat u voor ieder afzonderlijk proces een andere IoT-oplossing nodig heeft. Gelukkig bestaat er de Thingsway. Dit is een Internet of Things-sensor ontwikkeld door Salland Electronics. Het grote voordeel van de Thingsway is dat deze snel aan te passen is op het te meten proces.\n\nDe Thingsway is een basisproduct dat aangepast kan worden op uw wensen. Salland Electronics installeert voor u de benodigde sensoren en kan de behuizing aanpassen op de omgeving. De Thingsway werkt op een batterij die gegarandeerd 10 jaar meegaat.\n\nZoekt u een innovatieve tool voor onderhoudstechniek? Een tool die de effectiviteit en productiviteit van uw bedrijf zal vergroten? Dan heeft u met de Thingsway een topproduct gevonden. Ook de internetverbinding wordt door Salland Electronics verzorgd. U kunt kiezen uit meerdere bekende providers.\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>','Innovatieve tools voor onderhoudstechniek','','inherit','closed','closed','','271-revision-v1','','','2022-01-31 09:51:48','2022-01-31 09:51:48','',271,'https://thingsway.media2netdev.nl/?p=430',0,'revision','',0),(431,1,'2022-01-31 09:51:48','2022-01-31 09:51:48','Het hebben van een goede onderhoudsstrategie is voor elk bedrijf van belang, maar voor sommige bedrijven is het van levensbelang. Dat gaat bijvoorbeeld op als u een productiebedrijf heeft of een bedrijf dat aan maintenance doet. De opkomst van het Internet of Things zorgt voor enorme technologische sprongen, ook op gebied van onderhoud. Predictive maintenance door middel van een IoT-oplossing kan uw bedrijf helpen grote stappen voorwaarts te maken op gebied van efficiëntie en kostenverlaging.\n<h2>Wat is predictive maintenance?</h2>\nPredictive maintenance is het onderhoud waarbij de werking van machines of objecten continu wordt gemonitord. Dit wordt gedaan tijdens normaal gebruik en om de kans op problemen te verlagen. Het constant monitoren heeft meerdere doelen. Het eerste doel is om de frequentie van onderhoud te verminderen. Het tweede doel is om onverwachte storingen te verminderen en het laatste doel is om onnodig preventief onderhoud te voorkomen. Dit te samen zorgt voor het verlagen van onderhoudskosten.\n\nBedrijven die werken volgens predictive maintenance meten continu bepaalde condities in de omgeving van een machine of object, zoals warmte of corrosie. De methoden die gebruikt worden tijdens predictive maintenance zijn onder andere akoestische metingen, metingen van trillingen, geluid, beweging en infrarood. Een geautomatiseerd onderhoudssysteem helpt het bedrijf verder om de data van deze metingen om te zetten in een onderhoudsstrategie.\n\nZo kunt u bijvoorbeeld automatisch een email ontvangen of een werkopdracht versturen wanneer een bepaalde grens overschreden wordt.\n\n<img class=\"size-full wp-image-1686 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/10/predictive-maintenance-wat-is.jpg\" alt=\"predictive maintenance\" width=\"1170\" height=\"500\" />\n<h2>Het verschil tussen predictive maintenance en preventief onderhoud</h2>\nPredictive maintenance en preventief onderhoud zijn twee totaal verschillende manieren van onderhoud. Wilt u de beste onderhoudsstrategie voor uw bedrijf? Dan zult u een balans moeten vinden tussen deze twee manieren. Op basis van de verwachte levensduur van een object wordt preventief onderhoud gepland. Bij predictive maintenance wordt gekeken naar de staat van het object.\n\nEen preventief onderhoudsprogramma wordt meestal samengesteld door de aanbevelingen van een fabrikant samen te voegen met de metingen van een technisch team. Regelmatig metingen uitvoeren zorgt ervoor dat u een redelijk beeld heeft hoe lang iets mee gaat, of wanneer het vervangen dient te worden. Predictive maintenance wordt niet gedaan aan de hand van voorspellingen, maar door middel van up-to-date data.\n<h2>Hoe werkt predictive maintenance?</h2>\nPredictive maintenance werkt door continu de werking en conditie van een object te monitoren. In geval van machines wordt dit gedaan terwijl de apparatuur werkt. De dagelijkse werkzaamheden worden tijdens dit monitoren niet verstoord. Het monitoren van het proces zorgt voor gegevens die voor zeer betrouwbare statistieken kunnen zorgen. Aan de hand van deze statistieken wordt onderhoud gepleegd.\n\nWe kunnen als voorbeeld een auto nemen. De olie van een auto wordt vaak standaard om een bepaalde periode ververst. Met predictive maintenance kunt u monsters van de olie verzamelen en pas olie verversen wanneer dit echt nodig is. Predictive maintenance werkt via verschillende tools, zowel hardware als software. Een apparaat doet metingen aan het proces, en de software zorgt ervoor dat de data omgezet kan worden in beleid of actie.\n<h2>Hoe past u predictive maintenance toe in een onderhoudsprogramma?</h2>\nHet maakt niet uit welk proces er gemeten moet worden; de trillingen in een machine, of de doorstroming van een buis. De tools die gebruikt worden in een geautomatiseerd onderhoudssysteem helpen u om nauwkeurige voorspellingen te doen. Het systeem meldt wanneer het object onderhoud of vervanging nodig heeft.\n\nPredictive maintenance kan het best uitgevoerd worden door middel van een Internet of Things-oplossing. Een IoT-oplossing biedt het beste van twee werelden; continue monitoring van een proces en een internetaansluiting. Hierdoor kunnen alle gegevens van de metingen meteen worden doorgestuurd, geanalyseerd en omgezet worden in automatische orders of later in onderhoudsbeleid.\n\nDe metingen worden uitgevoerd door middel van een apparaat met sensoren. Deze bieden u real-time data die u kunt volgen van welke locatie dan ook. Tevens kunnen deze gegevens doorgestuurd worden naar smartphone of tablet. Dit geeft een bedrijf de mogelijkheid om een zeer goed beeld te krijgen van de werking van een machine en eventueel snel te handelen wanneer nodig.\n\nPredictive maintenance met een IoT-oplossing zorgt ervoor dat u onderhoud beter kunt plannen. Ook kunt u uitval verkorten en de reactietijd op storingen en problemen verbeteren.\n<h2>De Thingsway, een IoT-oplossing</h2>\nDe Thingsway is een IoT-sensor die ontwikkeld is door Salland Electronics. Deze IoT-oplossing is zeer goed in te zetten wanneer uw bedrijf aan predictive maintenance wilt doen. Het voordeel van de Thingsway is zijn multifunctionaliteit. Het apparaat is snel aan te passen aan het te meten object. Dit wordt gedaan door de sensoren en de behuizing naar wens aan te passen.\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>','Wat is predictive maintenance, en hoe werkt het?','','inherit','closed','closed','','273-revision-v1','','','2022-01-31 09:51:48','2022-01-31 09:51:48','',273,'https://thingsway.media2netdev.nl/?p=431',0,'revision','',0),(432,1,'2022-01-31 09:51:50','2022-01-31 09:51:50','Ieder bedrijf heeft wel eens last van een storing. Het kan echter voor een flinke kostenpost zorgen wanneer storingen regelmatig optreden. Storingen kunnen niet alleen irritant zijn, ze kunnen de effectiviteit van een bedrijf enorm verstoren. Zou het voor uw bedrijf niet heel fijn zijn wanneer storingen voorkomen kunnen worden, in ieder geval voor een groot deel?\n<h2>Hoe worden storingen meestal voorkomen?</h2>\nOm storingen te voorkomen doet een bedrijf aan onderhoud of het bedrijf besteedt het onderhoud uit aan een externe partij. Dit geldt vooral voor bedrijven die veel te maken hebben met onderhoud, zoals bijvoorbeeld een productiebedrijf dat veel werkt met machines. Het kan ook gaan om bedrijven in vastgoed, zoals een woningcorporatie.\n\nHet soort onderhoud waar de meeste bedrijven aan doen is preventief onderhoud. Een bedrijf zou ook kunnen doen aan reactief onderhoud. Dan wordt onderhoud pas gepleegd wanneer er een melding of klacht binnenkomt. De storing wordt pas op dat moment verholpen. Reactief onderhoud heeft als nadeel dat u regelmatig met storingen te maken zal hebben. U loopt als het ware achter de feiten aan. Bovendien kunt u als bedrijf een deuk oplopen op gebied van betrouwbaarheid en aanzien.\n\nPreventief onderhoud heeft het voordeel dat het storingen voor kan zijn. Aan de hand van aanbevelingen van fabrikanten en historische gegevens van het object kan een onderhoudsplanning worden gemaakt. Er kan een redelijke voorspelling worden gedaan hoe lang iets meegaat, en wanneer er onderhoud gepleegd moet worden om een storing te voorkomen. Om zo’n moment van storing te voorkomen wordt er periodiek onderhoud aan een machine of object uitgevoerd.\n\n<img class=\"size-full wp-image-1690 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/10/storing-voorkomen.jpg\" alt=\"storing en storingen voorkomen\" width=\"1000\" height=\"800\" />\n<h2>Het nadeel van preventief onderhoud om storingen te voorkomen</h2>\nEr zit echter ook een nadeel aan preventief onderhoud. Het is namelijk gebaseerd op voorspellingen en deze voorspellingen zijn gedaan op basis van vrij relevante gegevens. Helaas houden storingen zich niet altijd aan voorspellingen. Storingen komen vooral op onverwachte momenten, soms door factoren die u niet in de hand heeft. Denkt u dan aan veranderingen in de omgeving, bijvoorbeeld weersomstandigheden of door trillingen van een andere machine.\n\nPeriodiek onderhoud kan veel storingen voorkomen wanneer deze volgens een juist plan uitgevoerd wordt. U heeft echter nog steeds te maken met voorspellingen, menselijk handelen en veranderende factoren die u niet in de hand heeft.\n<h2>Storingen voorkomen door predictief onderhoud</h2>\nEen andere manier van onderhoud is predictief onderhoud. Predictief geeft al aan dat het hier ook gaat om onderhoud op basis van voorspellingen, maar deze voorspellingen worden gedaan aan de hand van accurate gegevens die door middel van real-time monitoring verkregen worden.\n\nEen bepaald proces wordt continu gemonitord door middel van een apparaat. Veranderingen in een proces kunnen storingen veroorzaken. Wanneer zo’n verandering optreedt dan geeft het apparaat dit door en kan er onmiddellijk worden ingegrepen. Op zo’n moment wordt er dus onderhoud uitgevoerd, voordat een storing optreedt.\n\nHet apparaat dat dit proces monitort is voorzien van sensoren en een directe internetverbinding. Zo’n apparaat wordt een Internet of Things-oplossing genoemd.\n<h2>Storingen voorkomen door een Internet of Things-oplossing</h2>\nEen Internet of Things-oplossing is dus een apparaat met sensoren in combinatie met een draadloze internetverbinding. Het voordeel van zo’n oplossing is het feit dat deze sensor continu een proces in de gaten houdt en bovendien voor enorm veel gegevens zorgt over de werking van een machine of object. Dit geeft u de mogelijkheid om deze data te analyseren en een nog veel beter beeld te krijgen van het object. Voorspellingen over de werking, of eventuele storingen, kunnen nog exacter worden gedaan.\n\nHet voordeel van de real-time data en de internetverbinding, is dat de gegevens naar iedere locatie kunnen worden gestuurd. U kunt de gegevens naar een computer sturen op het hoofdkantoor, maar ook naar smartphones op de werkvloer. Zo kunnen medewerkers, of een technisch team, snel ingrijpen om een komende storing te voorkomen.\n<h2>De Thingsway</h2>\nEen voorbeeld van een IoT-oplossing is de Thingsway. Dit is een apparaat dat voorzien kan worden met verschillende sensoren. Ieder proces heeft namelijk een ander soort sensor nodig. Sensoren bestaan in veel verschillende soorten, bijvoorbeeld sensoren die warmte, druk, beweging of vocht meten.\n\nSalland Electronics heeft de Thingsway ontwikkeld. Een basisproduct dat snel aan te passen is aan uw wensen. Wilt u de werking van een bepaalde machine meten? De Thingsway bestaat in een industriële versie. Wilt u metingen doen in een buitenlocatie? Dan is ook daar een geschikte Thingsway voor. Aanpassingen worden gedaan aan de behuizing en de benodigde sensoren.\n\nDe Thingsway kan u helpen om storingen te voorkomen. Zodoende kan uw bedrijf stappen maken op gebied van efficiëntie en kostenbesparing.\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>','Storingen voorkomen: hoe doe je dat? En welke mogelijkheden zijn er?','','inherit','closed','closed','','275-revision-v1','','','2022-01-31 09:51:50','2022-01-31 09:51:50','',275,'https://thingsway.media2netdev.nl/?p=432',0,'revision','',0),(433,1,'2022-01-31 09:51:51','2022-01-31 09:51:51','Het verzamelen van informatie is voor elk bedrijf belangrijk. Op de hoogte zijn van zoveel mogelijk cijfers zorgt ervoor dat u een goed inzicht heeft in het functioneren van uw bedrijf. Dat geldt voor alle aspecten van uw bedrijfsplan, bijvoorbeeld op gebied van verbruik, kosten, inkomsten en natuurlijk onderhoud.\n\nVoor elk bedrijf is het tevens van belang om een onderhoudsplan te hebben dat goed bij het bedrijf past. Of het onderhoudsplan van uw bedrijf nu gebaseerd is op correctief onderhoud, of op proactief onderhoud, u heeft gegevens nodig om een strategisch plan te kunnen maken. Deze gegevens ten behoeve van onderhoud noemen we onderhoudsdata.\n<h2>Wat is onderhoudsdata?</h2>\nVoor een gedegen onderhoudssysteem heeft u data nodig waar u in de toekomst werkelijk iets aan heeft. In dit systeem zouden in ieder geval de volgende gegevens over een machine of artikel moeten staan:\n<ul>\n 	<li>Wat is gerepareerd of vervangen?</li>\n 	<li>Welke onderdelen zijn bij de reparatie gebruikt?</li>\n 	<li>Wanneer is het vervangen of gerepareerd?</li>\n 	<li>Wat was de reden van de storing?</li>\n</ul>\nOm met deze gegevens een zinvolle analyse te kunnen uitvoeren heeft u een basis hoeveelheid aanvullende data nodig zoals:\n<ul>\n 	<li>Hoe oud was het artikel tot moment van falen?</li>\n 	<li>Wat voor onderdelen zijn er voor de storing tijdens preventief of voorspellend onderhoud vervangen of verwijderd?</li>\n</ul>\n<img class=\"size-full wp-image-1559 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/10/continue-monitoren.jpg\" alt=\"continue monitoren\" width=\"1170\" height=\"500\" />\n<h2>Wat zijn de mogelijkheden van onderhoudsdata?</h2>\nMet deze data kunt u verschillende soorten analyses uitvoeren zoals:\n<ul>\n 	<li>Weibull: dit is een analyse methode die veel gebruikt wordt. Het is namelijk een relatief eenvoudige methode, maar evengoed veelzijdig. U kunt het gedrag van een machine analyseren waardoor u een beter beeld heeft hoe lang de machine mee gaat.</li>\n 	<li>Een betrouwbaarheidsanalyse. Deze wordt ook wel Crow-AMSAA genoemd. Dit is een methode om de veranderingen en de betrouwbaarheid van een machine te bepalen. De datum wanneer een machine zal uitvallen wordt voorspeld.</li>\n 	<li>Een cumulatief frequentiepolygoon is het bepalen van de fouten in een bepaalde tijd. Dit is een relatief simpele manier om data te kunnen analyseren op aantallen en kosten.</li>\n</ul>\nDoor het analyseren van de onderhoudsdata kunt u een beter inzicht krijgen in de werking, of storingen, van machines of artikelen. Dit kan zorgen voor een goed onderhoudsplan en reductie van kosten. Deze analyses zijn echter gedaan op grond van basis gegevens. Wanneer u nog meer data zou hebben, zou u de mogelijkheid hebben om nog betere analyses te maken. Hiermee zou u een zeer duurzaam en efficiënt onderhoudsplan kunnen maken.\n<h2>Veel en interessante onderhoudsdata via het Internet of Things</h2>\nEen machine, onderdeel of object zou u nog veel meer data kunnen opleveren behalve de basisgegevens van een machine of artikel zoals leeftijd, reden van storing en vervangen onderdelen. Zo zou u bijvoorbeeld de staat, werking en het verbruik continu kunnen laten monitoren. Dit continu monitoren kan worden gedaan met een Internet of Things-oplossing.\n\nEen IoT-oplossing is een apparaat dat werkt op sensoren. Deze sensoren houden de verandering in een bepaalde omgeving in de gaten. Dat kan bijvoorbeeld gaan om druk, beweging of warmte, maar er bestaan nog veel meer veranderingen die sensoren kunnen meten. Wanneer een verandering optreedt in een machine of proces, dan wordt dit door de sensor opgepikt en door middel van een internetverbinding rechtstreeks doorgestuurd in de vorm van data.\n\nAls voorbeeld kunnen we een machine noemen waarbij de doorstroming van een bepaalde buis zeer belangrijk is. Raakt deze buis verstopt, dan valt de machine uit. Onderhoud moet dan gepleegd worden, zoals het vervangen van de buis. Oude onderhoudsdata, die u verkreeg via correctief onderhoud, liet zien dat de buis gemiddeld 6 maanden mee ging.\n\nMet een IoT-oplossing wordt de doorstroming van de buis continu gemonitord. Wanneer de buis na 5 maanden vol raakt dan geeft de sensor dit aan u door. U kunt onderhoud plegen voordat de machine vastloopt en eventueel extra schade oploopt. Loopt de buis na 6 maanden nog steeds prima door? Periodiek onderhoud is dan niet nodig.\n\nDit is een eenvoudig voorbeeld van wat onderhoudsdata via een IoT-oplossing voor u kan betekenen.\n<h2>De ThingsWay</h2>\nDe Thingsway is een IoT-sensor dat uw bedrijf van zulke interessante data kan voorzien. Het is een sensor dat in verschillende gebieden in te zetten is. Er bestaat een industriële versie, voor het vergaren van onderhoudsdata op gebied van machines en productie, maar de basis van de Thingsway is echter een product dat aan te passen is voor veel verschillende doeleinden.\n\nDe Thingsway is aan te passen op gebied van behuizing, sensoren en aansluitingen. Ook voor de internetaansluiting kunt u kiezen voor verschillende aanbieders. Meer onderhoudsdata biedt uw bedrijf de mogelijkheid om optimaal te profiteren, kosten te verlagen en uw bedrijf verder te laten groeien.\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>','Wat is onderhoudsdata? En wat kunt u ermee doen?','','inherit','closed','closed','','277-revision-v1','','','2022-01-31 09:51:51','2022-01-31 09:51:51','',277,'https://thingsway.media2netdev.nl/?p=433',0,'revision','',0),(434,1,'2022-01-31 09:51:52','2022-01-31 09:51:52','De opkomst van het Internet of Things betekent voor bedrijven soms een gedurfde sprong, maar het is een sprong naar een nieuwe industriële revolutie. Deze manier van werken bespaart bedrijven veel menselijke inspanningen en kosten. Bovendien betekent het een enorme sprong in kwaliteit van een procesbesturing. Nog niet zo lang geleden werden fabrieken en bedrijven in de industriële sector gezien als werkplekken waar nog flink gezwoegd werd. Het Internet of Things heeft gezorgd voor meer veiligheid, efficiëntie en stroomlijning in een geheel productieproces.\n\nEen werkvloer waar gezwoegd wordt doet idyllisch aan, misschien is dat de reden waarom nog niet iedereen het IoT wil omarmen. Een IoT-oplossing, zoals bijvoorbeeld de Thingsway van IoT-ontwikkelaar Salland Electronics, kan drastische veranderingen met zich meebrengen. Grote veranderingen zijn altijd spannend, en soms lastig te overtuigen voor een geheel team of werkvloer. Bent u benieuwd wat een IoT-oplossing kan betekenen voor uw procesautomatisering? Misschien kunnen de volgende voorbeelden u van dienst zijn en overtuigen.\n<h2>Wat kunnen IoT-oplossingen betekenen voor procesautomatisering?</h2>\nIn de industriële markt draait veel om intelligente besturing en controle van het productieproces. Een automatisch proces is ten slotte veel makkelijker dan constant een medewerker van de ene machine naar een andere lopende band te sturen. Procesautomatisering via een computer is veel effectiever.\n\nEen stapje verder dan een geautomatiseerd systeem is het IoT. In plaats van een knop omdraaien en vertrouwen in het systeem, monitort een IoT-oplossing het gehele proces continu. Zo krijgt u veel meer informatie over de werking en besturing van een proces of machine.\n<h2>Hoe verschilt dit met bestaande procesautomatiseringssystemen?</h2>\nEr zitten een aantal verschillen tussen traditionele procesautomatisering en een IoT-oplossing zoals:\n<ul>\n 	<li>Het IoT staat los van uw machines, het werkt via onafhankelijke systemen, sensoren en netwerken.</li>\n 	<li>Een IoT-oplossing gaat verder dan de functies van een bepaalde machine en/of de software.</li>\n 	<li>Wanneer u een IoT-oplossing gebruikt in een industrieel automatiseringsproces dan kunt u meerdere werkplekken met elkaar verbinden. Dit zorgt voor meer harmonie.</li>\n</ul>\n<h2>Een IoT-oplossing werkt draadloos</h2>\nEen draadloos met het internet verbonden systeem maakt het gemakkelijker om een procesbesturing te monitoren in een bepaalde omgeving, bijvoorbeeld wanneer deze omgeving gevaarlijk is. Het kan een probleem zijn wanneer een machine of kraan via een systeem met bedrading zou moeten werken. Vooral als dit de bewegingsvrijheid van een apparaat beïnvloed.\n\nDe draadloze technologie van een IoT-oplossing kan heel nuttig zijn om verfijning toe te passen bij procesautomatisering.\n<h2>Procesbesturing via een IoT-oplossing zorgt voor beheersbare groei</h2>\nHet groeien van een bedrijf heeft natuurlijk voordelen, maar het kan ook nadelen hebben. Zaken doen op hoger niveau zorgt voor extra risico’s, zoals bijvoorbeeld meer verspilling. Het Internet of Things is heel populair bij industrieel automatiseringsexperts, want het zorgt ervoor dat de juiste koers gevaren kan worden. Het continu monitoren zorgt voor enorm veel waardevolle data, waardoor er veel effectiever geproduceerd kan worden. Een vervangend onderdeel is bijvoorbeeld veel eerder bij een machine wanneer een IoT-oplossing een eventueel euvel herkend. Continu monitoren van verbruik geeft u de mogelijkheid om spaarzamer om te gaan met middelen.\n<h2>Een betere procesautomatisering door realtime communicatie</h2>\nEen IoT-oplossing zoals de Thingsway staat constant in contact met het internet. Via sensoren wordt een proces of een machine gemonitord. Deze data kan worden opgeslagen, maar ook direct worden ingezien. Dit kan ter plekke, maar ook op afstand via computer, tablet of smartphone. Dit zorgt voor kortere lijnen binnen een bedrijf. Een medewerker kan op de werkvloer gegevens inzien, maar ook een manager op afstand. Kortere lijnen betekenen minder vertraging.\n<h2>Snellere opsporing van fouten en benodigd onderhoud</h2>\nVerschillende bedrijven gebruiken verschillende manieren van onderhoud. Maintenance of onderhoud is een groot onderdeel van uw dagelijkse werkzaamheden. Doet u aan periodiek onderhoud? Dan bent u overgeleverd aan voorspellingen en een onderhoudsschema. Door middel van een IoT-oplossing kunt u onderhoud plegen, of laten plegen, wanneer dit echt nodig is. Een sensor kan een bepaald proces continu monitoren waardoor eventueel uitval van een machine of vastlopen van een proces snel opgespoord kan worden.\n\nNiet alleen kosten voor onderhoud kunnen zo verminderd worden, de werking van een machine kan veel beter geanalyseerd worden. Dit geeft betere inzichten en zorgt voor meer efficiëntie.\n\nBent u overtuigd van de voordelen die een Internet of Things-oplossing u kan bieden? Kijkt u dan eens naar de mogelijkheden van de Thingsway op gebied van procesautomatisering en procesbesturing.\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>','Procesautomatisering en procesbesturing verbeteren en optimaliseren','','inherit','closed','closed','','278-revision-v1','','','2022-01-31 09:51:52','2022-01-31 09:51:52','',278,'https://thingsway.media2netdev.nl/?p=434',0,'revision','',0),(435,1,'2022-01-31 09:51:53','2022-01-31 09:51:53','Sensoren zijn overal terug te vinden; in ons huis, in winkels, ziekenhuizen en op ons werk. Ze zitten in computers en smartphones en zijn een belangrijk onderdeel van Internet of Things- oplossingen. Sensoren bestaan al zeer lange tijd; zo bestaan infrarood sensoren namelijk al sinds het eind van de jaren 40 van de vorige eeuw. Een sensor die veel in ons huis gebruikt wordt kennen we sinds het eind van de jaren 80, de thermostaat. Deze sensor doet constante temperatuurmetingen en we merken er niets van, behalve een aangenaam warm huis. Dit toont aan hoe groot de waarde van sensoren kan zijn op de kwaliteit van ons leven. Sinds de opkomst van het Internet of Things is het gebruik van sensoren enorm gestegen.\n<h2>Wat doen sensoren?</h2>\nSensoren zijn apparaten die detecteren of er een verandering in de omgeving optreedt. Als deze verandering aanwezig is dan reageert de sensor hierop. De input die sensoren krijgen kunnen van verschillende bronnen afkomstig zijn zoals licht, beweging, druk en temperatuur. Wanneer deze sensoren op een netwerk zijn aangesloten, zoals bij een IoT-oplossing, dan kunnen de sensoren waardevolle informatie leveren aan aangesloten apparaten en een systeem die het beheert.\n\nVoor hedendaagse bedrijven zijn sensoren tegenwoordig cruciaal. Een sensor meldt een verandering in een proces. Deze informatie kan voortijdig problemen voorkomen. Hierdoor kunnen bedrijven aan zeer betrouwbaar voorspellend onderhoud doen. Dit voorkomt uitval, stilstand, hoge werkdruk en zorgt voor het verlagen van kosten. Een ander voordeel van een IoT-oplossing met sensoren is dat de gegevens geanalyseerd kunnen worden op trends. Hierdoor kunnen managers of eigenaren een goed inzicht krijgen en betere beslissingen nemen die op feiten gebaseerd zijn. IoT-sensoren zijn daarom heel belangrijk geworden om de efficiëntie te vergroten. Bovendien vergroten ze de veiligheid op de werkvloer.\n\nEr bestaan sensoren in veel verschillende soorten en maten. Sommige worden speciaal aangepast voor het betrokken bedrijf. De sensor bevat dan ingebouwde sensoren die een bepaald proces meten. Een voorbeeld van zo’n IoT-sensor is de Thingsway.\n<h2>De Thingsway</h2>\nDe Thingsway is een IoT-sensor die ingezet kan worden om veel verschillende processen te monitoren. Het product is heel snel aan te passen, daarmee is het een zeer flexibel product. De aanpassingen kunnen gedaan worden op gebied van behuizing en sensoren. Ieder proces vraagt namelijk om een ander soort sensor. De Thingsway is een IoT-oplossing voor bedrijven voor wie onderhoud en maintenance belangrijk is, zoals bijvoorbeeld woningcorporaties. Maar het is ook zeer goed in te zetten in de industriële sector. Temperatuurmetingen zijn namelijk erg belangrijk in de industriële sector, zo’n soort meting kan heel goed uitgevoerd worden door de Thingsway.\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\n\n&nbsp;\n<h2>Temperatuurmetingen</h2>\nHet is begrijpelijk om aan te nemen dat temperatuursensoren worden gebruikt om de temperatuur van een object of omgeving te meten. Het ligt echter wat genuanceerder dan dat. Temperatuursensoren controleren namelijk of een proces binnen een bepaald kader plaatsvindt. Om een proces of systeem goed te laten functioneren is vaak een bepaalde temperatuur nodig. De temperatuurmeting van de sensoren is daarom een soort preventieve toepassing die vooraf kan bepalen of er storing of zelfs gevaar gaat optreden.\n\nDe hoeveelheid warmte in een object wordt gemeten door een temperatuursensor. Veranderingen in de temperatuur worden gedetecteerd, omgezet in data en in geval van een IoT-oplossing via een internetverbinding verstuurd.\n\nDit is bijvoorbeeld bij het gebruik van machines van groot belang. Deze vereisen vaak dat de temperatuur van het apparaat, maar ook van de omgeving, op een standaard niveau ligt. Ook in de landbouw is het belangrijk om temperatuurmetingen uit te voeren. Zo zijn er nog enkele andere sectoren waarvoor een sensor die de temperatuur meet van groot belang is.\n<h2>In welke sectoren zijn temperatuurmetingen belangrijk?</h2>\nTemperatuurmetingen door middel van sensoren wordt in veel sectoren uitgevoerd. Deze sensoren leveren informatie aan een systeem, waardoor de temperatuur van een object, of een omgeving, constant en nauwkeurig kan worden bepaald.\n\nSectoren voor wie dit van groot belang is zijn bijvoorbeeld de eerder genoemde productie-industrie en de landbouw. U kunt zich voorstellen dat bepaalde gewassen het best groeien op een standaard temperatuur. Andere sectoren zijn de farmaceutische- en chemische industrie, en natuurlijk de voedingsmiddelenindustrie. Bij temperatuurmetingen moeten we namelijk niet alleen denken aan warmte en oververhitting, maar natuurlijk ook aan koeling.\n\nTemperatuurmetingen via een IoT-oplossing zoals de Thingsway, bieden de zekerheid die deze industrieën nodig hebben. Nauwkeurige en continue metingen zorgen voor veiligheid, betrouwbaarheid en efficiëntie van het gehele proces.\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>','Temperatuurmetingen met een IoT-oplossing','','inherit','closed','closed','','280-revision-v1','','','2022-01-31 09:51:53','2022-01-31 09:51:53','',280,'https://thingsway.media2netdev.nl/?p=435',0,'revision','',0);
INSERT INTO `gxdQbZ_posts` VALUES (436,1,'2022-01-31 09:51:55','2022-01-31 09:51:55','Heeft u ook een tekort aan onderhoudspersoneel? Het tekort aan technisch personeel is een probleem dat niet nieuw is en voor veel bedrijven niet gemakkelijk op te lossen. In de afgelopen jaren hebben verschillende factoren bijgedragen aan dit groeiende probleem. Het goede nieuws is dat er oplossingen bestaan. Een groot probleem kan bijna nooit in een dag worden opgelost, maar een IoT-oplossing kan u al een heel stuk verder brengen.\n<h2>Waardoor is het tekort aan onderhoudspersoneel ontstaan?</h2>\nEr zijn verschillende redenen waarom er in de huidige industrie een tekort aan onderhoudspersoneel is:\n<h2>Meer gepensioneerden dan nieuwe instroom</h2>\nEen belangrijke reden voor het tekort aan onderhoudspersoneel is dat er meer ervaren ouderen met pensioen gaan dan dat er startende werknemers instromen.\nDoor de razendsnelle technologische ontwikkelingen is het nodig om talloze nieuwe functies voor onderhoudstechnici te vervullen. De geavanceerde technologie maakt machines en processen complexer en vereist andere vaardigheden. Dit creëert op zijn beurt de behoefte aan meer specialisatie, waardoor er meer nieuwe vacatures nodig zijn.\n<h2>Studeren gepromoot boven beroepsonderwijs</h2>\nMet de handen werken werd jarenlang niet bepaald gepromoot. Nee, iemand kon maar het best zo lang mogelijk blijven studeren, liefst aan een universiteit of hbo. Het beroepsonderwijs heeft daaronder geleden, de studenten bleven veelal weg. Deze focus heeft geleid tot een vaardigheidskloof tussen generaties, dit betekent dat er veel minder twintigers zijn die de juiste vaardigheden hebben om een technische functie uit te kunnen oefenen.\n<h2>Afnemende belangstelling</h2>\nVeel bedrijven noemen een gebrek aan interesse de grootste reden van het tekort aan technisch personeel. De technische beroepen stonden lang bekend als minder lucratief waardoor de belangstelling aanzienlijk afnam. In deze bedrijfstakken liggen de lonen vaak lager dan in andere takken, daarom wordt het moeilijker om werknemers met het juiste niveau aan te trekken.\n\nEen verouderde en inefficiënte werkomgeving is een andere factor die bijdraagt aan de afnemende belangstelling. Sommige bedrijven werken nog steeds met verouderde methodes en rommelige werkplekken. Nieuwe werknemers voelen zich vaak niet thuis in zo’n omgeving.\n<h2>Oplossingen voor een tekort aan onderhoudspersoneel</h2>\nHet probleem van het tekort aan technisch onderhoudspersoneel is complex. Toch zijn er oplossingen die uw bedrijf kunnen helpen:\n<h2>Investeer in technische training</h2>\nEen belangrijke oplossing waar elk bedrijf gebruik van zou moeten maken is technische training. De technologie gaat continu vooruit, ook op gebied van onderhoud. Een onderhoudsprogramma zou gemoderniseerd kunnen worden door middel van betere software en de inzet van het Internet of Things. Het is daarbij cruciaal om uw onderhoudsteam te trainen en informeren zodat de efficiëntie van hun inzet vergroot wordt.\n\nNieuwkomers op de arbeidsmarkt komen vers van een technische opleiding, ze zullen daarom eerder kiezen voor een bedrijf met een modern onderhoudsprogramma.\n<h2>Investeer in een IoT-oplossing</h2>\nHet Internet of Things zorgt voor een nieuwe industriële revolutie. Steeds meer objecten en machines worden voorzien van sensoren en een internetverbinding. Het voordeel hiervan is dat u als bedrijf continue geïnformeerd wordt over de werking van een proces of apparaat. Kunt u zich voorstellen hoe handig dit kan zijn op gebied van onderhoud?\n\nAls voorbeeld kunnen we een machine nemen dat zeer belangrijk is in uw productieproces. Er wordt daarom regelmatig onderhoud uitgevoerd aan de machine, preventief en bij uitval. Als u de machine voorziet van een sensor dat vitale delen monitort dan bent u eventuele problemen voor, bovendien is er minder periodiek onderhoud nodig. Onderhoud hoeft dan alleen uitgevoerd te worden wanneer de sensor een probleem oppikt en aan u communiceert via de internetverbinding. Dit scheelt vanzelfsprekend veel tijd en inzet van onderhoudspersoneel.\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\n<h2>De Thingsway van Salland Electronics</h2>\nDe Thingsway is een Iot-sensor dat ontwikkeld is door Salland Electronics. Het grote voordeel van de Thingsway is dat deze enorm snel in te zetten is in uw bedrijf. Heeft u een tekort aan onderhoudspersoneel? Morgen kunt u al een IoT-oplossing in handen hebben dat een proces of machine continu monitort. Op die manier kunt u veel efficiënter gebruik maken van uw technische personeel.\n\nDe Thingsway is bijna in alle sectoren in te zetten, niet alleen de productie-industrie, maar ook bijvoorbeeld ook in de vastgoedsector. De sensor is een basisproduct dat snel aangepast kan worden op de wensen van uw bedrijf. Ook de internetverbinding wordt verzorgd door Salland Electronics.\n\nHet Internet of Things is één van de manieren om het tekort aan onderhoudspersoneel op te lossen.\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>','Te kort onderhoudspersoneel: hoe op te lossen?','','inherit','closed','closed','','282-revision-v1','','','2022-01-31 09:51:55','2022-01-31 09:51:55','',282,'https://thingsway.media2netdev.nl/?p=436',0,'revision','',0),(437,1,'2022-01-31 09:51:56','2022-01-31 09:51:56','Uitval en stilstand van een machinepark kost bedrijven enorm veel inkomsten. Om dit te voorkomen doen de meeste bedrijven aan preventief onderhoud. Het vermindert namelijk aanzienlijk gepland en ongepland onderhoud. Behalve preventief onderhoud kunt u als bedrijf nog meer doen om uitval van machines te voorkomen.\n<h2>Wat is uitval?</h2>\nUitval of stilstand is elke ongeplande gebeurtenis die de productie voor een bepaalde tijd stopt. Ongeplande stilstand wordt meestal veroorzaakt door menselijke fouten, slecht onderhoud, hardware- of softwarefouten en andere oorzaken zoals slechte prestaties of langzame omschakeling.\n<h2>Tips om uitval van een machinepark te verlagen</h2>\nBent u opzoek naar tips en aandachtspunten om uitval van uw machinepark te verlagen? Onderstaand nemen we tips met u door\n<h2>Voer een risico analyse uit</h2>\nEen risico analyse is de snelste en meest effectieve manier om uitval in de toekomst te verminderen. De veroudering van machines vormt een groot risico in een productieproces. Ondanks dat veel bedrijven moderniseren, wordt er ook nog vaak gebruik gemaakt van apparatuur dat 15 tot 20 jaar oud is. Vaak gaat het dan om verouderde systemen die niet langer door fabrikanten worden ondersteund. Het gevolg is dan dat onderdelen niet beschikbaar meer zijn, of in het buitenland besteld moet worden, wat soms wekenlang kan duren. Een onderdeel dat snel vervangen kan worden betekent het verschil tussen een paar uur stilstand of een paar maanden lang.\n\nVeiligheid en kwaliteit zijn andere risico\'s die van invloed zijn op uw machinepark. Een risico analyse zal problemen en oplossingen aan het licht brengen, zodat u beter voorbereid bent wanneer uitval zich voordoet.\n<h2>Bereken de kosten van uitval</h2>\nEen van de grootste fouten die gemaakt worden bij uitval of stilstand is het niet berekenen van de werkelijke kosten. De echte kosten omvatten verlies van productiviteit van medewerkers, verlies van productie, de besteedde manuren om het probleem te verhelpen, de bijkomende kosten om de machines te repareren en de tijd die u heeft besteed om klanten tevreden te stellen en uw reputatie te verzekeren.\n\nUitval en stilstand moet altijd in geld worden berekend. Het is van vitaal belang omdat de ware kosten u helpen om te focussen op de preventie van toekomstig uitval.\n<h2>Maak gebruik van voorspellend onderhoud</h2>\nDe wereld wordt steeds meer door data gedreven. Ook in de productie industrie maken fabrikanten gebruik van sensoren om uitval op de werkvloer te detecteren, voorkomen en verminderen. Sensoren kunnen veranderingen in een bepaalde ruimte of proces detecteren zoals trillingen, temperatuur, hitte en licht. Dit zijn veranderingen die schade of storing aan een machine kunnen veroorzaken. De sensoren sturen deze gegevens door naar bepaalde hardware, zoals een laptop of smartphone. Zodoende worden managers gewaarschuwd als er iets mis is. Operators van de machine, of een technisch team kan worden aangespoord om de omstandigheden te wijzigen. Dit voorkomt schade en uitval voordat het daadwerkelijk plaatsvindt.\n\nSensoren, zoals bijvoorbeeld de Thingsway van Salland Electronics zijn relatief voordelig. De Thingsway heeft een lange batterijduur en kan gemakkelijk aan elke machine worden bevestigd. Daarom is het zeker een kleine investering waard.\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\n<h2>Maak gebruik van software en data</h2>\nHet is logisch dat software van grote invloed kan zijn op uw inzicht van en controle over een productieproces. Veel bedrijven maken nog steeds gebruik van handmatige methoden om gegevens te verzamelen. Of ze maken gebruik van software dat ongeschikt is voor de taak.\n\nHet is van belang om uw huidige systeem van data verzameling te evalueren. Krijgt u de juiste en relevante informatie? De gegevens zouden de grootste oorzaken moeten aangeven van de uitval. Een geschreven rapport waarin staat dat machine 23 uitviel en twee uur stilstond is geen relevante informatie. Real-time operationele gegevens zijn relevant!\n\nDeze gegevens kunt u verkrijgen door een IoT-systeem in uw bedrijf te laten integreren. Een systeem dat data verzamelt van uw gehele machinepark. Hierdoor kan de fabrikant van een machine exact bepalen wanneer een machine uitvalt. Dit kan vergeleken worden met andere processen in de fabriek om een verband vast te stellen.\n<h2>Zorg dat uw technische onderhoudsteam up-to-date is</h2>\nDe snelle technologische ontwikkelingen zorgen ook op gebied van onderhoud ook voor veel veranderingen. De kans is groot dat u machines gebruikt van verschillende fabrikanten. Het is daarom van groot belang dat uw technische personeel constant getraind wordt en up-to-date blijft.\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>','Uitval machine park verlagen: tips en aandachtspunten','','inherit','closed','closed','','284-revision-v1','','','2022-01-31 09:51:56','2022-01-31 09:51:56','',284,'https://thingsway.media2netdev.nl/?p=437',0,'revision','',0),(438,1,'2022-01-31 09:51:57','2022-01-31 09:51:57','Preventief onderhoud van apparatuur is cruciaal om de levensduur van kritische machines te verlengen en de efficiëntie van installaties te maximaliseren. De installaties en machines stellen een bedrijf niet alleen in staat om op grote schaal te produceren, maar ze bepalen ook de winst wanneer dit efficiënt gebeurt. Een machine die uitvalt kan rampzalig zijn voor een bedrijf, omdat dit leidt tot stilstand en hoge kosten. Onderhoud van machines en installaties is daarom van groot belang, maar onderhoud brengt ook kosten met zich mee. Hoe kunt u installaties en machines efficiënt onderhouden? We geven een aantal tips:\n<h2>Voorspellend onderhoud door middel van een sensor</h2>\nDoor de snelheid van slijtage of veroudering te bewaken kan worden bepaald of er reparaties en vervangingen nodig zijn. Om dit te bepalen werd er in het verleden vaak gebruik gemaakt van een periodiek inspectieschema. Daarbij werden vitale delen om de zoveel tijd geïnspecteerd, denk dan aan riemen, kettingen, tandwielen en vloeistoffen.\n\nBedrijven kiezen er steeds vaker voor om vitale delen te laten bewaken door sensoren. Deze houden het proces continu in de gaten waardoor een periodiek inspectieschema niet meer nodig is.\n\n<img class=\"size-full wp-image-1565 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/10/Tools-continue-monitoren.jpg\" alt=\"toosl continue monitoren\" width=\"1170\" height=\"500\" />\n<h2>Houd de procesapparatuur schoon</h2>\nInstallaties en machines bevatten verschillende filters en afdichtingen om werkende componenten schoon te houden. Vervuiling, zoals vetophoping, kan leiden tot een plotselinge storingen en uitval. Water is bovendien een belangrijke bron van vervuiling en corrosie. Om apparaten optimaal te laten presteren moeten daarom afdichtingen en filters regelmatig worden geïnspecteerd.\n\nU kunt dit doen via periodiek onderhoud, maar u kunt er ook voor kiezen om bepaalde filters of afdichtingen continu te laten monitoren met een sensor.\n<h2>Smeer apparatuur regelmatig om de efficiëntie te garanderen</h2>\nSmering speelt een grote rol bij het handhaven van de prestaties van apparatuur. Het zorgt ervoor dat alle bewegende delen soepel blijven werken. Wrijving tussen bewegende delen wordt verminderd door smering, daarom verbetert het de efficiëntie van uw machines en verlengt het de levensduur. Maak gebruik van het juiste smeermiddel, volg daarbij de aanbevelingen van de fabrikant.\n\nOm op het juiste moment te smeren moet al het apparatuur bewaakt worden. U kunt dit laten doen door periodieke inspectie, maar ook door middel van een sensor.\n<h2>Zorg voor een efficiënt onderhoudsschema</h2>\nOm uw machines en installaties in topconditie te houden is onderhoud nu eenmaal nodig. Een efficiënt onderhoudsschema zorgt ervoor dat alle inspecties, reparaties en vervangingen exact op het juiste tijdstip gedaan worden. Natuurlijk het liefst voordat er uitval plaatsvindt.\n\nEen efficiënt onderhoudsschema is een combinatie van reactief en proactief onderhoud. Reactief onderhoud kunt u toepassen op onderdelen die relatief goedkoop zijn en makkelijk te vervangen. Dit gaat om niet vitale onderdelen, wanneer deze stuk gaan dan ligt niet het gehele proces stil.\n\nEr bestaan verschillende vormen van proactief onderhoud waaronder periodiek onderhoud en conditie gestuurd onderhoud. Periodiek onderhoud kunt u het best uit laten voeren op onderdelen waarvan u een goed beeld heeft van de werking en slijtage. De efficiëntie van uw onderhoud kunt u vergroten door middel van conditie gestuurd onderhoud. Daarbij laat u vitale delen monitoren door middel van sensoren. Deze registreren veranderingen in een proces en maken daar melding van zodat u exact op het juiste moment onderhoud kunt laten uitvoeren.\n<h2>Bewaar apparatuur veilig wanneer deze niet in gebruik is</h2>\nWanneer uw machines niet in gebruik zijn, of uw installaties staan een tijd stil, sla deze dan op in een schone omgeving. Dit voorkomt dat ze door vuil of corrosie worden aangetast. Laat apparaten tevens niet lang stilstaan, rust roest. Laat de apparaten daarom regelmatig draaien.\n<h2>Maak gebruik van het Internet of Things</h2>\nIn onze tips werd regelmatig het gebruik van sensoren genoemd. Deze sensoren kunnen u helpen om de efficiëntie van uw onderhoudsprogramma te vergroten. Dat doen ze door continu een proces te monitoren. De sensoren registreren een verandering in een omgeving dat kritiek kan zijn voor het hele proces. Via een directe internetverbinding meldt de sensor dit op een centraal punt, denk dan aan een computer of smartphone. Op dat moment kunt u ingrijpen en een storing of uitval voor zijn.\n\nDe Thingsway is een voorbeeld van zo’n IoT-sensor. Het is een prachtig product dat uw bedrijf kan helpen in het efficiënt onderhouden van uw installaties en machines.\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>','Hoe kan ik mijn installaties en machines efficiënt onderhouden?','','inherit','closed','closed','','286-revision-v1','','','2022-01-31 09:51:57','2022-01-31 09:51:57','',286,'https://thingsway.media2netdev.nl/?p=438',0,'revision','',0),(439,1,'2022-01-31 09:51:58','2022-01-31 09:51:58','Eén van de oudste bedrijfstakken in de wereld is verzekeringen. Het idee van het delen van risico’s begon 5000 jaar geleden toen Chinese kooplieden hun vracht over meerdere schepen verdeelden. Natuurlijk bleven er risico’s, maar de kooplieden hadden de verzekering dat hun voorraad niet volledig ten onder zou gaan als een schip zou zinken. Het vervoeren van goederen over zee gebeurt nog steeds en de methode van verzekeren is ook lange tijd niet veel veranderd. De opkomst van het Internet of Things zorgt echter ook in de verzekeringswereld voor een transformatie. Heeft u een bedrijf dat veel te maken heeft met onderhoud? Dan kunt u het best gebruik maken van het IoT om onderhoudsdata vast te leggen.\n<h2>Waar wordt onderhoudsdata voor gebruikt?</h2>\nGegevens die verzameld worden tijdens onderhoud worden over het algemeen gebruikt om de werking van een object of machine te waarborgen. Door het analyseren van deze data kunnen verschillende meerdere essentiële factoren worden bepaald; hoe snel slijtage ontstaat, onder welke omstandigheden een proces het meest efficiënt verloopt, hoe vaak er onderhoud gepleegd moet worden en welke onderdelen vitaal zijn in het gehele proces.\n\nHet verzamelen van deze gegevens heeft echter nog een functie, namelijk als bewijslast voor de verzekering.\n<h2>Onderhoudsdata als bewijslast voor de verzekering</h2>\nOok al doet u als bedrijf alles om problemen te voorkomen, storingen, schade en uitval komt nu eenmaal overal voor. Het valt helaas bijna niet te vermijden. In geval van een storing of uitval heeft u te maken met meerdere partijen: uw klanten die wachten op uw product; de fabrikant van de machine die uitgevallen is of het object dat schade opgelopen heeft, en de verzekeringsmaatschappijen van alle partijen.\n\nAls bedrijf wilt u dat het probleem zo snel mogelijk opgelost wordt. Een storing moet zo snel mogelijk verholpen worden, een defect zo snel mogelijk gerepareerd. Langere stilstand kost u veel geld, het maakt de schade in sommige gevallen groter en doet bovendien uw reputatie niet goed. Ook in geval van de verzekering wilt u het liefst dat alles zo snel mogelijk afgehandeld wordt. Om die afhandeling te sneller te kunnen laten verlopen is het van belang om zo duidelijk mogelijk te hebben wat de reden was van de storing, uitval of bijkomende schade. De schuldige partij kan dan snel worden bepaald.\n\n<img class=\"alignnone size-full wp-image-1671\" src=\"https://thingsway.nl/wp-content/uploads/2020/10/data-inspectie-onderhoud.jpg\" alt=\"inspectie onderhoud\" width=\"1170\" height=\"500\" />\n<h2>Hoe komt u aan real-time onderhoudsdata?</h2>\nAls het goed is worden vitale objecten, machines en hun onderdelen in uw bedrijf bewaakt. Dit doet u door middel van periodieke inspecties en eventueel onderhoud. Dit wordt uitgevoerd door technici of een maintenancebedrijf. Het nadeel van deze methode is dat het bewaken niet continu wordt gedaan. Gegevens worden niet constant gemeten en genoteerd. Hierdoor bent u niet altijd in bezit van real-time en accurate gegevens. Een ander nadeel is dat u nog steeds afhankelijk bent van wat er genoteerd wordt tijdens een inspectie.\n\nHet Internet of Things wordt steeds meer toegepast in het bewaken van machines en processen. Deze worden continu gemonitord door middel van sensoren. Wanneer er een verandering in de omgeving plaatsvindt wat een toekomstig probleem kan opleveren, dan registreert de sensor dit en stuurt deze gegevens onmiddellijk door zodat er ingegrepen kan worden door een operator of onderhoudstechnicus. Het grote voordeel hiervan is dat uitval en stilstand kan worden voorkomen.\n\nHet andere voordeel is dat u de beschikbaarheid heeft over enorm veel real-time data. Door deze data te analyseren kunt u bepalen waarom het probleem zich heeft voorgedaan. Kwam het door fout gebruik van de operator? Was er een verandering in de omgeving van het object waar u niets aan kon doen? Zat er een fabricagefout in de machine? Door middel van sensoren kan alles vastgelegd worden, in real-time.\n<h2>De Thingsway, een Internet of Things sensor</h2>\nDoor Salland Electronics is de Thingsway ontwikkeld. Het is een IoT-sensor dat in veel sectoren toepasbaar is. Heeft u te maken met veel onderhoud? Dan kan de Thingsway een oplossing voor u zijn. Niet alleen voor het monitoren van een proces, maar ook om gegevens vast te leggen die belangrijk kunnen zijn voor uw verzekeringen en eventuele claims.\n\nOok de verzekeraars gaan ook met hun tijd mee. Beslissingen worden steeds vaker genomen op basis van data. Meer efficiëntie zorgt voor lagere kosten, dat geldt voor de verzekeringsmaatschappij en tevens voor uw bedrijf.\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>','Onderhoudsdata gebruiken als bewijslast voor verzekeringen?','','inherit','closed','closed','','288-revision-v1','','','2022-01-31 09:51:58','2022-01-31 09:51:58','',288,'https://thingsway.media2netdev.nl/?p=439',0,'revision','',0),(440,1,'2022-01-31 09:51:59','2022-01-31 09:51:59','Het Internet of Things wordt sinds enige jaren volop ingezet om de werking van apparaten en activa van bedrijven te monitoren. Steeds meer machines en objecten worden voorzien van sensoren. Door middel van een directe internetverbinding wordt er data verkregen dat een bedrijf kan helpen om de efficiëntie te vergroten.\n\nWist u dat het Iot ook zeer nuttig kan zijn in het zo veilig mogelijk houden van de werkomgeving? Een veilige werkomgeving is één van de eerste prioriteiten van een bedrijf. U wilt natuurlijk dat uw werknemers zo goed en veilig mogelijk hun werk kunnen doen. Ongevallen op de werkvloer wilt u zoveel mogelijk vermijden. Een veilige werkomgeving creëert u door een goede infrastructuur, goed werkende machines, veilige hulpmiddelen en een strikte regelgeving.\n<h2>Waarom het naleven van de regelgeving belangrijk is</h2>\nDe regelgeving in uw bedrijf heeft u voor goede redenen opgesteld. U wilt dat de productie van uw bedrijf zo efficiënt mogelijk draait. Bovendien wilt u een werkomgeving garanderen waar uw medewerkers zich niet alleen veilig voelen, maar waar ze ook daadwerkelijk veilig zijn. Het naleven van de regels is daarom zeer belangrijk, vooral in een omgeving waar veel gewerkt wordt met machines of zware en instabiele objecten.\n\nEr bestaat nog een andere reden waarom de naleving van de regelgeving belangrijk is, namelijk vanwege verzekeringen en eventuele claims van klanten. Wanneer iemand van uw technische team niet volgens de regels onderhoud heeft gepleegd dan kan niet alleen de veiligheid van medewerkers in het geding komen. Er zouden namelijk ook claims van fabrikanten of klanten kunnen komen in geval van schade, uitval of stilstand. Dit kan voor hoge kosten zorgen voor uw bedrijf en een negatief effect hebben op uw omzet en betrouwbaarheid.\n\n<img class=\"size-full wp-image-1752 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/11/regels-en-regelgeving.jpg\" alt=\"regels en regelgeving \" width=\"1000\" height=\"800\" />\n<h2>Onderhoudsdata gebruiken als bewijslast voor regelgeving</h2>\nHet is duidelijk dat het heel belangrijk is dat iedereen in uw bedrijf werkt volgens de regelgeving. Om de naleving van de regels te controleren wordt er veelal gebruik gemaakt van fysieke controles en steekproeven. Dit zorgt ervoor dat u gegevens heeft over de inzet en naleving van regels door specifieke medewerkers.\n\nU kunt er echter ook voor kiezen om de naleving van de regelgeving continu te laten monitoren, bijvoorbeeld op gebied van onderhoud. De onderhoud van machines of activa is van groot belang, ook daarvoor zijn specifieke regels opgesteld. Dit garandeert de werking, productiviteit, effectiviteit en veiligheid van medewerkers of zelfs eventuele bewoners (bijvoorbeeld in geval van een lift in een flat).\n\nOnderdelen van een machine moeten af en toe gesmeerd worden, de temperatuur van een motor mag niet te hoog worden, slijtage kan voor uitval zorgen en moet worden gerapporteerd, een volle dakgoot kan voor waterschade zorgen. Dit zijn slechts enkele voorbeelden waarom onderhoud gepleegd moet worden, en volgens bepaalde regelgeving. Het juist uitvoeren van deze regels kan gecontroleerd worden door middel van onderhoudsdata.\n<h2>Hoe kunt u onderhoudsdata verkrijgen?</h2>\nEen oude manier van het vergaren van gegevens van onderhoud is via spreadsheets en geschreven notities in bijvoorbeeld een logboek. Dit is echter een vrij algemeen beeld en geeft u vaak niet de actuele toestand van een machine of object. Bovendien komt de notitie van de onderhoudsmedewerker die het onderhoud uitgevoerd heeft. U zou natuurlijk extra controle kunnen laten doen door een andere medewerker. Maar zou het niet veel effectiever zijn wanneer u gebruik maakt van een sensor? Sensoren kunnen exact monitoren of de werking van een proces optimaal verloopt. Wanneer dit niet het geval is, dan is onderhoud nodig en is de regelgeving (mogelijk) niet goed nageleefd.\n<h2>De Thingsway, een IoT-sensor</h2>\nDe Thingsway is een voorbeeld van zo’n sensor. Deze is in staat om allerlei processen te monitoren. Een verandering in de omgeving wordt onmiddellijk door de sensor geregistreerd, deze gegevens worden doorgestuurd via een directe internetverbinding naar een centraal punt (computer, laptop etc.) Na het analyseren van de gegevens kunt u bepalen of de regelgeving is nageleefd.\n\nSalland Electronics is de ontwikkelaar van de Thingsway. Het grote voordeel is dat de Thingsway zeer snel in te zetten is, bovendien in verschillende omgevingen. Er bestaat een Thingsway voor toepassingen in de buitenlucht, maar ook een industriële versie. Binnen een dag kunt u al voorzien zijn van een sensor inclusief internetverbinding. Zodoende kunt u zorgen dat iedereen in uw bedrijf volgens de regels werkt.\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>','Onderhoudsdata gebruiken als bewijslast voor regelgeving','','inherit','closed','closed','','290-revision-v1','','','2022-01-31 09:51:59','2022-01-31 09:51:59','',290,'https://thingsway.media2netdev.nl/?p=440',0,'revision','',0),(441,1,'2022-01-31 09:52:00','2022-01-31 09:52:00','[et_pb_section admin_label=\"section\"]\n			[et_pb_row admin_label=\"row\"]\n				[et_pb_column type=\"4_4\"][et_pb_text admin_label=\"Text\"]Door veel managers op het hoogste niveau wordt onderhoud slechts beschouwd als een kostenpost. Daarom worden er door onderhoudsmanagers vaak nieuwe manieren gezocht om de kosten te verlagen. Een kleiner budget zorgt vaak voor een kleiner onderhoudsteam, wat de werkdruk steeds meer vergroot op de leden van dit team. Gelukkig bestaan er een aantal manieren waarop u deze druk kunt weghalen. Daardoor behoudt u onderhoudspersoneel die gemotiveerd en efficiënt blijven werken.\n<h2>Hoe kunt u de druk op onderhoudspersoneel wegnemen?</h2>\nHet eerste wat u kunt doen om de druk weg te halen bij het onderhoudspersoneel is door te zorgen voor een preventief onderhoudsschema dat in balans is en daarmee effectief. Het opstellen hiervan kan soms moeilijker zijn dan u denkt. Het is belangrijk dat het schema gebaseerd is op accurate gegevens. Tevens moeten uw beschikbare middelen objectief bekeken worden.\n\nVoor een effectief preventief onderhoudsschema heeft u onderhoudsdoelen nodig, daarnaast moet u een goede strategie hebben om deze doelen te bereiken. U dient accurate gegevens te hebben van uw activa en inventaris. Daarnaast is het belangrijk om te bepalen wie het meest geschikt is voor welke taak en deze toe te wijzen. Teveel preventief werk inplannen is een valkuil die u het best kunt vermijden. Dit kunt u doen door uw onderhoudsplan te verfijnen met goede hulpmiddelen zoals bijvoorbeeld software.\n\nAls manager is het noodzakelijk om goed te luisteren wanneer onderhoudspersoneel naar u toe komt met vragen of suggesties. Het kan zijn dat een medewerker een goed idee heeft hoe het uitvoeren van een taak vereenvoudigd kan worden, of hoe er efficiënter omgegaan kan worden met de voorraad. Medewerkers die moeite doen om u feedback te geven zullen meer waardering voelen wanneer dit serieus genomen wordt. Uiteindelijk zal dit de motivatie van de medewerker ten goede komen.\n\nUw onderhoudspersoneel zal regelmatig onregelmatigheden opmerken en daardoor voor nuttige gegevens zorgen. Wat hun daarbij kan assisteren zijn hulpmiddelen zoals onderhoudssoftware en sensoren.\n<h2>Verlaag de druk op uw onderhoudspersoneel met sensoren</h2>\nPreventief onderhoud is één van de beste manieren om uitval en storingen van machines te voorkomen. Door deze regelmatig te onderwerpen aan inspectie kunt u problemen voor zijn, zoals bijvoorbeeld slijtage en ingrijpen waar nodig. Om de druk bij uw onderhoudspersoneel weg te nemen kunt u ook kiezen voor een ander soort onderhoud, namelijk conditie gestuurd onderhoud. Dat wil zeggen dat het onderhoudsteam pas aangestuurd wordt wanneer dit echt nodig is.\n\nVoor een optimale werking zijn bepaalde factoren nodig, dat geldt voor machines maar ook voor objecten zoals bijvoorbeeld een dakgoot. Uitval, storing of schade kan plaatsvinden wanneer een machine te heet wordt, of wanneer een dakgoot niet doorstroomt. Om deze indicaties vast te stellen kunt u natuurlijk preventieve inspecties doen, maar het werkt veel effectiever door middel van sensoren.\n\nBij het Internet of Things wordt veel gebruik gemaakt van sensoren. Deze sensoren monitoren continu veranderingen in de omgeving, zoals warmte, druk of beweging. Wanneer een verandering plaats vindt dan registreert de sensor dit, via een rechtstreekse internetverbinding wordt deze verandering gemeld. U ontvangt deze melding en kan ingrijpen voordat een storing, uitval of eventuele schade optreedt.\n<h2>De Thingsway, een Internet of Things-sensor</h2>\nEen Iot-oplossing kan u helpen om de druk bij uw onderhoudspersoneel weg te nemen. De Thingsway is zo’n Iot-oplossing, ontwikkeld door Salland Electronics. Deze sensor is voor veel verschillende toepassingen inzetbaar. Het grote voordeel is dat de Thingsway zeer snel aangepast wordt op uw wensen. Binnen een dag kunt u al voorzien zijn van een sensor inclusief internetverbinding.\n\nHet basismodel kan aangepast worden op gebied van behuizing, aansluiting en natuurlijk de geschikte sensor om veranderingen in de omgeving te meten.\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\n<h2>Wat zijn de voordelen van de druk weghalen?</h2>\nDe voordelen van het wegnemen van de druk op onderhoudspersoneel zijn enorm. Ten eerste zijn er de voordelen voor de werknemers. Deze zullen meer balans hebben in hun schema, daardoor zullen ze gemotiveerder en uitgerust aan het werk gaan. Dat zal de kwaliteit, veiligheid en efficiëntie van het werken verhogen. Dit zal van invloed zijn op de efficiëntie van het gehele bedrijf. Machines en activa die goed werken zorgen voor meer werkplezier en productiviteit.\n\nHet bedrijf zal verder profiteren van de lagere kosten voor onderhoud.\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>[/et_pb_text][/et_pb_column]\n			[/et_pb_row]\n		[/et_pb_section]','De voordelen van verlaagde druk op onderhoudspersoneel','','inherit','closed','closed','','292-revision-v1','','','2022-01-31 09:52:00','2022-01-31 09:52:00','',292,'https://thingsway.media2netdev.nl/?p=441',0,'revision','',0),(442,1,'2022-01-31 09:52:02','2022-01-31 09:52:02','In de toekomst zullen steeds meer bedrijven aan voorspellend onderhoud doen via een IoT-oplossing. Voor bedrijven die veel te maken hebben met onderhoud is het lastig om de kosten voor onderhoud laag te houden en tegelijkertijd de beschikbaarheid van activa hoog. Om dit evenwicht te bewaren is een effectief onderhoudsplan nodig. Voorspellend- of conditie gestuurd onderhoud via een IoT-oplossing geeft bedrijven de mogelijkheid om aan regelgeving te voldoen, kosten voor onnodig onderhoud te beperken en storingen, uitval en stilstand te voorkomen.\n<h2>Het verschil tussen preventief en voorspellend onderhoud</h2>\nPreventief onderhoud is onderhoud dat gepland volgens een bepaalde interval periode. Dit onderhoud vindt plaats ongeacht de conditie van de middelen en is bedoeld om defecten te voorkomen. Voorspellend onderhoud vindt plaats wanneer het nodig is, er is een voorspeld risico dat defecten zullen optreden aan machines of objecten.\n\nVoorspellend onderhoud brengt enige investeringen met zich mee, maar zal op de lange termijn winst opleveren omdat onnodig onderhoud niet meer uitgevoerd hoeft te worden.\n<h2>Voorspellend onderhoud in de praktijk</h2>\nIn de praktijk werkt voorspellend onderhoud via IoT zo; de werking van een proces of apparatuur wordt gemeten door middel van continue monitoring. De gegevens worden vastgelegd door sensoren en via een internetverbinding doorgestuurd naar een centraal punt. Na het analyseren van deze gegevens kunnen bedrijven veel betere voorspellingen doen wanneer een machine uit zal vallen, maar ook hoe een proces zo effectief mogelijk verloopt. Dit zijn proactieve stappen die een bedrijf kan nemen om meer controle te houden op een geheel productieproces.\n<h2>Voorspellend onderhoud met de Thingsway</h2>\nDe Thingsway is zo’n IoT-sensor dat ingezet kan worden om voorspellend onderhoud mogelijk te maken. Salland Electronics heeft een flexibel product gemaakt met de Thingsway. Het is namelijk zeer snel aanpasbaar en in te zetten in elke omgeving. Dat in tegenstelling tot veel andere IoT-sensoren die nog wel eens log worden genoemd.\n\nBinnen een dag kunt u al voorzien zijn van een Thingsway, geheel aangepast op het proces dat gemonitord dient te worden.\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\n<h2>Wat zijn de voordelen van het IoT bij onderhoud?</h2>\nDe voordelen van het IoT bij onderhoud zijn:\n• Verlaging van onderhoudskosten;\n• Verhoging van het gebruik van activa;\n• Verlenging van de levensduur;\n• Efficiëntere inzet van personeel;\n• Een veiligere en gezondere werkomgeving.\n<h2>Verlaging van onderhoudskosten</h2>\nAl het onderhoud brengt kosten met zich mee. Bovendien zijn de bijkomende kosten door onverwachte uitval vaak aanzienlijk. Door bepaalde machines of objecten continu te laten monitoren kan een bedrijf geld besparen door problemen voor te zijn en voortaan te voorkomen. IoT-sensoren kunnen nauwkeurige voorspellingen doen over de werking van een proces. De data die verkregen wordt geeft de mogelijkheid om het onderhoudsplan naar een nieuw niveau te tillen.\n<h2>Verhoging van het gebruik van activa</h2>\nHet voorkomen van storingen en uitval zal ongeplande stilstand verlagen. Dit verhoogt logischerwijs het gebruik van uw machines. Bovendien is het niet meer nodig om periodiek onderhoud te plegen, waardoor machines nog minder stil hoeven te staan. Het IoT zorgt ervoor dat u operationeel kunt blijven, de sensoren vormen uw bewakers van het gehele proces.\n<h2>Verlenging van de levensduur</h2>\nHet continu monitoren zorgt voor veel gegevens, daardoor krijgt u een beter inzicht in de werking van uw machines. Hierdoor kunt u storingen beter voorspellen en de kritieke onderdelen identificeren. Het gebruik van activa wordt daardoor niet alleen vergroot, ook de levensduur zal toenemen. Door op tijd onderdelen te vervangen, of het juiste onderhoud te plegen zal slijtage aan machines beperkt blijven.\n<h2>Efficiëntere inzet van personeel</h2>\nDoor gebruik te maken van een IoT- oplossing kunt u uw personeel efficiënter inzetten. De werking van uw middelen wordt met een IoT-oplossing bewaakt door sensoren. Dat geeft een bedrijf de mogelijkheid om beter te plannen en prioriteiten te stellen. Een probleem zorgt er voor dat onderhoudsmedewerkers onverwacht ergens ter plekke moeten komen. Dit zorgt vaak voor vertraging in het productieproces en eist flexibiliteit van andere medewerkers. Misschien moet u personeel verplaatsten van plek, of zelfs extra personeel inhuren.\n\nDoor IoT onderhoud toe te passen worden dit soort problemen vermeden. De inzet van onderhoudsmedewerkers wordt veel effectiever en de uitvaltijd verminderd.\n<h2>Een gezondere en veiligere werkomgeving</h2>\nProblemen met middelen of machines kunnen ook zorgen voor gevaarlijke situaties op de werkvloer. Door gebruik te maken van IoT- sensoren kunnen deze situaties vermeden worden. De sensoren kunnen een proces monitoren en veranderingen in de omgeving registreren en melden. Dit stelt u in staat om mogelijke gevaarlijke situaties voor te zijn. Door het analyseren van gegevens over een langere periode kunnen deze mogelijke gevaarlijke omstandigheden geïdentificeerd worden.\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>','Onderhoud en IoT: wat zijn de mogelijkheden en de voordelen ervan?','','inherit','closed','closed','','294-revision-v1','','','2022-01-31 09:52:02','2022-01-31 09:52:02','',294,'https://thingsway.media2netdev.nl/?p=442',0,'revision','',0),(443,1,'2022-01-31 09:52:02','2022-01-31 09:52:02','De kosten voor onderhoud maken voor veel bedrijven een groot deel uit van de totale bedrijfskosten, soms wel 25%. Ongeveer de helft van deze kosten bestaan uit arbeidskosten, dat is de reden waarom efficiency van onderhoud zo belangrijk is. Het verhogen van de efficiency op onderhoud heeft bovendien positieve gevolgen op de betrouwbaarheid van een bedrijf. De prestaties blijven op het juiste niveau, terwijl de kosten voor onderhoud verlaagd worden.\n\nHelaas wordt niet overal even efficiënt gewerkt. Bij het uitvoeren van onderhoudstaken is er vaak sprake van verspilling en inefficiëntie. Dan zijn er bijvoorbeeld onnodig veel mensen met een taak bezig, er moet worden gezocht naar vervangende onderdelen, of technici moeten wachten tot een bepaalde machine vrij komt. Het maakt niet uit of u het onderhoud in eigen beheer heeft of dat u het uitbesteedt, de kosten voor de inefficiëntie komen op uw rekening.\n\nEr zijn verschillende redenen waarom de efficiency van onderhoud niet optimaal is zoals; teveel reactief onderhoud, teveel mankracht in de nachtdienst en een slechte planning.\n<h2>Leunen op reactief onderhoud is inefficiënt</h2>\nHelaas zijn er veel bedrijven die leunen op reactief onderhoud. De focus van deze bedrijven ligt bij een zo hoog mogelijke productie. Pas wanneer een probleem zich voordoet wordt er ingegrepen en onderhoud gepleegd. Eigenlijk is er dan geen sprake van onderhoud, maar reparatie. Een storing of probleem kan door reactief onderhoud nooit worden voorspeld. Dit zorgt ervoor dat onderhoud bijna niet te plannen is, u weet nooit wanneer de problemen zich voordoen. Gevolg hiervan is dat u constant een onderhoudsteam paraat moet hebben.\n\nOm de efficiency te vergroten zou u een gedegen actief onderhoudsplan moeten hebben. Reactief onderhoud zou u moeten beperken tot de middelen die snel vervangbaar zijn.\n\n<img class=\"size-full wp-image-1769 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/11/onderhoud-winst-maken.jpg\" alt=\"onderhoudskosten verlagen\" width=\"960\" height=\"638\" />\n<h2>Veel mankracht in de nachtdienst is inefficiënt</h2>\nVeel bedrijven werken in ploegendiensten, dat geldt ook vaak voor de technici van onderhoudsteams. De gedachte hierachter is dat storingen altijd kunnen plaatsvinden en er dus iemand aanwezig moet zijn. In de praktijk is het echter zo dat 75% van de storingen tijdens de dagdienst gebeuren. Het inzetten van personeel op de juiste werktijden kan de efficiëntie verhogen.\n<h2>Slechte planning zorgt voor inefficiëntie</h2>\nDe kwaliteit van onderhoud wordt voor een groot gedeelte bepaald door een goede planning van onderhoudstaken. Een goed schema zorgt ervoor dat de juiste activa op het juiste moment wordt onderhouden. Bovendien zorgt een efficiënt schema voor balans in de taken van technici en het gaat verspilling tegen. Het onverwacht verplaatsen van mankracht van plek naar plek kost reistijd, personeelskosten en zorgt voor stilstand.\n\nDe efficiency van een bedrijf wordt flink verhoogd door middel van een systematisch onderhoudssysteem. U heeft natuurlijk ook positieve mensen nodig met capaciteiten. Daarnaast kunt u gebruik maken van de technologie om de efficiency op onderhoud te verhogen. Dat kunt u doen door middel van een IoT-oplossing.\n<h2>Meer efficiency door het Internet of Things</h2>\nHet Internet of Things is enorm in opkomst bij bedrijven die veel te maken hebben met onderhoud. De voordelen van het IoT zijn namelijk talrijk. Door systemen, objecten of machines te laten monitoren door sensoren wordt de efficiency van een bedrijf verhoogd. Het kan een bedrijf daardoor veel kosten besparen op gebied van onderhoud.\nStel u heeft een productiebedrijf dat gebruik maakt van machines. Deze machines zijn kritisch voor u, uitval betekent stilstand en kan voor hoge kosten zorgen. Dit is de reden waarom u waarschijnlijk aan periodiek onderhoud doet. U wilt problemen voor zijn door de conditie van de machines in de gaten te houden middels periodieke metingen. Tijdens deze metingen wordt indien nodig onderhoud uitgevoerd.\n\nU zou deze metingen ook kunnen laten uitvoeren door middel van een sensor. De vele voordelen van de sensor zijn dat deze eenmalig kosten met zich meebrengt, continu het proces monitort en problemen meldt voordat deze zich voordoen.\nDit scheelt u veel inzet en reistijd van onderhoudspersoneel, deze worden gerichter ingezet, namelijk pas op momenten dat de sensor een melding geeft.\n<h2>De Thingsway</h2>\nDe Thingsway is een IoT-sensor dat uw bedrijf kan helpen om de efficiency van onderhoud te verhogen. Deze sensor is een basisproduct dat snel aan te passen is op het te meten proces. De aanpassingen worden gedaan op gebied van behuizing, aansluiting en de benodigde sensoren.\n\nBinnen een dag kan Salland Electronics u voorzien van een Thingsway. Maak gebruik van het IoT om de efficiency op onderhoud te verhogen!\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>','Efficiency onderhoud verhogen: hoe doe je dat?','','inherit','closed','closed','','296-revision-v1','','','2022-01-31 09:52:02','2022-01-31 09:52:02','',296,'https://thingsway.media2netdev.nl/?p=443',0,'revision','',0),(444,1,'2022-01-31 09:52:03','2022-01-31 09:52:03','Het werven van talent en deze plaatsen op de juiste posities in uw bedrijf is al een opgave op zich. Dat geldt zeker wanneer het gaat om het werven van goed geschoold technisch personeel. Veel bedrijven over de hele wereld worden met deze uitdaging geconfronteerd. Het tekort aan technisch personeel bestaat al een aantal jaar, maar de voorspellingen zijn dat dit tekort de komende jaren alleen maar zal toenemen.\n\nHet is logisch dat dit tekort zorgen baart voor bedrijven die veel te maken hebben met technisch onderhoud. Wanneer een bedrijf niet in staat is om geschoold technisch personeel te werven dan heeft dit gevolgen op de korte termijn, maar ook voor alle vooruitzichten op lange termijn.\n\nGelukkig bestaan er een aantal manieren om het tekort aan technisch personeel in uw bedrijf op te lossen.\n<h2>Maak gebruik van nieuwe technologieën</h2>\nDe technologie op gebied van technisch onderhoud gaat razendsnel. Dat is te danken aan de opkomst van het Internet of Things. Steeds meer apparaten en objecten worden voorzien van sensoren die de werking van een proces continu monitoren. Veranderingen in een proces die eventuele problemen kunnen veroorzaken worden geregistreerd en doorgestuurd via een internetverbinding. Het technisch personeel hoeft pas opgeroepen te worden wanneer deze melding gegeven wordt.\n\nEen voorbeeld van zo’n Iot-sensor is de Thingsway. Deze sensor wordt al door meerdere bedrijven ingezet om de werking van een proces te monitoren. Zo wordt er bijvoorbeeld gebruik gemaakt van de Thingsway om de doorstroming van een dakgoot in de gaten te houden. Maar er bestaat ook een industriële versie van de Thingsway.\n\nDit is een veel effectievere manier van onderhoud plegen, door de enorme stroom aan data krijgt een bedrijf een veel beter inzicht in de werking van een object of apparaat. Periodiek onderhoud kan veel beter gepland worden, voorspellingen kunnen veel nauwkeuriger worden gedaan. Voor het technisch personeel betekent dit dat ze veel gerichter kunnen worden aangestuurd en ingezet. Deze dienen dan wel getraind te worden in het werken met de laatste IoT-technologie.\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\n<h2>Train de bestaande technische medewerkers</h2>\nOm het tekort aan nieuwe technische arbeidskrachten op te vangen, gaan veel bedrijven hun bestaand personeel bijscholen. Zodoende kan het technisch personeel op de hoogte blijven van de nieuwste technologie. Bijscholing kan gedaan worden door middel van een interne opleiding, een deskundige werknemer zou bijvoorbeeld zijn kennis en expertise kunnen delen met anderen. Dit is een goede en goedkope manier om de kennis te verhogen van uw personeel.\n\nU zou de training van uw personeel ook kunnen uitbesteden. Er bestaan verschillende bedrijven die cursussen geven op technisch gebied. Dit is een optie dat wat duurder is en wat meer tijd nodig heeft, maar het zal op den duur zeker zijn vruchten afwerpen. Uw technisch personeel wordt namelijk opgeleid volgens de laatste technologieën en volgens de standaard in de industrie. Nieuw technisch personeel zal tevens sneller kiezen voor een bedrijf dat zijn personeel up-to-date houdt.\n<h2>Huur een maintenance bedrijf in</h2>\nMisschien heeft u altijd uw eigen technisch personeel in dienst gehad? Wanneer u niet meer aan genoeg technisch personeel kunt komen, is het inhuren van een maintenance bedrijf een goede optie. Door gebruik te maken van hun expertise en beschikbaarheid wordt uw eigen flexibiliteit verhoogd. Het onderhoudsbedrijf zou ook kunnen fungeren als ondersteuning van uw eigen technisch personeel.\n\nU kunt er ook voor kiezen om tijdelijk personeel in te huren. Jongere werknemers kiezen er steeds meer voor om freelance te werken. Deze tijdelijke krachten zouden uw bedrijf kunnen helpen zo lang u ze nodig heeft.\n<h2>Ga een samenwerking aan met een onderwijsinstelling in de buurt</h2>\nU zou uw bedrijf kunnen openstellen voor stageplekken voor leerlingen van een technische school in de buurt. Dit betekent dat u constant nieuwe instroom heeft van potentiële werknemers die bovendien goed geschoold zijn. Door de volgende generatie technisch werknemers binnen te halen, kunt u gebruik maken van de kennis van de toekomst.\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>','Gebrek technisch personeel: hoe op te lossen?','','inherit','closed','closed','','298-revision-v1','','','2022-01-31 09:52:03','2022-01-31 09:52:03','',298,'https://thingsway.media2netdev.nl/?p=444',0,'revision','',0),(445,1,'2022-01-31 09:52:04','2022-01-31 09:52:04','Zonder dat we het merken worden we steeds meer omringd door sensoren. Het gebeurt overal, in onze werkomgeving, op straat en zelfs bij ons thuis. Deze sensoren zorgen ervoor dat ons leven steeds aangenamer wordt. We hoeven steeds minder zelf te doen, sensoren nemen een bepaalde handelingen van ons over voor ons gemak. Neem als voorbeeld uw thermostaat; niet zo heel lang geleden was u zelf verantwoordelijk voor het regelen van de temperatuur in uw huis, tegenwoordig regelt de thermostaat alles voor u.\n\nSteeds meer apparaten om ons heen nemen onze taken over, dit worden slimme apparaten genoemd. De thermostaat, de koelkast, uw horloge, alles is voorzien van sensoren en een internetaansluiting, alles om het gemak van de mens te dienen. Maar wist u dat er tegenwoordig zelfs slimme gebouwen bestaan?\n<h2>Wat zijn slimme gebouwen?</h2>\nEen slim gebouw is een gebouw dat gebruik maakt van technologie om informatie te delen. Bij de informatie dat gedeeld wordt kunt u denken aan alles wat er in het gebouw gebeurt dat de prestaties van het gebouw bepaald. Aan de hand van deze informatie worden bepaalde processen geautomatiseerd, zoals verwarming, ventilatie en beveiliging.\n\nDe eigenaar van een gebouw heeft aanzienlijke kosten om het gebouw te gebruiken. Dit zijn noodzakelijke uitgaven, maar er wordt vaak onnodig veel kosten gemaakt. Als voorbeeld noemen we lampen die branden op plekken waar dat niet nodig is, ruimtes die onnodig verwarmd worden of deuren die automatisch draaien zonder dat er mensen in de buurt zijn. Gebouwen worden slimmer gemaakt om het gebouw voor de gebruiker aantrekkelijker te maken, maar ook om verspilling van energie tegen te gaan. Zodoende kan efficiënt met energie worden omgegaan en kunnen veel kosten bespaard worden.\n\n<img class=\"size-full wp-image-1789 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/11/slimme-kantoren-en-gebouwen.jpg\" alt=\"slimme kantoren en gebouwen\" width=\"1000\" height=\"800\" />\n<h2>Wat zijn de mogelijkheden voor slimme gebouwen?</h2>\nDe mogelijkheden voor slimme gebouwen zijn enorm. Zo kan de luchtkwaliteit in een gebouw verbeterd worden, dit komt onze gezondheid en productiviteit ten goede. Sensoren kunnen het niveau van CO2 in een ruimte kunnen meten alsmede eventuele schadelijke deeltjes in de lucht. Wanneer de aanwezigheid hiervan te hoog is dan kan de ventilatie aangepast worden.\n\nEr zou tevens gebruik gemaakt kunnen worden van sensoren om voorspellingen te doen op gebied van onderhoud. Sensoren zouden de werking van bepaalde apparaten in de gaten kunnen houden. Als er iets in de omgeving verandert dan meldt de sensor dit zodat onderhoud gepleegd kan worden. U kunt dan denken aan bijvoorbeeld een lift waarvan de deur niet goed sluit, of een verwarmingsketel waarbij ongewenste trillingen worden waargenomen. Niet alleen apparaten kunnen voorzien worden van een sensor, maar bijvoorbeeld ook een dakgoot. Wanneer deze niet goed doorstroomt dan krijgt de beheerder een melding voordat problemen zich voordoen.\n<h2>Van welke tools wordt gebruik gemaakt bij slimme gebouwen?</h2>\nBij een slim gebouw wordt gebruik gemaakt van verschillende tools. Als eerste worden er belangrijke systemen met elkaar verbonden. Door deze met elkaar te laten communiceren wordt een gebouw “slim”. Denkt u dan aan systemen zoals watermeters, stroomvoorziening, pompen etc.\n\nSensoren spelen een grote rol in slimme gebouwen. Ze zorgen ervoor dat gegevens verzameld worden. Aan de hand van deze gegevens worden beslissingen genomen om het gebruik van het gebouw te optimaliseren.\n\nAutomatisering is tevens een groot onderdeel van een slim gebouw. Alle verzamelde data wordt geanalyseerd door een automatisch systeem in het gebouw. Dit gebeurt continu en in real-time. Deze continu monitoring zorgt ervoor dat automatisch aanpassingen gedaan kunnen worden. Aanpassingen die ervoor zorgen dat bepaalde omstandigheden in het gebouw verbeterd worden.\n\nData is een belangrijke tool voor slimme gebouwen. De grote hoeveelheid waardevolle gegevens zorgen ervoor dat er veel effectiever gebruik gemaakt kan worden met middelen en grondstoffen. Gewone gebouwen hebben dit voordeel niet.\n<h2>Gebruik de Thingsway om uw gebouw slimmer te maken</h2>\nOver het algemeen zijn het vooral nieuwe gebouwen die slim zijn. Het gebruik van sensoren en de nodige tools wordt dan al meegenomen bij het ontwerpen van het gebouw. U kunt echter wel degelijk een oud gebouw “slimmer” maken.\n\nZo zou u bijvoorbeeld de Thingsway kunnen inzetten om bepaalde processen in uw gebouw te monitoren. De Thingsway is een IoT-sensor dat ontwikkeld is door Salland Electronics. Het voordeel van deze sensor is dat het multifunctioneel is en bovendien zeer snel aan te passen. Wilt u dat vanaf morgen de lift in een gebouw gemonitord wordt? Dat kan met de Thingsway!\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>','Wat zijn de mogelijkheden en tools van slimme gebouwen?','','inherit','closed','closed','','300-revision-v1','','','2022-01-31 09:52:04','2022-01-31 09:52:04','',300,'https://thingsway.media2netdev.nl/?p=445',0,'revision','',0),(446,1,'2022-01-31 09:52:05','2022-01-31 09:52:05','Er bestaat een industrie dat aan veel mensen voorbij gaat; namelijk de koel-vriesindustrie. Toch is dit een bedrijfstak dat enorm belangrijk is in het dagelijks leven. Dankzij de koel-vriesindustrie heeft heel Nederland dagelijks vers eten op hun bord. Ook in de farmaceutische industrie wordt veel gebruik gemaakt van koel- en vrieskasten. De juiste temperatuur bewaken is ook in deze industrie van groot belang.\n\nIn een professionele keuken staat de koelkast centraal. Veel bedrijven zijn afhankelijk van vers voedsel, daarom zijn bedrijfsleiders zich ter terdege bewust van het belang van goede koeling. Vers voedsel is de belangrijkste bron van inkomsten van deze bedrijven, dus koelapparatuur dat betrouwbaar en effectief werkt is van cruciaal belang.\n\nOndernemers kunnen hun klanten vers voedsel bieden door optimale temperaturen te behouden. Wanneer deze temperatuur te veel stijgt of daalt, dan zal voedselbederf optreden. Voor de farmaceutische industrie betekent het controleren van de temperatuur dat de betrouwbaarheid van een proces beheerst wordt. Precisie is van groot belang om gecertificeerde producten te kunnen produceren.\n\nWanneer voedingsmiddelen bedorven raken, voorschriften niet nageleefd worden en apparatuur defect raakt dan zal dit leiden naar verloren inkomsten. Niet alleen dat, het zal reputatieschade opleveren voor een bedrijf, het zorgt voor extra kosten en misschien zelfs boetes.\n<h2>Waarom is onderhoud belangrijk in de koel-vriesindustrie?</h2>\nOm de goede werking van koelapparatuur te garanderen is onderhoud essentieel. De risico’s van het niet onderhouden van deze apparaten zijn:\n<ul>\n 	<li>de machine zal sneller verouderen;</li>\n 	<li>de machine zal meer energie verbruiken dan nodig is;</li>\n 	<li>het koelvermogen van de machine zal afnemen;</li>\n 	<li>veiligheidsnormen en milieu eisen kunnen niet worden nageleefd.</li>\n</ul>\nOm bovenstaande risico’s te vermijden dient er regelmatig onderhoud gepleegd te worden aan koelings- en vriesapparaten. Dit periodiek onderhoud wordt meestal gedaan volgens een bepaald schema en volgens richtlijnen die aangegeven worden door fabrikanten. Deze richtlijnen worden bepaald op basis van ervaringen uit het verleden en door metingen en testen. Aan de hand van deze gegevens worden voorspellingen gedaan hoe lang een machine of onderdeel meegaat en hoe vaak het onderhoud nodig heeft. Het grote nadeel hiervan is dat het nog steeds om voorspellingen gaat, storingen kunnen nog altijd optreden.\n\nEr wordt echter steeds meer gebruik gemaakt van het Internet of Things om de werking van apparaten te monitoren. Ook op gebied van onderhoud kan het Internet of Things u grote voordelen opleveren. Een sensor kan namelijk continu bepaalde indicatoren in de gaten houden.\n\n<img class=\"size-full wp-image-1807 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/11/onderhoud-koel-vries-industrie.jpg\" alt=\"onderhoud koel en vries industrie \" width=\"1000\" height=\"800\" />\n<h2>Maak gebruik van het Internet of Things om efficiënte koeling te garanderen</h2>\nHet Internet of Things heeft voor een nieuwe industriële revolutie gezorgd. Door apparaten en alledaagse objecten te voorzien van sensoren en een directe internetverbinding kunnen bedrijven veel efficiënter werken en kosten voor onderhoud verlagen.\n\nIn de voedingsindustrie en farmaceutische industrie is koeling van het grootste belang. Door de werking van koelingsapparaten te laten monitoren door middel van sensoren bent u als bedrijf gegarandeerd dat de juiste temperatuur gehandhaafd blijft. De sensoren zullen veranderingen in de omgeving onmiddellijk melden via de rechtstreekse internetverbinding. Denkt u dan aan de stijging of daling van de temperatuur, een hoger energieverbruik of ongewenste trillingen in een koelmotor. Zodoende kan onderhoud gepleegd worden voordat kritische waarden bereikt zijn.\n<h2>De Thingsway van Salland Electronics</h2>\nSalland Electronics is een bedrijf uit Zwolle dat Internet of Things oplossingen voor bedrijven verzorgd. Zij hebben de Thingsway ontwikkeld, een IoT-sensor dat zeer snel toepasbaar is voor elk bedrijf, ook in de koel-vriesindustrie.\n\nDe Thingsway is een basisproduct dat zeer snel aan te passen is, u kunt binnen een dag al voorzien zijn van een sensor en internetverbinding. De Thingsway wordt voorzien van de benodigde sensoren, de behuizing wordt aangepast aan de omgeving en het wordt voorzien van de juiste aansluiting. Met de Thingsway heeft u een sensor in uw bedrijf die de werking van uw koelsystemen continu kan monitoren. Dit geeft u de mogelijkheid om kritische temperaturen te bewaken en onderhoud te plegen exact wanneer dat nodig is.\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>','Het belang van onderhoud in de koel- en vriesindustrie','','inherit','closed','closed','','302-revision-v1','','','2022-01-31 09:52:05','2022-01-31 09:52:05','',302,'https://thingsway.media2netdev.nl/?p=446',0,'revision','',0),(447,1,'2022-01-31 09:52:06','2022-01-31 09:52:06','Wanneer we het hebben over onderhoud dan denken we al snel aan onderhoud van machines of auto’s. Onderhoud is echter essentieel voor de optimale werking van bijna alles om ons heen, ons huis, onze werkplek, winkels en alles wat zorgt voor een aangenaam leefklimaat in deze ruimtes.\n\nDe technologie waar gebruik van gemaakt wordt om het klimaat in bepaalde ruimtes te optimaliseren wordt klimaattechniek genoemd. Onderhoud is van essentieel belang in vele bedrijfstakken, dus ook in deze specifieke tak. Waarom en hoe kan voorspellend onderhoud door middel van een Internet of Things oplossing daarbij helpen? Dat leest u in dit artikel!\n<h2>Wat is klimaattechniek?</h2>\nAls eerste kijken we naar de branche dat klimaattechniek heet. Het is een brede branche waaronder de volgende takken vallen;\n<ul>\n 	<li>ventilatie en luchtbehandeling;</li>\n 	<li>verwarming;</li>\n 	<li>koeltechniek;</li>\n 	<li>meet en regeltechniek.</li>\n</ul>\nKlimaattechniek omvangt alle techniek dat invloed uitoefent op het klimaat in bepaalde binnenruimtes. Apparaten zorgen ervoor dat de juiste temperatuur aangehouden wordt, ze zorgen voor de juiste luchtvochtigheid en verse lucht. Voorbeelden van klimaattechniek zijn alle verwarmingssystemen, airconditioners, luchtbevochtigers maar ook koelsystemen.\n\nOm te zorgen voor een prettig klimaat in een woonruimte zijn verschillende technieken nodig. Als eerste moet er bepaald worden wat het huidige klimaat is. Hierna moeten ongewenste invloeden beperkt of voorkomen worden, zoals bijvoorbeeld tocht of lekkages. Vervolgens wordt bepaald wat voor installatie nodig is om het gewenste klimaat te bereiken. Dezelfde procedure wordt toegepast op werkruimtes.\n<h2>Het belang van onderhoud bij klimaattechniek</h2>\nBij klimaattechniek wordt zeer veel gebruik gemaakt van apparaten en systemen. Deze systemen zorgen ervoor dat een bepaalde ruimte niet alleen prettig is om in te vertoeven, ze zorgen tevens voor een veilige en gezonde ruimte. In sommige gevallen is het in stand houden van de juiste omstandigheden van essentieel belang. U kunt dan denken aan het in stand houden van de juiste temperatuur en vochtigheid in kassen, of aan koeling in de voedings- en farmaceutische industrie. Een apparaat dat niet goed werkt kan zorgen voor grote productieproblemen en uiteindelijk voor hoge kosten.\n\nOm de veilige werking van deze systemen te garanderen is regelmatig onderhoud absoluut noodzakelijk. Tijdens dit onderhoud worden vooral de belangrijkste componenten gecontroleerd. Onderdelen worden gereinigd en opnieuw juist afgesteld. Belangrijke componenten die zorgen voor een correcte werking zijn onder andere motoren en filters. Tijdens periodiek onderhoud worden de filters gecontroleerd en eventueel vervangen wanneer nodig.\n\n<img class=\"size-full wp-image-1812 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/11/klimaattechniek.jpg\" alt=\"klimaattechniek\" width=\"1000\" height=\"800\" />\n<h2>Hoe het Internet of Things kan helpen bij klimaattechniek</h2>\nOver het algemeen wordt er gebruik gemaakt van periodiek onderhoud om de werking van klimaatsystemen te garanderen. Een vast onderhoudsschema wordt gevolgd dat is bepaald volgens de richtlijnen van fabrikanten. Deze geven aan hoe vaak een apparaat onderhoud nodig heeft. Dit heeft echter enige nadelen, in de meeste gevallen blijkt onderhoud namelijk niet nodig te zijn. Dan werken motoren nog prima volgens de richtlijnen en filters zijn nog niet aan vervanging toe. Toch wordt dit onderhoud gedaan om storingen en problemen voor te zijn. Dit is niet erg effectief en brengt onnodige kosten met zich mee.\n\nVoorspellend onderhoud met gebruik van een Internet of Things-oplossing is een andere manier van onderhoud uitvoeren. Waarschijnlijk weet u precies welke componenten essentieel zijn voor de werking van een apparaat. U kunt de werking van deze componenten laten monitoren door middel van een IoT-sensor. Het grote voordeel van zo’n sensor is dat deze een directe internetverbinding heeft. Wanneer er veranderingen optreden in de omgeving van het proces dan meldt de sensor dit direct. U ontvangt een melding zodat onderhoud direct gepleegd kan worden. Dit is een veel effectievere manier van onderhoud omdat u precies op het juiste moment ingrijpt, onnodig filters vervangen is verleden tijd.\n<h2>De Thingsway, een IoT-oplossing</h2>\nWilt u ervoor zorgen dat de juiste vochtigheid in uw kas wordt gehandhaafd? Wilt u een gezond leefklimaat op uw kantoor? Is koeling voor uw bedrijf van essentieel belang? Om deze factoren te garanderen wordt er waarschijnlijk veelvuldig onderhoud gepleegd aan de klimaatsystemen.\n\nDe Thingsway kan u daarbij helpen, dit is een IoT-sensor dat ontwikkeld is door Salland Electronics. Het grote voordeel van de Thingsway is dat deze snel aan te passen is op uw wensen. Aanpassingen worden gedaan op gebied van benodigde sensor, behuizing en aansluiting. Na installatie zal de Thingsway continu een proces monitoren, eventuele veranderingen worden via de internetverbinding onmiddellijk gemeld.\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>','Het belang van onderhoud bij klimaattechniek','','inherit','closed','closed','','304-revision-v1','','','2022-01-31 09:52:06','2022-01-31 09:52:06','',304,'https://thingsway.media2netdev.nl/?p=447',0,'revision','',0),(448,1,'2022-01-31 09:52:07','2022-01-31 09:52:07','[et_pb_section fb_built=\"1\" admin_label=\"section\" _builder_version=\"3.22\"][et_pb_row admin_label=\"row\" _builder_version=\"3.25\" background_size=\"initial\" background_position=\"top_left\" background_repeat=\"repeat\"][et_pb_column type=\"4_4\" _builder_version=\"3.25\" custom_padding=\"|||\" custom_padding__hover=\"|||\"][et_pb_text admin_label=\"Text\" _builder_version=\"4.9.0\" background_size=\"initial\" background_position=\"top_left\" background_repeat=\"repeat\" hover_enabled=\"0\" sticky_enabled=\"0\"]<p>Elk jaar zorgen arbeidsongevallen voor (blijvend) letsel bij werknemers, sommige ongevallen hebben zelfs een fatale afloop. Een bedrijf wil er vanzelfsprekend alles aan doen om dit te voorkomen, daarom wordt er veel gedaan aan de werkomstandigheden, moeten werkvoorschriften nageleefd worden en moeten arbeidsmiddelen regelmatig gekeurd worden. De werkomstandigheden en een verantwoordelijke productiecultuur heeft u zelf in de hand. Het keuren van de arbeidsmiddelen kunt u verbeteren door middel van de Thingsway, een Internet of Things sensor.</p>\n<h2>Wat is het Internet of Things (IoT)?</h2>\n<p>Het Internet of Things (IoT) zorgt voor een vrije stroom aan informatie tussen mensen, computers, machines en objecten. Het IoT verbindt alles in een omgeving met elkaar en zorgt dat informatie gedeeld wordt door middel van real-time communicatie. Deze communicatie zorgt voor meer beschikbare informatie, dit kan ervoor zorgen dat de veiligheid op de werkplek verbetert wordt.</p>\n<p>De informatieverstrekking bij het Internet of Things werkt via sensoren. Deze sensoren registreren veranderingen in een bepaalde omgeving. Er bestaan veel verschillende sensoren, allen voor verschillende doeleinden. Zo bestaan er bijvoorbeeld sensoren die warmte kunnen registreren, maar ook trillingen, druk en beweging. Dit zijn slechts enkele voorbeelden. Bijna alles valt te meten door middel van een sensor. Het voordeel van het IoT is dat deze sensoren zijn voorzien van een directe internetverbinding. Dit geeft de sensor de mogelijkheid om continu data door te sturen van een bepaald proces.</p>\n<h2>De Thingsway</h2>\n<p>De Thingsway is een IoT-sensor, ontwikkeld door Salland Electronics. Iot-sensoren kunnen nog wel eens logge apparaten zijn. Het grote voordeel van de Thingsway is dat het een basisproduct is dat zeer snel aangepast kan worden. Daardoor is het een zeer flexibel product dat voor veel verschillende toepassingen geschikt is. De basis wordt aangepast op het te meten of monitoren object en uw specifieke wensen. Dit kan al binnen een dag aangepast worden zodat u snel gebruik kunt maken van een IoT-oplossing.</p>\n<p><img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" /></p>\n<h2>Wat kan de Thingsway betekenen bij het keuren van arbeidsmiddelen?</h2>\n<p>Door middel van de Thingsway kunt u de werking van arbeidsmiddelen laten monitoren. Er bestaan verschillende manieren waarop gevaar kan ontstaan voor de gezondheid van uw medewerkers bijvoorbeeld door middel van gas.</p>\n<p>U wilt het natuurlijk zo snel mogelijk weten wanneer ergens een gaslek is zodat u maatregelen kunt nemen. Door middel van een IoT-oplossing kunt u dat doen. Sensoren die koolmonoxide detecteren bestaan al jaren. Het bijkomende voordeel van het IoT is dat u veel meer informatie ontvangt behalve de melding van koolmonoxide. De sensoren zijn namelijk in staat om concentraties te meten op verschillende plaatsen, zo weet u dat er een lek is, maar ook precies waar.</p>\n<p>Warmte en trillingen kunnen andere indicatoren zijn die kunnen zorgen voor een gevaarlijke situatie. Ook deze indicatoren kunnen gemeten worden door middel van sensoren. Wanneer er ongewenste veranderingen in de omgeving zijn dat wordt dit onmiddellijk door de Thingsway geregistreerd en gemeld via de directe internetverbinding. Door deze melding kunt u ingrijpen voordat gevaarlijke situaties ontstaan die letsel kunnen veroorzaken.</p>\n<p>Er is nog een groot voordeel van een IoT-oplossing zoals de Thingsway. Het keuren van arbeidsmiddelen doet u niet alleen voor de veiligheid, maar ook om de effectiviteit van uw middelen te waarborgen. Door gebruik te maken van de Thingsway kunt u ook deze effectiviteit vergroten.</p>\n<h2>Effectiviteit van arbeidsmiddelen en voorspellend onderhoud</h2>\n<p>Door het continue monitoren zorgt de Thingsway voor een enorme hoeveelheid data. Door deze data te analyseren kunt u een veel beter beeld krijgen van de werking van uw arbeidsmiddelen. Dat geeft u de mogelijkheid om een proces effectiever te laten verlopen. Misschien werkt een machine veel effectiever onder bepaalde omstandigheden. Een sensor meet de omstandigheden continu, dus u krijgt een zeer betrouwbaar beeld van de werking onder alle omstandigheden.</p>\n<p>Een Internet of Things oplossing geeft u tevens de mogelijkheid om voorspellend onderhoud toe te passen. Eigenlijk worden uw arbeidsmiddelen continu gekeurd door middel van de sensoren. Dit neemt de verplichting weg om eens in de zoveel tijd de machine stil te leggen om periodiek onderhoud te plegen. Veranderingen in de omgeving kunnen indicatoren zijn van een komende storing of uitval van de machine. Deze veranderingen worden geregistreerd door de Thingsway.</p>\n<p>Door uw arbeidsmiddelen continu te monitoren kan Thingsway uw bedrijf helpen op gebied van effectiviteit en veiligheid.</p>\n<h2>Vrijblijvend contact</h2>\n<p>Met het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!</p>\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n<p><strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong></p>\n</div>[/et_pb_text][/et_pb_column][/et_pb_row][/et_pb_section]','Keuren van arbeidsmiddelen: tips en tools','','inherit','closed','closed','','306-revision-v1','','','2022-01-31 09:52:07','2022-01-31 09:52:07','',306,'https://thingsway.media2netdev.nl/?p=448',0,'revision','',0),(449,1,'2022-01-31 09:52:08','2022-01-31 09:52:08','Bij de gedachte aan een onderhoudstechnicus zullen veel mensen nog steeds denken aan een man in een blauwe overal vol olievlekken. In zijn hand heeft hij een gereedschapskist dat vol zit met sleutels en tangen. Dit is een nostalgisch beeld waar we maar moeilijk van af komen. Een onderhoudsmedewerker zal altijd wel een koffer met tangen en sleutels bij zich dragen, maar de laatste jaren is de manier van onderhoud uitvoeren enorm veranderd. De technologie gaat met grote sprongen vooruit, er wordt steeds meer gebruik gemaakt van apparatuur, computers en digitale systemen. We kunnen dit gerust de engineering van onderhoud noemen.\n<h2>Engineering van onderhoud</h2>\nEngineering van onderhoud wordt toegepast om de apparatuur van een bedrijf optimaal te kunnen laten werken, de betrouwbaarheid en beschikbaarheid wordt daarbij verhoogd. Door steeds meer gebruik te maken van verschillende apparaten, systemen en procedures wordt de mate waarin onderhoud gepleegd wordt effectiever. Dit zorgt voor een verlaging van de kosten voor onderhoud.\n\nDoor de toename van productieapparatuur, machines, systemen en infrastructuur wordt onderhoud steeds belangrijker. Alles wordt misschien wat gebruik betreft steeds makkelijker, maar om te onderhouden wordt alles steeds complexer. Dat is de reden waarom er steeds meer behoefte is aan geschoold technisch onderhoudspersoneel. Onderhoud is voor bedrijven vaak een grote kostenpost, maar tegelijkertijd een onmisbare. Het is bedoeld om ervoor te zorgen dat een bedrijf zijn doelen kan behalen. Activa zou maximaal beschikbaar moeten zijn tegen de laagste kosten. Engineering van onderhoud moet hiervoor zorgen, samen met de kennis en kunde van de moderne onderhoudsmonteur.\n<h2>Wat engineering betekent voor de onderhoudsmedewerker</h2>\nDe moderne onderhoudsmonteur moet beschikken over enorm veel kennis. Natuurlijk moet hij de basiskennis hebben van de werking van apparatuur en machines en tevens hoe deze te repareren indien een storing optreedt. Verder moet hij een goede kennis hebben op gebied van statistiek, kansberekening en op de hoogte zijn van de laatste technologieën. Zijn communicatievaardigheden moeten tevens in orde zijn en hij moet snel beslissingen kunnen maken.\n\nVerantwoordelijkheden van de onderhoudstechnici zijn onder andere:\n<ul>\n 	<li>Zorg voor naleving van het onderhoudssysteem.</li>\n 	<li>Storingen die zich vaker voordoen analyseren.</li>\n 	<li>Schattingen maken van kosten en alternatieven bedenken.</li>\n 	<li>Reserveonderdelen beheren.</li>\n 	<li>Beoordelen wanneer apparatuur vervangen moet worden.</li>\n 	<li>Benodigde gereedschap beoordelen.</li>\n 	<li>Juiste vaardigheden bezitten.</li>\n 	<li>Controleren, repareren en rapporteren van de werking van apparatuur.</li>\n</ul>\n<h2>Het IoT, de nieuwe industriële revolutie</h2>\nDe opkomst van het Internet of Things heeft voor een nieuwe industriële revolutie gezorgd. Steeds meer machines, apparaten en alledaagse objecten worden voorzien van sensoren en aangesloten op het internet. Dit heeft grote voordelen op gebied van onderhoud en betekent voor bedrijven een goede kans om zo effectief mogelijk te kunnen produceren.\n\nDoor middel van een sensor kan de werking van een bepaald proces continu gemonitord worden. Treden er veranderingen op in de omgeving wat de werking van het proces negatief kan beïnvloeden dan zal de sensor dit via de rechtstreekse internetverbinding melden. Deze melding kan binnenkomen op een centraal punt, zoals een computer. Het kan echter ook gestuurd worden naar de smartphone van de onderhoudsmedewerker. Deze kan dan direct in actie komen en onderhoud plegen waar nodig. Onderhoud via een Internet of Things-oplossing is een vorm van voorspellend onderhoud.\n\nEen ander voordeel van een Internet of Things-oplossing is de enorme hoeveelheid data dat het oplevert. De sensor monitort een systeem continu, dit levert heel veel gegevens op. Door deze gegevens te analyseren krijgt een bedrijf een veel beter beeld van de werking van een systeem. Voorspellingen kunnen veel beter worden gedaan, bijvoorbeeld wanneer een storing zal optreden. Dit is belangrijk voor de onderhoudstechnicus, maar ook voor de fabrikant van de machine. Dit is hoe sensoren helpen bij de engineering van onderhoud.\n<h2>De Thingsway, een IoT-sensor</h2>\nHet Internet of Things zorgt voor grote vooruitgang bij engineering van onderhoud. Een IoT-sensor dat kan worden gebruikt om een onderhoudsprogramma te optimaliseren is de Thingsway. Dit is een sensor dat toepasbaar is voor veel bedrijfstakken. Er bestaat een Thingsway voor gebruik in de buitenlucht, maar er is ook een industriële versie.\nSalland Electronics is de ontwikkelaar van de Thingsway. Binnen een dag kan het bedrijf u voorzien van een Thingsway inclusief internetconnectie. De sensor kan geheel naar uw wens worden aangepast, dit hangt af van het te meten proces. De Thingsway betekent een nieuwe stap op gebied van engineering van onderhoud.\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>','Hoe het IoT helpt bij de engineering van onderhoud','','inherit','closed','closed','','308-revision-v1','','','2022-01-31 09:52:08','2022-01-31 09:52:08','',308,'https://thingsway.media2netdev.nl/?p=449',0,'revision','',0),(450,1,'2022-01-31 09:52:09','2022-01-31 09:52:09','Kunt u zich nog herinneren dat u moest inbellen als u het internet wilde gebruiken? Hoort u de irritante toon nog? Het laden van een pagina duurde een uur en als het eenmaal geladen was, dan wilde iemand anders in het gezin een email sturen. Dit is niet eens zo heel lang geleden, namelijk aan het eind van de jaren 90.\n\nDe ontwikkelingen zijn de laatste jaren razendsnel gegaan. Het internet is nu overal om ons heen en we hebben er ook direct toegang toe. We doen er werkelijk alles mee, we kijken video’s, we delen foto’s en onze mening, luisteren muziek en checken het laatste nieuws. Als we heel eerlijk zijn kunnen we zeggen dat we erg veel tijd verspillen op het internet.\n\nSinds een aantal jaar wordt er niet alleen door mensen gebruik gemaakt van het internet, veel apparaten en andere alledaagse dingen hebben nu ook hun eigen internetaansluiting. Dit wordt ook wel het Internet of Things genoemd.\n<h2>Wat is het Internet of Things?</h2>\nHet Internet of Things is een netwerk waarbij alledaagse apparaten worden voorzien van sensoren en een internetverbinding. Wasmachines, horloges, industriële machines, maar ook objecten als dakgoten zijn voorzien van een internetconnectie. Hierdoor kunnen deze apparaten verbinding met ons, maar ook elkaar maken en gegevens uitwisselen.\n\nDe achterliggende gedachte van het Internet of Things is om het leven van ons te vergemakkelijken. Door apparaten te laten communiceren kunnen processen veel effectiever verlopen. Dit is de reden waarom het Internet of Things wordt ook wel de nieuwe industriële revolutie genoemd. Niet alleen machines of apparaten worden hierdoor slimmer, ook bij gebouwen wordt het Internet of Things ingezet om deze slimmer te maken.\n<h2>Slimme gebouwen en het IoT</h2>\nHet Internet of Things zorgt sinds korte tijd ook voor grote veranderingen bij gebouwen. Het biedt namelijk grote kansen om veel effectiever met middelen om te gaan. Bovendien kan het IoT helpen om de productiviteit van werknemers te vergroten.\n\nEr bestaan veel verschillende processen die nodig zijn om een gebouw goed te laten functioneren, verwarming, koeling, verlichting, elektra, etc. Helaas wordt er in reguliere gebouwen veel hiervan verspild, bijvoorbeeld door alle lampen die aanstaan in kamers waar het niet nodig is. Door gebruik te maken van sensoren kan deze verspilling tegen worden gegaan. Hierdoor wordt de effectiviteit dus verhoogd en de kosten verlaagd.\n\nAl deze processen zorgen ook voor een bepaald leefklimaat. Het leefklimaat is van groot belang voor bewoners of werknemers om prettig te kunnen leven of goed te kunnen functioneren. De juiste temperatuur, een gezonde lucht en zuurstofgehalte. Sensoren kunnen ervoor zorgen dat de optimale omstandigheden aangehouden worden.\n<h2>Hoe wordt gebruik gemaakt worden van het IoT bij slimme gebouwen?</h2>\nEr bestaan twee verschillende manieren waarop het Internet of Things gebruikt wordt om gebouwen slim te maken. De typische manier waarop aan gebouw beheersing wordt gedaan is door afzonderlijke sensoren (met hun eigen gateway) te gebruiken om verwarming, koeling, verlichting etc. aan te sturen.\n\nEr bestaan echter ook hypermoderne gebouwen waar er door middel van software gezorgd dat alle afzonderlijke sensoren met elkaar kunnen communiceren en samenwerken. Zo ontstaat er een echt zelfdenkend en slim gebouw. Op dit moment wordt deze manier van het Internet of Things inzetten vooral gedaan bij grote nieuwbouw projecten zoals bijvoorbeeld bedrijfspanden en ziekenhuizen. Het is echter een kwestie van tijd dat alle nieuwbouw woningen slim zullen worden.\n<h2>De Thingsway</h2>\nEen voorbeeld van een IoT-sensor is de Thingsway. Van deze sensor wordt op dit moment al gebruik gemaakt om gebouwen slimmer te maken. Een bepaalde versie van de Thingsway monitort namelijk de werking van een dakgoot. Wanneer de doorstroming van de dakgoot vermindert, dan zal de Thingsway dit vaststellen en melden via de internetverbinding. Door deze melding kan er aan onderhoud gedaan worden zodat er geen verstoppingen, overstromingen en schadeposten ontstaan.\n\nDit is slechts één manier waarop de Thingsway in te zetten is, het grote voordeel van de Thingsway is namelijk dat het een basisproduct is dat zeer snel aangepast kan worden. Binnen een dag kan ontwikkelaar Salland Electronics een Thingsway op maat van uw bedrijf verzorgen. Zodoende kunt u uw gebouwen slimmer maken en effectiever gebruik maken van al uw middelen.\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>','IoT bij slimme gebouwen: de mogelijkheden','','inherit','closed','closed','','310-revision-v1','','','2022-01-31 09:52:09','2022-01-31 09:52:09','',310,'https://thingsway.media2netdev.nl/?p=450',0,'revision','',0),(451,1,'2022-01-31 09:52:10','2022-01-31 09:52:10','De weegschaal is een stukje techniek dat al duizenden jaren bestaat. Het wegen werd in de prehistorie gedaan met de hand, maar toen de mens eenmaal aan ruilhandel ging doen was het belangrijk om de waarde van voorwerpen met elkaar te kunnen afwegen. Om eerlijk te kunnen ruilen moest de exacte hoeveelheid van producten zoals graan en melk gemeten kunnen worden.\n\nWeegschalen werden al vanaf de tijd van de Egyptenaren gebruikt, zo’n 7000 jaar geleden. Om het gewicht te kunnen bepalen werd een balans gebruikt met een contragewicht. Zo werd de weegschaal een onmisbaar voorwerp voor de mensheid. Tegenwoordig is de weegtechniek nog steeds erg belangrijk, niet alleen voor particulieren, maar ook in verschillende industrieën. De weegschaal is sinds de Egyptenaren enorm veranderd en verbeterd, maar nooit zoveel als de afgelopen jaren met de opkomst van sensoren en het Internet of Things. De moderne technologische vooruitgang zorgt ervoor dat de weegtechniek grote sprongen maakt in efficiëntie.\n<h2>In welke industrieën zijn weegtechnieken belangrijk?</h2>\nDe meeste mensen hebben thuis een weegschaal staan, vaak onder een laag stof verstopt in een kast of lade. Voor veel industrieën is de weegschaal echter een onmisbaar stukje techniek, voorbeeld hiervan is bijvoorbeeld de productie-industrie. Bij het verpakken van voedingsmiddelen, goederen, farmaceutische middelen en chemicaliën is het van groot belang dat exact het juiste gewicht bepaald wordt. Een bedrijf wil natuurlijk niet teveel of te weinig van hun product leveren.\n\nWeegtechnieken zijn ook zeer belangrijk in de vrachtsector. Het is heel belangrijk om vrachtwagens, boten en vliegtuigen op de juiste manier te beladen. Dit zorgt er namelijk voor dat een voertuig goed in balans is en veilig op weg kan. Bovendien rijdt, vaart of vliegt een voertuig dan een stuk zuiniger.\n\nOm goed het gewicht te kunnen bepalen worden er in deze bedrijfssectoren gebruik gemaakt van weegsensoren.\n<h2>Weegtechnieken en het Internet of Things</h2>\nEen weegsensor wordt ook wel eens een loadcell of krachtsensor genoemd. Het is een elektronisch apparaat dat trek- en compressiekracht omzet in een elektrisch signaal. Deze sensoren worden meestal gebruikt om het gewicht van iets te bepalen, maar ze kunnen ook gebruikt worden om de spanning op iets te bepalen (zoals de spanning op een touw of katrol).\n\nWeegsensoren verschillen van ontwerp en specifieke functie, maar ze meten allen de weerstand of vervorming binnen de sensor. Hierdoor wordt de grootte van trek- en drukkrachten bepaald. De farmaceutische industrie, de auto-industrie, de voedingsindustrie en de productie-industrie kunnen allen profiteren van deze weegtechnieken, mede dankzij het Internet of Things.\n\nVeel IoT-toepassingen maken gebruik van weegsensoren. Mooie voorbeelden hiervan zijn het bepalen van het gewicht in magazijnen en afvalmonitoring op afstand. Voor een magazijn betekent het dat exact bepaald wordt hoeveel er nog van een bepaald product op voorraad is. In geval van afval monitoring kan bepaald worden of een afvalbak vol is en dus geleegd moet worden.\n\n<img class=\"size-full wp-image-1840 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/11/weegtechnieken-iot.jpg\" alt=\"weegtechnieken iot\" width=\"1920\" height=\"1080\" />\n<h2>De mogelijkheden van weegtechniek en het IoT</h2>\nDe bovenstaande voorbeelden zijn slechts enkele vormen die mogelijk zijn binnen de weegtechniek en het IoT. Weegsensoren en IoT-toepassingen worden ook ingezet bij het laden van vracht. Medewerkers kunnen in real-time alle beladingsgegevens digitaal aflezen.\n\nDankzij sensoren en het IoT kan er ook in de productie-industrie veel sneller gewogen en daardoor geproduceerd worden. Door hun unieke ontwerp kunnen deze weegschalen fijne producten zoals medicijnen, muesli of suiker razendsnel wegen. Sensoren, systemen, data en hulpmiddelen zoals tablets nemen bovendien de kans weg op menselijke fouten.\n\nHet vergaren van gegevens is de belangrijkste taak binnen de weegtechniek. Het biedt de mogelijkheid om op de hoogte te blijven van elke verandering. Veranderingen kunnen hierna geanalyseerd worden en beleid erop aangepast. De moderne weegschalen zijn voorzien van een internetverbinding. Dit geeft bedrijven de mogelijkheid om toegang te krijgen tot exacte gegevens zonder er fysiek bij aanwezig te hoeven zijn. Dit komt de efficiëntie van ieder bedrijf ten goede!\n<h2>De Thingsway</h2>\nHet wegen met contragewichten is lang voorbij. De moderne weegtechniek werkt met sensoren en een IoT-toepassing. Voor veel verschillende bedrijfstakken kan dit voor meer efficiëntie zorgen en verlaging van de kosten.\n\nDe Thingsway is een sensor die een bedrijf daarbij zou kunnen helpen. Deze IoT-sensor werd ontwikkeld door Salland Electronics. De Thingsway is een basisproduct dat eenvoudig aan te passen is, binnen een dag kan de Thingsway van een weegsensor worden voorzien. Zodoende kunt u zeer snel gebruik maken van zijn voordelen.\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>','Weegtechnieken en IoT: waarom belangrijk? En wat zijn de mogelijkheden?','','inherit','closed','closed','','312-revision-v1','','','2022-01-31 09:52:10','2022-01-31 09:52:10','',312,'https://thingsway.media2netdev.nl/?p=451',0,'revision','',0),(452,1,'2022-01-31 09:52:11','2022-01-31 09:52:11','We hebben een nieuw tijdperk bereikt, ook als we het hebben over gebouwen. Onderdak bieden en ons warm en droog houden was jarenlang het grootste doel van een huis of kantoor. Tegenwoordig moet een gebouw alle diensten leveren die wij als gebruikers wensen. Dankzij de razendsnelle evolutie van de technologie kunnen deze wensen vervuld worden. Gebouwen moeten de gebruikers niet alleen maximaal comfort brengen, een gebouw moet ook zo zuinig, milieuvriendelijk en efficiënt mogelijk zijn. Ondanks al deze wensen is het doel om tijdens de levensduur van een gebouw de kosten zo laag mogelijk te houden.\n\nJuist door gebouwen slimmer te maken kan het juiste evenwicht gevonden worden tussen deze doelen. De tijd van slimme gebouwen is daarom aangebroken.\n<h2>Wat is een slim gebouw?</h2>\nIn een slim gebouw wordt gebruik gemaakt van technologie om gegevens te delen over de systemen die plaatsvinden in een gebouw. Na het analyseren van deze gegevens kunnen bepaalde processen geautomatiseerd worden. U kunt dan denken aan beveiliging, verwarming en verlichting. Het doel is om een gebouw zo optimaal mogelijk te gebruiken op gebied van comfort, duurzaamheid en efficiëntie.\n\nEen beheerder van een gebouw heeft jaarlijks flinke kosten. Vanzelfsprekend zijn deze onafwendbaar en noodzakelijk om een gebouw draaiend te houden, maar helaas wordt er vaak veel geld verspild. Lampen blijven branden zonder dat het nodig is, ruimtes worden onnodig verwarmd of geventileerd, zo zijn er veel voorbeelden te noemen van verspilling. Eén van de grote doelen van een slim gebouw is om deze kosten te besparen. Een gebouw slimmer maken noemt men ook wel gebouw automatiseringen.\n\n<img class=\"size-full wp-image-1844 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/11/gebouw-automatiseringen.jpeg\" alt=\"gebouw automatiseringen\" width=\"1158\" height=\"1500\" />\n<h2>Gebouw automatiseringen</h2>\nSinds de opkomst van het Internet of Things en zijn enorme mogelijkheden komen er steeds meer bedrijven die aan gebouw automatiseringen doen. Dit zijn bedrijven die installaties ontwerpen en plaatsen in gebouwen. Niet alleen nieuwbouw projecten worden slimmer gebouwd, ook steeds meer eigenaren en beheerders van oudere panden kiezen ervoor om het gebouw te laten automatiseren.\n\nNiet alleen het ontwerpen en plaatsen van deze installaties is belangrijk om een gebouw slimmer te maken, een ander belangrijk aspect is het onderhoud.\n<h2>Onderhoudstoepassingen voor gebouw automatiseringen</h2>\nDe installaties die gebruikt worden voor intelligente gebouw automatisering worden steeds complexer. De prestaties van deze installaties moeten optimaal zijn, om dit te kunnen bereiken moeten de juiste meet- en regelsystemen aangebracht worden. Wanneer de regelingen en metingen kloppen dan is het comfort in het gebouw optimaal, de installaties presteren naar wens en het verbruik van energie is zo laag mogelijk.\n\nOm dit te kunnen bereiken zijn verschillende toepassingen van onderhoud nodig. Zo dienen alle installaties regelmatig onderhouden en gecontroleerd te worden volgens een periodiek systeem. Tijdens dit onderhoud zou regulier onderhoud gepleegd moeten worden zoals het afstellen van pompen en kleppen. Maar er zou ook gekeken moeten worden of alle meters optimaal ingesteld zijn, of alle software up-to-date is en of storingen nog automatisch gemeld worden.\n\nOm deze storingen te laten melden kan gebruik gemaakt worden van voorspellend onderhoud door middel van een IoT-toepassing.\n<h2>Voorspellend onderhoud met een IoT-toepassing</h2>\nHet uitvoeren van onderhoud is van groot belang bij gebouw automatiseringen. Om alle systemen in een gebouw optimaal te laten draaien is regelmatig onderhoud vereist. Helaas kan een onderhoudsmedewerker niet constant lijfelijk aanwezig zijn om alle systemen in de gaten houden. Sensoren bieden hiervoor de oplossing.\n\nOm een kritisch onderdeel van een installatie te monitoren wordt er steeds vaker gebruik gemaakt van IoT-sensoren. Deze monitoren continu de omgeving van een bepaald proces. Vinden hier veranderingen plaats dan wordt dit geconstateerd en in real-time gemeld via een rechtstreekse internetverbinding. De onderhoudsmedewerker kan na het ontvangen van deze melding onmiddellijk onderhoud plegen. Onderhoud dat gepleegd wordt door middel van een IoT-sensor wordt voorspellend onderhoud genoemd. De sensor voorspelt namelijk storingen voordat deze plaatsvinden.\n<h2>De Thingsway</h2>\nDe Thingsway is een Internet of Things sensor dat ingezet wordt voor voorspellend onderhoud. Bepaalde systemen zijn kritisch in een gebouw dat geautomatiseerd is, daarom moet er regelmatig onderhoud aan gepleegd worden. Deze installaties kunt u laten monitoren door de Thingsway.\n\nHet grote voordeel van de Thingsway is zijn snelle inzetbaarheid. Ontwikkelaar Salland Electronics kan u al in een dag voorzien van een Thingsway. Het basisproduct wordt razendsnel aan uw wensen aangepast. Deze sensor kan u helpen om voorspellend onderhoud uit te voeren. Zo wordt niet alleen het gebouw slimmer en effectiever, maar ook de onderhoudstoepassingen.\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>','Gebouw automatiseringen en de toepassingen van onderhoud','','inherit','closed','closed','','314-revision-v1','','','2022-01-31 09:52:11','2022-01-31 09:52:11','',314,'https://thingsway.media2netdev.nl/?p=452',0,'revision','',0),(453,1,'2022-01-31 09:52:12','2022-01-31 09:52:12','Lekkages zijn een veel voorkomend probleem bij vooral oudere gebouwen. Op den duur kunnen lekkages voor veel grotere problemen zorgen, zeker wanneer de oorzaak niet goed aangepakt wordt. Dit kan voor hoge kosten zorgen voor de eigenaren van huizen, kantoren of gebouwen. In dit artikel kunt u lezen waardoor de meeste lekkages ontstaan en hoe u gebouwen kunt beveiligen tegen lekkages.\n<h2>Waardoor ontstaan lekkages aan huizen en gebouwen?</h2>\nEr bestaan verschillende oorzaken voor lekkages, maar de meest voorkomende zijn:\n<h2>Een reparatie leidt naar grotere problemen</h2>\nRegelmatig gebeurt het dat een lekkage optreedt en alleen het gevolg wordt aangepakt. De noodreparatie wordt uitgevoerd zodat tijdelijk de problemen verholpen zijn. De oorzaak van de lekkage wordt echter vergeten. Daardoor zullen lekkages terugkeren en soms verergeren.\n<h2>Lekkage door achterstallig onderhoud</h2>\nAchterstallig onderhoud is één van de belangrijkste oorzaken van lekkages. Bij achterstallig onderhoud kunt u denken aan het niet vervangen van oude dakbedekking, het niet vernieuwen van afdichtingen of verouderde loodslabben.\n\n<img class=\"size-full wp-image-1849 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/11/lekkage-door-gebrekkig-onderhoud.jpg\" alt=\"lekkage \" width=\"626\" height=\"352\" />\n<h2>Lekkages door onzorgvuldige renovaties</h2>\nTijdens renovaties worden nieuwe delen soms niet goed aangesloten op het bestaande pand. U kunt dan denken aan bijvoorbeeld nieuwe kozijnen. Wanneer de waterkeringen niet meer goed passen op de nieuwe kozijnen dan kan er lekkage ontstaan.\n<h2>Lekkages door oude leidingen</h2>\nDe waterleidingen kunnen ook voor lekkages zorgen, vooral wanneer deze verouderd zijn. Het gebeurt in Nederland niet zo vaak meer maar in een lange koude periode kunnen zelfs nieuwe leidingen bevriezen en kapot gaan.\n\nAndere lekkages door waterleidingen worden veroorzaakt door de combinatie van inwendige corrosie en waterdruk. De corrosie zorgt voor zure omstandigheden in de leidingen, daardoor ontstaan gaten en scheurtjes in de leiding. Een breuk of lek is het gevolg, maar het water kan hier ook moeilijk langs bewegen waardoor de waterdruk voor meer problemen zorgt.\n<h2>Lekkages door regenpijpen en dakgoten</h2>\nDakgoten en regenpijpen zorgen voor het afvoeren van regenwater. Wanneer deze niet meer goed functioneren dan kunnen er lekkages ontstaan in grote delen van een gebouw. Dakgoten dienen jaarlijks schoongemaakt te worden en de doorstroom van regenpijpen moet gecontroleerd worden.\n<h2>Wat kunt u doen om lekkages te voorkomen?</h2>\nOm lekkages te voorkomen kunt u het volgende doen:\n<ul>\n 	<li>Wanneer er een renovatie plaatsvindt dan is een goed plan nodig waarin aandacht besteed wordt aan het correct aansluiten van nieuwe bouwdelen aan de oude.</li>\n 	<li>Een noodreparatie van een lekkage is een noodreparatie. Er moet altijd een vervolg op zijn, de oorzaak moet gevonden en opgelost worden.</li>\n 	<li>Maak een gedegen onderhoudsplan dat meerdere jaren omvat. De kritische onderdelen van een pand kunt u monitoren, onderhouden en vervangen wanneer nodig. Kritische onderdelen kunnen zijn: dakgoot, dak, leidingen, afdichtingen etc.</li>\n 	<li>Laat deze kritische onderdelen monitoren door middel van een Internet of Things-oplossing.</li>\n</ul>\n<h2>Gebouwen, kantoren en huizen beveiligen tegen lekkage</h2>\nEén van de beste manieren om lekkages te voorkomen is door regelmatig onderhoud te plegen. De kritische onderdelen moeten daarbij worden gecontroleerd en eventueel onderhouden. U heeft daarvoor een goed onderhoudsplan nodig. Om problemen voor te zijn dient u namelijk goed te weten hoe vaak deze kritische onderdelen onderhoud nodig hebben.\n\nU kunt er ook voor kiezen om een IoT-oplossing in te zetten om een gebouw te beveiligen tegen lekkage. Een Internet of Things-oplossing werkt door middel van sensoren en een internetverbinding. De sensor monitort continu de werking van een bepaald proces. Wanneer er veranderingen optreden in dat proces dan worden deze gegevens direct via de internetverbinding doorgestuurd naar een laptop, computer of smartphone. Na het ontvangen van de melding kan er onderhoud gepleegd worden voordat problemen zoals lekkages ontstaan.\n<h2>De Thingsway</h2>\nDe Thingsway is zo’n Internet of Things-oplossing. Het is een product dat kan worden ingezet om allerlei soorten processen te monitoren. Voor bedrijven die veel te maken hebben met onderhoud kan de Thingsway een belangrijke oplossing zijn. Het continu monitoren van de Thingsway kunt u zien als voorspellend onderhoud. Het zorgt voor een effectiever onderhoudsbeleid en verlaagt daarmee aanzienlijk de kosten.\n\nOp dit moment wordt de Thingsway al ingezet voor het beveiligen tegen lekkages. Er is namelijk een versie van de Thingsway die de doorstroom van dakgoten monitort. Wanneer deze doorstroom niet optimaal is dan geeft de Thingsway een melding. Onderhoud kan onmiddellijk gepleegd worden voordat problemen, zoals lekkages, zich voordoen.\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>','Gebouw, kantoren en huizen beveiligen tegen lekkage','','inherit','closed','closed','','316-revision-v1','','','2022-01-31 09:52:12','2022-01-31 09:52:12','',316,'https://thingsway.media2netdev.nl/?p=453',0,'revision','',0),(454,1,'2022-01-31 09:52:13','2022-01-31 09:52:13','Onderhoud is voor veel bedrijven enorm belangrijk, ook voor bedrijven in de installatiebranche. In dit artikel leest u waarom onderhoud zo belangrijk is voor deze bedrijven, maar tevens hoe het Internet of Things daarbij kan helpen.\n<h2>Wat houdt de installatiebranche in?</h2>\nIn de installatiebranche werken bedrijven die technische installaties aanleggen en bovendien onderhouden. Als voorbeelden kunnen we bedrijven noemen in de woningbouw, utiliteitsbouw en in de industrie. Een installatie wordt ontworpen door een installatiebedrijf, maar in sommige gevallen ook door een technisch bureau of door een technische afdeling van een opdrachtgever.\n\nDeze installaties worden aangelegd en onderhouden door een installateur of installatiemonteur. Dit zijn verzamelnamen voor medewerkers in verschillende technische takken. U kunt dan denken aan elektriciens, loodgieters en cv-monteurs.\nDe werkzaamheden van de installateur hangen af van de taken van het bedrijf. Enkele voorbeelden van de werkzaamheden van een installateur zijn:\n<h2>Het belang van onderhoud in de installatiebranche</h2>\nZoals u leest is het aanleggen van een installatie slechts een klein deel van de taken van een installateur. Onderhoud is voor bedrijven in de installatiebranche één van de belangrijkste taken. Een installatie kan nog zo goed aangelegd zijn, het zal niet goed functioneren wanneer er daarna geen onderhoud aan gepleegd wordt.\n\nCv-ketels, airconditionings, liften, koelinstallaties, het heeft allemaal onderhoud nodig om een veilige en efficiënte werking te garanderen. Alle onderdelen zijn nu eenmaal aan slijtage onderhevig. Het is daarom belangrijk voor deze bedrijven om een gedegen onderhoudsplan te hebben. In dit plan kunt u het best gebruik maken van verschillende soorten onderhoud; reactief onderhoud op onderdelen die niet kritisch zijn en makkelijk vervangbaar, periodiek onderhoud en voorspellend onderhoud.\n\nPeriodiek onderhoud wordt gedaan op basis van voorspellingen uit het verleden en volgens aanwijzingen van fabrikanten. Deze fabrikanten weten door testen vrij goed te voorspellen hoelang een bepaald onderdeel of een apparaat meegaat en hoe vaak er dus onderhoud gepleegd moet worden. De installateurs werken dagelijks met deze onderdelen en apparaten, hun rapportage en ervaringen dienen ook meegenomen te worden in de voorspellingen voor periodiek onderhoud.\n\nVoorspellend onderhoud is een andere vorm van onderhoud. Het kan een bedrijf helpen om een nadeel van periodiek onderhoud weg te nemen; namelijk onverwachte storingen aan of uitval van installaties. Voorspellend onderhoud wordt gedaan door middel van Internet of Things- toepassingen.\n\n<img class=\"size-full wp-image-1856 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/11/onderhoud-installatiebranche.jpg\" alt=\"belang van onderhoud in de installatiebranche\" width=\"1000\" height=\"800\" />\n<h2>De mogelijkheden van het IoT in de installatiebranche</h2>\nEen bedrijf in de installatiebranche weet vaak precies welke onderdelen van installaties kritisch zijn voor het veilig en effectief functioneren van een installatie. Gaat zo’n onderdeel kapot dan valt het gehele proces stil of er wordt mogelijk schade veroorzaakt aan de gehele installatie. Dit is de reden waarom deze onderdelen regelmatig gecontroleerd, vervangen en schoongemaakt worden.\n\nOm de effectiviteit van uw installatiebedrijf te vergroten zou u gebruik kunnen maken van een IoT-oplossing om deze onderdelen te monitoren. Bij het Internet of Things wordt gebruik gemaakt van sensoren. Deze sensoren meten continu bepaalde veranderingen in de omgeving, dat gaan om beweging, gas, licht, warmte etc. Deze veranderingen kunnen indicatoren zijn van slijtage en dus toekomstige storingen en uitval. Wanneer zo’n verandering plaatsvindt dan wordt dit via een directe internetverbinding naar een centraal punt gestuurd. Dat kan gaan om een laptop, computer of de smartphone van één van uw installatie medewerkers.\n\nDeze kan onderhoud plegen exact op het juiste moment, voordat zich een storing voordoet. De sensor neemt de periodieke onderhoudstaak weg van de installatiemonteur. Dit zorgt voor een veel effectiever onderhoudsplan.\n<h2>De Thingsway</h2>\nEen mooi voorbeeld van zo’n IoT-sensor is de Thingsway. Dit is een sensor dat voor veel verschillende toepassingen in de installatiebranche geschikt is. Deze sensor is namelijk eenvoudig en snel aan te passen aan de werkzaamheden en wensen van uw bedrijf. Bij aanpassingen die gedaan worden aan het basisproduct moet u denken aan de benodigde sensoren, de behuizing en de aansluiting. Salland Electronics, de ontwikkelaar van de Thingsway, kan al deze aanpassingen binnen een dag doen. Zodoende heeft u razendsnel een IoT-oplossing in uw bedrijf die u van dienst zal zijn bij het onderhoud van installaties.\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>','Het belang van onderhoud in de installatiebranche','','inherit','closed','closed','','319-revision-v1','','','2022-01-31 09:52:13','2022-01-31 09:52:13','',319,'https://thingsway.media2netdev.nl/?p=454',0,'revision','',0),(455,1,'2022-01-31 09:52:14','2022-01-31 09:52:14','IoT is een afkorting van het Internet of Things. Dit is een systeem waarbij allerlei alledaagse objecten met elkaar worden verbonden via het internet. U kunt dan denken aan computers, machines en apparaten, maar ook aan bijvoorbeeld dakgoten. Deze objecten kunnen zonder de tussenkomst van de mens met elkaar communiceren.\nAndere dagelijkse voorbeelden van Internet of Things-toepassingen zijn een hartimplantaat bij een persoon, een dier met een bio chip-ontvanger of een auto met sensoren om de bestuurder te waarschuwen voor gladde wegen of een lage bandenspanning. Voorwaarde voor een IoT-toepassing is dat het object een eigen IP-adres heeft en daardoor onafhankelijk gegevens over een netwerk kan verzenden.\n\nEr wordt steeds meer gebruik gemaakt van het IoT door bedrijven in verschillende bedrijfstakken. Het IoT helpt bedrijven om efficiënter te draaien, klanten beter te kunnen helpen, betere besluiten te kunnen nemen en voor het vergroten van de waarde.\n<h2>Hoe het IoT werkt</h2>\nEen IoT-toepassing bestaat uit verschillende slimme onderdelen zoals processors, sensoren en hardware voor communicatie. Deze onderdelen worden gebruikt om informatie uit de omgeving te halen, verzamelen, verzenden en om op te reageren. De gegevens die verzameld worden door sensoren worden gedeeld door middel van een gateway. Deze stuurt gegevens naar een cloud waar ze geanalyseerd kunnen worden.\n\nIn sommige IoT-systemen communiceren apparaten met elkaar en reageren zelf op de data die ze van elkaar krijgen. Het meeste werk in een IoT-systeem wordt dus gedaan door de apparaten, menselijke tussenkomt is vaak niet nodig. Natuurlijk kunnen mensen wel met deze apparaten communiceren, bijvoorbeeld wanneer ze ingesteld worden of wanneer toegang tot gegevens verkregen moet worden.\n\nDe specifieke IoT-toepassingen bepalen wat voor connectie en netwerk het best werkt voor de communicatie. Binnen het IoT wordt ook vaak gebruik gemaakt van kunstmatige intelligentie (AI). Hierbij leren machines zelf hoe een bepaald proces beter kan verlopen en past zich aan.\n<h2>Waarom is het IoT belangrijk?</h2>\nHet Internet of Things is een hulpmiddel voor mensen om slimmer en tegelijkertijd eenvoudiger te kunnen leven. Behalve het slimmer maken van huizen en apparaten om ons heen, is het IoT heel belangrijk voor bedrijven. Het IoT zorgt ervoor dat bedrijven continu real-time informatie krijgen over hun systemen. Dit biedt de mogelijkheid om een gedetailleerd inzicht te krijgen in bepaalde processen, hoe machines werken, productie, onderhoud en logistiek.\n\nMeerdere processen binnen een bedrijf kunnen met het IoT geautomatiseerd worden. Dit helpt een bedrijf om de arbeidskosten te verlagen. Andere positieve gevolgen zijn het tegengaan van verspilling, het verbeteren van de dienstverlening en het vergroten van efficiëntie op gebied van productie en onderhoud.\n\nHet Internet of Things wordt gezien als één van de belangrijkste technologieën van de afgelopen jaren. De verwachting is dat het niet alleen bepalend zal worden in ons dagelijks leven, maar ook voor de concurrerende positie van bedrijven.\n<h2>De invloed van het IoT op onderhoud</h2>\nBijna alle bedrijven hebben te maken met onderhoud, want alles om ons heen is nu eenmaal onderhevig aan slijtage. Om de werking van bepaalde processen te garanderen is onderhoud nodig. Of het nu gaat om een lift, een productiemachine of een dakgoot, door omstandigheden kunnen er storingen optreden in een proces.\n\nOm storingen en uitval te voorkomen wordt er aan onderhoud gedaan. Een veel gebruikte vorm is periodiek onderhoud. Deze vorm van onderhoud wordt gedaan op basis van instructies van fabrikanten en door gebruik van informatie uit het verleden. Hierdoor kunnen voorspellingen worden gedaan hoe vaak en wanneer een bepaald object onderhoud nodig heeft voordat het uitvalt.\n\nHet nadeel hiervan is dat storingen evengoed onverwacht kan plaatsvinden. Dit zou voorkomen kunnen worden door gebruik te maken van een IoT-toepassing zoals de Thingsway.\n<h2>De Thingsway</h2>\nDe Thingsway is een IoT-systeem dat voor veel verschillende toepassingen inzetbaar is. U kunt de Thingsway inzetten om een bepaald onderdeel te monitoren dat essentieel is in een bepaald proces.\nSensoren in de Thingsway houden eventuele veranderingen in een omgeving continu in de gaten. Als deze optreden dan zal de Thingsway via een directe internetverbinding een signaal geven waardoor u in kunt grijpen voordat storingen of problemen zich voordoen.\nEen ander groot voordeel is dat u door het continu monitoren een veel beter beeld krijgt van het gehele proces. Hierdoor kunt u aanpassingen doen die de efficiëntie van onderhoud zullen vergroten.\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>','Wat is de betekenis van IoT?','','inherit','closed','closed','','321-revision-v1','','','2022-01-31 09:52:14','2022-01-31 09:52:14','',321,'https://thingsway.media2netdev.nl/?p=455',0,'revision','',0),(456,1,'2022-01-31 09:52:14','2022-01-31 09:52:14','Bijna in elke bedrijfsbranche wordt gesproken over hoe het Internet of Things zorgt voor een revolutie op de markt. Deze gesprekken worden vooral gevoerd bij grote bedrijven, die over voldoende kapitaal beschikken om mee te gaan in deze revolutie. MKB bedrijven beschikken vaak over minder tot beperkte middelen, toch kan het IoT ook deze bedrijven helpen. De inzet van het IoT zal er voor MKB bedrijven echter iets anders uitzien.\n<h2>De voordelen van het IoT</h2>\nDe voordelen van het IoT zijn zo goed als eindeloos, veel bedrijfsleiders zullen u dat weten te vertellen. Helaas kan niet ieder bedrijf profiteren van alle voordelen van het IoT, omdat het hoge kosten met zich mee kan brengen. Toch kunnen MKB bedrijven met beperkte middelen ook veel baat hebben bij een IoT-toepassing.\n\nWat het IoT voor uw bedrijf kan betekenen is afhankelijk van uw bedrijfstak en de beschikbare middelen. De voordelen die u als MKB bedrijf kunt krijgen van een IoT-toepassing vallen in twee categorieën; efficiëntie en verlaging van kosten.\n<h2>Voorbeelden van het IoT voor MKB bedrijven</h2>\nDoor arbeidsprocessen te vereenvoudigen en te stroomlijnen kunt u de efficiëntie in uw bedrijf vergroten. Een IoT-apparaat kan u daarbij helpen. Planning en andere administratieve taken kosten vaak veel van uw tijd, door deze te automatiseren kunt u de productiviteit binnen het bedrijf verhogen. Dit kunt u doen door deze taken te laten uitvoeren door bijvoorbeeld Google Assistant, een virtuele assistent. Uw werknemers kunnen zich daardoor concentreren op belangrijkere taken.\n\nHeeft u een MKB-bedrijf dat veel met magazijnbeheer te maken heeft? Het IoT is dan zeer geschikt voor u om de efficiëntie te vergroten. Door gebruik te maken van sensoren kunnen uw medewerkers alle goederen volgen en vinden in het magazijn.\n\nOver het algemeen zorgen IoT-toepassingen ervoor dat het leven van medewerkers, bewoners of gebruikers gemakkelijker wordt gemaakt. Ook voor MKB bedrijven kan dit leiden tot een hogere productiviteit. Een ander groot voordeel van IoT voor het MKB is de verlaging van kosten. Een Internet of Things versie van een alledaags apparaat kan op langere termijn voor aanzienlijke besparingen zorgen. Denkt u dan bijvoorbeeld aan een slimme thermostaat.\n\nHet IoT is tevens zeer effectief op gebied van voorspellend onderhoud, daarom is het een populaire toepassing geworden voor veel bedrijven. Wanneer u als bedrijf voorspellend onderhoud toepast, dan kunt u storingen en defecten aan machines en apparaten voorspellen voordat de problemen zich voordoen.\n\nVoorspellend onderhoud wordt gedaan door middel van sensoren, deze houden continu machines in de gaten. Hierdoor kan onderhoud uitgevoerd worden wanneer het echt nodig is. Het IoT helpt hiermee een bedrijf om reparaties en stilstand te voorkomen, dit scheelt enorm in de kosten.\n<h2>Toepassen van het IoT in het MKB</h2>\nDe revolutionaire technologie van het IoT is niet alleen geschikt voor grote bedrijven, maar kan ook MKB bedrijven dezelfde voordelen bieden. Deze kunnen dat echter vaak niet op dezelfde schaal toepassen. Sommige MKB bedrijven kiezen niet voor een IoT-toepassing, omdat ze zorgen hebben over de aanschaf- en installatiekosten. Grote bedrijven hebben daarbij een voordeel, maar ook voor MKB bedrijven bestaan er oplossingen en mogelijkheden zonder grote risico’s. Het is daarbij belangrijk om als bedrijf te bepalen wat de kritieke onderdelen of processen zijn in uw bedrijf.\n<h2>Wat kan een MKB bedrijf met het IoT?</h2>\nOm als MKB bedrijf op een goede manier gebruik te maken van het IoT, dient u te bepalen waar uw behoeften liggen. Waar zitten de inefficiënties in uw bedrijf? Door deze te bepalen kunt u op een gerichte manier een investering doen door een IoT-toepassing te implementeren. Is het gebruik van elektriciteit één van de grote kostenposten in uw bedrijf? Dan kunt u bijvoorbeeld gebruiken maken van slimme lampen of een slimme thermostaat. Is een bepaalde machine essentieel voor uw bedrijf? Laat deze dan monitoren door een IoT-sensor.\n<h2>De Thingsway, een IoT-sensor</h2>\nDe Thingsway is een IoT-sensor dat ontwikkeld is door Salland Electronics. Deze sensor heeft een aantal grote voordelen:\n• De sensor is makkelijk en snel aan te passen aan de wensen van uw bedrijf;\n• Binnen een dag kunt u een sensor in uw bedrijf hebben;\n• De Thingsway is een voordelig product.\n\nDoor deze voordelen is de Thingsway een zeer toegankelijk en geschikt product voor een MKB bedrijf. Wilt u als MKB bedrijf profiteren van de mogelijkheden van het IoT? Dan is de Thingsway het geschikte product voor u!\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>','Wat kan IoT voor een ZZP\'er en MKB bedrijf betekenen?','','inherit','closed','closed','','323-revision-v1','','','2022-01-31 09:52:14','2022-01-31 09:52:14','',323,'https://thingsway.media2netdev.nl/?p=456',0,'revision','',0),(457,1,'2022-01-31 09:52:16','2022-01-31 09:52:16','De naam duikt steeds vaker op en we maken er ongemerkt steeds meer gebruik van, maar toch klinkt voor velen de term “Internet of Things” nog als een onbekende toekomstvisie. Het Internet of Things is simpelweg het concept van het verbinden van alledaagse dingen aan het internet, waardoor ze in staat zijn om onderling te communiceren. Het principe achter dit idee is niet nieuw. Voorheen werd het Machine-to-Machine genoemd, maar het IoT is veel groter dan dat.\n\nZonder dat we er bewust van zijn, is het aantal verbonden dingen in onze wereld enorm groot geworden en de vraag neemt alleen maar toe. De waarde van de markt in IoT producten en toepassingen groeit daardoor explosief. In dit artikel kunt u lezen van het IoT precies is en geven we u enkele voorbeelden van IoT toepassingen in de wereld.\n<h2>Wat is het IoT en wat is dat ding dan precies?</h2>\nUw computer en uw smartphone zijn voor u bekende dingen die met het internet verbonden zijn. Het Internet of Things gaat verder dan dat, want het gaat om het woord dingen. Alledaagse dingen die nu voorzien worden van een internetverbinding kunnen apparaten, machines en systemen zijn, maar ook objecten zoals een brug, weg of dakgoot. Door de internetverbinding kunnen deze met elkaar communiceren, met als ultieme doel het leven van mensen te versimpelen en effectiever te maken.\n<h2>Hoe maken IoT-toepassingen verbinding met elkaar?</h2>\nOm verbinding te maken met het internet wordt er binnen het IoT gebruik gemaakt van verschillende soorten netwerken zoals:\n<h2>Mobiel netwerk</h2>\nSmartphones hebben gezorgd voor een enorme groei van het IoT want ze zijn een soort assistent geworden van andere apparaten, zonder ingebouwde internetnetconnectie. U kunt dan denken aan persoon weegschalen, fitness-meters en smarthome-apparaten. Deze zijn afhankelijk van de smartphone om zich met het internet te verbinden.\nHet Internet of Things is een grote reden waarom het 5G netwerk opgezet wordt. 5G kan namelijk aan veel meer apparaten connectiviteit bieden dan 4G.\n<h2>Het WiFi-netwerk</h2>\nWe maken steeds meer gebruik van slimme apparaten in ons huis, dit zijn de duidelijkste voorbeelden van het IoT om ons heen. Denkt u maar eens aan een slimme thermostaat, slimme luidsprekers, slimme koelkasten en een videodeurbel. Deze apparaten maken gebruik van uw WIFI-netwerk om uit zichzelf te kunnen functioneren.\n<h2>Vast internet</h2>\nVeel bedrijven in de productie-industrie maken nog steeds gebruik van vast internet om de connectie van hun IoT-toepassingen te waarborgen. Dit wordt echter steeds vaker vervangen door IoT-sensoren met een eigen gateway.\n<h2>Voorbeelden van IoT toepassingen</h2>\nWe hebben al enkele voorbeelden genoemd hoe het Internet of Things steeds meer in ons dagelijks leven aanwezig is. De meeste toepassingen gaan echter ongemerkt zoals bij de volgende voorbeelden:\n<h2>Slimme afvalverwerking in steden</h2>\nAfval wordt afgehaald op een vaste dag in de maand, toch? Helaas niet erg praktisch. Steeds meer gemeentes maken gebruik van het IoT om afval op te halen wanneer het nodig is, dus wanneer de containers vol zijn.\n\n<img class=\"size-full wp-image-1957 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/12/iot-toepassing-bij-afvalverwerking.jpg\" alt=\"iot toepassing\" width=\"1920\" height=\"1080\" />\n<h2>Slimme gebouwen</h2>\nHet IoT is de ideale manier om ons leven makkelijker en aangenamer te maken in gebouwen. Een klein voorbeeld daarvan is een slimme thermostaat. Deze kan voor u regelen dat het op het juiste moment aangenaam is in uw huis. Grote voorbeelden worden gebruikt in grotere gebouwen. IoT-toepassingen zorgen ervoor dat kantoren, ziekenhuizen, fabrieken maar ook hele woningcomplexen ‘slim’ worden. Het gebouw zorgt zelf voor de juiste temperatuur, voor een gezond leefklimaat en dat er zuinig met stroom wordt omgegaan.\n<h2>IoT en de invloed op bedrijven</h2>\nHet IoT heeft voor veel bedrijven gezorgd voor een nieuwe industriële revolutie. Door systemen, machines en objecten te monitoren met sensoren kan een bedrijf een veel beter inzicht krijgen in een proces. Dit kan veel positieve gevolgen hebben voor de effectiviteit van een bedrijf, wat zorgt voor een hogere winst. Om concurrent te blijven als bedrijf is het van groot belang om mee te gaan in de wereld van het IoT.\n\nEen voorbeeld van zo’n sensor is de Thingsway. Deze kan ingezet worden voor veel verschillende IoT-toepassingen. Op dit moment monitort een Thingsway sensor de werking van een dakgoot. Door dit continu te monitoren weet de eigenaar van het pand precies wanneer onderhoud gepleegd moet worden, voordat problemen zich voordoen. Dit is slechts een voorbeeld van de mogelijkheden van de Thingsway. Het is een basisproduct dat zeer snel aan te passen is op uw wensen en het te meten proces.\n\n<img class=\"size-full wp-image-1117 aligncenter\" src=\"https://thingsway.nl/wp-content/uploads/2020/08/ThingsWay-davinci.png\" alt=\"onderhoud en maintenaice\" width=\"416\" height=\"294\" />\n<h2>Vrijblijvend contact</h2>\nMet het IoT ThingsWay producten en diensten portfolio is een totaalpakket gerealiseerd van sensor tot en met cloud om snel en eenvoudig IoT projecten voor preventief onderhoud te implementeren. De onderdelen bestaan uit een hardware platform, connectivity via het mobiele telecommunicatie netwerk en een cloud dienst. Omdat het een platform is en geen standaard oplossing is het eenvoudig aan te passen voor integratie met bestaande producten en/of installaties. Heeft u vragen of  bent u benieuwd naar de mogelijkheden? Neem dan vrijblijvend contact met ons op!\n<div style=\"background-color: #f44336; border-radius: 5px; text-align: center; color: #ffffff;\">\n\n<strong><a style=\"font: 400 1.6875rem/48px arial; color: #ffffff;\" href=\"/contact\"><span style=\"font-family: arial, helvetica, sans-serif;\">Contact</span> opnemen</a></strong>\n\n</div>','Voorbeelden van IoT toepassingen','','inherit','closed','closed','','325-revision-v1','','','2022-01-31 09:52:16','2022-01-31 09:52:16','',325,'https://thingsway.media2netdev.nl/?p=457',0,'revision','',0),(458,1,'2022-01-31 09:56:00','2022-01-31 09:56:00','[fusion_builder_container type=\"flex\" hundred_percent=\"no\" hundred_percent_height=\"no\" hundred_percent_height_scroll=\"no\" align_content=\"stretch\" flex_align_items=\"flex-start\" flex_justify_content=\"flex-start\" hundred_percent_height_center_content=\"yes\" equal_height_columns=\"no\" container_tag=\"div\" hide_on_mobile=\"small-visibility,medium-visibility,large-visibility\" status=\"published\" spacing_medium=\"\" spacing_small=\"\" padding_dimensions_medium=\"\" padding_dimensions_small=\"\" border_sizes=\"\" border_style=\"solid\" box_shadow=\"no\" box_shadow_blur=\"0\" box_shadow_spread=\"0\" gradient_start_color=\"\" gradient_end_color=\"\" gradient_start_position=\"0\" gradient_end_position=\"100\" gradient_type=\"linear\" radial_direction=\"center center\" linear_angle=\"180\" background_position=\"center center\" background_repeat=\"no-repeat\" fade=\"no\" background_parallax=\"none\" enable_mobile=\"no\" parallax_speed=\"0.3\" background_blend_mode=\"none\" video_aspect_ratio=\"16:9\" video_loop=\"yes\" video_mute=\"yes\" render_logics=\"\" absolute=\"off\" absolute_devices=\"small,medium,large\" sticky=\"off\" sticky_devices=\"small-visibility,medium-visibility,large-visibility\" sticky_transition_offset=\"0\" scroll_offset=\"0\" animation_direction=\"left\" animation_speed=\"0.3\" filter_hue=\"0\" filter_saturation=\"100\" filter_brightness=\"100\" filter_contrast=\"100\" filter_invert=\"0\" filter_sepia=\"0\" filter_opacity=\"100\" filter_blur=\"0\" filter_hue_hover=\"0\" filter_saturation_hover=\"100\" filter_brightness_hover=\"100\" filter_contrast_hover=\"100\" filter_invert_hover=\"0\" filter_sepia_hover=\"0\" filter_opacity_hover=\"100\" filter_blur_hover=\"0\"][fusion_builder_row][fusion_builder_column type=\"1_1\" align_self=\"auto\" content_layout=\"column\" align_content=\"flex-start\" valign_content=\"flex-start\" content_wrap=\"wrap\" center_content=\"no\" target=\"_self\" hide_on_mobile=\"small-visibility,medium-visibility,large-visibility\" sticky_display=\"normal,sticky\" type_medium=\"\" type_small=\"\" type=\"1_1\" order_medium=\"0\" order_small=\"0\" dimension_spacing_medium=\"\" dimension_spacing_small=\"\" dimension_spacing=\"\" dimension_margin_medium=\"\" dimension_margin_small=\"\" dimension_margin=\"\" padding_medium=\"\" padding_small=\"\" padding=\"\" hover_type=\"none\" border_sizes=\"\" border_style=\"solid\" border_radius=\"\" box_shadow=\"no\" dimension_box_shadow=\"\" box_shadow_blur=\"0\" box_shadow_spread=\"0\" background_type=\"single\" gradient_start_color=\"\" gradient_end_color=\"\" gradient_start_position=\"0\" gradient_end_position=\"100\" gradient_type=\"linear\" radial_direction=\"center center\" linear_angle=\"180\" background_position=\"left top\" background_repeat=\"no-repeat\" background_blend_mode=\"none\" render_logics=\"\" filter_type=\"regular\" filter_hue=\"0\" filter_saturation=\"100\" filter_brightness=\"100\" filter_contrast=\"100\" filter_invert=\"0\" filter_sepia=\"0\" filter_opacity=\"100\" filter_blur=\"0\" filter_hue_hover=\"0\" filter_saturation_hover=\"100\" filter_brightness_hover=\"100\" filter_contrast_hover=\"100\" filter_invert_hover=\"0\" filter_sepia_hover=\"0\" filter_opacity_hover=\"100\" filter_blur_hover=\"0\" animation_direction=\"left\" animation_speed=\"0.3\" min_height=\"\" last=\"no\" link=\"\" border_position=\"all\"][fusion_text columns=\"\" rule_style=\"default\" rule_size=\"\" text_transform=\"none\" animation_direction=\"left\" animation_speed=\"0.3\" hide_on_mobile=\"small-visibility,medium-visibility,large-visibility\" sticky_display=\"normal,sticky\"]<h1 class=\"et_pb_module_header\">Maak kennis met SallandElectronics</h1><div class=\"et_pb_header_content_wrapper\"><p>Meer dan 20 jaar ervaring in de elektronica branch en meer dan 15 jaar ervaring met <a href=\"https://thingsway.nl/management/betekenis-iot/\">IoT</a> oplossingen. Expert op het gebied van Internet of Things.</p><div class=\"et_pb_module et_pb_text et_pb_text_0  et_pb_text_align_center et_pb_bg_layout_light\"><div class=\"et_pb_text_inner\"><h2>Embedded hard- en software experts sinds 2001</h2></div></div><div class=\"et_pb_module et_pb_text et_pb_text_1  et_pb_text_align_center et_pb_bg_layout_light\"><div class=\"et_pb_text_inner\"><p><strong>Salland</strong>Electronics is dé specialist op het gebied van IoT-oplossingen. Wij realiseren al ruim 20 jaar IoT-oplossingen die van grote waarde zijn voor onze klanten.</p><p>Wij ontwikkelen en produceren op een veilige, efficiënte én duurzame wijze intelligente IoT-producten voor onze klanten. Onze IoT-producten worden voorzien van hoogstaande en gebruiksvriendelijke hard- en software. Met de mogelijkheden die onze IoT-oplossingen bieden, verhogen wij de efficiëntie van de bedrijfsvoering van onze klanten. Bij <strong>Salland</strong>Electronics staat u als klant centraal. Wij hechten grote waarde aan de samenwerkingen met onze klanten. Ons motto: <strong>samen efficiënt én resultaatgericht werken.</strong></p><p>Wij denken in elke fase van de realisering van de IoT-oplossing met u mee om zo tot de beste oplossing voor uw vraagstuk te komen. Naast de ontwikkeling realiseren wij voor u de productie van de oplossing. Bovendien onderscheiden wij ons met de volgende kerncompetenties:</p><p> </p><ul><li>Embedded hard- en software</li><li>Internettechnologie en infrastructuren</li><li>Draadloze en energiezuinige oplossingen</li></ul></div></div></div>[/fusion_text][fusion_youtube autoplay=\"true\" hide_on_mobile=\"small-visibility,medium-visibility,large-visibility\" id=\"https://www.youtube.com/watch?v=x_Xv7N7Lxiw&amp;t=1s\" alignment=\"left\" /][/fusion_builder_column][/fusion_builder_row][/fusion_builder_container]','Over ons','','inherit','closed','closed','','24-revision-v1','','','2022-01-31 09:56:00','2022-01-31 09:56:00','',24,'https://thingsway.media2netdev.nl/?p=458',0,'revision','',0),(460,1,'2022-02-04 12:50:06','2022-01-31 10:05:13',' ','','','publish','closed','closed','','460','','','2022-02-04 12:50:06','2022-02-04 12:50:06','',0,'https://thingsway.media2netdev.nl/?p=460',2,'nav_menu_item','',0),(461,1,'2022-02-04 12:50:06','2022-01-31 10:05:14',' ','','','publish','closed','closed','','461','','','2022-02-04 12:50:06','2022-02-04 12:50:06','',0,'https://thingsway.media2netdev.nl/?p=461',1,'nav_menu_item','',0),(462,1,'2022-02-04 12:50:07','2022-01-31 10:05:14',' ','','','publish','closed','closed','','462','','','2022-02-04 12:50:07','2022-02-04 12:50:07','',0,'https://thingsway.media2netdev.nl/?p=462',9,'nav_menu_item','',0),(463,1,'2022-02-04 12:50:07','2022-01-31 10:05:14',' ','','','publish','closed','closed','','463','','','2022-02-04 12:50:07','2022-02-04 12:50:07','',0,'https://thingsway.media2netdev.nl/?p=463',8,'nav_menu_item','',0),(464,1,'2022-02-04 12:50:06','2022-01-31 10:05:14','','Projecten','','publish','closed','closed','','projecten','','','2022-02-04 12:50:06','2022-02-04 12:50:06','',0,'https://thingsway.media2netdev.nl/?p=464',3,'nav_menu_item','',0),(465,1,'2022-02-04 12:50:07','2022-01-31 10:05:15','','Contact','','publish','closed','closed','','contact','','','2022-02-04 12:50:07','2022-02-04 12:50:07','',0,'https://thingsway.media2netdev.nl/?p=465',10,'nav_menu_item','',0),(466,1,'2022-02-04 12:50:07','2022-01-31 10:05:15','','Maak een afspraak','','publish','closed','closed','','maak-een-afspraak','','','2022-02-04 12:50:07','2022-02-04 12:50:07','',0,'https://thingsway.media2netdev.nl/?p=466',11,'nav_menu_item','',0),(467,1,'2022-02-03 13:59:40','2022-02-03 13:59:40','[fusion_builder_container type=\"flex\" hundred_percent=\"no\" hundred_percent_height=\"min\" min_height=\"500px\" hundred_percent_height_scroll=\"no\" align_content=\"stretch\" flex_align_items=\"stretch\" flex_justify_content=\"center\" hundred_percent_