\n<p><span style=\"color: #ffffff;\">Oplossing voor schaarste personeel</span></p>\r\n[/fusion_li_item][fusion_li_item icon=\"fa-search-dollar fas\"]\r\n<p><span style=\"color: #ffffff;\">Levert BIG data voor analyse</span></p>\r\n[/fusion_li_item][fusion_li_item icon=\"fa-hammer fas\"]\r\n<p><span style=\"color: #ffffff;\">Voorspellend onderhoud</span></p>\r\n[/fusion_li_item][fusion_li_item icon=\"fa-location-arrow fas\"]\r\n<p><span style=\"color: #ffffff;\">Plaats onafhankelijk</span></p>\r\n[/fusion_li_item][fusion_li_item icon=\"fa-download fas\"]\r\n<p><span style=\"color: #ffffff;\">Installatiegemak</span></p>\r\n[/fusion_li_item][/fusion_checklist][/fusion_builder_column][/fusion_builder_row][/fusion_builder_container][fusion_builder_container type=\"flex\" hundred_percent=\"no\" hundred_percent_height=\"no\" hundred_percent_height_scroll=\"no\" align_content=\"stretch\" flex_align_items=\"flex-start\" flex_justify_content=\"flex-start\" hundred_percent_height_center_content=\"yes\" equal_height_columns=\"no\" container_tag=\"div\" hide_on_mobile=\"small-visibility,medium-visibility,large-visibility\" status=\"published\" border_style=\"solid\" box_shadow=\"no\" box_shadow_blur=\"0\" box_shadow_spread=\"0\" gradient_start_position=\"0\" gradient_end_position=\"100\" gradient_type=\"linear\" radial_direction=\"center center\" linear_angle=\"180\" background_position=\"center center\" background_repeat=\"no-repeat\" fade=\"no\" background_parallax=\"none\" enable_mobile=\"no\" parallax_speed=\"0.3\" background_blend_mode=\"none\" video_aspect_ratio=\"16:9\" video_loop=\"yes\" video_mute=\"yes\" absolute=\"off\" absolute_devices=\"small,medium,large\" sticky=\"off\" sticky_devices=\"small-visibility,medium-visibility,large-visibility\" sticky_transition_offset=\"0\" scroll_offset=\"0\" animation_direction=\"left\" animation_speed=\"0.3\" filter_hue=\"0\" filter_saturation=\"100\" filter_brightness=\"100\" filter_contrast=\"100\" filter_invert=\"0\" filter_sepi