er=\"0\" filter_sepia_hover=\"0\" filter_opacity_hover=\"100\" filter_blur_hover=\"0\" animation_direction=\"left\" animation_speed=\"0.3\" last=\"true\" border_position=\"all\" first=\"true\" min_height=\"\" link=\"\"][fusion_title title_type=\"text\" rotation_effect=\"bounceIn\" display_time=\"1200\" highlight_effect=\"circle\" loop_animation=\"off\" highlight_width=\"9\" highlight_top_margin=\"0\" title_link=\"off\" link_target=\"_self\" hide_on_mobile=\"small-visibility,medium-visibility,large-visibility\" sticky_display=\"normal,sticky\" content_align=\"left\" size=\"1\" text_color=\"#003b7f\" text_shadow=\"no\" text_shadow_blur=\"0\" gradient_font=\"no\" gradient_start_position=\"0\" gradient_end_position=\"100\" gradient_type=\"linear\" radial_direction=\"center center\" linear_angle=\"180\" style_type=\"default\" animation_direction=\"left\" animation_speed=\"0.3\"]\r\n\r\nVoordelen van IoT bij onderhoud\r\n\r\n[/fusion_title][/fusion_builder_column][fusion_builder_column type=\"1_2\" layout=\"1_2\" align_self=\"auto\" content_layout=\"column\" align_content=\"flex-start\" valign_content=\"flex-start\" content_wrap=\"wrap\" center_content=\"no\" target=\"_self\" hide_on_mobile=\"small-visibility,medium-visibility,large-visibility\" sticky_display=\"normal,sticky\" order_medium=\"0\" order_small=\"0\" hover_type=\"none\" border_style=\"solid\" box_shadow=\"no\" box_shadow_blur=\"0\" box_shadow_spread=\"0\" background_type=\"single\" gradient_start_position=\"0\" gradient_end_position=\"100\" gradient_type=\"linear\" radial_direction=\"center center\" linear_angle=\"180\" background_position=\"left top\" background_repeat=\"no-repeat\" background_blend_mode=\"none\" filter_type=\"regular\" filter_hue=\"0\" filter_saturation=\"100\" filter_brightness=\"100\" filter_contrast=\"100\" filter_invert=\"0\" filter_sepia=\"0\" filter_opacity=\"100\" filter_blur=\"0\" filter_hue_hover=\"0\" filter_saturation_hover=\"100\" filter_brightness_hover=\"100\" filter_contrast_hover=\"100\" filter_invert_hover=\"0\" filter_sepia_hover=\"0\" filter_opacity_hover=\"100\" filter_blur_hover=\"0\" animation_direction=\"left\" animation_speed=\"0.3\" last=\"false\" border_position=\"all\" first=\"true\" border_sizes_top=\"2px\" border_sizes_right=\"2px\" border_sizes_bottom=\"2px\" border_sizes_left=\"2px\" border_color=\"#003b7f\" border_radius_top_left=\"5px\" border_radius_top_right=\"5px\" border_radius_bottom_right=\"5px\" border_radius_bottom_left=\"5px\" background_color=\"#003b7f\" min_height=\"\" link=\"\"][fusion_text rule_style=\"default\" hide_on_mobile=\"small-visibility,medium-visibility,large-visibility\" sticky_display=\"normal,sticky\" margin_top=\"20px\" margin_right=\"20px\" margin_bottom=\"20px\" margin_left=\"20px\" text_transform=\"none\" animation_direction=\"left\" animation_speed=\"0.3\"]\r\n\r\n<span style=\"color: #003b7f; font-family: Ubuntu; font-weight: 500;\" data-fusion-font=\"true\" data-fusion-google-font=\"Ubuntu\" data-fusion-google-variant=\"500\"><span style=\"letter-spacing: normal; color: #ffffff;\" data-fusion-font=\"true\">\'\'Er staan van ons honderden pompen in Nederland en wisten niet of de installaties wel goed werkt. Nu krijgen wij een seintje via SMS of email wanneer er niet meer gepompt wordt en kunnen wij direct actie ondernemen, bespaart ons veel tijd en dus geld.\'\'</span></span>\r\n\r\n&nbsp;\r\n\r\n<span style=\"color: #003b7f; font-family: Ubuntu;\" data-fusion-font=\"true\" data-fusion-google-font=\"Ubuntu\" data-fusion-google-variant=\"500\"><b style=\"color: #ffffff;\">- Piet</b></span>\r\n\r\n<span style=\"color: #ffffff; font-family: Ubuntu; font-weight: 500;\" data-fusion-font=\"true\" data-fusion-google-font=\"Ubuntu\" data-fusion-google-variant=\"500\">Actief in bronbemaling</span>\r\n<h5 class=\"\" style=\"--fontsize: 24; line-height: 1.4;\" data-fontsize=\"24\" data-lineheight=\"33.6px\"></h5>\r\n[/fusion_text][/fusion_builder_column][fusion_builder_column type=\"1_2\" layout=\"1_2\" align_self=\"auto\" content_layout=\"column\" align_content=\"flex-start\" valign_content=\"flex-start\" content_wrap=\"wrap\" center_content=\"no\" target=\"_self\" hide_on_mobile=\"small-visibility,medium-visibility,large-visibility\" sticky_display=\"normal,sticky\" order_medium=\"0\" order_small=\"0\" hover_type=\"none\" border_style=\"solid\" box_shadow=\"no\" box_shadow_blur=\"0\" box_shadow_spread=\"0\" background_type=\"single\" gradient_start_position=\"0\" gradient_end_position=\"100\" gradient_type=\"linear\" radial_direction=\"center center\" linear_angle=\"180\" background_color=\"#f49200\" background_position=\"left top\" background_repeat=\"no-repeat\" background_blend_mode=\"none\" filter_type=\"regular\" filter_hue=\"0\" filter_saturation=\"100\" filter_brightness=\"100\" filter_contrast=\"100\" filter_invert=\"0\" filter_sepia=\"0\" filter_opacity=\"100\" filter_blur=\"0\" filter_hue_hover=\"0\" filter_saturation_hover=\"100\" filter_brightness_hover=\"100\" filter_contrast_hover=\"100\" filter_invert_hover=\"0\" filter_sepia_hover=\"0\" filter_opacity_hover=\"100\" filter_blur_hover=\"0\" animation_direction=\"left\" animation_speed=\"0.3\" last=\"true\" border_position=\"all\" first=\"false\" padding_bottom=\"10px\" border_sizes_top=\"2px\" border_sizes_right=\"2px\" border_sizes_bottom=\"2px\" border_sizes_left=\"2px\" margin_bottom=\"0px\" border_color=\"#f49200\" border_radius_top_left=\"5px\" border_radius_top_right=\"5px\" border_radius_bottom_right=\"5px\" border_radius_bottom_left=\"5px\" min_height=\"\" link=\"\"][fusion_text rule_style=\"default\" hide_on_mobile=\"small-visibility,medium-visibility,large-visibility\" sticky_display=\"normal,sticky\" margin_top=\"20px\" margin_right=\"20px\" margin_bottom=\"20px\" margin_left=\"20px\" text_transform=\"none\" animation_direction=\"left\" animation_speed=\"0.3\"]\r\n<p style=\"color: #f9f9f9; font-family: Ubuntu; font-weight: 500;\" data-fusion-font=\"true\" data-fusion-google-font=\"Ubuntu\" data-fusion-google-variant=\"500\">\'\' Ons bedrijf hebben veel toegangsdeuren die nog niet op afstand te monitoren zijn. Door gebruik te maken van het Salland Electronics ThingsWay platform is dat wel mogelijk. Binnen een week was de eerste deur connected. De service afdeling werkt nu veel efficiënter en wij weten nu veel meer van de gebruiker.\'\'</p>\r\n<p style=\"color: #003b7f; font-family: Ubuntu;\" data-fusion-font=\"true\" data-fusion-google-font=\"Ubuntu\" data-fusion-google-variant=\"500\"><span style=\"font-weight: 500; color: #f9f9f9;\">-</span><b style=\"color: #f9f9f9;\"> Theresa</b></p>\r\n<p style=\"color: #003b7f; font-family: Ubuntu; font-weight: 500;\" data-fusion-font=\"true\" data-fusion-google-font=\"Ubuntu\" data-fusion-google-variant=\"500\"><span style=\"color: #f9f9f9;\">Toegangsverlening</span></p>\r\n[/fusion_text][/fusion_builder_column][fusion_builder_column type=\"1_2\" layout=\"1_2\" align_self=\"auto\" content_layout=\"column\" align_content=\"flex-start\" valign_content=\"flex-start\" content_wrap=\"wrap\" center_content=\"no\" target=\"_self\" hide_on_mobile=\"small-visibility,medium-visibility,large-visibility\" sticky_display=\"normal,sticky\" order_medium=\"0\" order_small=\"0\" hover_type=\"none\" border_style=\"solid\" box_shadow=\"no\" box_shadow_blur=\"0\" box_shadow_spread=\"0\" background_type=\"single\" gradient_start_position=\"0\" gradient_end_position=\"100\" gradient_type=\"linear\" radial_direction=\"center center\" linear_angle=\"180\" background_color=\"#f49200\" background_position=\"left top\" background_repeat=\"no-repeat\" background_blend_mode=\"none\" filter_type=\"regular\" filter_hue=\"0\" filter_saturation=\"100\" filter_brightness=\"100\" filter_contrast=\"100\" filter_invert=\"0\" filter_sepia=\"0\" filter_opacity=\"100\" filter_blur=\"0\" filter_hue_hover=\"0\" filter_saturation_hover=\"100\" filter_brightness_hover=\"100\" filter_contrast_hover=\"100\" filter_invert_hover=\"0\" filter_sepia_hover=\"0\" filter_opacity_hover=\"100\" filter_blur_hover=\"0\" animation_direction=\"left\" animation_speed=\"0.3\" last=\"false\" border_position=\"all\" first=\"true\" border_sizes_top=\"2px\" border_sizes_right=\"2px\" border_sizes_bottom=\"2px\" border_sizes_left=\"2px\" border_color=\"#f49200\" border_radius_top_left=\"5px\" border_radius_top_right=\"5px\" border_radius_bottom_right=\"5px\" border_radius_bottom_left=\"5px\" min_height=\"\" link=\"\"][fusion_text rule_style=\"default\" hide_on_mobile=\"small-visibility,medium-visibility,large-visibility\" sticky_display=\"normal,sticky\" margin_top=\"20px\" margin_right=\"20px\" margin_bottom=\"20px\" margin_left=\"20px\" text_transform=\"none\" animation_direction=\"left\" animation_speed=\"0.3\"]\r\n\r\n<span style=\"color: #ffffff; font-family: Ubuntu; font-weight: 500;\" data-fusion-font=\"true\" data-fusion-google-font=\"Ubuntu\" data-fusion-google-variant=\"500\">\'\' Wij zetten in op IoT technologie om ons bedrijf te internationaliseren. Wij weten veel van onderhoud van daken, maar met het ThingsWay platform weten wij nu echt wat er gebeurt en kunnen aan predictive maintenance beginnen. Wij lopen hiermee ver voor op de internationale concurrentie met onze slimme dakgoot.\'\'</span>\r\n<p style=\"color: #003b7f;\"><b style=\"color: #ffffff;\">- Peter</b></p>\r\n<p style=\"color: #003b7f; font-family: Ubuntu; font-weight: 500;\" data-fusion-font=\"true\" data-fusion-google-font=\"Ubuntu\" data-fusion-google-variant=\"500\"><span style=\"color: #ffffff;\">Actief in dak onderhoud</span></p>\r\n[/fusion_text][/fusion_builder_column][fusion_builder_column type=\"1_2\" layout=\"1_2\" align_self=\"auto\" content_layout=\"column\" align_content=\"flex-start\" valign_content=\"flex-start\" content_wrap=\"wrap\" center_content=\"no\" target=\"_self\" hide_on_mobile=\"small-visibility,medium-visibility,large-visibility\" sticky_display=\"normal,sticky\" order_medium=\"0\" order_small=\"0\" hover_type=\"none\" border_