\r\n\r\n<span style=\"color: #ffffff; font-family: Ubuntu; font-weight: 500;\" data-fusion-font=\"true\" data-fusion-google-font=\"Ubuntu\" data-fusion-google-variant=\"500\">Millie sector</span>\r\n\r\n[/fusion_text][/fusion_builder_column][/fusion_builder_row][/fusion_builder_container]','Homepagina','','inherit','closed','closed','','2-revision-v1','','','2022-02-04 12:51:39','2022-02-04 12:51:39','',2,'https://thingsway.media2netdev.nl/?p=588',0,'revision','',0),(589,2,'2022-02-04 12:55:05','2022-02-04 12:55:05','[fusion_builder_container type=\"flex\" hundred_percent=\"no\" hundred_percent_height=\"min\" min_height=\"500px\" hundred_percent_height_scroll=\"no\" align_content=\"stretch\" flex_align_items=\"stretch\" flex_justify_content=\"center\" hundred_percent_height_center_content=\"yes\" equal_height_columns=\"no\" container_tag=\"div\" hide_on_mobile=\"small-visibility,medium-visibility,large-visibility\" status=\"published\" margin_top=\"-60px\" border_style=\"solid\" box_shadow=\"no\" box_shadow_blur=\"0\" box_shadow_spread=\"0\" gradient_start_color=\"#000000\" gradient_end_color=\"rgba(0,0,0,0.3)\" gradient_start_position=\"0\" gradient_end_position=\"100\" gradient_type=\"linear\" radial_direction=\"center center\" linear_angle=\"180\" background_image=\"https://thingsway.nl/wp-content/uploads/2021/12/2327-iot.webp\" background_position=\"center center\" background_repeat=\"no-repeat\" fade=\"no\" background_parallax=\"none\" enable_mobile=\"no\" parallax_speed=\"0.3\" background_blend_mode=\"none\" video_aspect_ratio=\"16:9\" video_loop=\"yes\" video_mute=\"yes\" absolute=\"off\" absolute_devices=\"small,medium,large\" sticky=\"off\" sticky_devices=\"small-visibility,medium-visibility,large-visibility\" sticky_transition_offset=\"0\" scroll_offset=\"0\" animation_direction=\"left\" animation_speed=\"0.3\" filter_hue=\"0\" filter_saturation=\"100\" filter_brightness=\"100\" filter_contrast=\"100\" filter_invert=\"0\" filter_sepia=\"0\" filter_opacity=